  `alternativeSchedule` VARCHAR(200) COMMENT 'جدول بديل (إن وجد)',
  `targetAudience` VARCHAR(200) COMMENT 'الفئة المستهدفة (طلاب، معلمين، أولياء أمور، إداريون، الكل)',
  `targetGrades` DECIMAL(5,2) COMMENT 'الصفوف المستهدفة (JSON) - اختياري',
  `isPublic` BOOLEAN COMMENT 'هل تظهر لأولياء الأمور في التطبيق؟',
  `description` TEXT COMMENT 'وصف تفصيلي للفعالية',
  `location` VARCHAR(200) COMMENT 'مكان الفعالية',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - صور، بروشورات',
  `notificationSent` VARCHAR(200) COMMENT 'هل تم إرسال إشعار؟',
  `notificationDate` DATE COMMENT 'تاريخ إرسال الإشعار',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل (FK → SystemUser.userId)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`calendarId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='التقويم الدراسي التفصيلي';

-- Table: SchoolCurriculumPlan (الخطط الدراسية للمدرسة)
CREATE TABLE IF NOT EXISTS `SchoolCurriculumPlan` (
  `curriculumPlanId` BIGINT NOT NULL COMMENT 'معرف الخطة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `planNameAr` VARCHAR(200) COMMENT 'اسم الخطة بالعربية',
  `planNameEn` VARCHAR(200) COMMENT 'اسم الخطة بالإنجليزية',
  `planCode` VARCHAR(50) COMMENT 'كود الخطة (فريد)',
  `gradeLevelId` BIGINT COMMENT 'الصف الدراسي المرتبط (اختياري، يمكن ربط الخطة بصف معين) (FK → GradeCapacity.gradeLevelId)',
  `schoolLevelId` BIGINT COMMENT 'المرحلة الدراسية المرتبطة (اختياري) (FK → SchoolLevel.schoolLevelId)',
  `academicYearId` BIGINT COMMENT 'العام الدراسي (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'الفصل الدراسي (اختياري) (FK → SchoolSemester.semesterId)',
  `version` VARCHAR(200) COMMENT 'إصدار الخطة الدراسية (V1.0, V2.1)',
  `adoptionDate` DATE COMMENT 'تاريخ اعتماد المدرسة لهذه الخطة',
  `totalCreditHours` VARCHAR(200) COMMENT 'إجمالي الساعات المعتمدة (لحساب نصاب الخطة التعليمي آلياً)',
  `planStatus` VARCHAR(50) COMMENT 'حالة الخطة (مسودة، معتمد، ملغي)',
  `ministerialApproval` VARCHAR(200) COMMENT 'حالة الاعتماد الوزاري (قيد المراجعة، معتمد، مرفوض، مؤجل)',
  `approvalDocument` VARCHAR(200) COMMENT 'مستند الاعتماد (مسار الملف)',
  `isActive` BOOLEAN COMMENT 'هل الخطة مفعلة حالياً؟',
  `effectiveDate` DATE COMMENT 'تاريخ بدء العمل بالخطة',
  `expiryDate` DATE COMMENT 'تاريخ انتهاء العمل بالخطة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل (FK → SystemUser.userId)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`curriculumPlanId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`schoolLevelId`) REFERENCES `SchoolLevel`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='الخطط الدراسية للمدرسة';

-- Table: GradeCapacity (الصفوف الدراسية والطاقة الاستيعابية)
CREATE TABLE IF NOT EXISTS `GradeCapacity` (
  `gradeCapacityId` BIGINT NOT NULL COMMENT 'معرف الطاقة الاستيعابية (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف العام الدراسي (FK → SchoolAcademicYear.academicYearId)',
  `schoolLevelId` BIGINT COMMENT 'معرف المرحلة الدراسية (FK → SchoolLevel.schoolLevelId)',
  `gradeLevel` DECIMAL(5,2) COMMENT 'رقم الصف (1 للثاني، 10 للأول ثانوي، إلخ) - يمكن استخدامه كمعرف فريد داخل المدرسة والعام',
  `gradeNameAr` DECIMAL(5,2) COMMENT 'اسم الصف بالعربية (الأول الابتدائي، الأول الثانوي)',
  `gradeNameEn` DECIMAL(5,2) COMMENT 'اسم الصف بالإنجليزية',
  `maxStudentsPerClass` VARCHAR(200) COMMENT 'الحد الأقصى للطلاب في الشعبة الواحدة',
  `maxSectionsCount` INT COMMENT 'عدد الشعب المتاحة (الفصول الفيزيائية)',
  `totalCapacity` VARCHAR(200) COMMENT 'إجمالي الطاقة الاستيعابية (تُحسب آلياً: maxStudentsPerClass × maxSectionsCount)',
  `availableCapacity` VARCHAR(200) COMMENT 'السعة المتاحة المتبقية (تُحسب آلياً: totalCapacity - عدد المسجلين)',
  `currentEnrolled` VARCHAR(200) COMMENT 'عدد الطلاب المسجلين حالياً في هذا الصف (يُحدث تلقائياً من Enrollment)',
  `genderAllocation` VARCHAR(200) COMMENT 'تخصيص الجنس (بنين، بنات، مختلط) - للمدارس المختلطة',
  `isActive` BOOLEAN COMMENT 'حالة الصف (نشط، معلق - لعدم فتح التسجيل)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل (FK → SystemUser.userId)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`gradeCapacityId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`schoolLevelId`) REFERENCES `SchoolLevel`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='الصفوف الدراسية والطاقة الاستيعابية';

-- Table: SchoolAuditLog (سجل التغييرات والأرشفة)
CREATE TABLE IF NOT EXISTS `SchoolAuditLog` (
  `auditId` BIGINT NOT NULL COMMENT 'معرف سجل التدقيق (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `tableName` VARCHAR(200) COMMENT 'اسم الجدول المتأثر (Students, Employees, Invoices, إلخ)',
  `entityId` BIGINT COMMENT 'معرف الكيان المتأثر (رقم السجل الذي تم تعديله)',
  `operationType` VARCHAR(50) COMMENT 'نوع العملية (إضافة، تعديل، حذف، استرجاع)',
  `changeType` VARCHAR(50) COMMENT 'نوع التغيير (تغيير اسم، إيقاف، تغيير مدير، تحديث بيانات)',
  `oldValue` VARCHAR(200) COMMENT 'البيانات قبل التعديل (JSON)',
  `newValue` VARCHAR(200) COMMENT 'البيانات بعد التعديل (JSON)',
  `changeSummary` VARCHAR(200) COMMENT 'ملخص التغيير (نص قابل للقراءة)',
  `userId` BIGINT COMMENT 'معرف المستخدم المنفذ (FK → SystemUser.userId)',
  `userName` VARCHAR(200) COMMENT 'اسم المستخدم (كنسخة احتياطية)',
  `userRole` VARCHAR(200) COMMENT 'دور المستخدم عند التنفيذ',
  `ipAddress` VARCHAR(200) COMMENT 'عنوان IP للجهاز المستخدم',
  `deviceInfo` VARCHAR(200) COMMENT 'معلومات عن الجهاز والمتصفح',
  `actionDate` DATE COMMENT 'وقت تنفيذ الإجراء',
  `severity` VARCHAR(200) COMMENT 'مستوى الخطورة (معلومة، تحذير، حرج)',
  `isSuspicious` BOOLEAN COMMENT 'إجراء مشبوه؟ (نعم/لا) - للتعديلات في أوقات غير رسمية',
  `decisionDocPath` VARCHAR(200) COMMENT 'مسار ملف القرار المرفوع (إن وجد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`auditId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`entityId`) REFERENCES `Entity`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`)
) COMMENT='سجل التغييرات والأرشفة';

-- Table: ReferenceCoding (الترميز المرجعي)
CREATE TABLE IF NOT EXISTS `ReferenceCoding` (
  `referenceId` BIGINT NOT NULL COMMENT 'معرف الكود المرجعي (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - اختياري (قد تكون بعض الأكواد عامة لجميع المدارس)',
  `codeType` VARCHAR(50) COMMENT 'نوع الكود (GENDER, SCHOOL_TYPE, STUDENT_STATUS, DOCUMENT_TYPE, LEAVE_TYPE, ACTIVITY_TYPE, EMPLOYEE_TYPE, FEE_CATEGORY, إلخ)',
  `codeKey` VARCHAR(50) COMMENT 'مفتاح الكود (MALE, FEMALE, PUBLIC, PRIVATE, ACTIVE, GRADUATED, إلخ)',
  `codeValueAr` VARCHAR(50) COMMENT 'القيمة بالعربية (ذكر، أنثى، حكومي، أهلي، نشط، متخرج)',
  `codeValueEn` VARCHAR(50) COMMENT 'القيمة بالإنجليزية',
  `descriptionAr` TEXT COMMENT 'وصف بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف بالإنجليزية',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب ظهور الخيارات في القوائم المنسدلة',
  `isSystemCode` BOOLEAN COMMENT 'كود نظامي (لا يمكن للمستخدم حذفه أو تعديله)',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `parentCodeId` BIGINT COMMENT 'معرف الكود الأب (لإنشاء تصنيفات هرمية) (FK → ReferenceCoding.referenceId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل (FK → SystemUser.userId)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`referenceId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`parentCodeId`) REFERENCES `ReferenceCoding`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='الترميز المرجعي';

-- Table: CommitmentDeviation (الالتزامات والانحرافات)
CREATE TABLE IF NOT EXISTS `CommitmentDeviation` (
  `deviationId` BIGINT NOT NULL COMMENT 'معرف الانحراف/الإقرار (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - لتحديد العام المرتبط به',
  `type` VARCHAR(50) COMMENT 'نوع الإقرار (إقرار التزام، بلاغ انحراف عن التقويم، بلاغ انحراف عن الخطة)',
  `title` VARCHAR(200) COMMENT 'عنوان الإقرار/البلاغ (مثل "إقرار التزام بالخطة السنوية 2025-2026")',
  `deviationDate` DATE COMMENT 'تاريخ الانحراف الفعلي (لحظة وقوع التغيير)',
  `description` TEXT COMMENT 'وصف تفصيلي للانحراف أو الإقرار',
  `affectedItems` VARCHAR(200) COMMENT 'العناصر المتأثرة (JSON) - مثل أيام دراسية محددة، فعاليات، مواد',
  `reason` VARCHAR(200) COMMENT 'سبب الانحراف (مطلوب في حال وجود "انحراف")',
  `impactLevel` VARCHAR(50) COMMENT 'مستوى التأثير (بسيط، متوسط، جسيم)',
  `compensatoryPlan` VARCHAR(200) COMMENT 'الخطة التعويضية (مثل حصص إضافية، أيام بديلة)',
  `isCompensatoryPlanApproved` BOOLEAN COMMENT 'هل تم اعتماد الخطة التعويضية من المكتب؟',
  `digitalSignature` VARCHAR(200) COMMENT 'التوقيع الإلكتروني للمدير',
  `signedAt` DATE COMMENT 'تاريخ التوقيع',
  `status` VARCHAR(50) COMMENT 'حالة الإقرار/البلاغ (مسودة، قيد المراجعة، معتمد، مرفوض، تحت التعديل)',
  `submittedAt` DATE COMMENT 'تاريخ الرفع للمكتب',
  `reviewedByUserId` BIGINT COMMENT 'معرف المراجع من المكتب (FK → SystemUser.userId)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewNotes` TEXT COMMENT 'ملاحظات المراجع',
  `officeDecision` VARCHAR(200) COMMENT 'قرار المكتب (قبول الإقرار، قبول البلاغ مع الخطة، رفض البلاغ، طلب تعديل)',
  `decisionDate` DATE COMMENT 'تاريخ القرار',
  `decisionNotes` TEXT COMMENT 'ملاحظات القرار (تبرير الرفض أو التعليقات)',
  `attachmentPath` VARCHAR(200) COMMENT 'مسار ملف المستند الداعم (قرار إداري، تعميم من الدفاع المدني، الخ)',
  `linkedCalendarId` BIGINT COMMENT 'معرف الحدث في التقويم المدرسي المرتبط (FK → SchoolCalendar.eventId) - إن وجد',
  `linkedPlanId` BIGINT COMMENT 'معرف الخطة المرتبطة (FK → ApprovedPlan.planId) - إن وجد',
  `complianceStatus` VARCHAR(50) COMMENT 'حالة الامتثال (ملتزم، منحرف، قيد المعالجة) - للإقرارات الدورية',
  `complianceDueDate` DATE COMMENT 'تاريخ استحقاق الالتزام (للإقرارات الدورية)',
  `complianceSubmittedAt` DATE COMMENT 'تاريخ تقديم الالتزام (إن وجد)',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم المنشئ (عادة مدير المدرسة)',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف من حذف',
  PRIMARY KEY (`deviationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`linkedCalendarId`) REFERENCES `SchoolCalendar`(`...`),
  -- FOREIGN KEY (`linkedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='الالتزامات والانحرافات';

-- Table: AcademicException (طلبات الاستثناءات الأكاديمية)
CREATE TABLE IF NOT EXISTS `AcademicException` (
  `exceptionId` BIGINT NOT NULL COMMENT 'معرف طلب الاستثناء (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `requestType` VARCHAR(50) COMMENT 'نوع الطلب (منهج خاص، تقديم اختبارات، تأخير اختبارات، توقيت دوام، إعفاء من مادة، تعديل لائحة)',
  `studentId` BIGINT COMMENT 'معرف الطالب المستفيد (FK → Student.studentId) - إن كان الطلب فردياً',
  `affectedGroup` VARCHAR(200) COMMENT 'المجموعة المتأثرة (فصل، مرحلة، مدرسة كاملة) - للطلبات الجماعية',
  `justification` VARCHAR(200) COMMENT 'مبررات طلب الاستثناء',
  `supportingDocuments` VARCHAR(200) COMMENT 'مسار الوثائق الداعمة للطلب (JSON)',
  `requestedStartDate` DATE COMMENT 'تاريخ بدء الاستثناء المطلوب',
  `requestedEndDate` DATE COMMENT 'تاريخ انتهاء الاستثناء المطلوب',
  `expectedImpact` VARCHAR(200) COMMENT 'الأثر المتوقع للاستثناء',
  `alternativePlan` VARCHAR(200) COMMENT 'الخطة البديلة (إن وجدت)',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (مسودة، قيد دراسة المدرسة، قيد دراسة المكتب، مقبول، مرفوض، منتهي)',
  `submittedAt` DATE COMMENT 'تاريخ الرفع للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من رفع الطلب (عادة مدير المدرسة)',
  `officeDecision` VARCHAR(200) COMMENT 'قرار المكتب (مقبول، مرفوض، طلب تعديل)',
  `decisionNotes` TEXT COMMENT 'تبرير المكتب للقرار',
  `decisionReference` VARCHAR(200) COMMENT 'رقم القرار المرجعي الصادر من المكتب',
  `decisionDate` DATE COMMENT 'تاريخ إصدار القرار',
  `approvedByUserId` BIGINT COMMENT 'معرف الموافق من المكتب (FK → SystemUser.userId)',
  `expirationDate` DATE COMMENT 'تاريخ انتهاء الاستثناء (للطلبات المؤقتة) - يتم إيقاف الاستثناء آلياً عند هذا التاريخ',
  `isRenewable` BOOLEAN COMMENT 'هل يمكن تجديد الاستثناء؟',
  `renewalCount` INT COMMENT 'عدد مرات التجديد',
  `parentExceptionId` BIGINT COMMENT 'معرف طلب الاستثناء السابق (للتجديد)',
  `linkToWorkflowId` BIGINT COMMENT 'معرف مسار الاعتماد (FK → Workflow.workflowId) - اختياري',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المنشئ',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`exceptionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SubmittedByUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`parentExceptionId`) REFERENCES `ParentException`(`...`),
  -- FOREIGN KEY (`linkToWorkflowId`) REFERENCES `Workflow`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='طلبات الاستثناءات الأكاديمية';

-- Table: LeadershipNomination (ترشيحات القيادة)
CREATE TABLE IF NOT EXISTS `LeadershipNomination` (
  `nominationId` BIGINT NOT NULL COMMENT 'معرف الترشيح (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة المستهدفة (FK → School.schoolId) - لا بد أن يكون موجوداً حتى لو كان المرشح من جهة أخرى',
  `officeId` BIGINT COMMENT 'معرف مكتب التربية المشرف (FK → Office.officeId)',
  `candidateEmployeeId` BIGINT COMMENT 'معرف الموظف المرشح (FK → Employee.employeeId) - يجب أن يكون موظفاً مسجلاً في النظام',
  `candidateName` DATE COMMENT 'الاسم الرباعي للمرشح (كحقل نسخ احتياطي)',
  `targetPosition` VARCHAR(200) COMMENT 'المنصب المستهدف (مدير، وكيل، مساعد)',
  `nominationType` VARCHAR(50) COMMENT 'نوع الترشيح (داخلي - من مدرسة، خارجي - من خارج النظام)',
  `nominationSource` VARCHAR(200) COMMENT 'مصدر الترشيح (مدير المدرسة، مكتب التربية، ترقية داخلية)',
  `nominationDate` DATE COMMENT 'تاريخ تقديم الترشيح',
  `nominationDocumentPath` VARCHAR(200) COMMENT 'مسار ملف الترشيح (إن وجد)',
  `cvAttachment` VARCHAR(200) COMMENT 'مسار ملف السيرة الذاتية للمرشح',
  `coverLetter` VARCHAR(200) COMMENT 'خطاب الترشيح (نص أو مسار ملف)',
  `qualifications` VARCHAR(200) COMMENT 'مؤهلات المرشح التي تبرز في ملفه (JSON) - لسرعة العرض',
  `experienceSummary` VARCHAR(200) COMMENT 'ملخص الخبرات ذات الصلة',
  `finalShortlist` VARCHAR(200) COMMENT 'هل المرشح ضمن القائمة النهائية؟',
  `interviewDate` DATE COMMENT 'تاريخ المقابلة (المرحلة الأولى أو النهائية)',
  `interviewTime` TIME COMMENT 'وقت المقابلة',
  `interviewLocation` VARCHAR(200) COMMENT 'مكان المقابلة',
  `interviewPanel` VARCHAR(200) COMMENT 'لجنة المقابلة (JSON) - أسماء وأدوار أعضاء اللجنة',
  `interviewScore` DECIMAL(5,2) COMMENT 'نتيجة المقابلة (رقمية أو مئوية)',
  `interviewFeedback` DECIMAL(15,2) COMMENT 'ملاحظات المقابلة',
  `interviewDecision` VARCHAR(200) COMMENT 'قرار المقابلة (مستبعد، مرشح احتياطي، مرشح نهائي)',
  `placementTestRequired` VARCHAR(200) COMMENT 'هل يتطلب اختبار تحديد مستوى؟',
  `placementTestDate` DATE COMMENT 'تاريخ الاختبار',
  `placementTestScore` DECIMAL(5,2) COMMENT 'نتيجة الاختبار',
  `evaluationSummary` VARCHAR(200) COMMENT 'ملخص التقييم النهائي (مرشح)',
  `finalDecision` VARCHAR(200) COMMENT 'القرار النهائي للترشيح (تحت الدراسة، مقبول للتعيين، مرفوض)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (في حال الرفض)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الترشيح النهائي (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `linkedAssignmentId` BIGINT COMMENT 'معرف قرار التعيين المرتبط (FK → LeadershipAssignment.assignmentId) - بعد التحويل',
  `status` VARCHAR(50) COMMENT 'حالة الترشيح (تحت الدراسة، مرشح احتياطي، مقبول، مرفوض)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف من أنشأ الترشيح (عادة مدير المدرسة أو مسؤول المكتب)',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`nominationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`officeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`candidateEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`linkedAssignmentId`) REFERENCES `LeadershipAssignment`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='ترشيحات القيادة';

-- Table: LeadershipAssignment (قرارات التعيين والربط)
CREATE TABLE IF NOT EXISTS `LeadershipAssignment` (
  `assignmentId` BIGINT NOT NULL COMMENT 'معرف قرار التعيين (المفتاح الرئيسي)',
  `nomineeId` BIGINT COMMENT 'معرف الترشيح (FK → LeadershipNomination.nominationId) - كل قرار يأتي من ترشيح سابق',
  `employeeId` BIGINT COMMENT 'معرف الموظف المعين (FK → Employee.employeeId) - غالباً نفس المرشح من جدول الترشيح',
  `schoolId` BIGINT COMMENT 'معرف المدرسة التي تم التعيين فيها (FK → School.schoolId)',
  `officeId` BIGINT COMMENT 'معرف المكتب الذي أصدر القرار (FK → Office.officeId)',
  `decisionNumber` INT COMMENT 'رقم القرار الرسمي (فريد)',
  `decisionDate` DATE COMMENT 'تاريخ صدور القرار',
  `decisionDocumentPath` VARCHAR(200) COMMENT 'مسار ملف القرار الممسوح ضوئياً',
  `position` VARCHAR(200) COMMENT 'المسمى الوظيفي الفعلي (مدير، وكيل الشؤون التعليمية، وكيل الشؤون المالية، مساعد)',
  `positionLevel` VARCHAR(50) COMMENT 'مستوى المنصب (قيادي أول، قادي ثاني)',
  `startDate` DATE COMMENT 'تاريخ المباشرة الفعلي في المنصب',
  `endDate` DATE COMMENT 'تاريخ النقل أو التقاعد المتوقع (إن وجد)',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي (عند ترك المنصب)',
  `isActive` BOOLEAN COMMENT 'هل المنصب لا يزال نشطاً (المدير الحالي - True)؟',
  `assignmentNature` VARCHAR(200) COMMENT 'طبيعة التعيين (ترقية، ندب، تكليف، نقل)',
  `handoverStatus` VARCHAR(50) COMMENT 'حالة تسليم العهدة (معلق، مكتمل)',
  `handoverDate` DATE COMMENT 'تاريخ إتمام تسليم العهدة',
  `handoverDocumentPath` VARCHAR(200) COMMENT 'مسار ملف محضر تسليم العهدة',
  `salaryGrade` DECIMAL(15,2) COMMENT 'الدرجة المالية للمنصب الجديد (إن تغيرت)',
  `allowance` VARCHAR(200) COMMENT 'البدلات الإضافية للمنصب (JSON)',
  `notes` TEXT COMMENT 'ملاحظات (مثل أسباب النقل أو التقاعد)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف من أنشأ القرار (عادة إدارة المكتب)',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`assignmentId`),
  -- FOREIGN KEY (`nomineeId`) REFERENCES `LeadershipNomination`(`...`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`officeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='قرارات التعيين والربط';

-- Table: OrganizationalStructure (الهياكل التنظيمية)
CREATE TABLE IF NOT EXISTS `OrganizationalStructure` (
  `structureId` BIGINT NOT NULL COMMENT 'معرف الهيكل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `officeId` BIGINT COMMENT 'معرف مكتب التربية (FK → Office.officeId) - للمواعفة',
  `structureName` VARCHAR(200) COMMENT 'اسم الهيكل التنظيمي (مثل الهيكل التنظيمي لثانوية الأندلس)',
  `versionNumber` INT COMMENT 'رقم الإصدار (V1.0، V2.1)',
  `versionDate` DATE COMMENT 'تاريخ إصدار هذا الإصدار',
  `description` TEXT COMMENT 'وصف الهيكل (التغييرات الرئيسية عن الإصدار السابق)',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد (مسودة، معتمد من المكتب)',
  `approvalDate` DATE COMMENT 'تاريخ موافقة مكتب التربية',
  `approvalDocumentPath` VARCHAR(200) COMMENT 'مسار ملف خطاب الاعتماد',
  `structureFile` VARCHAR(200) COMMENT 'مسار صورة أو ملف الهيكل (PDF/صورة)',
  `effectiveDate` DATE COMMENT 'اليوم الفعلي الذي يبدأ فيه العمل بهذا الهيكل',
  `isActive` BOOLEAN COMMENT 'هل هذا الهيكل هو الفعال حالياً (True/False) - هيكل نشط واحد فقط لكل مدرسة',
  `createdByUserId` BIGINT COMMENT 'معرف من قام بتصميم أو رفع هذا الهيكل (FK → SystemUser.userId)',
  `previousVersionId` BIGINT COMMENT 'معرف الهيكل السابق (للربط المتسلسل)',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`structureId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`officeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`previousVersionId`) REFERENCES `PreviousVersion`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الهياكل التنظيمية';

-- Table: SchoolDepartment (الأقسام الإدارية)
CREATE TABLE IF NOT EXISTS `SchoolDepartment` (
  `deptId` BIGINT NOT NULL COMMENT 'معرف القسم (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `structureId` BIGINT COMMENT 'معرف الهيكل التنظيمي الذي يتبعه القسم (FK → OrganizationalStructure.structureId)',
  `deptCode` VARCHAR(50) COMMENT 'كود القسم (فريد داخل المدرسة)',
  `deptName` VARCHAR(200) COMMENT 'اسم القسم (مثل "شؤون المعلمين")',
  `deptNameEn` VARCHAR(200) COMMENT 'اسم القسم بالإنجليزية',
  `deptType` VARCHAR(50) COMMENT 'نوع القسم (أكاديمي، إداري، مالي، فني)',
  `parentDeptId` BIGINT COMMENT 'معرف القسم الأعلى (للهيكل الشجري) (FK → SchoolDepartment.deptId)',
  `managerId` BIGINT COMMENT 'معرف مدير القسم (FK → Employee.employeeId)',
  `actingManagerId` BIGINT COMMENT 'معرف القائم بأعمال المدير (إن وجد)',
  `maxCapacity` VARCHAR(200) COMMENT 'الحد الأقصى لعدد الموظفين في القسم',
  `currentEmployeeCount` INT COMMENT 'عدد الموظفين الحاليين (يُحسب آلياً)',
  `budgetCode` VARCHAR(50) COMMENT 'رمز الميزانية المرتبط بالقسم (للمصروفات)',
  `location` VARCHAR(200) COMMENT 'موقع القسم (مبنى، طابق)',
  `phone` VARCHAR(20) COMMENT 'هاتف القسم',
  `email` VARCHAR(100) COMMENT 'بريد القسم الإلكتروني',
  `status` VARCHAR(50) COMMENT 'حالة القسم (نشط، مدمج، ملغي)',
  `mergedIntoDeptId` BIGINT COMMENT 'معرف القسم المدمج إليه (إذا كان status = ''مدمج'')',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المنشئ',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`deptId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`structureId`) REFERENCES `OrganizationalStructure`(`...`),
  -- FOREIGN KEY (`parentDeptId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`managerId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`actingManagerId`) REFERENCES `ActingManager`(`...`),
  -- FOREIGN KEY (`mergedIntoDeptId`) REFERENCES `MergedIntoDept`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأقسام الإدارية';

-- Table: OrganizationalPermission (مصفوفة الصلاحيات التنظيمية)
CREATE TABLE IF NOT EXISTS `OrganizationalPermission` (
  `permissionId` BIGINT NOT NULL COMMENT 'معرف الصلاحية (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `departmentId` BIGINT COMMENT 'معرف القسم المسؤول عن هذه الصلاحية (FK → SchoolDepartment.deptId)',
  `positionTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي المرتبط بالصلاحية',
  `systemModule` VARCHAR(200) COMMENT 'وحدة النظام المعنية (شؤون الطلاب، شؤون الموظفين، الرواتب، الدرجات، التقارير، إدارة النظام...)',
  `accessLevel` VARCHAR(50) COMMENT 'مستوى الوصول (عرض، تعديل، اعتماد، رفع تقرير، تصدير)',
  `canSign` VARCHAR(200) COMMENT 'هل يملك حق التوقيع الرقمي (نعم/لا)',
  `financialLimit` VARCHAR(200) COMMENT 'الحد المالي للتوقيع (للصلاحيات المالية)',
  `roleId` BIGINT COMMENT 'معرف الدور البرمجي المرتبط (FK → Role.roleId من القسم السابع) - للتكامل مع نظام الصلاحيات التقني',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة حالياً؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المنشئ',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`permissionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مصفوفة الصلاحيات التنظيمية';

-- Table: SchoolDecision (القرارات الإدارية المدرسية)
CREATE TABLE IF NOT EXISTS `SchoolDecision` (
  `decisionId` BIGINT NOT NULL COMMENT 'معرف القرار (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `decisionNumber` INT COMMENT 'رقم القرار (فريد داخل المدرسة لكل سنة)',
  `decisionDate` DATE COMMENT 'تاريخ القرار (تاريخ الصدور الرسمي)',
  `decisionType` VARCHAR(50) COMMENT 'نوع القرار (تكليف، إعفاء، لفت نظر، تنظيم داخلي، تشكيل لجنة، تعديل هيكل)',
  `subject` VARCHAR(200) COMMENT 'عنوان القرار المختصر',
  `decisionText` VARCHAR(200) COMMENT 'ملخص القرار (النص الكامل أو ملخصه)',
  `effectiveDate` DATE COMMENT 'تاريخ بدء النفاذ (متى يبدأ تطبيق القرار فعلياً)',
  `expiryDate` DATE COMMENT 'تاريخ الانتهاء (للقرارات المؤقتة) - لإلغاء الصلاحية آلياً',
  `pdfAttachment` VARCHAR(200) COMMENT 'مسار الملف الموقّع والمختوم',
  `status` VARCHAR(50) COMMENT 'حالة القرار (مسودة، ساري، ملغى، منتهي)',
  `targetEmployees` VARCHAR(200) COMMENT 'الموظفون المستهدفون بالقرار (JSON) - قائمة بمعرفات الموظفين',
  `issuedByUserId` BIGINT COMMENT 'معرف من أصدر القرار (FK → SystemUser.userId) - عادة مدير المدرسة',
  `approvedByOfficeId` BIGINT COMMENT 'معرف المكتب الذي صادق على القرار (إن لزم) (FK → Office.officeId)',
  `linkedWorkflowId` BIGINT COMMENT 'معرف مسار الاعتماد (FK → Workflow.workflowId) - إذا كان القرار يحتاج إلى مراحل موافقة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `createdByUserId` BIGINT COMMENT 'معرف من قام بإدخال القرار في النظام',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`decisionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`issuedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByOfficeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`linkedWorkflowId`) REFERENCES `Workflow`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='القرارات الإدارية المدرسية';

-- Table: OrganizationalManual (الدليل التنظيمي)
CREATE TABLE IF NOT EXISTS `OrganizationalManual` (
  `manualId` BIGINT NOT NULL COMMENT 'معرف الدليل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `manualVersion` VARCHAR(200) COMMENT 'إصدار الدليل (مثلاً v3.0)',
  `lastUpdated` DATE COMMENT 'تاريخ آخر مراجعة للدليل (تاريخ آخر تحديث)',
  `filePath` VARCHAR(200) COMMENT 'مسار تخزين الدليل التشغيلي (ملف PDF)',
  `fileName` VARCHAR(200) COMMENT 'اسم الملف',
  `approvalRef` VARCHAR(200) COMMENT 'رقم خطاب اعتماد المكتب للدليل',
  `approvedByOfficeId` BIGINT COMMENT 'معرف المكتب الذي اعتمد الدليل (FK → Office.officeId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `requiresAcknowledgment` VARCHAR(200) COMMENT 'يتطلب إقراراً من الموظفين (نعم/لا) - لإظهار نافذة منبثقة للموظفين الجدد',
  `status` VARCHAR(50) COMMENT 'حالة النشر (مسودة، منشور، مؤرشف)',
  `publishedAt` DATE COMMENT 'تاريخ النشر',
  `publishedByUserId` BIGINT COMMENT 'معرف من نشر الدليل (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `createdByUserId` BIGINT COMMENT 'معرف المنشئ',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`manualId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`approvedByOfficeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`publishedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الدليل التنظيمي';

-- Table: Workflow (مسارات العمل)
CREATE TABLE IF NOT EXISTS `Workflow` (
  `workflowId` BIGINT NOT NULL COMMENT 'معرف مسار العمل (المفتاح الرئيسي)',
  `workflowName` VARCHAR(200) COMMENT 'اسم مسار العمل (مثل "مسار اعتماد الاستثناءات الأكاديمية")',
  `description` TEXT COMMENT 'وصف المسار والإجراءات',
  `entityName` VARCHAR(200) COMMENT 'اسم الكيان المرتبط (اسم الجدول في النظام مثل "AcademicException", "LeadershipNomination")',
  `totalSteps` VARCHAR(200) COMMENT 'إجمالي الخطوات (يُحدّث آلياً بناءً على WorkflowStep)',
  `isActive` BOOLEAN COMMENT 'مسار نشط؟',
  `isDefault` BOOLEAN COMMENT 'هل هو المسار الافتراضي لهذا الكيان؟',
  `createdByUserId` BIGINT COMMENT 'معرف من أنشأ المسار',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`workflowId`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مسارات العمل';

-- Table: WorkflowStep (خطوات مسار العمل)
CREATE TABLE IF NOT EXISTS `WorkflowStep` (
  `stepId` BIGINT NOT NULL COMMENT 'معرف الخطوة (المفتاح الرئيسي)',
  `workflowId` BIGINT COMMENT 'معرف مسار العمل (FK → Workflow.workflowId)',
  `stepOrder` VARCHAR(200) COMMENT 'ترتيب الخطوة (1، 2، 3... لضمان تسلسل الاعتمادات)',
  `stepNameAr` VARCHAR(200) COMMENT 'اسم الخطوة بالعربية',
  `stepNameEn` VARCHAR(200) COMMENT 'اسم الخطوة بالإنجليزية',
  `assignedToPosition` VARCHAR(200) COMMENT 'المنصب المسؤول عن هذه الخطوة (مثل "مدير المدرسة"، "رئيس قسم الإشراف")',
  `assignedToRoleId` BIGINT COMMENT 'معرف الدور البرمجي المسؤول (FK → Role.roleId) - لربطها بمستخدم معين في النظام',
  `slaHours` VARCHAR(200) COMMENT 'المدة الزمنية المحددة لإنجاز هذه الخطوة (بالساعات) - لتصعيد الطلب عند التأخير',
  `actionType` VARCHAR(50) COMMENT 'نوع الإجراء (اعتماد فقط، اعتماد مع ملاحظات، توقيع رقمي، مطالبة بتعديل)',
  `isFinalStep` BOOLEAN COMMENT 'هل هذه الخطوة الأخيرة؟',
  `escalationStepId` BIGINT COMMENT 'معرف الخطوة التي يتم التصعيد إليها إذا تجاوزت المدة (للتصعيد التلقائي)',
  `isActive` BOOLEAN COMMENT 'هل هذه الخطوة نشطة؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المنشئ',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر من عدل',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`stepId`),
  -- FOREIGN KEY (`workflowId`) REFERENCES `Workflow`(`...`),
  -- FOREIGN KEY (`assignedToRoleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`escalationStepId`) REFERENCES `EscalationStep`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='خطوات مسار العمل';

-- Table: AnnualPlanDraft (مسودات الخطط السنوية)
CREATE TABLE IF NOT EXISTS `AnnualPlanDraft` (
  `draftId` BIGINT NOT NULL COMMENT 'معرف المسودة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `draftNumber` INT COMMENT 'رقم المسودة (تسلسلي لكل عام دراسي)',
  `draftVersion` VARCHAR(200) COMMENT 'إصدار المسودة (V1.0, V1.1, V2.0...)',
  `titleAr` VARCHAR(200) COMMENT 'عنوان الخطة بالعربية',
  `titleEn` VARCHAR(200) COMMENT 'عنوان الخطة بالإنجليزية',
  `draftStatus` VARCHAR(50) COMMENT 'حالة المسودة (تحت الإعداد، مراجعة داخلية، جاهز للرفع، ملغاة)',
  `completionPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز في إعداد المسودة (تحسب آلياً بناءً على تعبئة الحقول الإلزامية)',
  `lastSavedAt` DATE COMMENT 'تاريخ آخر حفظ للمسودة',
  `lastSavedByUserId` BIGINT COMMENT 'معرف آخر مستخدم قام بحفظ المسودة',
  `goalsActivitiesJson` VARCHAR(200) COMMENT 'الأهداف والأنشطة (JSON) - تحتوي على مصفوفة الأهداف، المؤشرات، الأنشطة، الموارد، المسؤولين، والتواريخ الزمنية',
  `strategicGoals` DECIMAL(5,2) COMMENT 'الأهداف الاستراتيجية للخطة (JSON)',
  `operationalGoals` VARCHAR(200) COMMENT 'الأهداف التشغيلية (JSON)',
  `kpis` VARCHAR(200) COMMENT 'مؤشرات الأداء الرئيسية (JSON)',
  `requiredResources` VARCHAR(200) COMMENT 'الموارد المطلوبة (ميزانية، تجهيزات، كادر)',
  `risksAndChallenges` VARCHAR(200) COMMENT 'المخاطر والتحديات المتوقعة (JSON)',
  `successCriteria` VARCHAR(200) COMMENT 'معايير النجاح',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - مستندات داعمة، دراسات، تحليلات',
  `internalReviewDate` DATE COMMENT 'تاريخ المراجعة الداخلية',
  `internalReviewByUserId` BIGINT COMMENT 'معرف من قام بالمراجعة الداخلية',
  `internalReviewNotes` TEXT COMMENT 'ملاحظات المراجعة الداخلية',
  `internalReviewStatus` VARCHAR(50) COMMENT 'حالة المراجعة الداخلية (مقبولة، تحتاج تعديل، مرفوضة)',
  `isReadyForSubmission` BOOLEAN COMMENT 'هل المسودة جاهزة للرفع؟',
  `submittedToPlanId` BIGINT COMMENT 'معرف الخطة المرفوعة المرتبطة (بعد التحويل)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`draftId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`lastSavedByUserId`) REFERENCES `LastSavedByUser`(`...`),
  -- FOREIGN KEY (`internalReviewByUserId`) REFERENCES `InternalReviewByUser`(`...`),
  -- FOREIGN KEY (`submittedToPlanId`) REFERENCES `SubmittedToPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مسودات الخطط السنوية';

-- Table: SubmittedPlan (الخطط المرفوعة للمراجعة)
CREATE TABLE IF NOT EXISTS `SubmittedPlan` (
  `planId` BIGINT NOT NULL COMMENT 'معرف الخطة المرفوعة (المفتاح الرئيسي)',
  `draftId` BIGINT COMMENT 'معرف المسودة الأصلية (FK → AnnualPlanDraft.draftId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `submissionNumber` INT COMMENT 'رقم الرفع (تسلسلي سنوي)',
  `submissionTimestamp` DATE COMMENT 'تاريخ ووقت الرفع',
  `directorSignature` VARCHAR(200) COMMENT 'التوقيع الإلكتروني لمدير المدرسة (قيمة مشفرة أو مسار ملف)',
  `signatureDate` DATE COMMENT 'تاريخ التوقيع',
  `signatureMethod` VARCHAR(200) COMMENT 'طريقة التوقيع (رقمي، يدوي ممسوح)',
  `planFilePath` VARCHAR(200) COMMENT 'مسار ملف الخطة الشاملة (PDF) - الملف المرفوع',
  `planFileName` VARCHAR(200) COMMENT 'اسم الملف',
  `planFileSize` VARCHAR(200) COMMENT 'حجم الملف',
  `planHash` VARCHAR(200) COMMENT 'قيمة تجزئة الملف (للتحقق من سلامته)',
  `assignedReviewerId` BIGINT COMMENT 'معرف المشرف المراجع في المكتب (FK → SystemUser.userId)',
  `priority` VARCHAR(200) COMMENT 'الأولوية (عادية، عاجلة، شديدة الأهمية)',
  `priorityReason` VARCHAR(200) COMMENT 'سبب تحديد الأولوية',
  `submissionType` VARCHAR(50) COMMENT 'نوع الرفع (أولي، معدل، نهائي)',
  `isResubmission` BOOLEAN COMMENT 'هل هي إعادة رفع؟',
  `previousSubmissionId` BIGINT COMMENT 'معرف الرفع السابق (إن كان إعادة)',
  `resubmissionReason` VARCHAR(200) COMMENT 'سبب إعادة الرفع',
  `status` VARCHAR(50) COMMENT 'حالة الخطة المرفوعة (قيد المراجعة، مقبولة، مرفوضة، تحتاج تعديل، ملغاة)',
  `reviewStartDate` DATE COMMENT 'تاريخ بدء المراجعة',
  `reviewEndDate` DATE COMMENT 'تاريخ انتهاء المراجعة',
  `reviewerNotes` TEXT COMMENT 'ملاحظات المراجع (من المكتب)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `rejectionDetails` VARCHAR(200) COMMENT 'تفاصيل الرفض',
  `requiredModifications` VARCHAR(200) COMMENT 'التعديلات المطلوبة (JSON)',
  `modificationDeadline` VARCHAR(200) COMMENT 'مهلة التعديل',
  `resubmissionDate` DATE COMMENT 'تاريخ إعادة الرفع (إن وجد)',
  `resubmissionFilePath` VARCHAR(200) COMMENT 'مسار ملف الخطة المعدلة',
  `approvedPlanId` BIGINT COMMENT 'معرف الخطة المعتمدة المرتبطة (بعد القبول)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`planId`),
  -- FOREIGN KEY (`draftId`) REFERENCES `AnnualPlanDraft`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`assignedReviewerId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`previousSubmissionId`) REFERENCES `PreviousSubmission`(`...`),
  -- FOREIGN KEY (`approvedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الخطط المرفوعة للمراجعة';

-- Table: ApprovedPlan (الخطط المعتمدة)
CREATE TABLE IF NOT EXISTS `ApprovedPlan` (
  `approvedPlanId` BIGINT NOT NULL COMMENT 'معرف الخطة المعتمدة (المفتاح الرئيسي)',
  `submittedPlanId` BIGINT COMMENT 'معرف الخطة المرفوعة (FK → SubmittedPlan.planId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `approvalReferenceNumber` INT COMMENT 'رقم الاعتماد الرسمي الصادر من المكتب',
  `approvalReferenceDate` DATE COMMENT 'تاريخ الاعتماد الرسمي',
  `approvalReferenceDocument` VARCHAR(200) COMMENT 'مسار ملف خطاب الاعتماد',
  `approvalRefNo` VARCHAR(200) COMMENT 'مرجع الاعتماد (رقم مختصر للاستخدام السريع)',
  `effectiveDate` DATE COMMENT 'تاريخ بدء العمل الفعلي بالخطة (تاريخ السريان)',
  `effectiveDateHijri` DATE COMMENT 'تاريخ السريان (هجري)',
  `expiryDate` DATE COMMENT 'تاريخ انتهاء صلاحية الخطة (نهاية العام الدراسي عادة)',
  `planStatus` VARCHAR(50) COMMENT 'حالة الخطة (سارية، منتهية، ملغاة، معلقة)',
  `approvalNotes` TEXT COMMENT 'ملاحظات المكتب (من قسم التخطيط)',
  `approvalDetails` VARCHAR(200) COMMENT 'تفاصيل الاعتماد (من وقع، أي لجنة)',
  `approvedByOfficeId` BIGINT COMMENT 'معرف المكتب المصدر للاعتماد (FK → Office.officeId)',
  `finalPlanFilePath` VARCHAR(200) COMMENT 'مسار ملف الخطة النهائية المختومة (PDF)',
  `finalPlanFileName` VARCHAR(200) COMMENT 'اسم الملف',
  `finalPlanHash` VARCHAR(200) COMMENT 'قيمة تجزئة الملف',
  `signedPlanPath` VARCHAR(200) COMMENT 'مسار ملف الخطة المختوم بالتوقيعات الرقمية',
  `hasDigitalSignature` BOOLEAN COMMENT 'هل تحتوي على توقيعات رقمية؟',
  `digitalSignatureDetails` VARCHAR(200) COMMENT 'تفاصيل التوقيعات الرقمية (JSON)',
  `isActive` BOOLEAN COMMENT 'هل الخطة هي الخطة النشطة حالياً للمدرسة؟',
  `replacedByPlanId` BIGINT COMMENT 'معرف الخطة التي حلت محلها (في حال التعديل الجوهري)',
  `suspensionReason` VARCHAR(200) COMMENT 'سبب تعليق الخطة (إن وجد)',
  `suspendedAt` DATE COMMENT 'تاريخ التعليق',
  `suspendedByUserId` BIGINT COMMENT 'معرف من علق الخطة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`approvedPlanId`),
  -- FOREIGN KEY (`submittedPlanId`) REFERENCES `SubmittedPlan`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`approvedByOfficeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`replacedByPlanId`) REFERENCES `ReplacedByPlan`(`...`),
  -- FOREIGN KEY (`suspendedByUserId`) REFERENCES `SuspendedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الخطط المعتمدة';

-- Table: PlanAmendment (تعديلات الخطط)
CREATE TABLE IF NOT EXISTS `PlanAmendment` (
  `amendmentId` BIGINT NOT NULL COMMENT 'معرف التعديل (المفتاح الرئيسي)',
  `approvedPlanId` BIGINT COMMENT 'معرف الخطة المعتمدة (FK → ApprovedPlan.approvedPlanId)',
  `amendmentType` VARCHAR(50) COMMENT 'نوع التعديل (طارئ، ضروري، تحديث موارد، تعديل أهداف، تعديل أنشطة، تعديل ميزانية)',
  `amendmentNumber` INT COMMENT 'رقم التعديل (تسلسلي لكل خطة)',
  `amendmentTitle` VARCHAR(200) COMMENT 'عنوان التعديل',
  `amendmentDescription` TEXT COMMENT 'وصف التعديلات بالتفصيل',
  `changesDescription` TEXT COMMENT 'تفاصيل ما تم تغييره في الخطة (JSON) - يمكن أن يحتوي على (القيمة قبل، القيمة بعد، سبب التغيير)',
  `affectedSections` VARCHAR(200) COMMENT 'الأقسام أو الأنشطة المتأثرة (JSON)',
  `impactAnalysis` VARCHAR(200) COMMENT 'تحليل أثر التعديل على الخطة',
  `impactLevel` VARCHAR(50) COMMENT 'مستوى التأثير (بسيط، متوسط، جسيم)',
  `estimatedCostChange` DECIMAL(15,2) COMMENT 'التغيير في التكلفة التقديرية (إن وجد)',
  `estimatedTimelineChange` TIME COMMENT 'التغيير في الجدول الزمني',
  `requestedByUserId` BIGINT COMMENT 'معرف مقدم طلب التعديل (FK → SystemUser.userId)',
  `requestDate` DATE COMMENT 'تاريخ تقديم طلب التعديل',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الموافقة (طلب جديد، قيد المراجعة، مقبول، مرفوض، قيد التنفيذ، منفذ)',
  `approvedByUserId` BIGINT COMMENT 'معرف من وافق على التعديل (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الموافقة',
  `approvalNotes` TEXT COMMENT 'ملاحظات الموافقة',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `implementationDate` DATE COMMENT 'تاريخ تنفيذ التعديل',
  `implementedByUserId` BIGINT COMMENT 'معرف من نفذ التعديل',
  `implementationNotes` TEXT COMMENT 'ملاحظات التنفيذ',
  `linkedToRequestId` BIGINT COMMENT 'معرف طلب التعديل المرتبط (FK → AmendmentRequest.requestId)',
  `isPermanent` BOOLEAN COMMENT 'تعديل دائم أم مؤقت؟',
  `effectiveFrom` DATE COMMENT 'تاريخ سريان التعديل',
  `effectiveUntil` DATE COMMENT 'تاريخ انتهاء سريان التعديل (للتعديلات المؤقتة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`amendmentId`),
  -- FOREIGN KEY (`approvedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`requestedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`implementedByUserId`) REFERENCES `ImplementedByUser`(`...`),
  -- FOREIGN KEY (`linkedToRequestId`) REFERENCES `AmendmentRequest`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تعديلات الخطط';

-- Table: AmendmentRequest (طلبات تعديل الخطة)
CREATE TABLE IF NOT EXISTS `AmendmentRequest` (
  `requestId` BIGINT NOT NULL COMMENT 'معرف طلب التعديل (المفتاح الرئيسي)',
  `approvedPlanId` BIGINT COMMENT 'معرف الخطة المعتمدة (FK → ApprovedPlan.approvedPlanId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestNumber` INT COMMENT 'رقم الطلب (تسلسلي سنوي)',
  `requestDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `requestTitle` VARCHAR(200) COMMENT 'عنوان طلب التعديل',
  `requestDescription` TEXT COMMENT 'وصف الطلب بالتفصيل',
  `reasonForRequest` VARCHAR(200) COMMENT 'تبرير الحاجة للتغيير للمكتب (نص مفصل)',
  `proposedChanges` VARCHAR(200) COMMENT 'التغييرات المقترحة (JSON)',
  `affectedActivities` VARCHAR(200) COMMENT 'الأنشطة المتأثرة بالتعديل',
  `expectedImpact` VARCHAR(200) COMMENT 'الأثر المتوقع للتعديل',
  `supportingDocs` VARCHAR(200) COMMENT 'مرفقات داعمة (JSON) - صور، تقارير، دراسات، خطابات',
  `supportingDocsDescription` TEXT COMMENT 'وصف المرفقات',
  `priority` VARCHAR(200) COMMENT 'أولوية الطلب (عادي، مهم، عاجل)',
  `submittedByUserId` BIGINT COMMENT 'معرف مقدم الطلب (FK → SystemUser.userId)',
  `submittedByRole` VARCHAR(200) COMMENT 'دور مقدم الطلب (مدير مدرسة، رئيس تخطيط)',
  `assignedToOfficeId` BIGINT COMMENT 'معرف المكتب المرسل إليه الطلب (FK → Office.officeId)',
  `assignedToReviewerId` BIGINT COMMENT 'معرف المراجع المختص في المكتب (FK → SystemUser.userId)',
  `reviewStartDate` DATE COMMENT 'تاريخ بدء المراجعة',
  `reviewEndDate` DATE COMMENT 'تاريخ انتهاء المراجعة',
  `reviewNotes` TEXT COMMENT 'ملاحظات المراجعة',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (قيد المراجعة، مقبول، مرفوض، ملغي، قيد التنفيذ)',
  `approvalDecision` VARCHAR(200) COMMENT 'قرار المكتب (مقبول، مرفوض، طلب تعديل)',
  `decisionDate` DATE COMMENT 'تاريخ القرار',
  `decisionReferenceNumber` INT COMMENT 'رقم قرار المكتب',
  `decisionNotes` TEXT COMMENT 'تبرير القرار',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `requiredModifications` VARCHAR(200) COMMENT 'التعديلات المطلوبة على الطلب قبل القبول',
  `resubmissionDeadline` VARCHAR(200) COMMENT 'مهلة إعادة التقديم',
  `resubmittedAt` DATE COMMENT 'تاريخ إعادة التقديم (إن وجد)',
  `resubmittedFile` VARCHAR(200) COMMENT 'مسار ملف الطلب المعدل',
  `linkedToAmendmentId` BIGINT COMMENT 'معرف التعديل المرتبط (بعد الموافقة) (FK → PlanAmendment.amendmentId)',
  `closedAt` DATE COMMENT 'تاريخ إغلاق الطلب',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق الطلب',
  `closingNotes` TEXT COMMENT 'ملاحظات الإغلاق',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`requestId`),
  -- FOREIGN KEY (`approvedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`assignedToOfficeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`assignedToReviewerId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`linkedToAmendmentId`) REFERENCES `PlanAmendment`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `ClosedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='طلبات تعديل الخطة';

-- Table: ProgressReport (تقارير المتابعة الدورية)
CREATE TABLE IF NOT EXISTS `ProgressReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `approvedPlanId` BIGINT COMMENT 'معرف الخطة المعتمدة (FK → ApprovedPlan.approvedPlanId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportingPeriod` VARCHAR(200) COMMENT 'الفترة الزمنية (ربع أول، ربع ثاني، نصف سنوي، ثلاثة أرباع، سنوي)',
  `periodSequence` VARCHAR(200) COMMENT 'ترتيب الفترة (1، 2، 3، 4)',
  `startDate` DATE COMMENT 'تاريخ بداية الفترة',
  `endDate` DATE COMMENT 'تاريخ نهاية الفترة',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي حسب الفترة)',
  `reportDate` DATE COMMENT 'تاريخ إصدار التقرير',
  `completionRate` DECIMAL(5,2) COMMENT 'نسبة الإنجاز الكلية (يحسب آلياً)',
  `plannedActivitiesCount` INT COMMENT 'عدد الأنشطة المخططة',
  `completedActivitiesCount` INT COMMENT 'عدد الأنشطة المنفذة',
  `partiallyCompletedCount` INT COMMENT 'عدد الأنشطة المنفذة جزئياً',
  `notStartedCount` INT COMMENT 'عدد الأنشطة التي لم تبدأ',
  `cancelledActivitiesCount` INT COMMENT 'عدد الأنشطة الملغاة',
  `activitiesProgress` VARCHAR(200) COMMENT 'تفاصيل تقدم الأنشطة (JSON)',
  `kpiProgress` VARCHAR(200) COMMENT 'تقدم مؤشرات الأداء (JSON)',
  `budgetConsumed` VARCHAR(200) COMMENT 'الميزانية المنصرفة',
  `budgetPercentage` DECIMAL(5,2) COMMENT 'نسبة صرف الميزانية',
  `achievements` VARCHAR(200) COMMENT 'الإنجازات المحققة خلال الفترة (نص)',
  `challenges` VARCHAR(200) COMMENT 'التحديات والصعوبات التي واجهت التنفيذ',
  `correctiveActions` VARCHAR(200) COMMENT 'الإجراءات التصحيحية المتخذة أو المقترحة',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات للفترة القادمة',
  `deviationNotes` TEXT COMMENT 'ملاحظات عن انحرافات عن الخطة',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - مستندات داعمة، صور، تقارير إضافية',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير المرفوع (PDF)',
  `reportFileName` VARCHAR(200) COMMENT 'اسم الملف',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام برفع التقرير (FK → SystemUser.userId)',
  `submissionDate` DATE COMMENT 'تاريخ الرفع',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير (إلكتروني)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، قيد المراجعة، مقبول، مرفوض، يحتاج تعديل)',
  `reviewedByUserId` BIGINT COMMENT 'معرف المراجع من المكتب (FK → SystemUser.userId)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewerNotes` TEXT COMMENT 'ملاحظات المراجع',
  `reviewerRecommendations` VARCHAR(200) COMMENT 'توصيات المراجع',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `requiredModifications` VARCHAR(200) COMMENT 'التعديلات المطلوبة',
  `resubmissionDate` DATE COMMENT 'تاريخ إعادة الرفع (إن وجد)',
  `isFinal` BOOLEAN COMMENT 'هل هو التقرير النهائي للفترة؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`approvedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير المتابعة الدورية';

-- Table: FinalEvaluation (التقييمات النهائية للخطط)
CREATE TABLE IF NOT EXISTS `FinalEvaluation` (
  `evaluationId` BIGINT NOT NULL COMMENT 'معرف التقييم (المفتاح الرئيسي)',
  `approvedPlanId` BIGINT COMMENT 'معرف الخطة المعتمدة (FK → ApprovedPlan.approvedPlanId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `evaluationDate` DATE COMMENT 'تاريخ التقييم',
  `evaluationPeriod` VARCHAR(200) COMMENT 'فترة التقييم (نهاية العام، نصف العام، برنامج خاص)',
  `goalsAnalysis` VARCHAR(200) COMMENT 'تحليل الأهداف (مقارنة المخطط بالمحقق فعلياً) (JSON)',
  `goalsAchievementRate` DECIMAL(5,2) COMMENT 'نسبة تحقيق الأهداف الكلية',
  `activitiesCompletionRate` DECIMAL(5,2) COMMENT 'نسبة إنجاز الأنشطة',
  `kpiAchievementRate` DECIMAL(5,2) COMMENT 'نسبة تحقيق مؤشرات الأداء',
  `budgetAnalysis` VARCHAR(200) COMMENT 'تحليل الميزانية (المخطط، المنصرف، الانحراف)',
  `resourceEfficiency` VARCHAR(200) COMMENT 'كفاءة الموارد (تقييم صرف الميزانية مقابل الإنجاز)',
  `resourceEfficiencyScore` DECIMAL(5,2) COMMENT 'درجة كفاءة الموارد (1-10)',
  `humanResourcesEfficiency` VARCHAR(200) COMMENT 'كفاءة الكادر البشري',
  `timelineAdherence` TIME COMMENT 'الالتزام بالجدول الزمني',
  `deviationsSummary` VARCHAR(200) COMMENT 'ملخص الانحرافات (إيجابية/سلبية)',
  `positiveDeviations` VARCHAR(200) COMMENT 'الانحرافات الإيجابية (تجاوز الأهداف)',
  `negativeDeviations` VARCHAR(200) COMMENT 'الانحرافات السلبية (تقصير في الأهداف)',
  `deviationReasons` VARCHAR(200) COMMENT 'أسباب الانحرافات الرئيسية',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة (لاستخدامها في خطة العام القادم)',
  `bestPractices` VARCHAR(200) COMMENT 'أفضل الممارسات التي تم اكتشافها',
  `challengesEncountered` INT COMMENT 'التحديات الرئيسية التي واجهت الخطة',
  `recommendationsForNextYear` VARCHAR(200) COMMENT 'التوصيات للسنة القادمة (نص - يمكن نقله تلقائياً لمسودة العام القادم)',
  `finalScore` DECIMAL(5,2) COMMENT 'الدرجة النهائية للخطة (من 100)',
  `rating` VARCHAR(200) COMMENT 'التصنيف (ممتاز، جيد جداً، جيد، مقبول، ضعيف)',
  `evaluationTeam` VARCHAR(200) COMMENT 'فريق التقييم (JSON) - أسماء وأدوار',
  `evaluationNotes` TEXT COMMENT 'ملاحظات عامة على التقييم',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - تقارير مفصلة، تحليلات',
  `evaluationReportPath` VARCHAR(200) COMMENT 'مسار ملف تقرير التقييم النهائي (PDF)',
  `evaluationReportName` VARCHAR(200) COMMENT 'اسم الملف',
  `approvedByOfficeId` BIGINT COMMENT 'معرف المكتب المعتمد للتقييم (FK → Office.officeId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد (قيد المراجعة، معتمد، مرفوض)',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `isPublished` BOOLEAN COMMENT 'هل تم نشر التقييم؟',
  `publishedAt` DATE COMMENT 'تاريخ النشر',
  `exportedToNextYearPlan` VARCHAR(200) COMMENT 'هل تم تصدير التوصيات للسنة القادمة؟',
  `nextYearPlanDraftId` BIGINT COMMENT 'معرف مسودة خطة العام القادم المرتبطة (إن وجد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`evaluationId`),
  -- FOREIGN KEY (`approvedPlanId`) REFERENCES `ApprovedPlan`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`approvedByOfficeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`nextYearPlanDraftId`) REFERENCES `NextYearPlanDraft`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التقييمات النهائية للخطط';

-- Table: HistoricalRecords (السجلات التاريخية)
CREATE TABLE IF NOT EXISTS `HistoricalRecords` (
  `recordId` BIGINT NOT NULL COMMENT 'معرف السجل التاريخي (المفتاح الرئيسي)',
  `tableName` VARCHAR(200) COMMENT 'اسم الجدول الذي تم التعديل عليه (مثل ''Student'', ''Employee'', ''School'')',
  `entityId` BIGINT COMMENT 'معرف السجل المتأثر في الجدول الأصلي',
  `operationType` VARCHAR(50) COMMENT 'نوع العملية (إضافة، تعديل، حذف، استرجاع، تصدير، استيراد)',
  `oldValue` VARCHAR(200) COMMENT 'البيانات قبل التعديل (JSON) - لحفظ القيم القديمة',
  `newValue` VARCHAR(200) COMMENT 'البيانات بعد التعديل (JSON) - لحفظ القيم الجديدة',
  `fieldName` VARCHAR(200) COMMENT 'اسم الحقل الذي تم تعديله (في حالة التعديل على حقل واحد)',
  `oldFieldValue` VARCHAR(200) COMMENT 'القيمة القديمة للحقل (للتعديلات البسيطة)',
  `newFieldValue` VARCHAR(200) COMMENT 'القيمة الجديدة للحقل',
  `changeReason` VARCHAR(200) COMMENT 'سبب التعديل (إن وجد) - قد يكون "تصحيح خطأ إدخال"، "تحديث بيانات"، "نقل طالب"',
  `changeReasonCategory` VARCHAR(50) COMMENT 'فئة سبب التغيير (تصحيح، تحديث، إداري، قانوني، طارئ)',
  `userId` BIGINT COMMENT 'معرف المستخدم الذي قام بالعملية (FK → SystemUser.userId)',
  `userRole` VARCHAR(200) COMMENT 'دور المستخدم عند تنفيذ العملية',
  `userName` VARCHAR(200) COMMENT 'اسم المستخدم (كحفظ احتياطي)',
  `operationDate` DATE COMMENT 'تاريخ ووقت العملية',
  `ipAddress` VARCHAR(200) COMMENT 'عنوان IP الخاص بالجهاز الذي تمت منه العملية',
  `deviceInfo` VARCHAR(200) COMMENT 'معلومات الجهاز (نظام التشغيل، المتصفح، نوع الجهاز) (JSON)',
  `location` VARCHAR(200) COMMENT 'الموقع التقريبي (مدينة، منطقة) - بناءً على IP',
  `sessionId` BIGINT COMMENT 'معرف جلسة المستخدم',
  `affectedRowsCount` INT COMMENT 'عدد السجلات المتأثرة (للعمليات الجماعية)',
  `isReversible` BOOLEAN COMMENT 'هل العملية قابلة للاسترجاع؟',
  `reversalRecordId` BIGINT COMMENT 'معرف السجل الذي يمثل عملية الاسترجاع (إن وجد)',
  `reversedAt` DATE COMMENT 'تاريخ الاسترجاع (إن وجد)',
  `reversedByUserId` BIGINT COMMENT 'معرف من قام بالاسترجاع (FK → SystemUser.userId)',
  `digitalSignature` VARCHAR(200) COMMENT 'التوقيع الرقمي للعملية (لأغراض قانونية)',
  `riskScore` DECIMAL(5,2) COMMENT 'درجة المخاطرة للعملية (1-100) - تحسب بناءً على حساسية البيانات ونوع العملية',
  `isHighRisk` BOOLEAN COMMENT 'هل العملية عالية الخطورة؟',
  `reviewedByAudit` VARCHAR(200) COMMENT 'هل تمت مراجعة هذا السجل من قبل جهة التدقيق؟',
  `auditReviewDate` DATE COMMENT 'تاريخ مراجعة التدقيق',
  `auditReviewNotes` TEXT COMMENT 'ملاحظات التدقيق',
  `retentionPeriodYears` VARCHAR(200) COMMENT 'مدة الاحتفاظ بالسجل (بالسنوات)',
  `expiresAt` DATE COMMENT 'تاريخ انتهاء صلاحية الاحتفاظ بالسجل',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (نظام آلي عادة)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي (نادراً ما يحذف من هذا الجدول)',
  PRIMARY KEY (`recordId`),
  -- FOREIGN KEY (`entityId`) REFERENCES `Entity`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`sessionId`) REFERENCES `Session`(`...`),
  -- FOREIGN KEY (`reversalRecordId`) REFERENCES `ReversalRecord`(`...`),
  -- FOREIGN KEY (`reversedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`)
) COMMENT='السجلات التاريخية';

-- Table: ReceivedCirculars (التعاميم المستلمة)
CREATE TABLE IF NOT EXISTS `ReceivedCirculars` (
  `circularId` BIGINT NOT NULL COMMENT 'معرف التعميم (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة المستلمة (FK → School.schoolId)',
  `officeId` BIGINT COMMENT 'معرف المكتب المصدر (FK → Office.officeId)',
  `circularNumber` INT COMMENT 'رقم التعميم الصادر من المكتب (فريد نسبياً حسب المكتب)',
  `circularNumberFull` INT COMMENT 'الرقم الكامل للتعميم (مثلاً: 123/ت/2025)',
  `circularDate` DATE COMMENT 'تاريخ صدور التعميم من المكتب (هجري)',
  `circularDateGregorian` DATE COMMENT 'تاريخ الصدور بالميلادي',
  `subject` VARCHAR(200) COMMENT 'عنوان التعميم',
  `subjectNormalized` VARCHAR(200) COMMENT 'العنوان للتطبيع والبحث',
  `summary` VARCHAR(200) COMMENT 'ملخص التعميم (نص مختصر)',
  `content` VARCHAR(200) COMMENT 'نص التعميم الكامل (إن وجد نصياً)',
  `priorityLevel` VARCHAR(50) COMMENT 'درجة الأهمية (عادي، هام، هام جداً، سري، عاجل جداً)',
  `priorityColor` VARCHAR(200) COMMENT 'لون الأولوية للتمييز (أخضر، أصفر، برتقالي، أحمر)',
  `requiresReply` VARCHAR(200) COMMENT 'هل يتطلب رداً من المدرسة؟',
  `replyDeadline` VARCHAR(200) COMMENT 'الموعد النهائي للرد (إن وجد)',
  `requiresAction` VARCHAR(200) COMMENT 'هل يتطلب إجراءً ملموساً؟',
  `actionDeadline` VARCHAR(200) COMMENT 'الموعد النهائي للإجراء',
  `relatedToEntity` VARCHAR(200) COMMENT 'مرتبط بكيان (طلاب، موظفين، مالية، أصول، بناء، أمن)',
  `relatedEntityId` BIGINT COMMENT 'معرف الكيان المرتبط (إن وجد)',
  `isConfidential` BOOLEAN COMMENT 'تعميم سري؟',
  `isUrgent` BOOLEAN COMMENT 'تعميم عاجل؟',
  `receivedAt` DATE COMMENT 'تاريخ ووقت استلام التعميم في المدرسة',
  `receivedByUserId` BIGINT COMMENT 'معرف موظف الاستلام (FK → SystemUser.userId)',
  `receivedMethod` VARCHAR(200) COMMENT 'طريقة الاستلام (بريد إلكتروني، ورقي، بوابة، مندوب)',
  `receivedReference` VARCHAR(200) COMMENT 'رقم مرجعي داخلي للاستلام',
  `documentType` VARCHAR(50) COMMENT 'نوع المستند (PDF، Word، صورة، ورقى)',
  `documentPath` VARCHAR(200) COMMENT 'مسار نسخة PDF من التعميم (للحفظ الرقمي)',
  `documentName` VARCHAR(200) COMMENT 'اسم الملف الأصلي',
  `documentSize` VARCHAR(200) COMMENT 'حجم الملف (بايت)',
  `documentHash` VARCHAR(200) COMMENT 'قيمة تجزئة الملف (للتحقق من السلامة)',
  `physicalLocation` VARCHAR(200) COMMENT 'موقع الحفظ الورقي (إن وجد)',
  `status` VARCHAR(50) COMMENT 'حالة الاستلام (جديد، مستلم، مقروء، قيد التنفيذ، منفذ، مغلق)',
  `statusHistory` DATE COMMENT 'تاريخ الحالات (JSON)',
  `acknowledgedById` BIGINT COMMENT 'معرف من اطلع على التعميم (FK → SystemUser.userId)',
  `acknowledgedAt` DATE COMMENT 'تاريخ الاطلاع',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف من حذف',
  PRIMARY KEY (`circularId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`officeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`relatedEntityId`) REFERENCES `RelatedEntity`(`...`),
  -- FOREIGN KEY (`receivedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`acknowledgedById`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='التعاميم المستلمة';

-- Table: CircularsDocumentation (توثيق التعاميم في السجل)
CREATE TABLE IF NOT EXISTS `CircularsDocumentation` (
  `documentationId` BIGINT NOT NULL COMMENT 'معرف التوثيق (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId) - علاقة 1:1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار للربط السريع)',
  `registrationNumber` INT COMMENT 'رقم القيد الداخلي في سجلات المدرسة (يولد تسلسلياً)',
  `registrationDate` DATE COMMENT 'تاريخ القيد في سجل المدرسة (هجري)',
  `registrationDateGregorian` DATE COMMENT 'تاريخ القيد بالميلادي',
  `registeredByUserId` BIGINT COMMENT 'معرف الموظف الذي قام بالقيد (FK → SystemUser.userId)',
  `registeredAt` VARCHAR(200) COMMENT 'وقت القيد',
  `documentCategory` VARCHAR(50) COMMENT 'تصنيف الوثيقة (تعليمي، إداري، مالي، تنظيمي، أمني)',
  `subCategory` VARCHAR(50) COMMENT 'التصنيف الفرعي',
  `keywords` VARCHAR(200) COMMENT 'الكلمات المفتاحية (JSON) - لسهولة البحث',
  `physicalArchiveBox` VARCHAR(200) COMMENT 'رقم الصندوق أو المجلد في الأرشيف الورقي',
  `physicalArchiveShelf` VARCHAR(200) COMMENT 'رقم الرف',
  `physicalArchivePage` VARCHAR(200) COMMENT 'رقم الصفحة (إن وجد)',
  `physicalArchiveNotes` TEXT COMMENT 'ملاحظات عن الحفظ الفيزيائي',
  `digitalCopyPath` VARCHAR(200) COMMENT 'مسار النسخة الرقمية في أرشيف المدرسة (قد يختلف عن documentPath)',
  `digitalBackupPath` VARCHAR(200) COMMENT 'مسار النسخة الاحتياطية',
  `hasDigitalSignature` BOOLEAN COMMENT 'هل يحتوي على توقيع رقمي؟',
  `digitalSignatureVerified` VARCHAR(200) COMMENT 'هل تم التحقق من التوقيع؟',
  `retentionPeriodYears` VARCHAR(200) COMMENT 'مدة الاحتفاظ بالسنوات (حسب نظام أرشيف المدرسة)',
  `retentionEndDate` DATE COMMENT 'تاريخ انتهاء مدة الاحتفاظ',
  `disposalDate` DATE COMMENT 'تاريخ الإتلاف المتوقع',
  `disposalStatus` VARCHAR(50) COMMENT 'حالة الإتلاف (لم يتقرر، محدد، منفذ)',
  `disposalMethod` VARCHAR(200) COMMENT 'طريقة الإتلاف (تمزيق، حرق، حذف رقمي)',
  `disposalAuthorizedByUserId` BIGINT COMMENT 'معرف من أذن بالإتلاف',
  `disposalNotes` TEXT COMMENT 'ملاحظات الإتلاف',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`documentationId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`registeredByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`disposalAuthorizedByUserId`) REFERENCES `DisposalAuthorizedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='توثيق التعاميم في السجل';

-- Table: CircularsInternalDistribution (التوزيع الداخلي للتعاميم)
CREATE TABLE IF NOT EXISTS `CircularsInternalDistribution` (
  `distributionId` BIGINT NOT NULL COMMENT 'معرف التوزيع (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار)',
  `distributionType` VARCHAR(50) COMMENT 'نوع التوزيع (لجميع الأقسام، لقسم محدد، لموظف محدد)',
  `departmentId` BIGINT COMMENT 'معرف القسم المستلم (FK → SchoolDepartment.deptId) - إن كان التوزيع لقسم',
  `employeeId` BIGINT COMMENT 'معرف الموظف المستلم (FK → Employee.employeeId) - إن كان التوزيع لموظف محدد',
  `accessType` VARCHAR(50) COMMENT 'نوع الوصول (للعلم فقط، للتنفيذ، للرد، للمراجعة)',
  `isRequiredToAct` BOOLEAN COMMENT 'هل المستلم ملزم بتنفيذ إجراءات التعميم؟',
  `isRequiredToReply` BOOLEAN COMMENT 'هل المستلم ملزم بالرد على التعميم؟',
  `distributionNotes` TEXT COMMENT 'ملاحظات مدير المدرسة أو رئيس القسم على التعميم قبل التوزيع',
  `distributionTime` TIME COMMENT 'وقت التوزيع',
  `distributedByUserId` BIGINT COMMENT 'معرف من قام بالتوزيع (FK → SystemUser.userId)',
  `isAcknowledged` BOOLEAN COMMENT 'هل تم تأكيد الاستلام؟',
  `acknowledgedAt` VARCHAR(200) COMMENT 'وقت تأكيد الاستلام',
  `acknowledgedByUserId` BIGINT COMMENT 'معرف من أكد الاستلام (FK → SystemUser.userId)',
  `acknowledgedMethod` VARCHAR(200) COMMENT 'طريقة التأكيد (ضغط زر، توقيع إلكتروني، يدوي)',
  `acknowledgmentNotes` TEXT COMMENT 'ملاحظات المستلم عند الاستلام',
  `readAt` VARCHAR(200) COMMENT 'وقت القراءة الفعلية',
  `readDuration` VARCHAR(200) COMMENT 'المدة المستغرقة في القراءة (بالدقائق)',
  `hasQuestions` BOOLEAN COMMENT 'هل لدى المستلم استفسارات؟',
  `questionsText` VARCHAR(200) COMMENT 'نص الاستفسارات',
  `questionsRepliedAt` VARCHAR(200) COMMENT 'وقت الرد على الاستفسارات',
  `questionsRepliedByUserId` BIGINT COMMENT 'معرف من رد على الاستفسارات',
  `isForwarded` BOOLEAN COMMENT 'هل تم إعادة توجيه التعميم لشخص آخر؟',
  `forwardedToEmployeeId` BIGINT COMMENT 'معرف من تمت إعادة التوجيه إليه',
  `forwardingReason` VARCHAR(200) COMMENT 'سبب إعادة التوجيه',
  `forwardingDate` DATE COMMENT 'تاريخ إعادة التوجيه',
  `status` VARCHAR(50) COMMENT 'حالة التوزيع (معلق، مقروء، منفذ، ملغي)',
  `reminderSentCount` INT COMMENT 'عدد مرات إرسال التذكير',
  `lastReminderSentAt` VARCHAR(200) COMMENT 'وقت آخر تذكير',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`distributionId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`distributedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`acknowledgedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`questionsRepliedByUserId`) REFERENCES `QuestionsRepliedByUser`(`...`),
  -- FOREIGN KEY (`forwardedToEmployeeId`) REFERENCES `ForwardedToEmployee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التوزيع الداخلي للتعاميم';

-- Table: CircularsImplementationStatus (حالة تنفيذ التعميم)
CREATE TABLE IF NOT EXISTS `CircularsImplementationStatus` (
  `implementationId` BIGINT NOT NULL COMMENT 'معرف حالة التنفيذ (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId) - علاقة 1:1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار)',
  `currentStage` VARCHAR(200) COMMENT 'المرحلة الحالية (تخطيط، تنفيذ فعلي، متابعة، تقييم، إغلاق)',
  `stageStartDate` DATE COMMENT 'تاريخ بدء المرحلة الحالية',
  `progressRate` DECIMAL(5,2) COMMENT 'نسبة الإنجاز (من 0% إلى 100%)',
  `previousProgressRate` DECIMAL(5,2) COMMENT 'نسبة الإنجاز السابقة (لتتبع التطور)',
  `lastProgressUpdate` DATE COMMENT 'تاريخ آخر تحديث للنسبة',
  `responsibleEmployeeId` BIGINT COMMENT 'معرف الموظف المسؤول عن تنفيذ التعميم (FK → Employee.employeeId)',
  `responsibleDepartmentId` BIGINT COMMENT 'معرف القسم المسؤول عن التنفيذ (FK → SchoolDepartment.deptId)',
  `executionStartDate` DATE COMMENT 'تاريخ بدء التنفيذ الفعلي',
  `expectedCompletionDate` DATE COMMENT 'التاريخ المتوقع للانتهاء (من التعميم أو التقدير)',
  `actualCompletionDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `statusNotes` VARCHAR(50) COMMENT 'ملاحظات عن التنفيذ',
  `challenges` VARCHAR(200) COMMENT 'الصعوبات التي واجهت التنفيذ (JSON)',
  `challengesDetails` VARCHAR(200) COMMENT 'نص وصفي للصعوبات',
  `actionsTaken` VARCHAR(200) COMMENT 'الإجراءات التي تم اتخاذها (JSON)',
  `actionsTakenDetails` VARCHAR(200) COMMENT 'نص وصفي للإجراءات',
  `pendingActions` VARCHAR(200) COMMENT 'الإجراءات المتبقية (JSON)',
  `pendingActionsDetails` VARCHAR(200) COMMENT 'نص وصفي للإجراءات المتبقية',
  `resourcesNeeded` VARCHAR(200) COMMENT 'الموارد المطلوبة لإتمام التنفيذ (JSON)',
  `isOnTrack` BOOLEAN COMMENT 'هل التنفيذ يسير كما هو مخطط؟',
  `deviationReason` VARCHAR(200) COMMENT 'سبب الانحراف عن الخطة (إن وجد)',
  `delayDays` VARCHAR(200) COMMENT 'عدد أيام التأخير (تحسب آلياً)',
  `isCompleted` BOOLEAN COMMENT 'هل اكتمل التنفيذ؟',
  `completionPercentage` DECIMAL(5,2) COMMENT 'نسبة الإكمال (مرادف لـ progressRate)',
  `completionNotes` TEXT COMMENT 'ملاحظات عند الإكمال',
  `verifiedByUserId` BIGINT COMMENT 'معرف من تحقق من صحة التنفيذ (FK → SystemUser.userId)',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `reportedToOffice` VARCHAR(200) COMMENT 'هل تم إبلاغ المكتب بالتنفيذ؟',
  `reportedToOfficeAt` VARCHAR(200) COMMENT 'وقت الإبلاغ',
  `status` VARCHAR(50) COMMENT 'حالة التنفيذ الإجمالية (قيد التنفيذ، مكتمل، متعثر، معلق)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`implementationId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`responsibleEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`responsibleDepartmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حالة تنفيذ التعميم';

-- Table: CircularsImplementationReports (إفادات تنفيذ التعاميم)
CREATE TABLE IF NOT EXISTS `CircularsImplementationReports` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف الإفادة (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار)',
  `reportNumber` INT COMMENT 'رقم الإفادة (تسلسلي حسب التعميم)',
  `reportDate` DATE COMMENT 'تاريخ إعداد الإفادة',
  `reportType` VARCHAR(50) COMMENT 'نوع الإفادة (أولية، مرحلية، نهائية، معدلة)',
  `version` VARCHAR(200) COMMENT 'إصدار الإفادة (1.0، 1.1، 2.0)',
  `submissionDate` DATE COMMENT 'تاريخ رفع الإفادة للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من رفع الإفادة (FK → SystemUser.userId)',
  `submissionMethod` VARCHAR(200) COMMENT 'طريقة الرفع (بوابة إلكترونية، بريد، مندوب)',
  `submissionReference` VARCHAR(200) COMMENT 'رقم مرجعي للرفع',
  `resultsSummary` VARCHAR(200) COMMENT 'ملخص ما تم إنجازه (نص مفصل)',
  `achievements` VARCHAR(200) COMMENT 'الإنجازات المحققة (JSON)',
  `challenges` VARCHAR(200) COMMENT 'الصعوبات التي واجهت التنفيذ (للإفادة فقط)',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات (إن وجدت)',
  `evidencePath` VARCHAR(200) COMMENT 'مسار ملفات الإثبات (JSON) - صور، مستندات، تقارير',
  `evidenceTypes` VARCHAR(50) COMMENT 'أنواع المرفقات (صور، فيديو، تقارير، توقيعات)',
  `evidenceDescription` TEXT COMMENT 'وصف المرفقات',
  `directorSignature` VARCHAR(200) COMMENT 'التوقيع الإلكتروني للمدير (حقل نص أو مسار)',
  `signatureDate` DATE COMMENT 'تاريخ التوقيع',
  `signatureMethod` VARCHAR(200) COMMENT 'طريقة التوقيع',
  `officeDecision` VARCHAR(200) COMMENT 'قرار المكتب (قيد المراجعة، مقبول، مرفوض، طلب تعديل)',
  `officeDecisionDate` DATE COMMENT 'تاريخ قرار المكتب',
  `officeDecisionByUserId` BIGINT COMMENT 'معرف من أصدر القرار (FK → SystemUser.userId)',
  `decisionNotes` TEXT COMMENT 'ملاحظات المكتب على الإفادة',
  `modificationRequired` VARCHAR(200) COMMENT 'هل طلب المكتب تعديلاً؟',
  `modificationNotes` TEXT COMMENT 'ملاحظات التعديل المطلوب',
  `resubmissionDate` DATE COMMENT 'تاريخ إعادة الرفع بعد التعديل (إن وجد)',
  `finalApprovalDate` DATE COMMENT 'تاريخ الاعتماد النهائي',
  `finalApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد نهائياً',
  `status` VARCHAR(50) COMMENT 'حالة الإفادة (مسودة، مرفوعة، قيد المراجعة، مقبولة، مرفوضة، مطلوب تعديل)',
  `isFinal` BOOLEAN COMMENT 'هل هي الإفادة النهائية لهذا التعميم؟',
  `relatedReportId` BIGINT COMMENT 'معرف الإفادة السابقة (للتعديلات)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`officeDecisionByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`finalApprovedByUserId`) REFERENCES `FinalApprovedByUser`(`...`),
  -- FOREIGN KEY (`relatedReportId`) REFERENCES `RelatedReport`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إفادات تنفيذ التعاميم';

-- Table: ArchivedCirculars (الأرشيف الرقمي للتعاميم)
CREATE TABLE IF NOT EXISTS `ArchivedCirculars` (
  `archiveId` BIGINT NOT NULL COMMENT 'معرف الأرشيف (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId) - علاقة 1:1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار)',
  `archiveCategory` VARCHAR(50) COMMENT 'تصنيف الأرشيف (تعليمي، إداري، مالي، تنظيمي، أمني)',
  `archiveSubCategory` VARCHAR(50) COMMENT 'التصنيف الفرعي',
  `archiveDate` DATE COMMENT 'تاريخ الأرشفة (تاريخ نقل التعميم للأرشيف)',
  `archivedByUserId` BIGINT COMMENT 'معرف من قام بالأرشفة (FK → SystemUser.userId)',
  `archivedAt` VARCHAR(200) COMMENT 'وقت الأرشفة',
  `archiveReason` VARCHAR(200) COMMENT 'سبب الأرشفة (انتهاء التعميم، إكمال التنفيذ، انتهاء المدة)',
  `closureDate` DATE COMMENT 'تاريخ إغلاق التعميم النهائي',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق التعميم (FK → SystemUser.userId)',
  `closureNotes` TEXT COMMENT 'ملاحظات الإغلاق',
  `retentionPeriodYears` VARCHAR(200) COMMENT 'مدة الاحتفاظ بالسنوات (حسب نظام أرشيف المدرسة أو اللوائح)',
  `retentionPeriodStart` DATE COMMENT 'تاريخ بدء مدة الاحتفاظ (عادة تاريخ الأرشفة)',
  `retentionPeriodEnd` DATE COMMENT 'تاريخ انتهاء مدة الاحتفاظ (تحسب آلياً)',
  `retentionReason` VARCHAR(200) COMMENT 'سبب تحديد مدة الاحتفاظ (قانوني، نظامي، اختياري)',
  `disposalAllowed` VARCHAR(200) COMMENT 'هل يسمح بالإتلاف بعد انتهاء المدة؟',
  `disposalDateScheduled` DATE COMMENT 'التاريخ المقرر للإتلاف',
  `disposalActualDate` DATE COMMENT 'تاريخ الإتلاف الفعلي',
  `disposalMethod` VARCHAR(200) COMMENT 'طريقة الإتلاف (تمزيق، حرق، حذف رقمي)',
  `disposalAuthorizedByUserId` BIGINT COMMENT 'معرف من أذن بالإتلاف (FK → SystemUser.userId)',
  `disposalNotes` TEXT COMMENT 'ملاحظات الإتلاف',
  `isDestroyed` BOOLEAN COMMENT 'هل تم إتلاف التعميم؟',
  `destroyedAt` DATE COMMENT 'تاريخ الإتلاف',
  `restoredFromArchive` VARCHAR(200) COMMENT 'هل تم استرجاع التعميم من الأرشيف؟',
  `restoredAt` DATE COMMENT 'تاريخ الاسترجاع',
  `restoredByUserId` BIGINT COMMENT 'معرف من استرجع التعميم',
  `restoreReason` VARCHAR(200) COMMENT 'سبب الاسترجاع',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`archiveId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`archivedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`disposalAuthorizedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`restoredByUserId`) REFERENCES `RestoredByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأرشيف الرقمي للتعاميم';

-- Table: CircularsDeadlinesTracking (متابعة المهل الزمنية للتعاميم)
CREATE TABLE IF NOT EXISTS `CircularsDeadlinesTracking` (
  `deadlineId` BIGINT NOT NULL COMMENT 'معرف المتابعة (المفتاح الرئيسي)',
  `circularId` BIGINT COMMENT 'معرف التعميم (FK → ReceivedCirculars.circularId) - علاقة 1:1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) (للتكرار)',
  `deadlineType` VARCHAR(50) COMMENT 'نوع المهلة (للرد، للتنفيذ، للتوزيع، للرفع)',
  `deadlineDate` DATE COMMENT 'تاريخ انتهاء المهلة (المحدد من المكتب أو المدرسة)',
  `originalDeadline` DATE COMMENT 'التاريخ الأصلي للمهلة (إن تم تعديلها)',
  `extensionCount` INT COMMENT 'عدد مرات تمديد المهلة',
  `extensionReason` VARCHAR(200) COMMENT 'سبب التمديد (إن وجد)',
  `extensionApprovedBy` VARCHAR(200) COMMENT 'من اعتمد التمديد (From SystemUser)',
  `extensionApprovedAt` DATE COMMENT 'تاريخ اعتماد التمديد',
  `daysRemaining` VARCHAR(200) COMMENT 'عدد الأيام المتبقية (تحسب آلياً)',
  `alertLevel` VARCHAR(50) COMMENT 'مستوى التنبيه (أزرق، أخضر، أصفر، برتقالي، أحمر)',
  `alertLevelReason` VARCHAR(50) COMMENT 'سبب تحديد هذا المستوى',
  `lastAlertSentAt` VARCHAR(200) COMMENT 'وقت آخر تنبيه تم إرساله',
  `alertSentCount` INT COMMENT 'عدد مرات إرسال التنبيه',
  `alertRecipients` VARCHAR(200) COMMENT 'المستلمون للتنبيه (JSON) - معرفات الموظفين',
  `isResponded` BOOLEAN COMMENT 'هل تم اتخاذ إجراء بعد التنبيه؟',
  `responseDate` DATE COMMENT 'تاريخ الاستجابة',
  `responseType` VARCHAR(50) COMMENT 'نوع الاستجابة (تم التنفيذ، تم الرد، طلب تمديد، معلق)',
  `responseDetails` VARCHAR(200) COMMENT 'تفاصيل الاستجابة',
  `responseByUserId` BIGINT COMMENT 'معرف من استجاب (FK → SystemUser.userId)',
  `isOverdue` BOOLEAN COMMENT 'هل انتهت المهلة ولم يتم الرد؟',
  `overdueDays` VARCHAR(200) COMMENT 'عدد أيام التأخير (تحسب آلياً)',
  `overdueAction` VARCHAR(200) COMMENT 'الإجراء المتخذ بسبب التأخير (إنذار، تصعيد، إلزام)',
  `overdueActionDate` DATE COMMENT 'تاريخ الإجراء',
  `escalationLevel` VARCHAR(50) COMMENT 'مستوى التصعيد (داخلي، للمكتب)',
  `escalatedAt` DATE COMMENT 'تاريخ التصعيد',
  `escalatedToUserId` BIGINT COMMENT 'معرف من تم التصعيد إليه (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`deadlineId`),
  -- FOREIGN KEY (`circularId`) REFERENCES `ReceivedCirculars`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`responseByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`escalatedToUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='متابعة المهل الزمنية للتعاميم';

-- Table: ParentMeeting (اجتماع أولياء الأمور)
CREATE TABLE IF NOT EXISTS `ParentMeeting` (
  `meetingId` BIGINT NOT NULL COMMENT 'معرف الاجتماع (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `meetingType` VARCHAR(50) COMMENT 'نوع الاجتماع (عام، فردي، لجنة آباء، استشارة، تقييم أداء، مشكلة سلوكية)',
  `meetingNumber` INT COMMENT 'رقم الاجتماع (تسلسلي حسب النوع)',
  `title` VARCHAR(200) COMMENT 'عنوان الاجتماع',
  `objectives` VARCHAR(200) COMMENT 'أهداف الاجتماع',
  `agenda` VARCHAR(200) COMMENT 'جدول الأعمال (JSON)',
  `organizerId` BIGINT COMMENT 'معرف المنظم (FK → Employee.employeeId)',
  `organizerRole` VARCHAR(200) COMMENT 'دور المنظم (مدير، مرشد، معلم)',
  `meetingDate` DATE COMMENT 'تاريخ الاجتماع',
  `startTime` TIME COMMENT 'وقت البداية',
  `endTime` TIME COMMENT 'وقت النهاية المتوقع',
  `actualEndTime` TIME COMMENT 'وقت النهاية الفعلي',
  `duration` VARCHAR(200) COMMENT 'المدة (بالدقائق)',
  `location` VARCHAR(200) COMMENT 'مكان الاجتماع (مكتب المدير، قاعة الاجتماعات، افتراضي)',
  `locationType` VARCHAR(50) COMMENT 'نوع المكان (داخلي، خارجي، افتراضي)',
  `virtualMeetingLink` VARCHAR(200) COMMENT 'رابط الاجتماع الافتراضي (إن وجد)',
  `studentId` BIGINT COMMENT 'معرف الطالب المعني (FK → Student.studentId) - في الاجتماعات الفردية',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId) - في الاجتماعات الجماعية لصف معين',
  `classSectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId) - في الاجتماعات الجماعية لشعبة معينة',
  `targetGuardians` VARCHAR(200) COMMENT 'أولياء الأمور المستهدفون (JSON) - في الاجتماعات العامة',
  `invitedGuardiansCount` INT COMMENT 'عدد أولياء الأمور المدعوين',
  `confirmedGuardiansCount` INT COMMENT 'عدد المؤكدين حضورهم',
  `actualAttendeesCount` INT COMMENT 'عدد الحضور الفعلي',
  `attendees` VARCHAR(200) COMMENT 'قائمة الحضور (JSON) - معرفات ولي الأمر',
  `guardiansFeedback` DECIMAL(15,2) COMMENT 'ملاحظات أولياء الأمور (JSON)',
  `minutes` VARCHAR(200) COMMENT 'محضر الاجتماع (نص مفصل)',
  `discussionTopics` VARCHAR(200) COMMENT 'المواضيع التي تمت مناقشتها (JSON)',
  `decisions` VARCHAR(200) COMMENT 'القرارات المتخذة (JSON)',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات',
  `actionItems` DATE COMMENT 'مهام متابعة (JSON) - مسؤول، تاريخ، حالة',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `minutesFilePath` VARCHAR(200) COMMENT 'مسار ملف محضر الاجتماع (PDF)',
  `minutesApproved` VARCHAR(200) COMMENT 'هل تم اعتماد المحضر؟',
  `minutesApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد المحضر',
  `minutesApprovalDate` DATE COMMENT 'تاريخ اعتماد المحضر',
  `followUpDate` DATE COMMENT 'تاريخ المتابعة المقرر',
  `followUpStatus` VARCHAR(50) COMMENT 'حالة المتابعة (قيد التنفيذ، منجز، متعثر)',
  `followUpNotes` TEXT COMMENT 'ملاحظات المتابعة',
  `relatedComplaintId` BIGINT COMMENT 'معرف شكوى مرتبطة (FK → StudentComplaint.complaintId) - اختياري',
  `relatedDisciplineId` BIGINT COMMENT 'معرف حالة سلوكية مرتبطة (FK → Discipline.disciplineId) - اختياري',
  `status` VARCHAR(50) COMMENT 'حالة الاجتماع (مخطط، مؤكد، منعقد، ملغي، مؤجل)',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء (إن وجد)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`meetingId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`organizerId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`classSectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`minutesApprovedByUserId`) REFERENCES `MinutesApprovedByUser`(`...`),
  -- FOREIGN KEY (`relatedComplaintId`) REFERENCES `StudentComplaint`(`...`),
  -- FOREIGN KEY (`relatedDisciplineId`) REFERENCES `Discipline`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='اجتماع أولياء الأمور';

-- Table: Notifications (الإشعارات)
CREATE TABLE IF NOT EXISTS `Notifications` (
  `notificationId` BIGINT NOT NULL COMMENT 'معرف الإشعار (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - اختياري (للإشعارات العامة)',
  `userId` BIGINT COMMENT 'معرف المستخدم المستلم (FK → SystemUser.userId)',
  `userType` VARCHAR(50) COMMENT 'نوع المستخدم (مدير، معلم، طالب، ولي أمر)',
  `notificationType` VARCHAR(50) COMMENT 'نوع الإشعار (موعد اجتماع، غياب طالب، نتيجة اختبار، قرار إداري، تذكير، تنبيه أمني، إعلان عام)',
  `category` VARCHAR(50) COMMENT 'فئة الإشعار (أكاديمي، سلوكي، إداري، مالي، صحي، عام)',
  `priority` VARCHAR(200) COMMENT 'مستوى الأهمية (عادي، مهم، عاجل، شديد الأهمية)',
  `title` VARCHAR(200) COMMENT 'عنوان الإشعار',
  `message` VARCHAR(200) COMMENT 'نص الإشعار',
  `body` VARCHAR(200) COMMENT 'نص مفصل (اختياري)',
  `actionLink` VARCHAR(200) COMMENT 'رابط التوجيه (لصفحة الطلب أو الحدث)',
  `actionType` VARCHAR(50) COMMENT 'نوع الإجراء المطلوب (عرض، موافقة، تعبئة نموذج، حضور اجتماع)',
  `relatedEntityType` VARCHAR(50) COMMENT 'نوع الكيان المرتبط (Meeting, Attendance, Grade, Payment, Leave, Complaint)',
  `relatedEntityId` BIGINT COMMENT 'معرف الكيان المرتبط',
  `senderEntity` VARCHAR(200) COMMENT 'الجهة المرسلة (نظام آلي، مكتب، مدرسة، مدير، معلم)',
  `senderUserId` BIGINT COMMENT 'معرف المرسل (FK → SystemUser.userId) - اختياري',
  `sendDate` DATE COMMENT 'تاريخ الإرسال',
  `sendTime` TIME COMMENT 'وقت الإرسال',
  `deliveryChannel` VARCHAR(200) COMMENT 'قناة الإرسال (تطبيق، بريد إلكتروني، رسالة نصية، جميع)',
  `emailSent` VARCHAR(100) COMMENT 'هل تم إرسال بريد إلكتروني؟',
  `emailSentAt` DATE COMMENT 'تاريخ إرسال البريد',
  `smsSent` VARCHAR(200) COMMENT 'هل تم إرسال رسالة نصية؟',
  `smsSentAt` DATE COMMENT 'تاريخ إرسال الرسالة',
  `appSent` VARCHAR(200) COMMENT 'هل تم إرسال للتطبيق؟',
  `appSentAt` DATE COMMENT 'تاريخ إرسال للتطبيق',
  `isRead` BOOLEAN COMMENT 'هل تمت قراءة الإشعار؟',
  `readAt` DATE COMMENT 'تاريخ القراءة',
  `readDevice` VARCHAR(200) COMMENT 'الجهاز الذي تمت القراءة منه',
  `isActionTaken` BOOLEAN COMMENT 'هل تم اتخاذ إجراء؟',
  `actionTakenAt` DATE COMMENT 'تاريخ اتخاذ الإجراء',
  `actionTakenByUserId` BIGINT COMMENT 'معرف من اتخذ الإجراء',
  `isDismissed` BOOLEAN COMMENT 'هل تم تجاهل الإشعار؟',
  `dismissedAt` DATE COMMENT 'تاريخ التجاهل',
  `expiresAt` DATE COMMENT 'تاريخ انتهاء صلاحية الإشعار',
  `reminderSent` VARCHAR(200) COMMENT 'هل تم إرسال تذكير؟',
  `reminderCount` INT COMMENT 'عدد مرات إرسال التذكير',
  `lastReminderSentAt` DATE COMMENT 'تاريخ آخر تذكير',
  `status` VARCHAR(50) COMMENT 'حالة الإشعار (مرسل، مقروء، منفذ، منتهي، ملغي)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`notificationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`relatedEntityId`) REFERENCES `RelatedEntity`(`...`),
  -- FOREIGN KEY (`senderUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`actionTakenByUserId`) REFERENCES `ActionTakenByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإشعارات';

-- Table: QuarterlyReport (التقارير الربع سنوية)
CREATE TABLE IF NOT EXISTS `QuarterlyReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `quarterNumber` INT COMMENT 'رقم الربع (الأول 1، الثاني 2، الثالث 3، الرابع 4)',
  `reportNumber` INT COMMENT 'رقم التقرير (يولد آلياً)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `reportingPeriodStart` VARCHAR(200) COMMENT 'بداية فترة التقرير',
  `reportingPeriodEnd` VARCHAR(200) COMMENT 'نهاية فترة التقرير',
  `achievementsJson` VARCHAR(200) COMMENT 'بيانات الإنجازات والمؤشرات الرقمية (JSON)',
  `studentStats` VARCHAR(200) COMMENT 'إحصائيات الطلاب (عدد الطلاب، الجدد، المغادرين، نسب النجاح)',
  `staffStats` VARCHAR(200) COMMENT 'إحصائيات الموظفين (عدد المعلمين، الإداريين، الجدد، المغادرين)',
  `attendanceStats` VARCHAR(200) COMMENT 'إحصائيات الحضور (نسبة حضور الطلاب، نسبة حضور المعلمين)',
  `financialStats` VARCHAR(200) COMMENT 'ملخص مالي (الإيرادات، المصروفات، الميزانية المتبقية)',
  `activityStats` VARCHAR(200) COMMENT 'إحصائيات الأنشطة (عدد الأنشطة المنفذة، عدد المشاركين)',
  `disciplineStats` VARCHAR(200) COMMENT 'إحصائيات السلوك (عدد المخالفات، عدد المكافآت)',
  `achievementRate` DECIMAL(5,2) COMMENT 'نسبة الإنجاز الكلية (مقارنة بالخطة)',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهت المدرسة خلال الربع',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات للربع القادم',
  `filingNumber` INT COMMENT 'رقم الإيداع (يولد آلياً عند نجاح الرفع)',
  `submissionDate` DATE COMMENT 'تاريخ الرفع إلى المكتب',
  `submissionMethod` VARCHAR(200) COMMENT 'طريقة الرفع (بوابة إلكترونية، بريد رسمي، يدوي)',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `officeReviewStatus` VARCHAR(50) COMMENT 'حالة المراجعة من المكتب (قيد المراجعة، مقبول، مرفوض للتعديل)',
  `officeReviewDate` DATE COMMENT 'تاريخ المراجعة',
  `officeReviewerId` BIGINT COMMENT 'معرف مراجع المكتب (FK → SystemUser.userId) - اختياري',
  `officeReviewNotes` TEXT COMMENT 'ملاحظات المراجع',
  `officeDecision` VARCHAR(200) COMMENT 'قرار المكتب (مقبول، مرفوض للتعديل)',
  `officeDecisionNumber` INT COMMENT 'رقم قرار القبول (إن وجد)',
  `officeDecisionDate` DATE COMMENT 'تاريخ القرار',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير المرفوع (PDF)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات إضافية (JSON)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، قيد المراجعة، معتمد، مرفوض)',
  `notes` TEXT COMMENT 'ملاحظات داخلية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `submittedAt` DATE COMMENT 'تاريخ الرفع (نسخة محفوظة)',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`officeReviewerId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التقارير الربع سنوية';

-- Table: CalendarComplianceReport (تقارير الالتزام بالتقويم)
CREATE TABLE IF NOT EXISTS `CalendarComplianceReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `academicMonth` VARCHAR(200) COMMENT 'الشهر الدراسي (المسمى الشهري: سبتمبر، أكتوبر...)',
  `monthNumber` INT COMMENT 'رقم الشهر (1-12)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `plannedStudyDays` VARCHAR(200) COMMENT 'عدد أيام الدراسة المخطط لها حسب التقويم',
  `actualStudyDays` VARCHAR(200) COMMENT 'عدد الأيام التي تمت فيها الدراسة فعلياً',
  `plannedHolidays` VARCHAR(200) COMMENT 'عدد أيام الإجازات المخططة',
  `actualHolidays` VARCHAR(200) COMMENT 'عدد أيام الإجازات الفعلية (قد تزيد)',
  `emergencyClosures` VARCHAR(200) COMMENT 'عدد أيام الإغلاق الطارئ (تعليق الدراسة)',
  `closureReasons` VARCHAR(200) COMMENT 'أسباب الإغلاق الطارئ (JSON)',
  `deviationDays` VARCHAR(200) COMMENT 'عدد أيام الانحراف (negative إذا كان أقل من المخطط)',
  `deviationPercentage` DECIMAL(5,2) COMMENT 'نسبة الانحراف',
  `deviationDetails` VARCHAR(200) COMMENT 'شرح أسباب الإجازات الطارئة أو التعليق (نص مفصل)',
  `affectedGrades` DECIMAL(5,2) COMMENT 'الصفوف المتأثرة بالانحراف (JSON)',
  `affectedSubjects` VARCHAR(200) COMMENT 'المواد المتأثرة (JSON)',
  `learningLoss` VARCHAR(200) COMMENT 'تقدير الفاقد التعليمي (نص أو نسبة مئوية)',
  `compensationPlan` VARCHAR(200) COMMENT 'خطة التعويض (إلزامي في حال وجود فاقد تعليمي)',
  `compensationPlanDetails` VARCHAR(200) COMMENT 'تفاصيل الخطة (جداول إضافية، حصص تعويضية)',
  `compensationPlanStartDate` DATE COMMENT 'تاريخ بدء خطة التعويض',
  `compensationPlanEndDate` DATE COMMENT 'تاريخ انتهاء خطة التعويض',
  `compensationHours` VARCHAR(200) COMMENT 'عدد ساعات التعويض المخطط لها',
  `compensationStatus` VARCHAR(50) COMMENT 'حالة تنفيذ خطة التعويض (مخطط، قيد التنفيذ، منجز)',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `officeReviewStatus` VARCHAR(50) COMMENT 'حالة المراجعة من المكتب',
  `officeReviewNotes` TEXT COMMENT 'ملاحظات جهة الرقابة',
  `officeApprovalStatus` VARCHAR(50) COMMENT 'حالة اعتماد الخطة التعويضية (معتمد، مرفوض، قيد المراجعة)',
  `officeApprovalDate` DATE COMMENT 'تاريخ الاعتماد',
  `officeDecisionNumber` INT COMMENT 'رقم قرار الاعتماد (إن وجد)',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، معتمد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير الالتزام بالتقويم';

-- Table: WeeklyProcessReport (تقارير سير العملية التعليمية الأسبوعية)
CREATE TABLE IF NOT EXISTS `WeeklyProcessReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `weekNumber` INT COMMENT 'رقم الأسبوع (1، 2، 3... حسب التقويم الدراسي)',
  `startDate` DATE COMMENT 'بداية الأسبوع',
  `endDate` DATE COMMENT 'نهاية الأسبوع',
  `reportNumber` INT COMMENT 'رقم التقرير (يولد آلياً)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `curriculumProgress` VARCHAR(200) COMMENT 'النسبة المئوية المتوسطة لإتمام المواد (لكل مادة على حدة أو متوسط)',
  `subjectProgressDetails` VARCHAR(200) COMMENT 'تفاصيل إنجاز المناهج لكل مادة (JSON) - تحتوي على (subjectId, plannedProgress, actualProgress, deviation)',
  `averageProgress` VARCHAR(200) COMMENT 'متوسط الإنجاز لجميع المواد',
  `completedTopics` VARCHAR(200) COMMENT 'المواضيع التي تمت تغطيتها (JSON)',
  `pendingTopics` VARCHAR(200) COMMENT 'المواضيع المتبقية (JSON)',
  `educationalObstacles` VARCHAR(200) COMMENT 'مشاكل التجهيزات أو نقص الوسائل (نص مفصل)',
  `obstaclesDetails` DATE COMMENT 'تفاصيل المعوقات (نوع المعوقة، التاريخ، الأثر، الإجراء المؤقت)',
  `obstaclesCategories` VARCHAR(200) COMMENT 'فئات المعوقات (نقص تجهيزات، غياب معلمين، مشاكل تقنية، إدارة صف)',
  `teacherAbsences` VARCHAR(200) COMMENT 'غيابات المعلمين خلال الأسبوع (JSON)',
  `substituteTeachers` VARCHAR(200) COMMENT 'المعلمون البدلاء (JSON)',
  `studentAttendanceRate` DECIMAL(5,2) COMMENT 'نسبة حضور الطلاب خلال الأسبوع',
  `teacherAttendanceRate` DECIMAL(5,2) COMMENT 'نسبة حضور المعلمين خلال الأسبوع',
  `recommendations` VARCHAR(200) COMMENT 'توصيات لتحسين سير العملية التعليمية',
  `internalApproval` VARCHAR(200) COMMENT 'اعتماد رئيس قسم الإشراف بالمدرسة (نعم/لا)',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد (FK → Employee.employeeId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن لم يتم الاعتماد)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، قيد المراجعة، معتمد، مرفوض)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير سير العملية التعليمية الأسبوعية';

-- Table: MonthlyDisciplineReport (تقارير الانضباط المدرسي)
CREATE TABLE IF NOT EXISTS `MonthlyDisciplineReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `month` VARCHAR(200) COMMENT 'الشهر (1-12)',
  `year` VARCHAR(200) COMMENT 'السنة (ميلادية أو هجرية حسب التقويم)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `studentAttendanceRate` DECIMAL(5,2) COMMENT 'نسبة حضور الطلاب الإجمالية',
  `studentAttendanceByGrade` DECIMAL(5,2) COMMENT 'نسب حضور الطلاب حسب الصفوف (JSON)',
  `staffAttendanceRate` DECIMAL(5,2) COMMENT 'نسبة حضور الكادر الإجمالية (معلمين وإداريين)',
  `staffAttendanceByDepartment` VARCHAR(200) COMMENT 'نسب الحضور حسب الأقسام (JSON)',
  `totalPositiveBehaviors` VARCHAR(200) COMMENT 'عدد السلوكيات الإيجابية المسجلة',
  `positiveBehaviorDetails` VARCHAR(200) COMMENT 'تفاصيل السلوكيات الإيجابية (JSON) - حسب النوع، الصف، الطالب',
  `totalViolations` VARCHAR(200) COMMENT 'إجمالي عدد المخالفات',
  `violationsByType` VARCHAR(50) COMMENT 'المخالفات حسب النوع (JSON)',
  `violationsBySeverity` VARCHAR(200) COMMENT 'المخالفات حسب الخطورة (بسيط، متوسط، جسيم)',
  `violationsByGrade` DECIMAL(5,2) COMMENT 'المخالفات حسب الصف (JSON)',
  `topViolations` VARCHAR(200) COMMENT 'أكثر المخالفات تكراراً (JSON)',
  `mostAffectedGrades` DECIMAL(5,2) COMMENT 'الصفوف الأكثر تأثراً بالمخالفات (JSON)',
  `violationsSummary` VARCHAR(200) COMMENT 'ملخص المخالفات (نص)',
  `penaltiesApplied` VARCHAR(200) COMMENT 'الجزاءات المطبقة (JSON)',
  `guidancePrograms` VARCHAR(200) COMMENT 'الأنشطة المنفذة لتعزيز القيم والسلوك الإيجابي (JSON)',
  `guidanceProgramsCount` INT COMMENT 'عدد البرامج التوجيهية المنفذة',
  `guidanceProgramsBeneficiaries` VARCHAR(200) COMMENT 'عدد المستفيدين من البرامج',
  `recommendations` VARCHAR(200) COMMENT 'توصيات لتحسين الانضباط',
  `comparisonWithPreviousMonth` VARCHAR(200) COMMENT 'مقارنة مع الشهر السابق (JSON)',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير (إن وجد)',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، معتمد، مرفوع)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId) - اختياري',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير الانضباط المدرسي';

-- Table: SemesterEndReport (تقارير نهاية الفصل الدراسي)
CREATE TABLE IF NOT EXISTS `SemesterEndReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `semesterStatsJson` VARCHAR(200) COMMENT 'أعداد الطلاب والمعلمين الفعليين خلال الفصل (JSON)',
  `studentsStartCount` INT COMMENT 'عدد الطلاب في بداية الفصل',
  `studentsEndCount` INT COMMENT 'عدد الطلاب في نهاية الفصل',
  `studentsNewCount` INT COMMENT 'عدد الطلاب الجدد خلال الفصل',
  `studentsWithdrawnCount` INT COMMENT 'عدد الطلاب المنسحبين',
  `teachersCount` INT COMMENT 'عدد المعلمين',
  `staffCount` INT COMMENT 'عدد الإداريين',
  `classesCount` INT COMMENT 'عدد الفصول (الشعب) النشطة',
  `examResultsSummary` VARCHAR(200) COMMENT 'ملخص نسب النجاح العامة للفصل (نص)',
  `successRateByGrade` DECIMAL(5,2) COMMENT 'نسب النجاح حسب الصفوف (JSON)',
  `successRateBySubject` DECIMAL(5,2) COMMENT 'نسب النجاح حسب المواد (JSON)',
  `topPerformingSubjects` VARCHAR(200) COMMENT 'أفضل المواد أداءً',
  `lowestPerformingSubjects` VARCHAR(200) COMMENT 'أقل المواد أداءً',
  `gradeDistribution` DECIMAL(5,2) COMMENT 'توزيع التقديرات (JSON)',
  `studentRanking` VARCHAR(200) COMMENT 'ترتيب الطلاب الأوائل (JSON)',
  `teacherPerformanceSummary` VARCHAR(200) COMMENT 'ملخص أداء المعلمين (JSON)',
  `classPerformance` VARCHAR(200) COMMENT 'أداء كل شعبة (JSON)',
  `comparisonWithPreviousSemester` VARCHAR(200) COMMENT 'مقارنة مع الفصل السابق (JSON)',
  `strengths` VARCHAR(200) COMMENT 'نقاط القوة خلال الفصل',
  `weaknesses` VARCHAR(200) COMMENT 'نقاط الضعف',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهت العملية التعليمية',
  `futureRecommendations` VARCHAR(200) COMMENT 'مقترحات تطويرية للفصل التالي (نص)',
  `actionPlan` VARCHAR(200) COMMENT 'خطة عمل للفصل القادم (JSON)',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `officeReviewStatus` VARCHAR(50) COMMENT 'حالة المراجعة من المكتب',
  `officeReviewNotes` TEXT COMMENT 'ملاحظات المكتب',
  `officeApprovalStatus` VARCHAR(50) COMMENT 'حالة اعتماد المكتب (معتمد، مرفوض للتعديل)',
  `officeApprovalDate` DATE COMMENT 'تاريخ الاعتماد',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، معتمد)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير نهاية الفصل الدراسي';

-- Table: AnnualComprehensiveReport (التقارير السنوية الشاملة)
CREATE TABLE IF NOT EXISTS `AnnualComprehensiveReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي حسب السنة)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `executiveSummary` VARCHAR(200) COMMENT 'ملخص تنفيذي (نص)',
  `schoolVision` VARCHAR(200) COMMENT 'رؤية المدرسة',
  `schoolMission` VARCHAR(200) COMMENT 'رسالة المدرسة',
  `strategicGoals` DECIMAL(5,2) COMMENT 'الأهداف الاستراتيجية (JSON)',
  `academicAchievement` VARCHAR(200) COMMENT 'الإنجاز الأكاديمي (نسبة النجاح العامة، عدد المتفوقين، مقارنة بالعام السابق)',
  `studentStats` VARCHAR(200) COMMENT 'إحصائيات الطلاب (عدد الطلاب، نسبة النمو، نسبة الاستبقاء)',
  `staffStats` VARCHAR(200) COMMENT 'إحصائيات الموظفين (عدد المعلمين، نسبة الاستقرار، حالات المغادرة)',
  `financialSummary` VARCHAR(200) COMMENT 'ملخص مالي (الإيرادات، المصروفات، الميزانية المتبقية)',
  `facilityStatus` VARCHAR(50) COMMENT 'حالة المرافق والبنية التحتية (تحسينات، صيانة، احتياجات)',
  `activitiesSummary` VARCHAR(200) COMMENT 'ملخص الأنشطة (عدد الأنشطة، عدد المشاركين، الإنجازات)',
  `selfEvaluationResults` VARCHAR(200) COMMENT 'نتائج التقييم الذاتي للمدرسة لأدائها المؤسسي (نص أو درجات)',
  `selfEvaluationDetails` VARCHAR(200) COMMENT 'تفاصيل التقييم الذاتي حسب المحاور (JSON)',
  `goalAchievementAnalysis` VARCHAR(200) COMMENT 'تحليل الأهداف (مدى نجاح تنفيذ الخطة السنوية)',
  `goalAchievementRate` DECIMAL(5,2) COMMENT 'نسبة تحقيق الأهداف الاستراتيجية',
  `achievedGoals` VARCHAR(200) COMMENT 'الأهداف التي تحققت (JSON)',
  `partiallyAchievedGoals` VARCHAR(200) COMMENT 'الأهداف التي تحققت جزئياً (JSON)',
  `unachievedGoals` VARCHAR(200) COMMENT 'الأهداف التي لم تتحقق (JSON)',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهت المدرسة خلال العام',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة (لاستخدامها في خطة العام القادم)',
  `lessonsLearnedDetails` VARCHAR(200) COMMENT 'تفاصيل الدروس المستفادة (JSON)',
  `futureRecommendations` VARCHAR(200) COMMENT 'توصيات للعام القادم',
  `signedPdfPath` VARCHAR(200) COMMENT 'رابط ملف التقرير المعتمد والمنتهي (PDF)',
  `reportLanguage` VARCHAR(200) COMMENT 'لغة التقرير (عربية، إنجليزية، ثنائي)',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorName` VARCHAR(200) COMMENT 'اسم المدير (للتوقيع)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `directorSignatureDate` DATE COMMENT 'تاريخ التوقيع',
  `officeReviewStatus` VARCHAR(50) COMMENT 'حالة المراجعة من المكتب',
  `officeReviewDate` DATE COMMENT 'تاريخ المراجعة',
  `officeReviewerId` BIGINT COMMENT 'معرف مراجع المكتب (FK → SystemUser.userId)',
  `officeReviewNotes` TEXT COMMENT 'ملاحظات المكتب',
  `officeApprovalStatus` VARCHAR(50) COMMENT 'حالة اعتماد المكتب (معتمد، مرفوض للتعديل)',
  `officeApprovalDate` DATE COMMENT 'تاريخ الاعتماد',
  `officeDecisionNumber` INT COMMENT 'رقم قرار الاعتماد (إن وجد)',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، قيد المراجعة، معتمد، مرفوض)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`officeReviewerId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التقارير السنوية الشاملة';

-- Table: EducationalOutcomesReport (تقارير المخرجات التعليمية)
CREATE TABLE IF NOT EXISTS `EducationalOutcomesReport` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `generalSuccessRates` DECIMAL(5,2) COMMENT 'نسب النجاح مفصلة حسب المواد والصفوف (JSON)',
  `successRateByGrade` DECIMAL(5,2) COMMENT 'نسبة النجاح لكل صف (JSON)',
  `successRateBySubject` DECIMAL(5,2) COMMENT 'نسبة النجاح لكل مادة (JSON)',
  `successRateByCategory` DECIMAL(5,2) COMMENT 'نسبة النجاح حسب فئة المادة (إجباري، اختياري) (JSON)',
  `topPerformingSubjects` VARCHAR(200) COMMENT 'أفضل 5 مواد أداءً',
  `lowestPerformingSubjects` VARCHAR(200) COMMENT 'أقل 5 مواد أداءً',
  `gradeTrendAnalysis` DECIMAL(5,2) COMMENT 'مقارنة تحليلية مع النتائج السابقة (JSON)',
  `comparisonWithPreviousYear` VARCHAR(200) COMMENT 'مقارنة مع العام السابق',
  `comparisonWithLast3Years` VARCHAR(200) COMMENT 'مقارنة مع آخر 3 سنوات',
  `subjectsImprovement` VARCHAR(200) COMMENT 'المواد التي تحسنت نتائجها',
  `subjectsDecline` VARCHAR(200) COMMENT 'المواد التي تراجعت نتائجها',
  `educationalImpact` VARCHAR(200) COMMENT 'مدى فعالية البرامج في تحسين النتائج (نص)',
  `initiativesImpact` VARCHAR(200) COMMENT 'أثر المبادرات المنفذة (JSON)',
  `programsEffectiveness` VARCHAR(200) COMMENT 'فعالية البرامج التعليمية (تقييم)',
  `correlationAnalysis` VARCHAR(200) COMMENT 'تحليل العلاقة بين الحضور والنتائج',
  `correlationWithAttendance` VARCHAR(200) COMMENT 'معامل الارتباط بين الحضور والنتائج',
  `recommendations` VARCHAR(200) COMMENT 'توصيات لتحسين المخرجات التعليمية',
  `actionPlan` VARCHAR(200) COMMENT 'خطة عمل مقترحة للعام القادم',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير للمكتب',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'توقيع المدير الإلكتروني',
  `officialApprovalDate` DATE COMMENT 'تاريخ موافقة المكتب على المخرجات',
  `officeApprovalStatus` VARCHAR(50) COMMENT 'حالة الموافقة (معتمد، مرفوض للتعديل)',
  `officeApprovalNumber` INT COMMENT 'رقم قرار الاعتماد',
  `officeApprovalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `reportFilePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، مرفوع، معتمد)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير المخرجات التعليمية';


-- ============================
-- Module: M2_Student
-- ============================

-- Table: Application (طلب التسجيل)
CREATE TABLE IF NOT EXISTS `Application` (
  `applicationId` BIGINT NOT NULL COMMENT 'رقم تعريف فريد للطلب (المفتاح الرئيسي)',
  `ParentId` BIGINT COMMENT 'رقم ولي الأمر (يرتبط بجدول Guardian)',
  `schoolId` BIGINT COMMENT 'رقم المدرسة (يرتبط بجدول School)',
  `birthDate` DATE COMMENT 'تاريخ ميلاد الطالب',
  `birthPlace` VARCHAR(200) COMMENT 'مكان ميلاد الطالب',
  `gender` VARCHAR(200) COMMENT 'الجنس (ذكر/أنثى)',
  `nationality` VARCHAR(200) COMMENT 'الجنسية',
  `address` VARCHAR(200) COMMENT 'العنوان',
  `BirthCartificate` VARCHAR(200) COMMENT 'مسار ملف شهادة الميلاد',
  `PersonalPhoto` VARCHAR(200) COMMENT 'مسار ملف الصورة الشخصية',
  `IDCardImage` VARCHAR(200) COMMENT 'مسار ملف صورة الهوية',
  `requestStatue` VARCHAR(200) COMMENT 'حالة الطلب (قيد الانتظار، مقبول، مرفوض، غير مكتمل)',
  `submissionDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `firstNameAr` VARCHAR(200) COMMENT 'الاسم الأول بالعربية (لاستكمال الاسم الرباعي)',
  `fatherNameAr` VARCHAR(200) COMMENT 'اسم الأب بالعربية',
  `grandfatherNameAr` VARCHAR(200) COMMENT 'اسم الجد بالعربية',
  `familyNameAr` VARCHAR(200) COMMENT 'اسم العائلة بالعربية',
  `firstNameEn` VARCHAR(200) COMMENT 'الاسم الأول بالإنجليزية (للواجهة ثنائية اللغة)',
  `fatherNameEn` VARCHAR(200) COMMENT 'اسم الأب بالإنجليزية',
  `grandfatherNameEn` VARCHAR(200) COMMENT 'اسم الجد بالإنجليزية',
  `familyNameEn` VARCHAR(200) COMMENT 'اسم العائلة بالإنجليزية',
  `placeOfBirth` VARCHAR(200) COMMENT 'مكان الميلاد (مدينة)',
  `countryOfBirth` INT COMMENT 'دولة الميلاد',
  `motherName` VARCHAR(200) COMMENT 'اسم الأم الكامل',
  `motherNationality` VARCHAR(200) COMMENT 'جنسية الأم',
  `motherPhone` VARCHAR(20) COMMENT 'هاتف الأم (للتواصل البديل)',
  `previousSchool` VARCHAR(200) COMMENT 'المدرسة السابقة (إن وجد)',
  `previousGrade` DECIMAL(5,2) COMMENT 'الصف السابق',
  `requestedGradeLevel` DECIMAL(5,2) COMMENT 'الصف المطلوب الالتحاق به',
  `academicYearId` BIGINT COMMENT 'السنة الدراسية المطلوب الالتحاق بها',
  `hasSpecialNeeds` BOOLEAN COMMENT 'هل لديه احتياجات خاصة؟',
  `specialNeedsDetails` VARCHAR(200) COMMENT 'تفاصيل الاحتياجات الخاصة (إن وجدت)',
  `medicalNotes` TEXT COMMENT 'ملاحظات طبية مهمة',
  `siblingInSchool` VARCHAR(200) COMMENT 'هل له أشقاء في المدرسة؟',
  `siblingNames` VARCHAR(200) COMMENT 'أسماء الأشقاء (إن وجدوا)',
  `referralSource` VARCHAR(200) COMMENT 'مصدر التعريف بالمدرسة (صديق، إعلان، موقع، الخ)',
  `emergencyContactName` VARCHAR(200) COMMENT 'اسم جهة الاتصال في حالات الطوارئ',
  `emergencyContactPhone` VARCHAR(20) COMMENT 'هاتف جهة الاتصال في حالات الطوارئ',
  `emergencyContactRelation` VARCHAR(200) COMMENT 'صلة القرابة مع جهة الاتصال',
  `reviewedByUserId` BIGINT COMMENT 'معرف الموظف الذي راجع الطلب',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن تم الرفض)',
  `approvalDate` DATE COMMENT 'تاريخ الموافقة على الطلب',
  `convertedToStudentId` BIGINT COMMENT 'معرف الطالب بعد التحويل (يرتبط بجدول Student)',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل (من جدول SystemUser)',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي (0 = نشط، 1 = محذوف)',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  PRIMARY KEY (`applicationId`),
  -- FOREIGN KEY (`ParentId`) REFERENCES `Guardian`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `AcademicYear`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `ReviewedByUser`(`...`),
  -- FOREIGN KEY (`convertedToStudentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='طلب التسجيل';

-- Table: Student (الطالب)
CREATE TABLE IF NOT EXISTS `Student` (
  `schoolStudentNumber` INT COMMENT 'رقم الطالب داخل المدرسة',
  `nationalId` BIGINT NOT NULL COMMENT 'الرقم الوطني/الإقامة',
  `fullNameAr` VARCHAR(200) COMMENT 'الاسم الرباعي بالعربية',
  `fullNameEn` VARCHAR(200) COMMENT 'الاسم بالإنجليزية',
  `birthDate` DATE COMMENT 'تاريخ الميلاد',
  `birthPlace` VARCHAR(200) COMMENT 'مكان الميلاد',
  `gender` VARCHAR(200) COMMENT 'الجنس (ذكر/أنثى)',
  `nationality` VARCHAR(200) COMMENT 'الجنسية',
  `religion` VARCHAR(200) COMMENT 'الديانة',
  `bloodType` VARCHAR(50) COMMENT 'فصيلة الدم',
  `status` VARCHAR(50) COMMENT 'حالة الطالب',
  `enrollmentDate` DATE COMMENT 'تاريخ أول قيد',
  `currentEnrollmentDate` DATE COMMENT 'تاريخ القيد الحالي',
  `address` VARCHAR(200) COMMENT 'العنوان',
  `phone` VARCHAR(20) COMMENT 'الهاتف',
  `email` VARCHAR(100) COMMENT 'البريد الإلكتروني',
  `isSpecialNeeds` BOOLEAN COMMENT 'احتياجات خاصة',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `studentPhoto` VARCHAR(200) COMMENT 'صورة الطالب (مسار الملف)',
  `studentPhotoThumb` VARCHAR(200) COMMENT 'صورة مصغرة للعرض السريع',
  `firstNameAr` VARCHAR(200) COMMENT 'الاسم الأول بالعربية (للبحث المفصل)',
  `fatherNameAr` VARCHAR(200) COMMENT 'اسم الأب بالعربية',
  `grandfatherNameAr` VARCHAR(200) COMMENT 'اسم الجد بالعربية',
  `familyNameAr` VARCHAR(200) COMMENT 'اسم العائلة بالعربية',
  `firstNameEn` VARCHAR(200) COMMENT 'الاسم الأول بالإنجليزية',
  `fatherNameEn` VARCHAR(200) COMMENT 'اسم الأب بالإنجليزية',
  `grandfatherNameEn` VARCHAR(200) COMMENT 'اسم الجد بالإنجليزية',
  `familyNameEn` VARCHAR(200) COMMENT 'اسم العائلة بالإنجليزية',
  `fullNameArNormalized` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية للتطبيع (بدون تشكيل)',
  `fullNameEnNormalized` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية للتطبيع (أحرف كبيرة)',
  `placeOfBirth` VARCHAR(200) COMMENT 'مكان الميلاد (مدينة)',
  `countryOfBirth` INT COMMENT 'دولة الميلاد',
  `motherName` VARCHAR(200) COMMENT 'اسم الأم الكامل',
  `motherNationality` VARCHAR(200) COMMENT 'جنسية الأم',
  `motherPhone` VARCHAR(20) COMMENT 'هاتف الأم',
  `motherEmail` VARCHAR(100) COMMENT 'بريد الأم الإلكتروني',
  `motherOccupation` VARCHAR(200) COMMENT 'وظيفة الأم',
  `familyNumber` INT COMMENT 'رقم العائلة في السجل المدني',
  `passportNumber` INT COMMENT 'رقم جواز السفر (للطلاب غير السعوديين)',
  `passportExpiryDate` DATE COMMENT 'تاريخ انتهاء جواز السفر',
  `residenceNumber` INT COMMENT 'رقم الإقامة (لغير السعوديين)',
  `residenceExpiryDate` DATE COMMENT 'تاريخ انتهاء الإقامة',
  `socialSecurityNumber` INT COMMENT 'رقم الضمان الاجتماعي (إن وجد)',
  `hasMedicalInsurance` BOOLEAN COMMENT 'هل لديه تأمين طبي؟',
  `medicalInsuranceCompany` VARCHAR(200) COMMENT 'شركة التأمين الطبي',
  `medicalInsuranceNumber` INT COMMENT 'رقم وثيقة التأمين',
  `medicalInsuranceExpiry` DATE COMMENT 'تاريخ انتهاء التأمين',
  `specialNeedsType` VARCHAR(50) COMMENT 'نوع الاحتياجات الخاصة',
  `specialNeedsDetails` VARCHAR(200) COMMENT 'تفاصيل الاحتياجات الخاصة',
  `specialNeedsAttachment` VARCHAR(200) COMMENT 'ملف تقرير طبي للاحتياجات الخاصة',
  `isOrphan` BOOLEAN COMMENT 'هل الطالب يتيم؟',
  `orphanType` VARCHAR(50) COMMENT 'نوع اليتم (أب، أم، كلاهما)',
  `isSponsored` BOOLEAN COMMENT 'هل الطالب مكفول؟',
  `sponsorName` VARCHAR(200) COMMENT 'اسم الكافل',
  `sponsorType` VARCHAR(50) COMMENT 'نوع الكافل (جهة، فرد)',
  `isFromLowIncomeFamily` BOOLEAN COMMENT 'هل الأسرة محدودة الدخل؟',
  `familyIncomeLevel` VARCHAR(50) COMMENT 'مستوى دخل الأسرة',
  `numberOfFamilyMembers` INT COMMENT 'عدد أفراد الأسرة',
  `numberOfSiblings` INT COMMENT 'عدد الإخوة',
  `siblingsInSchool` VARCHAR(200) COMMENT 'عدد الأشقاء في نفس المدرسة',
  `siblingsNames` VARCHAR(200) COMMENT 'أسماء الأشقاء في المدرسة',
  `busSubscriptionId` BIGINT COMMENT 'رقم اشتراك الباص (إن وجد)',
  `busStopPoint` VARCHAR(200) COMMENT 'نقطة التقاط الباص',
  `busSubscriptionStatus` VARCHAR(50) COMMENT 'حالة اشتراك الباص',
  `previousSchool` VARCHAR(200) COMMENT 'المدرسة السابقة',
  `previousSchoolCity` VARCHAR(200) COMMENT 'مدينة المدرسة السابقة',
  `previousSchoolGrade` DECIMAL(5,2) COMMENT 'الصف في المدرسة السابقة',
  `previousSchoolYear` VARCHAR(200) COMMENT 'السنة الدراسية في المدرسة السابقة',
  `transferReason` VARCHAR(200) COMMENT 'سبب النقل من المدرسة السابقة',
  `joinDate` DATE COMMENT 'تاريخ الانضمام للمدرسة الحالية',
  `graduationDate` DATE COMMENT 'تاريخ التخرج المتوقع',
  `actualGraduationDate` DATE COMMENT 'تاريخ التخرج الفعلي',
  `isGraduated` BOOLEAN COMMENT 'هل تخرج؟',
  `graduationYear` VARCHAR(200) COMMENT 'سنة التخرج',
  `leavingDate` DATE COMMENT 'تاريخ المغادرة (إن ترك المدرسة)',
  `leavingReason` VARCHAR(200) COMMENT 'سبب المغادرة',
  `leavingDestination` VARCHAR(200) COMMENT 'الجهة المنتقل إليها',
  `lastAttendanceDate` DATE COMMENT 'تاريخ آخر حضور',
  `studentCode` VARCHAR(50) COMMENT 'كود الطالب الموحد (يولد آلياً)',
  `qrCode` VARCHAR(50) COMMENT 'رمز QR للطالب',
  `barcode` VARCHAR(50) COMMENT 'باركود للطالب',
  `rfidTag` VARCHAR(200) COMMENT 'رقم شريحة RFID (إن وجدت)',
  `studentCardIssued` VARCHAR(200) COMMENT 'هل تم إصدار كارت الطالب؟',
  `studentCardIssueDate` DATE COMMENT 'تاريخ إصدار الكارت',
  `studentCardExpiryDate` DATE COMMENT 'تاريخ انتهاء الكارت',
  `canUsePortal` VARCHAR(200) COMMENT 'هل يمكن للطالب استخدام البوابة؟',
  `portalUsername` VARCHAR(200) COMMENT 'اسم مستخدم البوابة',
  `portalPasswordHash` VARCHAR(200) COMMENT 'كلمة مرور البوابة (مشفرة)',
  `lastPortalLogin` VARCHAR(200) COMMENT 'آخر دخول للبوابة',
  `preferredLanguage` VARCHAR(200) COMMENT 'اللغة المفضلة للتواصل',
  `notificationPreference` VARCHAR(200) COMMENT 'تفضيلات الإشعارات (JSON)',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات (تسجيل يدوي، استيراد، بوابة)',
  `importBatchId` BIGINT COMMENT 'معرف دفعة الاستيراد (إن وجد)',
  `verificationStatus` VARCHAR(50) COMMENT 'حالة التحقق من البيانات',
  `verifiedByUserId` BIGINT COMMENT 'معرف الموظف الذي تحقق من البيانات',
  `verificationDate` DATE COMMENT 'تاريخ التحقق',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  PRIMARY KEY (`nationalId`),
  -- FOREIGN KEY (`nationalId`) REFERENCES `National`(`...`),
  -- FOREIGN KEY (`busSubscriptionId`) REFERENCES `BusSubscription`(`...`),
  -- FOREIGN KEY (`importBatchId`) REFERENCES `ImportBatch`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `VerifiedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='الطالب';

-- Table: Guardian (ولي الأمر)
CREATE TABLE IF NOT EXISTS `Guardian` (
  `nationalId` BIGINT COMMENT 'الرقم الوطني/الإقامة',
  `fullNameAr` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية',
  `relationship` VARCHAR(200) COMMENT 'صلة القرابة',
  `phonePrimary` VARCHAR(20) COMMENT 'الهاتف الأساسي',
  `phoneSecondary` VARCHAR(20) COMMENT 'هاتف إضافي',
  `email` VARCHAR(100) COMMENT 'البريد الإلكتروني',
  `jobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي',
  `isPrimary` BOOLEAN COMMENT 'ولي أمر أساسي',
  `isEmergencyContact` BOOLEAN COMMENT 'للطوارئ',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `guardianCode` VARCHAR(50) COMMENT 'كود ولي الأمر (يولد آلياً)',
  `firstNameAr` VARCHAR(200) COMMENT 'الاسم الأول بالعربية',
  `fatherNameAr` VARCHAR(200) COMMENT 'اسم الأب بالعربية',
  `grandfatherNameAr` VARCHAR(200) COMMENT 'اسم الجد بالعربية',
  `familyNameAr` VARCHAR(200) COMMENT 'اسم العائلة بالعربية',
  `firstNameEn` VARCHAR(200) COMMENT 'الاسم الأول بالإنجليزية',
  `fatherNameEn` VARCHAR(200) COMMENT 'اسم الأب بالإنجليزية',
  `grandfatherNameEn` VARCHAR(200) COMMENT 'اسم الجد بالإنجليزية',
  `familyNameEn` VARCHAR(200) COMMENT 'اسم العائلة بالإنجليزية',
  `fullNameEn` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية',
  `fullNameArNormalized` VARCHAR(200) COMMENT 'الاسم الكامل للتطبيع',
  `fullNameEnNormalized` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية للتطبيع',
  `birthDate` DATE COMMENT 'تاريخ الميلاد',
  `gender` VARCHAR(200) COMMENT 'الجنس',
  `nationality` VARCHAR(200) COMMENT 'الجنسية',
  `passportNumber` INT COMMENT 'رقم جواز السفر',
  `passportExpiryDate` DATE COMMENT 'تاريخ انتهاء الجواز',
  `residenceNumber` INT COMMENT 'رقم الإقامة (لغير السعوديين)',
  `residenceExpiryDate` DATE COMMENT 'تاريخ انتهاء الإقامة',
  `address` VARCHAR(200) COMMENT 'العنوان التفصيلي',
  `city` VARCHAR(200) COMMENT 'المدينة',
  `district` VARCHAR(200) COMMENT 'الحي',
  `street` VARCHAR(200) COMMENT 'الشارع',
  `buildingNumber` INT COMMENT 'رقم المبنى',
  `unitNumber` INT COMMENT 'رقم الوحدة',
  `postalCode` VARCHAR(50) COMMENT 'الرمز البريدي',
  `additionalNumber` INT COMMENT 'الرقم الإضافي',
  `workPhone` VARCHAR(20) COMMENT 'هاتف العمل',
  `workAddress` VARCHAR(200) COMMENT 'عنوان العمل',
  `educationLevel` VARCHAR(50) COMMENT 'المستوى التعليمي',
  `maritalStatus` VARCHAR(50) COMMENT 'الحالة الاجتماعية',
  `numberOfChildren` INT COMMENT 'عدد الأبناء',
  `familyIncomeLevel` VARCHAR(50) COMMENT 'مستوى دخل الأسرة',
  `canUsePortal` VARCHAR(200) COMMENT 'هل يمكن لولي الأمر استخدام البوابة؟',
  `portalUsername` VARCHAR(200) COMMENT 'اسم مستخدم البوابة',
  `portalPasswordHash` VARCHAR(200) COMMENT 'كلمة مرور البوابة (مشفرة)',
  `lastPortalLogin` VARCHAR(200) COMMENT 'آخر دخول للبوابة',
  `preferredLanguage` VARCHAR(200) COMMENT 'اللغة المفضلة للتواصل',
  `notificationPreference` VARCHAR(200) COMMENT 'تفضيلات الإشعارات (JSON)',
  `communicationPreference` VARCHAR(200) COMMENT 'تفضيلات التواصل (واتساب، بريد، رسائل نصية)',
  `whatsappNumber` INT COMMENT 'رقم الواتساب',
  `facebookProfile` VARCHAR(200) COMMENT 'رابط حساب فيسبوك',
  `twitterHandle` VARCHAR(200) COMMENT 'حساب تويتر',
  `profilePhoto` VARCHAR(200) COMMENT 'صورة الملف الشخصي',
  `idCardImage` VARCHAR(200) COMMENT 'صورة بطاقة الهوية',
  `passportImage` VARCHAR(200) COMMENT 'صورة جواز السفر',
  `residencyImage` VARCHAR(200) COMMENT 'صورة الإقامة',
  `verificationStatus` VARCHAR(50) COMMENT 'حالة التحقق من الهوية',
  `verifiedByUserId` BIGINT COMMENT 'معرف الموظف الذي تحقق',
  `verificationDate` DATE COMMENT 'تاريخ التحقق',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات',
  `importBatchId` BIGINT COMMENT 'معرف دفعة الاستيراد',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `lastCommunicationDate` DATE COMMENT 'تاريخ آخر تواصل مع المدرسة',
  `lastCommunicationType` VARCHAR(50) COMMENT 'نوع آخر تواصل',
  `communicationHistory` VARCHAR(200) COMMENT 'سجل التواصل (JSON)',
  `complaintsCount` INT COMMENT 'عدد الشكاوى المقدمة',
  `lastComplaintDate` DATE COMMENT 'تاريخ آخر شكوى',
  `meetingsCount` INT COMMENT 'عدد الاجتماعات',
  `lastMeetingDate` DATE COMMENT 'تاريخ آخر اجتماع',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  `studentGuardianId` BIGINT NOT NULL COMMENT 'رقم تعريف فريد للسجل (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `guardianId` BIGINT COMMENT 'معرف ولي الأمر (FK → Guardian.guardianId)',
  `custodyPercentage` DECIMAL(5,2) COMMENT 'نسبة الحضانة (في حال الانفصال)',
  `hasCustody` BOOLEAN COMMENT 'هل له حق الحضانة؟',
  `canPickup` VARCHAR(200) COMMENT 'هل يمكنه استلام الطالب من المدرسة؟',
  `authorizedBy` VARCHAR(200) COMMENT 'مصرح من قبل (في حال كان وصياً)',
  `authorizationDocument` VARCHAR(200) COMMENT 'مسار وثيقة التفويض',
  `authorizationStartDate` DATE COMMENT 'تاريخ بداية التفويض',
  `authorizationEndDate` DATE COMMENT 'تاريخ نهاية التفويض',
  `canAccessPortal` VARCHAR(200) COMMENT 'هل يمكن لهذا ولي الأمر الوصول لبيانات هذا الطالب بالتحديد؟',
  `canViewGrades` DECIMAL(5,2) COMMENT 'هل يمكنه رؤية الدرجات؟',
  `canViewAttendance` VARCHAR(200) COMMENT 'هل يمكنه رؤية الحضور؟',
  `canViewBehavior` VARCHAR(200) COMMENT 'هل يمكنه رؤية السلوك؟',
  `canViewFinance` VARCHAR(200) COMMENT 'هل يمكنه رؤية البيانات المالية؟',
  `canMakePayments` VARCHAR(200) COMMENT 'هل يمكنه سداد المدفوعات؟',
  `receivesNotifications` VARCHAR(200) COMMENT 'هل يتلقى إشعارات هذا الطالب؟',
  `notificationTypes` VARCHAR(50) COMMENT 'أنواع الإشعارات التي يتلقاها (JSON)',
  `priority` VARCHAR(200) COMMENT 'أولوية التواصل (في حال وجود عدة أولياء)',
  `isActive` BOOLEAN COMMENT 'هل العلاقة نشطة؟',
  `deactivatedAt` DATE COMMENT 'تاريخ إلغاء النشاط',
  `deactivatedByUserId` BIGINT COMMENT 'معرف من ألغى النشاط',
  `deactivationReason` VARCHAR(200) COMMENT 'سبب إلغاء النشاط',
  PRIMARY KEY (`studentGuardianId`),
  -- FOREIGN KEY (`nationalId`) REFERENCES `National`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `VerifiedByUser`(`...`),
  -- FOREIGN KEY (`importBatchId`) REFERENCES `ImportBatch`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`guardianId`) REFERENCES `Guardian`(`...`),
  -- FOREIGN KEY (`deactivatedByUserId`) REFERENCES `DeactivatedByUser`(`...`)
) COMMENT='ولي الأمر';

-- Table: Enrollment (الالتحاق)
CREATE TABLE IF NOT EXISTS `Enrollment` (
  `enrollmentType` VARCHAR(50) COMMENT 'نوع الالتحاق',
  `enrollmentDate` DATE COMMENT 'تاريخ الالتحاق',
  `enrollmentNumber` INT COMMENT 'رقم القيد',
  `enrollmentStatus` VARCHAR(50) COMMENT 'حالة القيد',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `studentId` BIGINT NOT NULL COMMENT 'معرف الطالب (FK → Student.studentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف الدراسي (FK → GradeCapacity.gradeLevelId)',
  `classSectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId) - اختياري (يمكن أن يكون NULL عند بداية السنة)',
  `previousSchoolId` BIGINT COMMENT 'معرف المدرسة السابقة (إن وجد)',
  `previousEnrollmentId` BIGINT COMMENT 'معرف الالتحاق السابق (لربط التحاق الطالب المتتالية)',
  `enrollmentCode` VARCHAR(50) COMMENT 'كود الالتحاق الفريد',
  `enrollmentDateGregorian` DATE COMMENT 'تاريخ الالتحاق (ميلادي)',
  `enrollmentSemester` VARCHAR(200) COMMENT 'الفصل الدراسي (الأول، الثاني، الثالث)',
  `enrollmentSource` VARCHAR(200) COMMENT 'مصدر الالتحاق (نظام القبول، استيراد، تسجيل يدوي)',
  `transferReason` VARCHAR(200) COMMENT 'سبب النقل (إن كان منقولاً)',
  `transferFromSchool` VARCHAR(200) COMMENT 'اسم المدرسة المنتقل منها',
  `transferFromCity` VARCHAR(200) COMMENT 'مدينة المدرسة المنتقل منها',
  `transferFromCountry` INT COMMENT 'دولة المدرسة المنتقل منها',
  `transferDocument` VARCHAR(200) COMMENT 'ملف قرار النقل',
  `previousGradeLevel` DECIMAL(5,2) COMMENT 'الصف الدراسي السابق',
  `previousAcademicYear` VARCHAR(200) COMMENT 'السنة الدراسية السابقة',
  `previousAverage` VARCHAR(200) COMMENT 'المعدل السابق',
  `previousGrade` DECIMAL(5,2) COMMENT 'التقدير السابق',
  `previousBehavior` VARCHAR(200) COMMENT 'السلوك السابق',
  `hasPreviousRecord` BOOLEAN COMMENT 'هل لديه ملف سابق؟',
  `previousSchoolContact` VARCHAR(200) COMMENT 'جهة اتصال المدرسة السابقة',
  `statusReason` VARCHAR(50) COMMENT 'سبب تغيير الحالة',
  `statusDate` DATE COMMENT 'تاريخ تغيير الحالة',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvedByUserId` BIGINT COMMENT 'معرف الموظف الذي اعتمد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `isActive` BOOLEAN COMMENT 'هل هذا الالتحاق نشط حالياً؟',
  `isCurrent` BOOLEAN COMMENT 'هل هذا هو الالتحاق الحالي للطالب؟',
  `enrollmentFeePaid` BIGINT COMMENT 'هل تم دفع رسوم الالتحاق؟',
  `enrollmentFeeAmount` DECIMAL(15,2) COMMENT 'مبلغ رسوم الالتحاق',
  `enrollmentFeeReceipt` DECIMAL(15,2) COMMENT 'رقم إيصال دفع الرسوم',
  `feeExemptionReason` DECIMAL(15,2) COMMENT 'سبب الإعفاء من الرسوم (إن وجد)',
  `scholarshipType` VARCHAR(50) COMMENT 'نوع المنحة الدراسية (إن وجدت)',
  `scholarshipPercentage` DECIMAL(5,2) COMMENT 'نسبة المنحة',
  `scholarshipSource` VARCHAR(200) COMMENT 'مصدر المنحة',
  `registrationComplete` VARCHAR(200) COMMENT 'هل اكتملت عملية التسجيل؟',
  `registrationCompletedAt` DATE COMMENT 'تاريخ اكتمال التسجيل',
  `documentsVerified` VARCHAR(200) COMMENT 'هل تم التحقق من الوثائق؟',
  `documentsVerifiedAt` DATE COMMENT 'تاريخ التحقق',
  `documentsVerifiedByUserId` BIGINT COMMENT 'معرف من تحقق من الوثائق',
  `documentsNotes` TEXT COMMENT 'ملاحظات حول الوثائق',
  `orientationSessionAttended` VARCHAR(200) COMMENT 'هل حضر جلسة التعريف؟',
  `orientationSessionDate` DATE COMMENT 'تاريخ جلسة التعريف',
  `contractSigned` VARCHAR(200) COMMENT 'هل تم توقيع العقد؟',
  `contractSignedDate` DATE COMMENT 'تاريخ توقيع العقد',
  `contractFilePath` VARCHAR(200) COMMENT 'مسار ملف العقد الموقع',
  `studentHandbookAcknowledged` VARCHAR(200) COMMENT 'هل أقر بدليل الطالب؟',
  `handbookAcknowledgedDate` DATE COMMENT 'تاريخ الإقرار',
  `medicalFormCompleted` VARCHAR(200) COMMENT 'هل اكتمل النموذج الطبي؟',
  `emergencyContactConfirmed` VARCHAR(200) COMMENT 'هل تم تأكيد جهات الاتصال للطوارئ؟',
  `pickupAuthorizedPersons` VARCHAR(200) COMMENT 'الأشخاص المصرح لهم باستلام الطالب (JSON)',
  `busServiceSubscribed` VARCHAR(200) COMMENT 'هل اشترك في خدمة الباص؟',
  `busRouteId` BIGINT COMMENT 'معرف مسار الباص',
  `busStopId` BIGINT COMMENT 'معرف محطة الباص',
  `mealPlanSubscribed` VARCHAR(200) COMMENT 'هل اشترك في خطة الوجبات؟',
  `mealPlanId` BIGINT COMMENT 'معرف خطة الوجبات',
  `specialMealRequirements` VARCHAR(200) COMMENT 'متطلبات غذائية خاصة',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات',
  `importBatchId` BIGINT COMMENT 'معرف دفعة الاستيراد',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  PRIMARY KEY (`studentId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`classSectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`previousSchoolId`) REFERENCES `PreviousSchool`(`...`),
  -- FOREIGN KEY (`previousEnrollmentId`) REFERENCES `PreviousEnrollment`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `ApprovedByUser`(`...`),
  -- FOREIGN KEY (`enrollmentFeePaid`) REFERENCES `EnrollmentFeePa`(`...`),
  -- FOREIGN KEY (`documentsVerifiedByUserId`) REFERENCES `DocumentsVerifiedByUser`(`...`),
  -- FOREIGN KEY (`busRouteId`) REFERENCES `BusRoute`(`...`),
  -- FOREIGN KEY (`busStopId`) REFERENCES `BusStop`(`...`),
  -- FOREIGN KEY (`mealPlanId`) REFERENCES `MealPlan`(`...`),
  -- FOREIGN KEY (`importBatchId`) REFERENCES `ImportBatch`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='الالتحاق';

-- Table: StudentDocument (وثائق الطالب)
CREATE TABLE IF NOT EXISTS `StudentDocument` (
  `documentType` VARCHAR(50) COMMENT 'نوع الوثيقة',
  `documentName` VARCHAR(200) COMMENT 'اسم الوثيقة',
  `filePath` VARCHAR(200) COMMENT 'مسار التخزين',
  `mimeType` VARCHAR(50) COMMENT 'نوع الملف',
  `isVerified` BOOLEAN COMMENT 'تم التحقق',
  `status` VARCHAR(50) COMMENT 'حالة الوثيقة',
  `uploadedAt` DATE COMMENT 'تاريخ الرفع',
  `studentId` BIGINT NOT NULL COMMENT 'معرف الطالب (FK → Student.studentId)',
  `enrollmentId` BIGINT COMMENT 'معرف الالتحاق (FK → Enrollment.enrollmentId) - اختياري (لربط الوثيقة بسنة دراسية محددة)',
  `documentCategory` VARCHAR(50) COMMENT 'فئة الوثيقة (شخصية، أكاديمية، صحية، قانونية)',
  `documentSubType` VARCHAR(50) COMMENT 'النوع الفرعي للوثيقة',
  `documentNumber` INT COMMENT 'رقم الوثيقة (مثل رقم جواز السفر، رقم الشهادة)',
  `issuingAuthority` BOOLEAN COMMENT 'جهة الإصدار',
  `issuingCountry` BOOLEAN COMMENT 'بلد الإصدار',
  `issuingCity` BOOLEAN COMMENT 'مدينة الإصدار',
  `issueDate` DATE COMMENT 'تاريخ الإصدار',
  `expiryDate` DATE COMMENT 'تاريخ انتهاء الصلاحية (إن وجد)',
  `isExpiryRequired` DATE COMMENT 'هل تتطلب الوثيقة تاريخ انتهاء؟',
  `reminderBeforeExpiry` VARCHAR(200) COMMENT 'التذكير قبل انتهاء الصلاحية (عدد الأيام)',
  `expiryNotificationSent` VARCHAR(200) COMMENT 'هل تم إرسال إشعار انتهاء الصلاحية؟',
  `expiryNotificationDate` DATE COMMENT 'تاريخ إرسال إشعار انتهاء الصلاحية',
  `documentLanguage` VARCHAR(200) COMMENT 'لغة الوثيقة',
  `isOriginal` BOOLEAN COMMENT 'هل هي الوثيقة الأصلية أم صورة؟',
  `hasTranslation` BOOLEAN COMMENT 'هل يوجد ترجمة معتمدة؟',
  `translationFilePath` VARCHAR(200) COMMENT 'مسار ملف الترجمة',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف (بايت)',
  `fileHash` VARCHAR(200) COMMENT 'قيمة تجزئة الملف (للتحقق من السلامة)',
  `filePages` VARCHAR(200) COMMENT 'عدد صفحات الملف',
  `thumbnailPath` VARCHAR(200) COMMENT 'مسار الصورة المصغرة',
  `description` TEXT COMMENT 'وصف إضافي للوثيقة',
  `tags` VARCHAR(200) COMMENT 'علامات تصنيف (للبحث)',
  `isRequired` BOOLEAN COMMENT 'هل الوثيقة إلزامية؟',
  `verificationDate` DATE COMMENT 'تاريخ التحقق',
  `verifiedByUserId` BIGINT COMMENT 'معرف الموظف الذي تحقق',
  `verificationMethod` VARCHAR(200) COMMENT 'طريقة التحقق (يدوي، آلي، مقارنة)',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب رفض الوثيقة (إن رفضت)',
  `reviewedAt` DATE COMMENT 'تاريخ المراجعة',
  `reviewedByUserId` BIGINT COMMENT 'معرف من راجع الوثيقة',
  `accessLevel` VARCHAR(50) COMMENT 'مستوى الوصول للوثيقة (عام، خاص، سري)',
  `sharedWith` VARCHAR(200) COMMENT 'الجهات المسموح لها بالاطلاع (JSON)',
  `sharedWithExternal` VARCHAR(200) COMMENT 'هل يمكن مشاركتها خارجياً؟',
  `externalShareToken` VARCHAR(200) COMMENT 'رمز المشاركة الخارجية (إن وجد)',
  `externalShareExpiry` DATE COMMENT 'تاريخ انتهاء صلاحية المشاركة',
  `downloadCount` INT COMMENT 'عدد مرات التحميل',
  `lastDownloadedAt` DATE COMMENT 'تاريخ آخر تحميل',
  `lastDownloadedByUserId` BIGINT COMMENT 'معرف آخر من حمّل الوثيقة',
  `isArchived` BOOLEAN COMMENT 'هل تمت أرشفة الوثيقة؟',
  `archivedAt` DATE COMMENT 'تاريخ الأرشفة',
  `archivedByUserId` BIGINT COMMENT 'معرف من أرشف الوثيقة',
  `archiveReason` VARCHAR(200) COMMENT 'سبب الأرشفة',
  `retentionPeriod` VARCHAR(200) COMMENT 'مدة الاحتفاظ (بالسنوات)',
  `retentionEndDate` DATE COMMENT 'تاريخ انتهاء مدة الاحتفاظ',
  `disposalDate` DATE COMMENT 'تاريخ الإتلاف المتوقع',
  `disposalStatus` VARCHAR(50) COMMENT 'حالة الإتلاف',
  `disposalMethod` VARCHAR(200) COMMENT 'طريقة الإتلاف',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات (رفع يدوي، بوابة، استيراد)',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  PRIMARY KEY (`studentId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`enrollmentId`) REFERENCES `Enrollment`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `VerifiedByUser`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `ReviewedByUser`(`...`),
  -- FOREIGN KEY (`lastDownloadedByUserId`) REFERENCES `LastDownloadedByUser`(`...`),
  -- FOREIGN KEY (`archivedByUserId`) REFERENCES `ArchivedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='وثائق الطالب';

-- Table: StudentHealthRecord (السجل الصحي)
CREATE TABLE IF NOT EXISTS `StudentHealthRecord` (
  `bloodType` VARCHAR(50) COMMENT 'فصيلة الدم',
  `height` VARCHAR(200) COMMENT 'الطول',
  `weight` VARCHAR(200) COMMENT 'الوزن',
  `chronicDiseases` VARCHAR(200) COMMENT 'أمراض مزمنة',
  `allergies` VARCHAR(200) COMMENT 'حساسيات',
  `vaccinationStatus` VARCHAR(50) COMMENT 'التطعيمات',
  `lastCheckupDate` DATE COMMENT 'آخر فحص',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `studentId` BIGINT NOT NULL COMMENT 'معرف الطالب (FK → Student.studentId)',
  `healthRecordNumber` INT COMMENT 'رقم السجل الصحي',
  `bmi` VARCHAR(200) COMMENT 'مؤشر كتلة الجسم (يُحسب آلياً من الطول والوزن)',
  `bmiStatus` VARCHAR(50) COMMENT 'حالة مؤشر كتلة الجسم (نحيف، طبيعي، زيادة وزن، سمنة)',
  `heightPercentile` VARCHAR(200) COMMENT 'النسبة المئوية للطول (حسب العمر)',
  `weightPercentile` VARCHAR(200) COMMENT 'النسبة المئوية للوزن (حسب العمر)',
  `visionLeft` VARCHAR(200) COMMENT 'نظر العين اليسرى',
  `visionRight` VARCHAR(200) COMMENT 'نظر العين اليمنى',
  `visionDate` DATE COMMENT 'تاريخ فحص النظر',
  `hearingLeft` VARCHAR(200) COMMENT 'سمع الأذن اليسرى',
  `hearingRight` VARCHAR(200) COMMENT 'سمع الأذن اليمنى',
  `hearingDate` DATE COMMENT 'تاريخ فحص السمع',
  `dentalHealth` VARCHAR(200) COMMENT 'صحة الأسنان',
  `dentalLastVisit` VARCHAR(200) COMMENT 'آخر زيارة لطبيب الأسنان',
  `dentalNotes` TEXT COMMENT 'ملاحظات عن الأسنان',
  `chronicDiseasesList` VARCHAR(200) COMMENT 'قائمة الأمراض المزمنة (JSON)',
  `chronicDiseasesDetails` VARCHAR(200) COMMENT 'تفاصيل الأمراض المزمنة (نص)',
  `chronicDiseasesMedications` VARCHAR(200) COMMENT 'أدوية الأمراض المزمنة',
  `chronicDiseasesDoctor` VARCHAR(200) COMMENT 'الطبيب المعالج',
  `chronicDiseasesHospital` VARCHAR(200) COMMENT 'المستشفى المتابع',
  `allergiesList` VARCHAR(200) COMMENT 'قائمة الحساسيات (JSON)',
  `allergiesDetails` VARCHAR(200) COMMENT 'تفاصيل الحساسيات',
  `allergiesReactions` VARCHAR(200) COMMENT 'ردود الفعل التحسسية',
  `allergiesMedications` VARCHAR(200) COMMENT 'أدوية الحساسية',
  `allergiesEmergencyTreatment` VARCHAR(200) COMMENT 'العلاج الطارئ للحساسية',
  `hasEpiPen` BOOLEAN COMMENT 'هل لديه حاقن إبينفرين؟',
  `vaccinationsList` VARCHAR(200) COMMENT 'قائمة التطعيمات (JSON)',
  `lastVaccinationDate` DATE COMMENT 'تاريخ آخر تطعيم',
  `nextVaccinationDate` DATE COMMENT 'تاريخ التطعيم القادم',
  `vaccinationReminder` VARCHAR(200) COMMENT 'تذكير بالتطعيم القادم',
  `surgeries` VARCHAR(200) COMMENT 'العمليات الجراحية السابقة (JSON)',
  `surgeriesDetails` VARCHAR(200) COMMENT 'تفاصيل العمليات',
  `medications` VARCHAR(200) COMMENT 'الأدوية المنتظمة (JSON)',
  `currentMedications` VARCHAR(200) COMMENT 'الأدوية الحالية',
  `medicationDosage` VARCHAR(200) COMMENT 'جرعات الأدوية',
  `medicationSchedule` VARCHAR(200) COMMENT 'جدول تناول الأدوية',
  `medicalConditions` VARCHAR(200) COMMENT 'حالات طبية أخرى',
  `physicalDisabilities` VARCHAR(200) COMMENT 'إعاقات جسدية',
  `learningDisabilities` VARCHAR(200) COMMENT 'صعوبات تعلم',
  `speechIssues` VARCHAR(200) COMMENT 'مشاكل النطق',
  `psychologicalConditions` VARCHAR(200) COMMENT 'حالات نفسية',
  `psychologicalSupport` VARCHAR(200) COMMENT 'الدعم النفسي المقدم',
  `dietaryRestrictions` VARCHAR(200) COMMENT 'قيود غذائية',
  `foodAllergies` VARCHAR(200) COMMENT 'حساسيات غذائية',
  `mealPlanRequired` VARCHAR(200) COMMENT 'هل يحتاج خطة غذائية خاصة؟',
  `physicalActivityRestrictions` VARCHAR(200) COMMENT 'قيود على النشاط البدني',
  `sportsExemption` VARCHAR(200) COMMENT 'إعفاء من الرياضة؟',
  `sportsExemptionReason` VARCHAR(200) COMMENT 'سبب الإعفاء من الرياضة',
  `sportsExemptionDocument` VARCHAR(200) COMMENT 'مستند إعفاء الرياضة',
  `emergencyContactName` VARCHAR(200) COMMENT 'اسم جهة الاتصال في الطوارئ الصحية',
  `emergencyContactPhone` VARCHAR(20) COMMENT 'هاتف جهة الاتصال في الطوارئ الصحية',
  `emergencyContactRelation` VARCHAR(200) COMMENT 'صلة القرابة مع جهة الاتصال',
  `primaryPhysician` VARCHAR(200) COMMENT 'اسم الطبيب المعالج',
  `primaryPhysicianPhone` VARCHAR(20) COMMENT 'هاتف الطبيب المعالج',
  `primaryPhysicianClinic` VARCHAR(200) COMMENT 'عيادة الطبيب المعالج',
  `preferredHospital` VARCHAR(200) COMMENT 'المستشفى المفضل',
  `healthInsuranceProvider` VARCHAR(200) COMMENT 'مزود التأمين الصحي',
  `healthInsuranceNumber` INT COMMENT 'رقم وثيقة التأمين',
  `healthInsuranceExpiry` DATE COMMENT 'تاريخ انتهاء التأمين',
  `insuranceCardImage` VARCHAR(200) COMMENT 'صورة بطاقة التأمين',
  `consentToShare` VARCHAR(200) COMMENT 'موافقة على مشاركة المعلومات الصحية',
  `consentSignedBy` VARCHAR(200) COMMENT 'موقع الموافقة',
  `consentDate` DATE COMMENT 'تاريخ الموافقة',
  `consentDocument` VARCHAR(200) COMMENT 'مستند الموافقة',
  `lastVisitDate` DATE COMMENT 'تاريخ آخر زيارة للعيادة',
  `lastVisitReason` VARCHAR(200) COMMENT 'سبب آخر زيارة',
  `lastVisitDiagnosis` VARCHAR(200) COMMENT 'تشخيص آخر زيارة',
  `visitCount` INT COMMENT 'عدد زيارات العيادة',
  `hospitalizationHistory` DATE COMMENT 'تاريخ التنويم في المستشفى (JSON)',
  `healthNotes` TEXT COMMENT 'ملاحظات صحية عامة',
  `healthAlerts` VARCHAR(200) COMMENT 'تنبيهات صحية (JSON)',
  `activeAlerts` VARCHAR(200) COMMENT 'تنبيهات نشطة (نعم/لا)',
  `isSpecialNeedsConfirmed` BOOLEAN COMMENT 'هل الاحتياجات الخاصة مؤكدة طبياً؟',
  `specialNeedsDiagnosis` VARCHAR(200) COMMENT 'تشخيص الاحتياجات الخاصة',
  `specialNeedsDoctor` VARCHAR(200) COMMENT 'الطبيب المشخص',
  `specialNeedsDate` DATE COMMENT 'تاريخ التشخيص',
  `specialNeedsReport` VARCHAR(200) COMMENT 'تقرير الاحتياجات الخاصة',
  `requiresNurse` VARCHAR(200) COMMENT 'هل يحتاج متابعة ممرض؟',
  `requiresMedicationAtSchool` VARCHAR(200) COMMENT 'هل يحتاج دواء أثناء الدوام؟',
  `medicationAtSchoolDetails` VARCHAR(200) COMMENT 'تفاصيل الدواء في المدرسة',
  `medicationStorage` VARCHAR(200) COMMENT 'مكان تخزين الدواء',
  `medicationAuthorizedPerson` VARCHAR(200) COMMENT 'المسؤول عن إعطاء الدواء',
  `healthDataVerifiedBy` VARCHAR(200) COMMENT 'تم التحقق من قبل',
  `healthDataVerifiedAt` DATE COMMENT 'تاريخ التحقق',
  `healthDataVerifiedStatus` VARCHAR(50) COMMENT 'حالة التحقق',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف المستخدم الذي حذف السجل',
  PRIMARY KEY (`studentId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='السجل الصحي';

-- Table: StudentTransportPreference (تفضيلات النقل)
CREATE TABLE IF NOT EXISTS `StudentTransportPreference` (
  `preferenceId` BIGINT NOT NULL COMMENT 'رقم تعريف فريد للتفضيل (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `transportType` VARCHAR(50) COMMENT 'نوع النقل (حافلة مدرسية، سيارة خاصة، مشي، نقل عام، أخرى)',
  `busSubscriptionId` BIGINT COMMENT 'رقم اشتراك الباص (إن وجد)',
  `preferredBusRouteId` BIGINT COMMENT 'معرف خط الباص المفضل (FK → Transportation.routeId)',
  `preferredBusStopId` BIGINT COMMENT 'معرف محطة الباص المفضلة',
  `alternativeBusRouteId` BIGINT COMMENT 'معرف خط الباص البديل',
  `alternativeBusStopId` BIGINT COMMENT 'معرف محطة الباص البديلة',
  `pickupPoint` VARCHAR(200) COMMENT 'نقطة الالتقاء (عنوان محدد)',
  `pickupLatitude` VARCHAR(200) COMMENT 'خط عرض نقطة الالتقاء',
  `pickupLongitude` VARCHAR(200) COMMENT 'خط طول نقطة الالتقاء',
  `pickupTimePreferred` TIME COMMENT 'وقت الالتقاء المفضل',
  `dropoffTimePreferred` TIME COMMENT 'وقت النزول المفضل',
  `morningPickup` VARCHAR(200) COMMENT 'هل يستخدم النقل في الصباح؟',
  `afternoonDropoff` VARCHAR(200) COMMENT 'هل يستخدم النقل في المساء؟',
  `daysOfWeek` VARCHAR(200) COMMENT 'أيام الأسبوع التي يحتاج فيها النقل (JSON)',
  `requiresEscort` VARCHAR(200) COMMENT 'هل يحتاج مرافق؟',
  `escortName` VARCHAR(200) COMMENT 'اسم المرافق (إن وجد)',
  `escortPhone` VARCHAR(20) COMMENT 'هاتف المرافق',
  `escortRelation` VARCHAR(200) COMMENT 'صلة القرابة مع المرافق',
  `specialNeedsTransport` VARCHAR(200) COMMENT 'هل يحتاج وسائل نقل خاصة لذوي الاحتياجات؟',
  `specialNeedsTransportDetails` VARCHAR(200) COMMENT 'تفاصيل احتياجات النقل الخاصة',
  `wheelchairAccessible` VARCHAR(200) COMMENT 'هل يحتاج حافلة مجهزة لكراسي متحركة؟',
  `medicalEquipmentTransport` VARCHAR(200) COMMENT 'هل يحتاج نقل معدات طبية؟',
  `medicalEquipmentDetails` VARCHAR(200) COMMENT 'تفاصيل المعدات الطبية',
  `subscriptionStatus` VARCHAR(50) COMMENT 'حالة الاشتراك (نشط، معلق، ملغي، قيد الانتظار)',
  `subscriptionStartDate` DATE COMMENT 'تاريخ بدء الاشتراك',
  `subscriptionEndDate` DATE COMMENT 'تاريخ انتهاء الاشتراك',
  `subscriptionFee` DECIMAL(15,2) COMMENT 'رسوم الاشتراك',
  `paymentStatus` VARCHAR(50) COMMENT 'حالة الدفع',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع',
  `paymentDate` DATE COMMENT 'تاريخ الدفع',
  `contractSigned` VARCHAR(200) COMMENT 'هل تم توقيع عقد النقل؟',
  `contractFilePath` VARCHAR(200) COMMENT 'مسار ملف عقد النقل',
  `emergencyContactName` VARCHAR(200) COMMENT 'اسم جهة الاتصال في حالات الطوارئ أثناء النقل',
  `emergencyContactPhone` VARCHAR(20) COMMENT 'هاتف جهة الاتصال',
  `authorizedToPickup` VARCHAR(200) COMMENT 'الأشخاص المصرح لهم باستلام الطالب (JSON)',
  `alternativeTransportArrangements` VARCHAR(200) COMMENT 'ترتيبات نقل بديلة (نص)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  PRIMARY KEY (`preferenceId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`busSubscriptionId`) REFERENCES `BusSubscription`(`...`),
  -- FOREIGN KEY (`preferredBusRouteId`) REFERENCES `Transportation`(`...`),
  -- FOREIGN KEY (`preferredBusStopId`) REFERENCES `PreferredBusStop`(`...`),
  -- FOREIGN KEY (`alternativeBusRouteId`) REFERENCES `AlternativeBusRoute`(`...`),
  -- FOREIGN KEY (`alternativeBusStopId`) REFERENCES `AlternativeBusStop`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تفضيلات النقل';

-- Table: StudentInventory (عهدة الطالب)
CREATE TABLE IF NOT EXISTS `StudentInventory` (
  `inventoryId` BIGINT NOT NULL COMMENT 'رقم تعريف فريد للعهدة (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `itemType` VARCHAR(50) COMMENT 'نوع العنصر (كتاب، زي مدرسي، أدوات، جهاز، أخرى)',
  `itemId` BIGINT COMMENT 'معرف العنصر (يرتبط بجدول الأصول Asset أو جدول خاص بالكتب)',
  `itemCode` VARCHAR(50) COMMENT 'كود العنصر',
  `itemName` VARCHAR(200) COMMENT 'اسم العنصر',
  `itemDescription` TEXT COMMENT 'وصف العنصر',
  `quantity` VARCHAR(200) COMMENT 'الكمية المسلمة',
  `unitOfMeasure` VARCHAR(200) COMMENT 'وحدة القياس (قطعة، كتاب، الخ)',
  `conditionAtDelivery` VARCHAR(200) COMMENT 'حالة العنصر عند التسليم (جديد، جيد، مستعمل)',
  `conditionNotes` TEXT COMMENT 'ملاحظات عن الحالة',
  `deliveryDate` DATE COMMENT 'تاريخ التسليم',
  `deliveredByUserId` BIGINT COMMENT 'معرف الموظف المسَلِّم',
  `receivedBy` VARCHAR(200) COMMENT 'المستلم (الطالب أو ولي الأمر)',
  `receivedByRelation` VARCHAR(200) COMMENT 'صلة المستلم بالطالب',
  `receiptSignature` VARCHAR(200) COMMENT 'توقيع الاستلام (إلكتروني أو مسار صورة)',
  `expectedReturnDate` DATE COMMENT 'تاريخ الإرجاع المتوقع',
  `actualReturnDate` DATE COMMENT 'تاريخ الإرجاع الفعلي',
  `conditionAtReturn` VARCHAR(200) COMMENT 'حالة العنصر عند الإرجاع',
  `returnNotes` TEXT COMMENT 'ملاحظات عن الإرجاع',
  `returnedToUserId` BIGINT COMMENT 'معرف الموظف المستلم للإرجاع',
  `returnReceiptSignature` VARCHAR(200) COMMENT 'توقيع استلام الإرجاع',
  `isReturned` BOOLEAN COMMENT 'هل تم الإرجاع؟',
  `isDamaged` BOOLEAN COMMENT 'هل العنصر تالف؟',
  `damageDescription` TEXT COMMENT 'وصف التلف',
  `damageDate` DATE COMMENT 'تاريخ اكتشاف التلف',
  `damageReportedByUserId` BIGINT COMMENT 'معرف من أبلغ عن التلف',
  `damagePhotos` VARCHAR(200) COMMENT 'صور التلف (مسار الملف)',
  `isLost` BOOLEAN COMMENT 'هل العنصر مفقود؟',
  `lostDate` DATE COMMENT 'تاريخ الفقدان',
  `lostReportedByUserId` BIGINT COMMENT 'معرف من أبلغ عن الفقدان',
  `lostNotes` TEXT COMMENT 'ملاحظات عن الفقدان',
  `penaltyAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة (إن وجدت)',
  `penaltyStatus` VARCHAR(50) COMMENT 'حالة الغرامة (مستحقة، مدفوعة، معفاة)',
  `penaltyPaidDate` DATE COMMENT 'تاريخ دفع الغرامة',
  `penaltyReceiptNumber` INT COMMENT 'رقم إيصال دفع الغرامة',
  `isExempt` BOOLEAN COMMENT 'هل الطالب معفى من الغرامة؟',
  `exemptionReason` VARCHAR(200) COMMENT 'سبب الإعفاء',
  `exemptionApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد الإعفاء',
  `replacementRequired` VARCHAR(200) COMMENT 'هل يتطلب استبدال؟',
  `replacementDate` DATE COMMENT 'تاريخ الاستبدال',
  `replacementItemId` BIGINT COMMENT 'معرف العنصر البديل',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  PRIMARY KEY (`inventoryId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`itemId`) REFERENCES `Item`(`...`),
  -- FOREIGN KEY (`deliveredByUserId`) REFERENCES `DeliveredByUser`(`...`),
  -- FOREIGN KEY (`returnedToUserId`) REFERENCES `ReturnedToUser`(`...`),
  -- FOREIGN KEY (`damageReportedByUserId`) REFERENCES `DamageReportedByUser`(`...`),
  -- FOREIGN KEY (`lostReportedByUserId`) REFERENCES `LostReportedByUser`(`...`),
  -- FOREIGN KEY (`exemptionApprovedByUserId`) REFERENCES `ExemptionApprovedByUser`(`...`),
  -- FOREIGN KEY (`replacementItemId`) REFERENCES `ReplacementItem`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='عهدة الطالب';

-- Table: Transportation (المواصلات)
CREATE TABLE IF NOT EXISTS `Transportation` (
  `transportId` BIGINT NOT NULL COMMENT 'رقم تعريف فريد (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `routeId` BIGINT COMMENT 'معرف المسار',
  `routeName` VARCHAR(200) COMMENT 'اسم المسار',
  `routeCode` VARCHAR(50) COMMENT 'كود المسار',
  `routeDescription` TEXT COMMENT 'وصف المسار',
  `busId` BIGINT COMMENT 'معرف الحافلة (يرتبط بجدول الأصول Asset للأصول المنقولة)',
  `busPlateNumber` INT COMMENT 'رقم لوحة الحافلة',
  `busCapacity` VARCHAR(200) COMMENT 'سعة الحافلة',
  `busType` VARCHAR(50) COMMENT 'نوع الحافلة (صغيرة، متوسطة، كبيرة)',
  `busFeatures` VARCHAR(200) COMMENT 'ميزات الحافلة (مكيف، مجهزة لذوي الاحتياجات، الخ)',
  `driverId` BIGINT COMMENT 'معرف السائق (FK → Employee.employeeId)',
  `driverName` VARCHAR(200) COMMENT 'اسم السائق',
  `driverLicenseNumber` INT COMMENT 'رقم رخصة السائق',
  `driverPhone` VARCHAR(20) COMMENT 'هاتف السائق',
  `supervisorId` BIGINT COMMENT 'معرف المشرف (FK → Employee.employeeId)',
  `supervisorName` VARCHAR(200) COMMENT 'اسم المشرف',
  `shiftId` BIGINT COMMENT 'معرف الفترة (FK → SchoolShiftSetting.shiftId)',
  `tripType` VARCHAR(50) COMMENT 'نوع الرحلة (صباحية، مسائية، جميع الأيام)',
  `startTime` TIME COMMENT 'وقت بدء الرحلة',
  `endTime` TIME COMMENT 'وقت انتهاء الرحلة',
  `estimatedDuration` VARCHAR(200) COMMENT 'المدة التقديرية للرحلة',
  `stops` VARCHAR(200) COMMENT 'محطات التوقف (JSON)',
  `stopPoints` VARCHAR(200) COMMENT 'نقاط التوقف (عناوين وإحداثيات)',
  `stopSequence` VARCHAR(200) COMMENT 'تسلسل المحطات',
  `estimatedArrivalAtStop` VARCHAR(200) COMMENT 'وقت الوصول المتوقع لكل محطة',
  `actualArrivalAtStop` VARCHAR(200) COMMENT 'وقت الوصول الفعلي لكل محطة',
  `studentsAssigned` VARCHAR(200) COMMENT 'الطلاب المخصصين لهذه الحافلة (عدد)',
  `maxStudents` VARCHAR(200) COMMENT 'الحد الأقصى للطلاب',
  `currentStudents` VARCHAR(200) COMMENT 'عدد الطلاب الحاليين',
  `routeMap` VARCHAR(200) COMMENT 'خريطة المسار (مسار ملف الصورة أو الرابط)',
  `routePolyline` VARCHAR(200) COMMENT 'مسار الرحلة للإحداثيات (للعرض على الخريطة)',
  `isActive` BOOLEAN COMMENT 'هل المسار نشط؟',
  `status` VARCHAR(50) COMMENT 'حالة الخدمة (نشطة، متوقفة، كاملة)',
  `operatorCompany` VARCHAR(200) COMMENT 'الشركة المشغلة (إن وجدت)',
  `contractId` BIGINT COMMENT 'معرف العقد مع الشركة المشغلة',
  `contractStartDate` DATE COMMENT 'تاريخ بداية العقد',
  `contractEndDate` DATE COMMENT 'تاريخ نهاية العقد',
  `serviceFee` DECIMAL(15,2) COMMENT 'رسوم الخدمة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أنشأ السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `updatedByUserId` BIGINT COMMENT 'معرف آخر مستخدم عدل السجل',
  `isDeleted` BOOLEAN COMMENT 'حالة الحذف المنطقي',
  PRIMARY KEY (`transportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`routeId`) REFERENCES `Route`(`...`),
  -- FOREIGN KEY (`busId`) REFERENCES `Bus`(`...`),
  -- FOREIGN KEY (`driverId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`supervisorId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`contractId`) REFERENCES `Contract`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المواصلات';

-- Table: Course (المواد والمناهج الدراسية)
CREATE TABLE IF NOT EXISTS `Course` (
  `courseId` BIGINT NOT NULL COMMENT 'معرف المادة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `curriculumId` BIGINT COMMENT 'معرف المنهج (FK → Curriculum.curriculumId) - اختياري',
  `departmentId` BIGINT COMMENT 'معرف القسم المسؤول عن المادة (FK → SchoolDepartment.deptId)',
  `courseCode` VARCHAR(50) COMMENT 'رمز المادة (فريد)',
  `courseNameAr` VARCHAR(200) COMMENT 'اسم المادة بالعربية',
  `courseNameEn` VARCHAR(200) COMMENT 'اسم المادة بالإنجليزية',
  `courseNameArNormalized` VARCHAR(200) COMMENT 'الاسم بالعربية للتطبيع',
  `courseNameEnNormalized` VARCHAR(200) COMMENT 'الاسم بالإنجليزية للتطبيع',
  `shortNameAr` VARCHAR(200) COMMENT 'الاسم المختصر بالعربية',
  `shortNameEn` VARCHAR(200) COMMENT 'الاسم المختصر بالإنجليزية',
  `courseType` VARCHAR(50) COMMENT 'نوع المادة (إجباري، اختياري، تأسيسي، نشاط، تقوية)',
  `category` VARCHAR(50) COMMENT 'فئة المادة (علمي، أدبي، ديني، تقني، رياضي)',
  `gradeLevelId` BIGINT COMMENT 'الصف الدراسي (FK → GradeCapacity.gradeLevelId)',
  `stage` VARCHAR(200) COMMENT 'المرحلة (ابتدائي، متوسط، ثانوي)',
  `track` VARCHAR(200) COMMENT 'المسار (علمي، أدبي، إداري، عام)',
  `creditHours` VARCHAR(200) COMMENT 'الساعات المعتمدة',
  `theoreticalHours` VARCHAR(200) COMMENT 'ساعات نظرية',
  `practicalHours` VARCHAR(200) COMMENT 'ساعات عملية',
  `totalWeeks` VARCHAR(200) COMMENT 'عدد الأسابيع',
  `minPassingGrade` DECIMAL(5,2) COMMENT 'درجة النجاح',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى',
  `weight` VARCHAR(200) COMMENT 'وزن المادة (في المعدل)',
  `hasFinalExam` BOOLEAN COMMENT 'هل لها اختبار نهائي؟',
  `hasMidtermExam` BOOLEAN COMMENT 'هل لها اختبار منتصف الفصل؟',
  `hasPracticalExam` BOOLEAN COMMENT 'هل لها اختبار عملي؟',
  `hasOralExam` BOOLEAN COMMENT 'هل لها اختبار شفوي؟',
  `hasProject` BOOLEAN COMMENT 'هل يتضمن مشروعاً؟',
  `hasActivity` BOOLEAN COMMENT 'هل يتضمن أنشطة؟',
  `gradingMethod` VARCHAR(200) COMMENT 'طريقة التقييم (نظام درجات، ناجح/راسب، تقدير)',
  `gradeScale` DECIMAL(5,2) COMMENT 'سلم التقدير المستخدم',
  `prerequisites` VARCHAR(200) COMMENT 'متطلبات سابقة (JSON)',
  `coRequisites` VARCHAR(200) COMMENT 'متطلبات مصاحبة (JSON)',
  `learningOutcomes` VARCHAR(200) COMMENT 'مخرجات التعلم (نص)',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `textbook` VARCHAR(200) COMMENT 'الكتاب الدراسي',
  `textbookISBN` VARCHAR(200) COMMENT 'رقم ISBN للكتاب',
  `textbookAuthor` VARCHAR(200) COMMENT 'مؤلف الكتاب',
  `textbookPublisher` VARCHAR(200) COMMENT 'الناشر',
  `textbookEdition` VARCHAR(200) COMMENT 'الطبعة',
  `textbookYear` VARCHAR(200) COMMENT 'سنة النشر',
  `references` VARCHAR(200) COMMENT 'المراجع (JSON)',
  `referenceLinks` VARCHAR(200) COMMENT 'روابط مرجعية (JSON)',
  `syllabus` VARCHAR(200) COMMENT 'المنهج التفصيلي (مسار ملف PDF)',
  `syllabusLastUpdate` DATE COMMENT 'آخر تحديث للمنهج',
  `teachingObjectives` VARCHAR(200) COMMENT 'الأهداف التعليمية',
  `teachingStrategies` DECIMAL(5,2) COMMENT 'استراتيجيات التدريس',
  `assessmentMethods` VARCHAR(200) COMMENT 'طرق التقييم',
  `resourcesNeeded` VARCHAR(200) COMMENT 'الموارد المطلوبة',
  `isActive` BOOLEAN COMMENT 'مفعلة؟',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  PRIMARY KEY (`courseId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`curriculumId`) REFERENCES `Curriculum`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المواد والمناهج الدراسية';

-- Table: Curriculum (المنهج الدراسي)
CREATE TABLE IF NOT EXISTS `Curriculum` (
  `curriculumId` BIGINT NOT NULL COMMENT 'معرف المنهج (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `curriculumCode` VARCHAR(50) COMMENT 'رمز المنهج',
  `curriculumNameAr` VARCHAR(200) COMMENT 'اسم المنهج بالعربية',
  `curriculumNameEn` VARCHAR(200) COMMENT 'اسم المنهج بالإنجليزية',
  `curriculumType` VARCHAR(50) COMMENT 'نوع المنهج (وطني، دولي، أمريكي، بريطاني، فرنسي)',
  `educationSystem` VARCHAR(200) COMMENT 'النظام التعليمي (عام، تحفيظ، دولي)',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `gradeLevels` DECIMAL(5,2) COMMENT 'الصفوف التي يغطيها المنهج (JSON)',
  `subjectsCount` INT COMMENT 'عدد المواد في المنهج',
  `totalCreditHours` VARCHAR(200) COMMENT 'إجمالي الساعات المعتمدة',
  `durationYears` VARCHAR(200) COMMENT 'مدة المنهج بالسنوات',
  `version` VARCHAR(200) COMMENT 'إصدار المنهج',
  `versionDate` DATE COMMENT 'تاريخ الإصدار',
  `approvedBy` VARCHAR(200) COMMENT 'جهة الاعتماد',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalDocument` VARCHAR(200) COMMENT 'مستند الاعتماد',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `startDate` DATE COMMENT 'تاريخ بدء العمل بالمنهج',
  `endDate` DATE COMMENT 'تاريخ انتهاء العمل بالمنهج (إن وجد)',
  `isDefault` BOOLEAN COMMENT 'هل هو المنهج الافتراضي للمدرسة؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`curriculumId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المنهج الدراسي';

-- Table: CoursePlan (الخطة الدراسية للمادة)
CREATE TABLE IF NOT EXISTS `CoursePlan` (
  `planId` BIGINT NOT NULL COMMENT 'معرف الخطة (المفتاح الرئيسي)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `teacherId` BIGINT COMMENT 'معرف المعلم المسؤول (FK → Employee.employeeId)',
  `gradeLevelId` BIGINT COMMENT 'الصف الدراسي (FK → GradeCapacity.gradeLevelId)',
  `planCode` VARCHAR(50) COMMENT 'رمز الخطة',
  `planVersion` VARCHAR(200) COMMENT 'إصدار الخطة',
  `totalWeeks` VARCHAR(200) COMMENT 'إجمالي الأسابيع',
  `teachingWeeks` VARCHAR(200) COMMENT 'أسابيع التدريس الفعلية',
  `revisionWeeks` VARCHAR(200) COMMENT 'أسابيع المراجعة',
  `examWeeks` VARCHAR(200) COMMENT 'أسابيع الاختبارات',
  `weeklyPlan` VARCHAR(200) COMMENT 'الخطة الأسبوعية (JSON) - تحتوي على موضوع كل أسبوع',
  `topics` VARCHAR(200) COMMENT 'المواضيع الرئيسية (JSON)',
  `learningOutcomes` VARCHAR(200) COMMENT 'مخرجات التعلم لهذا الفصل',
  `resources` VARCHAR(200) COMMENT 'الموارد المستخدمة (JSON)',
  `assessments` VARCHAR(200) COMMENT 'التقييمات المخططة (JSON)',
  `activities` VARCHAR(200) COMMENT 'الأنشطة المخططة (JSON)',
  `startDate` DATE COMMENT 'تاريخ بدء الخطة',
  `endDate` DATE COMMENT 'تاريخ انتهاء الخطة',
  `isCompleted` BOOLEAN COMMENT 'هل اكتملت الخطة؟',
  `completionPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز (يُحسب آلياً)',
  `actualProgress` VARCHAR(200) COMMENT 'التقدم الفعلي (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `approvedBy` VARCHAR(200) COMMENT 'معتمد من',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `isActive` BOOLEAN COMMENT 'مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`planId`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`teacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الخطة الدراسية للمادة';

-- Table: ClassSection (الشعب)
CREATE TABLE IF NOT EXISTS `ClassSection` (
  `sectionId` BIGINT NOT NULL COMMENT 'معرف الشعبة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `sectionCode` VARCHAR(50) COMMENT 'رمز الشعبة',
  `sectionNameAr` VARCHAR(200) COMMENT 'اسم الشعبة بالعربية',
  `sectionNameEn` VARCHAR(200) COMMENT 'اسم الشعبة بالإنجليزية',
  `sectionType` VARCHAR(50) COMMENT 'نوع الشعبة (عامة، خاصة، تقوية)',
  `capacity` VARCHAR(200) COMMENT 'السعة القصوى للشعبة',
  `currentStudents` VARCHAR(200) COMMENT 'عدد الطلاب الحاليين (يُحسب آلياً)',
  `availableSeats` VARCHAR(200) COMMENT 'المقاعد المتاحة (يُحسب آلياً)',
  `gender` VARCHAR(200) COMMENT 'جنس الطلاب في الشعبة (بنين، بنات، مختلط) - إذا كانت المدرسة مختلطة',
  `shiftId` BIGINT COMMENT 'معرف الفترة (صباحي، مسائي) (FK → SchoolShiftSetting.shiftId)',
  `classroomId` BIGINT COMMENT 'معرف القاعة الرئيسية (FK → Classroom.classroomId) - اختياري',
  `homeroomTeacherId` BIGINT COMMENT 'معرف معلم الفصل (FK → Employee.employeeId)',
  `assistantTeacherId` BIGINT COMMENT 'معرف المعلم المساعد (إن وجد)',
  `supervisorId` BIGINT COMMENT 'معرف المشرف على الشعبة',
  `isGraduating` BOOLEAN COMMENT 'شعبة تخرج؟',
  `isActive` BOOLEAN COMMENT 'مفعلة؟',
  `status` VARCHAR(50) COMMENT 'حالة الشعبة (نشطة، مكتملة، ملغاة)',
  `openingDate` DATE COMMENT 'تاريخ افتتاح الشعبة',
  `closingDate` DATE COMMENT 'تاريخ إغلاق الشعبة',
  `location` VARCHAR(200) COMMENT 'موقع الشعبة (مبنى، طابق)',
  `colorCode` VARCHAR(50) COMMENT 'رمز لوني للتمييز',
  `scheduleType` VARCHAR(50) COMMENT 'نوع الجدول (أسبوعي، دوري)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`sectionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`classroomId`) REFERENCES `Classroom`(`...`),
  -- FOREIGN KEY (`homeroomTeacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assistantTeacherId`) REFERENCES `AssistantTeacher`(`...`),
  -- FOREIGN KEY (`supervisorId`) REFERENCES `Supervisor`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الشعب';

-- Table: CourseRegistration (تسجيل المواد)
CREATE TABLE IF NOT EXISTS `CourseRegistration` (
  `registrationId` BIGINT NOT NULL COMMENT 'معرف التسجيل (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `enrollmentId` BIGINT COMMENT 'معرف الالتحاق (FK → Enrollment.enrollmentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `sectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `teacherId` BIGINT COMMENT 'معرف المعلم (FK → Employee.employeeId)',
  `registrationDate` DATE COMMENT 'تاريخ التسجيل',
  `registrationType` VARCHAR(50) COMMENT 'نوع التسجيل (عادي، إعادة، تحسين، استثنائي)',
  `registrationStatus` VARCHAR(50) COMMENT 'حالة التسجيل (مؤقت، مؤكد، منسحب، مكتمل)',
  `registrationSource` VARCHAR(200) COMMENT 'مصدر التسجيل (يدوي، تلقائي، استيراد)',
  `isApproved` BOOLEAN COMMENT 'هل تم اعتماد التسجيل؟',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد التسجيل',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `isRepeated` BOOLEAN COMMENT 'مادة معادة؟',
  `repeatCount` INT COMMENT 'عدد الإعادة',
  `previousRegistrationId` BIGINT COMMENT 'معرف التسجيل السابق لنفس المادة',
  `previousGrade` DECIMAL(5,2) COMMENT 'الدرجة السابقة',
  `withdrawalDate` DATE COMMENT 'تاريخ الانسحاب',
  `withdrawalReason` VARCHAR(200) COMMENT 'سبب الانسحاب',
  `withdrawalApprovedBy` VARCHAR(200) COMMENT 'من اعتمد الانسحاب',
  `isPassed` BOOLEAN COMMENT 'ناجح؟',
  `passDate` DATE COMMENT 'تاريخ النجاح',
  `finalGrade` DECIMAL(5,2) COMMENT 'الدرجة النهائية',
  `gradeLetter` DECIMAL(5,2) COMMENT 'الرمز (A+, A, B+, ...)',
  `gradePoints` DECIMAL(5,2) COMMENT 'النقاط',
  `percentage` DECIMAL(5,2) COMMENT 'النسبة المئوية',
  `gradeValue` DECIMAL(5,2) COMMENT 'قيمة الدرجة العددية',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى للمادة',
  `minPassingGrade` DECIMAL(5,2) COMMENT 'درجة النجاح',
  `isGraded` BOOLEAN COMMENT 'هل تم رصد الدرجة؟',
  `gradedByUserId` BIGINT COMMENT 'معرف من رصد الدرجة',
  `gradedAt` DECIMAL(5,2) COMMENT 'وقت رصد الدرجة',
  `gradeApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد الدرجة',
  `gradeApprovedAt` DECIMAL(5,2) COMMENT 'وقت اعتماد الدرجة',
  `gradeStatus` DECIMAL(5,2) COMMENT 'حالة الدرجة (مسودة، معتمدة، معدلة)',
  `attendanceRate` DECIMAL(5,2) COMMENT 'نسبة الحضور',
  `attendancePercentage` DECIMAL(5,2) COMMENT 'نسبة حضور المادة',
  `totalAbsences` VARCHAR(200) COMMENT 'إجمالي الغيابات',
  `excusedAbsences` VARCHAR(200) COMMENT 'غيابات بعذر',
  `unexcusedAbsences` VARCHAR(200) COMMENT 'غيابات بدون عذر',
  `isEligibleForExam` BOOLEAN COMMENT 'هل يستحق دخول الاختبار؟',
  `ineligibilityReason` VARCHAR(200) COMMENT 'سبب عدم الاستحقاق',
  `gpaContribution` VARCHAR(200) COMMENT 'مساهمة المادة في المعدل',
  `gpaBefore` VARCHAR(200) COMMENT 'المعدل قبل المادة',
  `gpaAfter` VARCHAR(200) COMMENT 'المعدل بعد المادة',
  `termWorkGrade` DECIMAL(5,2) COMMENT 'درجة الأعمال الفصلية',
  `midtermGrade` DECIMAL(5,2) COMMENT 'درجة منتصف الفصل',
  `practicalGrade` DECIMAL(5,2) COMMENT 'درجة العملي',
  `oralGrade` DECIMAL(5,2) COMMENT 'درجة الشفوي',
  `finalExamGrade` DECIMAL(5,2) COMMENT 'درجة الاختبار النهائي',
  `projectGrade` DECIMAL(5,2) COMMENT 'درجة المشروع',
  `activityGrade` DECIMAL(5,2) COMMENT 'درجة النشاط',
  `gradesBreakdown` DECIMAL(5,2) COMMENT 'تفاصيل الدرجات (JSON)',
  `gradeComponents` DECIMAL(5,2) COMMENT 'مكونات الدرجة حسب الخطة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`registrationId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`enrollmentId`) REFERENCES `Enrollment`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`sectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`teacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `ApprovedByUser`(`...`),
  -- FOREIGN KEY (`previousRegistrationId`) REFERENCES `PreviousRegistration`(`...`),
  -- FOREIGN KEY (`gradedByUserId`) REFERENCES `GradedByUser`(`...`),
  -- FOREIGN KEY (`gradeApprovedByUserId`) REFERENCES `GradeApprovedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تسجيل المواد';

-- Table: Grade (الدرجات)
CREATE TABLE IF NOT EXISTS `Grade` (
  `gradeId` BIGINT NOT NULL COMMENT 'معرف الدرجة (المفتاح الرئيسي)',
  `registrationId` BIGINT COMMENT 'معرف تسجيل المادة (FK → CourseRegistration.registrationId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل (FK → SchoolSemester.semesterId)',
  `gradeType` DECIMAL(5,2) COMMENT 'نوع الدرجة (اختبار قصير، واجب، نشاط، مشاركة، مشروع، اختبار شهري، اختبار نهائي)',
  `gradeCategory` DECIMAL(5,2) COMMENT 'فئة الدرجة (أعمال فصلية، اختبارات، أنشطة)',
  `gradeCode` DECIMAL(5,2) COMMENT 'كود نوع الدرجة',
  `gradeNameAr` DECIMAL(5,2) COMMENT 'اسم الدرجة بالعربية',
  `gradeNameEn` DECIMAL(5,2) COMMENT 'اسم الدرجة بالإنجليزية',
  `gradeValue` DECIMAL(5,2) COMMENT 'قيمة الدرجة',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى لهذا المكون',
  `percentage` DECIMAL(5,2) COMMENT 'النسبة المئوية (قيمة الدرجة/الدرجة القصوى)',
  `weight` VARCHAR(200) COMMENT 'وزن هذا المكون من الدرجة الكلية (نسبة مئوية)',
  `gradeDate` DATE COMMENT 'تاريخ الدرجة',
  `dueDate` DATE COMMENT 'تاريخ الاستحقاق (للواجبات)',
  `submissionDate` DATE COMMENT 'تاريخ التسليم (للطالب)',
  `isSubmitted` BOOLEAN COMMENT 'هل تم التسليم؟',
  `submissionStatus` VARCHAR(50) COMMENT 'حالة التسليم (في الوقت، متأخر، لم يسلم)',
  `lateDays` VARCHAR(200) COMMENT 'عدد أيام التأخير',
  `isGraded` BOOLEAN COMMENT 'هل تم تصحيحه؟',
  `gradedByUserId` BIGINT COMMENT 'معرف المصحح',
  `gradedAt` DECIMAL(5,2) COMMENT 'وقت التصحيح',
  `isAbsent` BOOLEAN COMMENT 'غياب (للاختبارات)',
  `isExcused` BOOLEAN COMMENT 'بعذر',
  `excuseDetails` VARCHAR(200) COMMENT 'تفاصيل العذر',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر',
  `excuseApprovedBy` VARCHAR(200) COMMENT 'من اعتمد العذر',
  `isExempt` BOOLEAN COMMENT 'معفى؟',
  `exemptionReason` VARCHAR(200) COMMENT 'سبب الإعفاء',
  `gradeStatus` DECIMAL(5,2) COMMENT 'حالة الدرجة (مسودة، نهائية، معدلة)',
  `modificationReason` VARCHAR(200) COMMENT 'سبب التعديل (إن وجد)',
  `previousGradeValue` DECIMAL(5,2) COMMENT 'قيمة الدرجة السابقة (للتعديلات)',
  `notes` TEXT COMMENT 'ملاحظات المعلم',
  `teacherNotes` TEXT COMMENT 'ملاحظات داخلية',
  `feedbackToStudent` DECIMAL(15,2) COMMENT 'ملاحظات للطالب',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (مسار الملف)',
  `isActive` BOOLEAN COMMENT 'نشطة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`gradeId`),
  -- FOREIGN KEY (`registrationId`) REFERENCES `CourseRegistration`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`gradedByUserId`) REFERENCES `GradedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الدرجات';

-- Table: Evaluation (التقيمات)
CREATE TABLE IF NOT EXISTS `Evaluation` (
  `evaluationId` BIGINT NOT NULL COMMENT 'معرف التقييم (المفتاح الرئيسي)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل (FK → SchoolSemester.semesterId)',
  `evaluationNameAr` VARCHAR(200) COMMENT 'اسم التقييم بالعربية',
  `evaluationNameEn` VARCHAR(200) COMMENT 'اسم التقييم بالإنجليزية',
  `evaluationType` VARCHAR(50) COMMENT 'نوع التقييم (مستمر، نهائي، شامل)',
  `components` VARCHAR(200) COMMENT 'مكونات التقييم (JSON) - تحتوي على اسم كل مكون ونسبته',
  `totalWeight` VARCHAR(200) COMMENT 'مجموع الأوزان (يجب أن يكون 100%)',
  `passingScore` DECIMAL(5,2) COMMENT 'درجة النجاح',
  `calculationMethod` VARCHAR(200) COMMENT 'طريقة الحساب (مئوية، تقدير، ناجح/راسب)',
  `gradeScale` DECIMAL(5,2) COMMENT 'سلم التقدير المستخدم',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `validFrom` DATE COMMENT 'تاريخ التفعيل',
  `validTo` DATE COMMENT 'تاريخ الانتهاء',
  `approvedBy` VARCHAR(200) COMMENT 'معتمد من',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`evaluationId`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التقيمات';

-- Table: ExamResult (الاختبارات)
CREATE TABLE IF NOT EXISTS `ExamResult` (
  `examResultId` BIGINT NOT NULL COMMENT 'معرف النتيجة (المفتاح الرئيسي)',
  `registrationId` BIGINT COMMENT 'معرف تسجيل المادة (FK → CourseRegistration.registrationId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل (FK → SchoolSemester.semesterId)',
  `examId` BIGINT COMMENT 'معرف الاختبار',
  `examName` VARCHAR(200) COMMENT 'اسم الاختبار',
  `examType` VARCHAR(50) COMMENT 'نوع الاختبار (نهائي، نصف الفصل، شهري، تجريبي)',
  `examDate` DATE COMMENT 'تاريخ الاختبار',
  `examTime` TIME COMMENT 'وقت الاختبار',
  `examHall` VARCHAR(200) COMMENT 'قاعة الاختبار',
  `examSeatNumber` INT COMMENT 'رقم المقعد',
  `examNumber` INT COMMENT 'رقم الجلوس',
  `secretNumber` INT COMMENT 'الرقم السري',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى للاختبار',
  `grade` DECIMAL(5,2) COMMENT 'الدرجة التي حصل عليها الطالب',
  `percentage` DECIMAL(5,2) COMMENT 'النسبة المئوية',
  `isAbsent` BOOLEAN COMMENT 'غائب؟',
  `isExcused` BOOLEAN COMMENT 'غياب بعذر؟',
  `excuseReason` VARCHAR(200) COMMENT 'سبب الغياب',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر',
  `isCheating` BOOLEAN COMMENT 'هل تم ضبطه في حالة غش؟',
  `cheatingDetails` VARCHAR(200) COMMENT 'تفاصيل حالة الغش',
  `cheatingPenalty` VARCHAR(200) COMMENT 'العقوبة المطبقة',
  `isPassed` BOOLEAN COMMENT 'ناجح؟',
  `passStatus` VARCHAR(50) COMMENT 'حالة النجاح',
  `correctedByUserId` BIGINT COMMENT 'معرف المصحح',
  `correctedAt` VARCHAR(200) COMMENT 'وقت التصحيح',
  `reviewedByUserId` BIGINT COMMENT 'معرف المراجع',
  `reviewedAt` VARCHAR(200) COMMENT 'وقت المراجعة',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد',
  `approvedAt` VARCHAR(200) COMMENT 'وقت الاعتماد',
  `resultStatus` VARCHAR(50) COMMENT 'حالة النتيجة (مسودة، معتمدة، معدلة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`examResultId`),
  -- FOREIGN KEY (`registrationId`) REFERENCES `CourseRegistration`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`examId`) REFERENCES `Exam`(`...`),
  -- FOREIGN KEY (`correctedByUserId`) REFERENCES `CorrectedByUser`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `ReviewedByUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `ApprovedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الاختبارات';

-- Table: Activity (الأنشطة)
CREATE TABLE IF NOT EXISTS `Activity` (
  `activityId` BIGINT NOT NULL COMMENT 'معرف النشاط (المفتاح الرئيسي)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId) - اختياري (للأنشطة المرتبطة بمادة)',
  `activityTypeId` BIGINT COMMENT 'معرف نوع النشاط (FK → ActivityType.activityTypeId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل (FK → SchoolSemester.semesterId)',
  `activityNameAr` VARCHAR(200) COMMENT 'اسم النشاط بالعربية',
  `activityNameEn` VARCHAR(200) COMMENT 'اسم النشاط بالإنجليزية',
  `activityCode` VARCHAR(50) COMMENT 'كود النشاط',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `objectives` VARCHAR(200) COMMENT 'أهداف النشاط',
  `targetAudience` VARCHAR(200) COMMENT 'الفئة المستهدفة (صفوف محددة، جميع الطلاب)',
  `gradeLevelIds` DECIMAL(5,2) COMMENT 'الصفوف المسموح لها بالمشاركة (JSON)',
  `maxParticipants` VARCHAR(200) COMMENT 'الحد الأقصى للمشاركين',
  `minParticipants` VARCHAR(200) COMMENT 'الحد الأدنى للمشاركين',
  `registrationStartDate` DATE COMMENT 'بداية التسجيل في النشاط',
  `registrationEndDate` DATE COMMENT 'نهاية التسجيل في النشاط',
  `startDate` DATE COMMENT 'تاريخ بدء النشاط',
  `endDate` DATE COMMENT 'تاريخ انتهاء النشاط',
  `location` VARCHAR(200) COMMENT 'مكان النشاط',
  `supervisorId` BIGINT COMMENT 'معرف المشرف (FK → Employee.employeeId)',
  `assistantSupervisorId` BIGINT COMMENT 'معرف مساعد المشرف',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى للنشاط',
  `passingGrade` DECIMAL(5,2) COMMENT 'درجة النجاح',
  `evaluationCriteria` VARCHAR(200) COMMENT 'معايير التقييم (نص)',
  `resources` VARCHAR(200) COMMENT 'الموارد المطلوبة',
  `budget` VARCHAR(200) COMMENT 'الميزانية المخصصة',
  `isMandatory` BOOLEAN COMMENT 'إجباري؟',
  `isGraded` BOOLEAN COMMENT 'هل يضاف للدرجات؟',
  `weight` VARCHAR(200) COMMENT 'وزنه من الدرجة الكلية (إن كان مرتبطاً بمادة)',
  `status` VARCHAR(50) COMMENT 'حالة النشاط (مخطط، مفتوح، منفذ، ملغي)',
  `completionRate` DECIMAL(5,2) COMMENT 'نسبة الإنجاز',
  `report` VARCHAR(200) COMMENT 'تقرير النشاط بعد الانتهاء',
  `photos` VARCHAR(200) COMMENT 'صور النشاط (مسارات ملفات)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`activityId`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`activityTypeId`) REFERENCES `ActivityType`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`supervisorId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assistantSupervisorId`) REFERENCES `AssistantSupervisor`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأنشطة';

-- Table: ActivityDetail (تفاصيل النشاط)
CREATE TABLE IF NOT EXISTS `ActivityDetail` (
  `detailId` BIGINT NOT NULL COMMENT 'معرف التفصيل (المفتاح الرئيسي)',
  `activityId` BIGINT COMMENT 'معرف النشاط (FK → Activity.activityId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `registrationDate` DATE COMMENT 'تاريخ التسجيل في النشاط',
  `registrationStatus` VARCHAR(50) COMMENT 'حالة التسجيل (مؤكد، قائمة انتظار، ملغي)',
  `role` VARCHAR(200) COMMENT 'دور الطالب في النشاط (مشارك، قائد فريق، منظم)',
  `attendanceStatus` VARCHAR(50) COMMENT 'حالة الحضور (حاضر، غائب، متأخر)',
  `attendanceDates` DATE COMMENT 'تواريخ الحضور (JSON)',
  `totalAttendance` VARCHAR(200) COMMENT 'إجمالي مرات الحضور',
  `obtainedGrade` DECIMAL(5,2) COMMENT 'الدرجة التي حصل عليها الطالب',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى للنشاط',
  `percentage` DECIMAL(5,2) COMMENT 'النسبة المئوية',
  `evaluation` VARCHAR(200) COMMENT 'تقييم الطالب (نص)',
  `evaluationByUserId` BIGINT COMMENT 'معرف المقيم',
  `evaluationDate` DATE COMMENT 'تاريخ التقييم',
  `feedback` DECIMAL(15,2) COMMENT 'ملاحظات للطالب',
  `achievements` VARCHAR(200) COMMENT 'إنجازات الطالب في النشاط',
  `certificateIssued` VARCHAR(200) COMMENT 'هل تم إصدار شهادة؟',
  `certificateNumber` INT COMMENT 'رقم الشهادة',
  `certificatePath` VARCHAR(200) COMMENT 'مسار ملف الشهادة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`detailId`),
  -- FOREIGN KEY (`activityId`) REFERENCES `Activity`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`evaluationByUserId`) REFERENCES `EvaluationByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تفاصيل النشاط';

-- Table: ActivityType (نوع النشاط)
CREATE TABLE IF NOT EXISTS `ActivityType` (
  `activityTypeId` BIGINT NOT NULL COMMENT 'معرف نوع النشاط (المفتاح الرئيسي)',
  `typeCode` VARCHAR(50) COMMENT 'كود النوع',
  `typeNameAr` VARCHAR(50) COMMENT 'الاسم بالعربية',
  `typeNameEn` VARCHAR(50) COMMENT 'الاسم بالإنجليزية',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `category` VARCHAR(50) COMMENT 'الفئة العامة',
  `colorCode` VARCHAR(50) COMMENT 'رمز لوني للتمييز',
  `icon` VARCHAR(200) COMMENT 'أيقونة للنوع',
  `requiresApproval` VARCHAR(200) COMMENT 'هل يتطلب موافقة مسبقة؟',
  `maxParticipantsPerActivity` VARCHAR(200) COMMENT 'الحد الأقصى للمشاركين لكل نشاط من هذا النوع',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب العرض',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`activityTypeId`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='نوع النشاط';

-- Table: LeaveType (نوع الإجازة)
CREATE TABLE IF NOT EXISTS `LeaveType` (
  `leaveTypeId` BIGINT NOT NULL COMMENT 'معرف نوع الإجازة (المفتاح الرئيسي)',
  `typeCode` VARCHAR(50) COMMENT 'كود النوع',
  `typeNameAr` VARCHAR(50) COMMENT 'الاسم بالعربية',
  `typeNameEn` VARCHAR(50) COMMENT 'الاسم بالإنجليزية',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `category` VARCHAR(50) COMMENT 'الفئة (مرضية، رسمية، شخصية)',
  `isPaid` BIGINT COMMENT 'مدفوعة؟',
  `isExcused` BOOLEAN COMMENT 'تعتبر عذراً مقبولاً؟',
  `requiresDocument` VARCHAR(200) COMMENT 'هل تتطلب مستنداً؟',
  `maxDaysPerYear` VARCHAR(200) COMMENT 'الحد الأقصى للأيام في السنة',
  `maxConsecutiveDays` VARCHAR(200) COMMENT 'الحد الأقصى للأيام المتتالية',
  `affectsAttendance` VARCHAR(200) COMMENT 'هل تؤثر على نسبة الحضور؟',
  `affectsGrading` VARCHAR(200) COMMENT 'هل تؤثر على أحقية دخول الاختبارات؟',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب العرض',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`leaveTypeId`),
  -- FOREIGN KEY (`isPaid`) REFERENCES `IsPa`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='نوع الإجازة';

-- Table: Attendance (الحضور والغياب)
CREATE TABLE IF NOT EXISTS `Attendance` (
  `attendanceId` BIGINT NOT NULL COMMENT 'معرف الحضور (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `classSectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `attendanceDate` DATE COMMENT 'تاريخ اليوم',
  `dayOfWeek` VARCHAR(200) COMMENT 'اليوم (السبت، الأحد...)',
  `attendanceType` VARCHAR(50) COMMENT 'نوع التسجيل (يومي، حصصي)',
  `status` VARCHAR(50) COMMENT 'الحالة (حاضر، غائب، متأخر، مأذون له، في مهمة مدرسية)',
  `arrivalTime` TIME COMMENT 'وقت الحضور',
  `lateMinutes` VARCHAR(200) COMMENT 'دقائق التأخير (تحسب آلياً)',
  `departureTime` TIME COMMENT 'وقت الانصراف (إن وجد)',
  `earlyDepartureMinutes` VARCHAR(200) COMMENT 'دقائق الانصراف المبكر',
  `isExcused` BOOLEAN COMMENT 'بعذر؟',
  `excuseId` BIGINT COMMENT 'معرف الإجازة (FK → StudentLeave.leaveId) - إذا كان غياباً بعذر',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر (إن وجد)',
  `excuseApprovedBy` VARCHAR(200) COMMENT 'من اعتمد العذر (FK → SystemUser.userId)',
  `excuseApprovedAt` DATE COMMENT 'تاريخ اعتماد العذر',
  `recordedById` BIGINT COMMENT 'معرف مسجل الحضور (FK → SystemUser.userId)',
  `recordedAt` VARCHAR(200) COMMENT 'وقت التسجيل',
  `verifiedById` BIGINT COMMENT 'معرف من تحقق من الحضور',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `verificationMethod` VARCHAR(200) COMMENT 'طريقة التحقق (يدوي، بصمة، كارت، تطبيق)',
  `locationVerified` VARCHAR(200) COMMENT 'هل تم التحقق من الموقع؟',
  `gpsLocation` VARCHAR(200) COMMENT 'موقع التسجيل (إحداثيات)',
  `deviceId` BIGINT COMMENT 'معرف جهاز التسجيل',
  `ipAddress` VARCHAR(200) COMMENT 'عنوان IP للتسجيل',
  `notes` TEXT COMMENT 'ملاحظات',
  `isOverridden` BOOLEAN COMMENT 'هل تم تجاوز النظام؟',
  `overrideReason` VARCHAR(200) COMMENT 'سبب التجاوز',
  `overriddenByUserId` BIGINT COMMENT 'معرف من تجاوز',
  `overrideAt` VARCHAR(200) COMMENT 'وقت التجاوز',
  `isSyncedWithParent` BOOLEAN COMMENT 'هل تم إرسال إشعار لولي الأمر؟',
  `parentNotifiedAt` VARCHAR(200) COMMENT 'وقت إرسال الإشعار',
  `parentAcknowledged` VARCHAR(200) COMMENT 'هل اطلع ولي الأمر؟',
  `parentAcknowledgedAt` VARCHAR(200) COMMENT 'وقت الاطلاع',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`attendanceId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`classSectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`excuseId`) REFERENCES `StudentLeave`(`...`),
  -- FOREIGN KEY (`excuseApprovedBy`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`recordedById`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`verifiedById`) REFERENCES `VerifiedBy`(`...`),
  -- FOREIGN KEY (`deviceId`) REFERENCES `Device`(`...`),
  -- FOREIGN KEY (`overriddenByUserId`) REFERENCES `OverriddenByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الحضور والغياب';

-- Table: AttendanceDetail (التفاصيل الحصصية للحضور اليومي للطالب)
CREATE TABLE IF NOT EXISTS `AttendanceDetail` (
  `attendanceDetailId` BIGINT NOT NULL COMMENT 'معرف التفصيل (المفتاح الرئيسي)',
  `attendanceId` BIGINT COMMENT 'معرف الحضور اليومي (FK → Attendance.attendanceId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `timetableSlotId` BIGINT COMMENT 'معرف موعد الحصة (FK → TimetableSlot.slotId)',
  `periodId` BIGINT COMMENT 'معرف الحصة (FK → ClassPeriod.periodId)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `teacherId` BIGINT COMMENT 'معرف المعلم (FK → Employee.employeeId)',
  `classSectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `periodNumber` INT COMMENT 'رقم الحصة (1، 2، 3...)',
  `periodStartTime` TIME COMMENT 'وقت بداية الحصة',
  `periodEndTime` TIME COMMENT 'وقت نهاية الحصة',
  `status` VARCHAR(50) COMMENT 'الحالة في هذه الحصة (حاضر، غائب، متأخر، مأذون له)',
  `arrivalTime` TIME COMMENT 'وقت حضور الطالب للحصة',
  `lateMinutes` VARCHAR(200) COMMENT 'دقائق التأخير عن هذه الحصة',
  `isExcused` BOOLEAN COMMENT 'بعذر لهذه الحصة؟',
  `excuseReason` VARCHAR(200) COMMENT 'سبب العذر',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر',
  `recordedById` BIGINT COMMENT 'معرف مسجل الحضور (المعلم عادة)',
  `recordedAt` VARCHAR(200) COMMENT 'وقت التسجيل',
  `notes` TEXT COMMENT 'ملاحظات المعلم',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`attendanceDetailId`),
  -- FOREIGN KEY (`attendanceId`) REFERENCES `Attendance`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`timetableSlotId`) REFERENCES `TimetableSlot`(`...`),
  -- FOREIGN KEY (`periodId`) REFERENCES `ClassPeriod`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`teacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`classSectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`recordedById`) REFERENCES `RecordedBy`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التفاصيل الحصصية للحضور اليومي للطالب';

-- Table: StudentLeave (الإجازات)
CREATE TABLE IF NOT EXISTS `StudentLeave` (
  `leaveId` BIGINT NOT NULL COMMENT 'معرف الإجازة (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `leaveTypeId` BIGINT COMMENT 'معرف نوع الإجازة (FK → LeaveType.leaveTypeId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `requestDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `startDate` DATE COMMENT 'تاريخ بداية الإجازة',
  `endDate` DATE COMMENT 'تاريخ نهاية الإجازة',
  `totalDays` VARCHAR(200) COMMENT 'إجمالي عدد الأيام (تحسب آلياً)',
  `daysCount` INT COMMENT 'عدد أيام الدراسة الفعلية في هذه الإجازة',
  `reason` VARCHAR(200) COMMENT 'سبب الإجازة (نص)',
  `description` TEXT COMMENT 'وصف تفصيلي',
  `attachmentPath` VARCHAR(200) COMMENT 'مسار المستند الداعم',
  `attachmentType` VARCHAR(50) COMMENT 'نوع المستند',
  `attachmentName` VARCHAR(200) COMMENT 'اسم المستند',
  `isUrgent` BOOLEAN COMMENT 'إجازة عاجلة؟',
  `contactDuringLeave` VARCHAR(200) COMMENT 'وسيلة الاتصال أثناء الإجازة',
  `emergencyPhone` VARCHAR(20) COMMENT 'هاتف للطوارئ أثناء الإجازة',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (قيد الانتظار، معتمدة، مرفوضة، ملغاة)',
  `reviewedByUserId` BIGINT COMMENT 'معرف المراجع (FK → SystemUser.userId)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewNotes` TEXT COMMENT 'ملاحظات المراجعة',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `isPaid` BIGINT COMMENT 'إجازة مدفوعة؟',
  `deductedFromBalance` DECIMAL(15,2) COMMENT 'هل تم خصمها من الرصيد؟',
  `remainingBalanceBefore` DECIMAL(15,2) COMMENT 'الرصيد المتبقي قبل الإجازة',
  `remainingBalanceAfter` DECIMAL(15,2) COMMENT 'الرصيد المتبقي بعد الإجازة',
  `attendanceIds` VARCHAR(200) COMMENT 'معرفات أيام الغياب المرتبطة بهذه الإجازة (JSON)',
  `isLinkedToAttendance` BOOLEAN COMMENT 'هل تم ربطها بالغياب؟',
  `linkedByUserId` BIGINT COMMENT 'معرف من قام بالربط',
  `linkedAt` DATE COMMENT 'تاريخ الربط',
  `isExpired` BOOLEAN COMMENT 'هل انتهت الإجازة؟',
  `expiredAt` DATE COMMENT 'تاريخ انتهاء الصلاحية (للإجازات المؤقتة)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`leaveId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`leaveTypeId`) REFERENCES `LeaveType`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`isPaid`) REFERENCES `IsPa`(`...`),
  -- FOREIGN KEY (`linkedByUserId`) REFERENCES `LinkedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإجازات';

-- Table: Discipline (السجل السلوكي)
CREATE TABLE IF NOT EXISTS `Discipline` (
  `disciplineId` BIGINT NOT NULL COMMENT 'معرف الحالة (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `caseNumber` INT COMMENT 'رقم الحالة (يولد آلياً بتسلسل سنوي)',
  `incidentDate` DATE COMMENT 'تاريخ الحدث',
  `incidentTime` TIME COMMENT 'وقت الحدث',
  `location` VARCHAR(200) COMMENT 'مكان الحدث (فصل، ساحة، مقصف، الخ)',
  `reportedById` BIGINT COMMENT 'معرف المبلغ (FK → SystemUser.userId)',
  `reportedByRole` VARCHAR(200) COMMENT 'دور المبلغ (معلم، مشرف، إداري، طالب)',
  `caseType` VARCHAR(50) COMMENT 'نوع الحالة (مخالفة، إيجابية، استشارة)',
  `category` VARCHAR(50) COMMENT 'فئة المخالفة/الإيجابية',
  `subCategory` VARCHAR(50) COMMENT 'الفئة الفرعية',
  `severityLevel` VARCHAR(50) COMMENT 'مستوى الخطورة (بسيط، متوسط، جسيم، شديد)',
  `description` TEXT COMMENT 'وصف الحدث بالتفصيل',
  `witnesses` VARCHAR(200) COMMENT 'الشهود (JSON) - أسماء وأدوار',
  `evidence` VARCHAR(200) COMMENT 'الأدلة (JSON) - مسارات ملفات الصور أو المستندات',
  `penaltyPoints` VARCHAR(200) COMMENT 'نقاط العقوبة',
  `rewardPoints` VARCHAR(200) COMMENT 'نقاط المكافأة',
  `totalPoints` VARCHAR(200) COMMENT 'صافي النقاط (reward - penalty)',
  `action` VARCHAR(200) COMMENT 'الإجراء المتخذ',
  `actionDetails` VARCHAR(200) COMMENT 'تفاصيل الإجراء',
  `actionDate` DATE COMMENT 'تاريخ تنفيذ الإجراء',
  `actionByUserId` BIGINT COMMENT 'معرف من نفذ الإجراء (FK → SystemUser.userId)',
  `actionApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد الإجراء',
  `actionApprovalDate` DATE COMMENT 'تاريخ اعتماد الإجراء',
  `notificationToGuardian` VARCHAR(200) COMMENT 'هل تم إشعار ولي الأمر؟',
  `guardianNotifiedAt` VARCHAR(200) COMMENT 'وقت الإشعار',
  `guardianResponse` VARCHAR(200) COMMENT 'رد ولي الأمر',
  `guardianAcknowledged` VARCHAR(200) COMMENT 'هل اطلع ولي الأمر؟',
  `meetingRequired` VARCHAR(200) COMMENT 'هل يتطلب اجتماعاً مع ولي الأمر؟',
  `meetingDate` DATE COMMENT 'تاريخ الاجتماع',
  `meetingNotes` TEXT COMMENT 'محضر الاجتماع',
  `meetingAttendees` VARCHAR(200) COMMENT 'الحضور (JSON)',
  `followUpRequired` VARCHAR(200) COMMENT 'هل يتطلب متابعة؟',
  `followUpDate` DATE COMMENT 'تاريخ المتابعة',
  `followUpNotes` TEXT COMMENT 'ملاحظات المتابعة',
  `followUpByUserId` BIGINT COMMENT 'معرف من يقوم بالمتابعة',
  `isClosed` BOOLEAN COMMENT 'مغلقة؟',
  `closedAt` DATE COMMENT 'تاريخ الإغلاق',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق الحالة',
  `closingNotes` TEXT COMMENT 'ملاحظات الإغلاق',
  `repeatCount` INT COMMENT 'عدد مرات التكرار (لنفس الطالب)',
  `linkedCases` VARCHAR(200) COMMENT 'حالات مرتبطة (JSON) - معرفات حالات سابقة',
  `attachments` VARCHAR(200) COMMENT 'مرفقات إضافية (JSON)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`disciplineId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`reportedById`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`actionByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`actionApprovedByUserId`) REFERENCES `ActionApprovedByUser`(`...`),
  -- FOREIGN KEY (`followUpByUserId`) REFERENCES `FollowUpByUser`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `ClosedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='السجل السلوكي';

-- Table: StudentComplaint (الشكاوي والتظلمات)
CREATE TABLE IF NOT EXISTS `StudentComplaint` (
  `complaintId` BIGINT NOT NULL COMMENT 'معرف الشكوى (المفتاح الرئيسي)',
  `complaintNumber` INT COMMENT 'رقم الشكوى (يولد آلياً)',
  `studentId` BIGINT COMMENT 'معرف الطالب المعني (FK → Student.studentId) - اختياري',
  `guardianId` BIGINT COMMENT 'معرف ولي الأمر مقدم الشكوى (FK → Guardian.guardianId)',
  `complainantType` VARCHAR(50) COMMENT 'نوع مقدم الشكوى (طالب، ولي أمر، معلم، إداري)',
  `complainantName` VARCHAR(200) COMMENT 'اسم مقدم الشكوى (إذا لم يكن مسجلاً في النظام)',
  `complainantPhone` VARCHAR(20) COMMENT 'هاتف مقدم الشكوى',
  `complainantEmail` VARCHAR(100) COMMENT 'بريد مقدم الشكوى',
  `complainantRelation` VARCHAR(200) COMMENT 'صلة المقدم بالطالب (إن وجد)',
  `complaintDate` DATE COMMENT 'تاريخ تقديم الشكوى',
  `complaintTime` TIME COMMENT 'وقت تقديم الشكوى',
  `channel` VARCHAR(200) COMMENT 'قناة التقديم (بوابة إلكترونية، زيارة شخصية، هاتف، بريد)',
  `category` VARCHAR(50) COMMENT 'فئة الشكوى (أكاديمية، سلوكية، إدارية، مالية، خدمات)',
  `subCategory` VARCHAR(50) COMMENT 'الفئة الفرعية',
  `againstType` VARCHAR(50) COMMENT 'نوع المشتكى عليه (معلم، إدارة، طالب، نظام، خدمات)',
  `againstId` BIGINT COMMENT 'معرف المشتكى عليه (حسب النوع)',
  `againstName` VARCHAR(200) COMMENT 'اسم المشتكى عليه (نص)',
  `subject` VARCHAR(200) COMMENT 'موضوع الشكوى (عنوان مختصر)',
  `description` TEXT COMMENT 'وصف تفصيلي للشكوى',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - مسارات ملفات',
  `desiredOutcome` VARCHAR(200) COMMENT 'النتيجة المرجوة من مقدم الشكوى',
  `priority` VARCHAR(200) COMMENT 'الأولوية (عادية، مهمة، عاجلة)',
  `severity` VARCHAR(200) COMMENT 'الخطورة (بسيطة، متوسطة، كبيرة)',
  `assignedToUserId` BIGINT COMMENT 'معرف المسؤول عن معالجة الشكوى (FK → SystemUser.userId)',
  `assignedAt` DATE COMMENT 'تاريخ التعيين',
  `assignedByUserId` BIGINT COMMENT 'معرف من قام بالتعيين',
  `status` VARCHAR(50) COMMENT 'حالة الشكوى (مستلمة، قيد الدراسة، قيد المعالجة، في انتظار رد، محلولة، مغلقة، مصعدة)',
  `internalNotes` TEXT COMMENT 'ملاحظات داخلية',
  `actionTaken` VARCHAR(200) COMMENT 'الإجراءات المتخذة',
  `actionDate` DATE COMMENT 'تاريخ الإجراء',
  `actionByUserId` BIGINT COMMENT 'معرف من قام بالإجراء',
  `responseToComplainant` VARCHAR(200) COMMENT 'الرد على مقدم الشكوى',
  `responseDate` DATE COMMENT 'تاريخ الرد',
  `complainantSatisfied` VARCHAR(200) COMMENT 'هل مقدم الشكوى راضٍ عن الحل؟',
  `complainantFeedback` DECIMAL(15,2) COMMENT 'رد مقدم الشكوى على الحل',
  `escalationLevel` VARCHAR(50) COMMENT 'مستوى التصعيد (مدرسة، مكتب، وزارة)',
  `escalatedTo` VARCHAR(200) COMMENT 'تم التصعيد إلى (نص)',
  `escalatedAt` DATE COMMENT 'تاريخ التصعيد',
  `escalationReason` VARCHAR(200) COMMENT 'سبب التصعيد',
  `escalationDocument` VARCHAR(200) COMMENT 'مستند التصعيد',
  `resolvedAt` DATE COMMENT 'تاريخ الحل',
  `resolvedByUserId` BIGINT COMMENT 'معرف من قام بالحل',
  `resolutionSummary` VARCHAR(200) COMMENT 'ملخص الحل',
  `closingNotes` TEXT COMMENT 'ملاحظات الإغلاق',
  `closedAt` DATE COMMENT 'تاريخ الإغلاق',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق',
  `isConfidential` BOOLEAN COMMENT 'هل الشكوى سرية؟',
  `isAnonymous` BOOLEAN COMMENT 'شكوى مجهولة المصدر؟',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات',
  `linkedComplaintId` BIGINT COMMENT 'معرف شكوى مرتبطة (تصعيد)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`complaintId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`guardianId`) REFERENCES `Guardian`(`...`),
  -- FOREIGN KEY (`againstId`) REFERENCES `Against`(`...`),
  -- FOREIGN KEY (`assignedToUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`assignedByUserId`) REFERENCES `AssignedByUser`(`...`),
  -- FOREIGN KEY (`actionByUserId`) REFERENCES `ActionByUser`(`...`),
  -- FOREIGN KEY (`resolvedByUserId`) REFERENCES `ResolvedByUser`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `ClosedByUser`(`...`),
  -- FOREIGN KEY (`linkedComplaintId`) REFERENCES `LinkedComplaint`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الشكاوي والتظلمات';

-- Table: GuidanceSession (جلسات الإرشاد)
CREATE TABLE IF NOT EXISTS `GuidanceSession` (
  `sessionId` BIGINT NOT NULL COMMENT 'معرف الجلسة (المفتاح الرئيسي)',
  `sessionNumber` INT COMMENT 'رقم الجلسة (تسلسلي)',
  `counselorId` BIGINT COMMENT 'معرف المرشد (FK → Employee.employeeId)',
  `sessionType` VARCHAR(50) COMMENT 'نوع الجلسة (فردية، جماعية، مجموعة صغيرة)',
  `category` VARCHAR(50) COMMENT 'فئة الجلسة (أكاديمية، سلوكية، نفسية، مهنية، توجيه)',
  `title` VARCHAR(200) COMMENT 'عنوان الجلسة',
  `objectives` VARCHAR(200) COMMENT 'أهداف الجلسة',
  `plannedDate` DATE COMMENT 'التاريخ المخطط للجلسة',
  `actualDate` DATE COMMENT 'التاريخ الفعلي',
  `startTime` TIME COMMENT 'وقت البداية',
  `endTime` TIME COMMENT 'وقت النهاية',
  `duration` VARCHAR(200) COMMENT 'المدة بالدقائق',
  `location` VARCHAR(200) COMMENT 'مكان الجلسة',
  `isRecurring` BOOLEAN COMMENT 'جلسة متكررة؟',
  `recurringPattern` VARCHAR(200) COMMENT 'نمط التكرار',
  `parentSessionId` BIGINT COMMENT 'معرف الجلسة الأم (للجلسات المتكررة)',
  `students` VARCHAR(200) COMMENT 'الطلاب المشاركون (JSON) - معرفات الطلاب',
  `studentIds` VARCHAR(200) COMMENT 'قائمة معرفات الطلاب (للبحث)',
  `attendeesCount` INT COMMENT 'عدد الحضور',
  `attendanceStatus` VARCHAR(50) COMMENT 'حالة حضور كل طالب (JSON)',
  `topics` VARCHAR(200) COMMENT 'المواضيع التي تمت مناقشتها',
  `summary` VARCHAR(200) COMMENT 'ملخص الجلسة',
  `notes` TEXT COMMENT 'ملاحظات المرشد (خاصة)',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات',
  `actionPlan` VARCHAR(200) COMMENT 'خطة العمل',
  `followUpRequired` VARCHAR(200) COMMENT 'هل تتطلب متابعة؟',
  `followUpDate` DATE COMMENT 'تاريخ المتابعة',
  `followUpNotes` TEXT COMMENT 'ملاحظات المتابعة',
  `relatedDisciplineId` BIGINT COMMENT 'معرف الحالة السلوكية المرتبطة (FK → Discipline.disciplineId)',
  `relatedAcademicIssue` VARCHAR(200) COMMENT 'المشكلة الأكاديمية المرتبطة (نص)',
  `progressBefore` VARCHAR(200) COMMENT 'مستوى التقدم قبل الجلسة',
  `progressAfter` VARCHAR(200) COMMENT 'مستوى التقدم بعد الجلسة',
  `progressRating` VARCHAR(200) COMMENT 'تقييم التقدم (1-5)',
  `isConfidential` BOOLEAN COMMENT 'جلسة سرية؟',
  `sharedWithGuardian` VARCHAR(200) COMMENT 'هل تم مشاركتها مع ولي الأمر؟',
  `guardianNotified` VARCHAR(200) COMMENT 'هل تم إشعار ولي الأمر؟',
  `guardianFeedback` DECIMAL(15,2) COMMENT 'رد ولي الأمر',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`sessionId`),
  -- FOREIGN KEY (`counselorId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`parentSessionId`) REFERENCES `ParentSession`(`...`),
  -- FOREIGN KEY (`relatedDisciplineId`) REFERENCES `Discipline`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='جلسات الإرشاد';

-- Table: LibraryLoan (استعارة المكتبة)
CREATE TABLE IF NOT EXISTS `LibraryLoan` (
  `loanId` BIGINT NOT NULL COMMENT 'معرف الإعارة (المفتاح الرئيسي)',
  `resourceId` BIGINT COMMENT 'معرف المصدر (FK → LibraryResource.resourceId)',
  `borrowerType` VARCHAR(50) COMMENT 'نوع المستعير (طالب، موظف، معلم)',
  `borrowerId` BIGINT COMMENT 'معرف المستعير (حسب النوع: Student.studentId أو Employee.employeeId)',
  `borrowerName` VARCHAR(200) COMMENT 'اسم المستعير (للحالات الخاصة)',
  `borrowerClass` VARCHAR(200) COMMENT 'صف المستعير (للطلاب)',
  `borrowerPhone` VARCHAR(20) COMMENT 'هاتف المستعير',
  `loanDate` DATE COMMENT 'تاريخ الإعارة',
  `dueDate` DATE COMMENT 'تاريخ الاستحقاق (موعد الإرجاع المطلوب)',
  `expectedReturnDate` DATE COMMENT 'تاريخ الإرجاع المتوقع',
  `actualReturnDate` DATE COMMENT 'تاريخ الإرجاع الفعلي',
  `extensionCount` INT COMMENT 'عدد مرات التمديد',
  `lastExtensionDate` DATE COMMENT 'تاريخ آخر تمديد',
  `extensionApprovedBy` VARCHAR(200) COMMENT 'من اعتمد التمديد (FK → SystemUser.userId)',
  `status` VARCHAR(50) COMMENT 'حالة الإعارة (نشطة، مسترجعة، متأخرة، مفقودة)',
  `conditionAtLoan` VARCHAR(200) COMMENT 'حالة المصدر عند الإعارة',
  `conditionAtReturn` VARCHAR(200) COMMENT 'حالة المصدر عند الإرجاع',
  `conditionNotes` TEXT COMMENT 'ملاحظات عن الحالة',
  `damageReported` VARCHAR(200) COMMENT 'هل تم الإبلاغ عن تلف؟',
  `damageDescription` TEXT COMMENT 'وصف التلف',
  `damagePhotos` VARCHAR(200) COMMENT 'صور التلف',
  `damageFee` DECIMAL(15,2) COMMENT 'رسوم التلف',
  `isOverdue` BOOLEAN COMMENT 'متأخرة؟',
  `overdueDays` VARCHAR(200) COMMENT 'أيام التأخير',
  `fineAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة',
  `finePaid` BIGINT COMMENT 'هل دفعت الغرامة؟',
  `finePaidDate` DATE COMMENT 'تاريخ دفع الغرامة',
  `fineReceiptNumber` INT COMMENT 'رقم إيصال الغرامة',
  `isLost` BOOLEAN COMMENT 'مفقودة؟',
  `lostDate` DATE COMMENT 'تاريخ الفقدان',
  `lostFee` DECIMAL(15,2) COMMENT 'رسوم الفقدان',
  `lostFeePaid` BIGINT COMMENT 'هل دفعت رسوم الفقدان؟',
  `renewalCount` INT COMMENT 'عدد مرات التجديد',
  `renewedAt` DATE COMMENT 'تاريخ آخر تجديد',
  `renewedBy` VARCHAR(200) COMMENT 'من جدد (FK → SystemUser.userId)',
  `issuedById` BIGINT COMMENT 'معرف أمين المكتبة المصدر (FK → Employee.employeeId)',
  `receivedById` BIGINT COMMENT 'معرف من استلم الإرجاع (FK → Employee.employeeId)',
  `purpose` VARCHAR(200) COMMENT 'الغرض من الاستعارة (بحث، تسلية، دراسة)',
  `reservationId` BIGINT COMMENT 'معرف الحجز المرتبط (إن وجد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`loanId`),
  -- FOREIGN KEY (`resourceId`) REFERENCES `LibraryResource`(`...`),
  -- FOREIGN KEY (`borrowerId`) REFERENCES `Borrower`(`...`),
  -- FOREIGN KEY (`extensionApprovedBy`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`finePaid`) REFERENCES `FinePa`(`...`),
  -- FOREIGN KEY (`lostFeePaid`) REFERENCES `LostFeePa`(`...`),
  -- FOREIGN KEY (`renewedBy`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`issuedById`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`receivedById`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`reservationId`) REFERENCES `Reservation`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='استعارة المكتبة';

-- Table: StudentActivityRegistration (تسجيل الطلاب في الأنشطة)
CREATE TABLE IF NOT EXISTS `StudentActivityRegistration` (
  `registrationId` BIGINT NOT NULL COMMENT 'معرف التسجيل (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `activityId` BIGINT COMMENT 'معرف النشاط (FK → SchoolActivity.activityId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `registrationDate` DATE COMMENT 'تاريخ التسجيل في النشاط',
  `registrationSource` VARCHAR(200) COMMENT 'مصدر التسجيل (بوابة الطالب، يدوي، تلقائي)',
  `status` VARCHAR(50) COMMENT 'حالة التسجيل (مؤكد، قيد الانتظار، ملغي، مكتمل)',
  `waitlistPosition` VARCHAR(200) COMMENT 'موقع الطالب في قائمة الانتظار (إن وجد)',
  `role` VARCHAR(200) COMMENT 'دور الطالب في النشاط (مشارك، قائد فريق، مساعد، منظم)',
  `roleDescription` TEXT COMMENT 'وصف الدور',
  `assignedByUserId` BIGINT COMMENT 'معرف من قام بتعيين الدور',
  `assignedAt` DATE COMMENT 'تاريخ التعيين',
  `isActive` BOOLEAN COMMENT 'تسجيل نشط؟',
  `startDate` DATE COMMENT 'تاريخ بدء المشاركة',
  `endDate` DATE COMMENT 'تاريخ انتهاء المشاركة (للأنشطة المؤقتة)',
  `completionStatus` VARCHAR(50) COMMENT 'حالة الإكمال (مشارك كامل، منسحب، لم يكتمل)',
  `withdrawalDate` DATE COMMENT 'تاريخ الانسحاب',
  `withdrawalReason` VARCHAR(200) COMMENT 'سبب الانسحاب',
  `withdrawalApprovedBy` VARCHAR(200) COMMENT 'من اعتمد الانسحاب',
  `attendanceCount` INT COMMENT 'عدد مرات الحضور (يحدث آلياً)',
  `totalSessions` VARCHAR(200) COMMENT 'إجمالي عدد جلسات النشاط',
  `attendancePercentage` DECIMAL(5,2) COMMENT 'نسبة الحضور',
  `finalScore` DECIMAL(5,2) COMMENT 'الدرجة النهائية في النشاط (إن وجدت)',
  `evaluation` VARCHAR(200) COMMENT 'تقييم الطالب في النشاط',
  `evaluatedByUserId` BIGINT COMMENT 'معرف المقيم',
  `evaluationDate` DATE COMMENT 'تاريخ التقييم',
  `certificateIssued` VARCHAR(200) COMMENT 'هل صدرت شهادة؟',
  `certificateNumber` INT COMMENT 'رقم الشهادة',
  `certificatePath` VARCHAR(200) COMMENT 'مسار ملف الشهادة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`registrationId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`activityId`) REFERENCES `SchoolActivity`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`assignedByUserId`) REFERENCES `AssignedByUser`(`...`),
  -- FOREIGN KEY (`evaluatedByUserId`) REFERENCES `EvaluatedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تسجيل الطلاب في الأنشطة';

-- Table: SchoolActivity (النشاط المدرسي)
CREATE TABLE IF NOT EXISTS `SchoolActivity` (
  `activityId` BIGINT NOT NULL COMMENT 'معرف النشاط (المفتاح الرئيسي)',
  `activityCode` VARCHAR(50) COMMENT 'كود النشاط',
  `activityNameAr` VARCHAR(200) COMMENT 'اسم النشاط بالعربية',
  `activityNameEn` VARCHAR(200) COMMENT 'اسم النشاط بالإنجليزية',
  `activityTypeId` BIGINT COMMENT 'معرف نوع النشاط (FK → ActivityType.activityTypeId)',
  `category` VARCHAR(50) COMMENT 'فئة النشاط (رياضي، ثقافي، علمي، اجتماعي، تطوعي، ترفيهي)',
  `subCategory` VARCHAR(50) COMMENT 'الفئة الفرعية',
  `descriptionAr` TEXT COMMENT 'وصف عربي',
  `descriptionEn` TEXT COMMENT 'وصف إنجليزي',
  `objectives` VARCHAR(200) COMMENT 'أهداف النشاط',
  `learningOutcomes` VARCHAR(200) COMMENT 'مخرجات التعلم من النشاط (إن وجدت)',
  `targetAudience` VARCHAR(200) COMMENT 'الفئة المستهدفة (صفوف محددة، مرحلة، جميع الطلاب)',
  `gradeLevelIds` DECIMAL(5,2) COMMENT 'الصفوف المسموح لها (JSON)',
  `minParticipants` VARCHAR(200) COMMENT 'الحد الأدنى للمشاركين',
  `maxParticipants` VARCHAR(200) COMMENT 'الحد الأقصى للمشاركين',
  `currentParticipants` VARCHAR(200) COMMENT 'عدد المشاركين الحاليين (يحدث آلياً)',
  `registrationRequired` VARCHAR(200) COMMENT 'هل يتطلب تسجيل مسبق؟',
  `registrationStartDate` DATE COMMENT 'بداية التسجيل',
  `registrationEndDate` DATE COMMENT 'نهاية التسجيل',
  `startDate` DATE COMMENT 'تاريخ بدء النشاط',
  `endDate` DATE COMMENT 'تاريخ انتهاء النشاط',
  `schedule` VARCHAR(200) COMMENT 'جدول النشاط (JSON) - أيام وأوقات الجلسات',
  `sessionDuration` VARCHAR(200) COMMENT 'مدة الجلسة الواحدة بالدقائق',
  `totalSessions` VARCHAR(200) COMMENT 'إجمالي عدد الجلسات',
  `location` VARCHAR(200) COMMENT 'مكان النشاط',
  `locationType` VARCHAR(50) COMMENT 'نوع المكان (داخل المدرسة، خارجي، افتراضي)',
  `virtualMeetingLink` VARCHAR(200) COMMENT 'رابط الاجتماع الافتراضي (إن وجد)',
  `supervisorId` BIGINT COMMENT 'معرف المشرف الرئيسي (FK → Employee.employeeId)',
  `supervisorName` VARCHAR(200) COMMENT 'اسم المشرف (للحالات الخاصة)',
  `coSupervisors` VARCHAR(200) COMMENT 'مشرفون مساعدون (JSON) - معرفات',
  `volunteers` VARCHAR(200) COMMENT 'المتطوعون (JSON)',
  `organizerId` BIGINT COMMENT 'معرف المنظم (FK → Employee.employeeId)',
  `contactPerson` VARCHAR(200) COMMENT 'شخص للتواصل',
  `contactPhone` VARCHAR(20) COMMENT 'هاتف التواصل',
  `contactEmail` VARCHAR(100) COMMENT 'بريد التواصل',
  `budget` VARCHAR(200) COMMENT 'الميزانية المخصصة',
  `expenses` VARCHAR(200) COMMENT 'المصروفات الفعلية (JSON)',
  `resources` VARCHAR(200) COMMENT 'الموارد المطلوبة (JSON)',
  `sponsors` VARCHAR(200) COMMENT 'الرعاة (JSON)',
  `isGraded` BOOLEAN COMMENT 'هل يضاف للدرجات؟',
  `weight` VARCHAR(200) COMMENT 'الوزن من الدرجة الكلية',
  `gradingCriteria` VARCHAR(200) COMMENT 'معايير التقييم',
  `maxGrade` DECIMAL(5,2) COMMENT 'الدرجة القصوى',
  `hasCertificate` BOOLEAN COMMENT 'هل يتم إصدار شهادات؟',
  `certificateTemplate` VARCHAR(200) COMMENT 'قالب الشهادة',
  `status` VARCHAR(50) COMMENT 'حالة النشاط (مخطط، مفتوح للتسجيل، جاري، مكتمل، ملغي، مؤجل)',
  `progressPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز',
  `completionReport` VARCHAR(200) COMMENT 'تقرير الإنجاز',
  `evaluationReport` VARCHAR(200) COMMENT 'تقرير التقييم',
  `photos` VARCHAR(200) COMMENT 'صور النشاط (JSON)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `isPublished` BOOLEAN COMMENT 'منشور للطلاب؟',
  `publishedAt` DATE COMMENT 'تاريخ النشر',
  `publishedByUserId` BIGINT COMMENT 'معرف من نشر',
  `isActive` BOOLEAN COMMENT 'مفعل؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`activityId`),
  -- FOREIGN KEY (`activityTypeId`) REFERENCES `ActivityType`(`...`),
  -- FOREIGN KEY (`supervisorId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`organizerId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`publishedByUserId`) REFERENCES `PublishedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='النشاط المدرسي';

-- Table: ClassPeriod (الحصة الدراسية)
CREATE TABLE IF NOT EXISTS `ClassPeriod` (
  `periodId` BIGINT NOT NULL COMMENT 'معرف الحصة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `shiftId` BIGINT COMMENT 'معرف الفترة (صباحي، مسائي) (FK → SchoolShiftSetting.shiftId)',
  `periodNumber` INT COMMENT 'رقم الحصة (1، 2، 3...)',
  `periodCode` VARCHAR(50) COMMENT 'كود الحصة (مثلاً: P1, P2)',
  `nameAr` VARCHAR(200) COMMENT 'اسم الحصة بالعربية (الحصة الأولى، الاستراحة)',
  `nameEn` VARCHAR(200) COMMENT 'اسم الحصة بالإنجليزية',
  `periodType` VARCHAR(50) COMMENT 'نوع الحصة (دراسية، استراحة، نشاط، طابور)',
  `startTime` TIME COMMENT 'وقت بداية الحصة',
  `endTime` TIME COMMENT 'وقت نهاية الحصة',
  `durationMinutes` VARCHAR(200) COMMENT 'المدة بالدقائق',
  `isBreak` BOOLEAN COMMENT 'هل هي استراحة؟',
  `isActive` BOOLEAN COMMENT 'مفعلة؟',
  `applicableDays` VARCHAR(200) COMMENT 'أيام الأسبوع المطبقة فيها هذه الحصة (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`periodId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الحصة الدراسية';

-- Table: TimetableSlot (مواعيد الجدول الدراسي)
CREATE TABLE IF NOT EXISTS `TimetableSlot` (
  `slotId` BIGINT NOT NULL COMMENT 'معرف موعد الحصة (المفتاح الرئيسي)',
  `timetableId` BIGINT COMMENT 'معرف الجدول (لربط مجموعة من الحصص بجدول واحد)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `sectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `dayOfWeek` VARCHAR(200) COMMENT 'اليوم (السبت=1، الأحد=2...)',
  `periodId` BIGINT COMMENT 'معرف الحصة (FK → ClassPeriod.periodId)',
  `periodNumber` INT COMMENT 'رقم الحصة (للبحث السريع)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `teacherId` BIGINT COMMENT 'معرف المعلم (FK → Employee.employeeId)',
  `assistantTeacherId` BIGINT COMMENT 'معرف المعلم المساعد (إن وجد)',
  `classroomId` BIGINT COMMENT 'معرف القاعة (FK → Classroom.classroomId)',
  `isActive` BOOLEAN COMMENT 'هل الحصة نشطة في الجدول؟',
  `isSubstituted` BOOLEAN COMMENT 'هل هي حصة بديلة (نيابة)؟',
  `substitutedByTeacherId` BIGINT COMMENT 'معرف المعلم البديل',
  `substitutionDate` DATE COMMENT 'تاريخ النيابة',
  `substitutionReason` VARCHAR(200) COMMENT 'سبب النيابة',
  `isCancelled` BOOLEAN COMMENT 'هل ألغيت الحصة؟',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء',
  `cancelledAt` DATE COMMENT 'تاريخ الإلغاء',
  `cancelledByUserId` BIGINT COMMENT 'معرف من ألغى',
  `isExam` BOOLEAN COMMENT 'هل هي حصة اختبار؟',
  `examId` BIGINT COMMENT 'معرف الاختبار المرتبط',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`slotId`),
  -- FOREIGN KEY (`timetableId`) REFERENCES `Timetable`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`sectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`periodId`) REFERENCES `ClassPeriod`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`teacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assistantTeacherId`) REFERENCES `AssistantTeacher`(`...`),
  -- FOREIGN KEY (`classroomId`) REFERENCES `Classroom`(`...`),
  -- FOREIGN KEY (`substitutedByTeacherId`) REFERENCES `SubstitutedByTeacher`(`...`),
  -- FOREIGN KEY (`cancelledByUserId`) REFERENCES `CancelledByUser`(`...`),
  -- FOREIGN KEY (`examId`) REFERENCES `Exam`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مواعيد الجدول الدراسي';

-- Table: ActivityAttendance (حضور الأنشطة)
CREATE TABLE IF NOT EXISTS `ActivityAttendance` (
  `attendanceId` BIGINT NOT NULL COMMENT 'معرف الحضور (المفتاح الرئيسي)',
  `activityRegistrationId` BIGINT COMMENT 'معرف تسجيل الطالب في النشاط (FK → StudentActivityRegistration.registrationId)',
  `activityId` BIGINT COMMENT 'معرف النشاط (FK → SchoolActivity.activityId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId)',
  `sessionDate` DATE COMMENT 'تاريخ الجلسة',
  `sessionNumber` INT COMMENT 'رقم الجلسة (1، 2، 3...)',
  `sessionTitle` VARCHAR(200) COMMENT 'عنوان الجلسة (إن وجد)',
  `startTime` TIME COMMENT 'وقت بدء الجلسة',
  `endTime` TIME COMMENT 'وقت انتهاء الجلسة',
  `status` VARCHAR(50) COMMENT 'حالة الحضور (حاضر، غائب، متأخر، معذور)',
  `checkInTime` TIME COMMENT 'وقت تسجيل الحضور',
  `checkOutTime` TIME COMMENT 'وقت تسجيل الانصراف',
  `lateMinutes` VARCHAR(200) COMMENT 'دقائق التأخير',
  `isExcused` BOOLEAN COMMENT 'غياب بعذر؟',
  `excuseReason` VARCHAR(200) COMMENT 'سبب العذر',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر',
  `excuseApprovedBy` VARCHAR(200) COMMENT 'من اعتمد العذر',
  `participationScore` DECIMAL(5,2) COMMENT 'درجة المشاركة في هذه الجلسة (إن وجدت)',
  `participationNotes` TEXT COMMENT 'ملاحظات عن المشاركة',
  `recordedById` BIGINT COMMENT 'معرف مسجل الحضور (FK → SystemUser.userId)',
  `recordedAt` VARCHAR(200) COMMENT 'وقت التسجيل',
  `locationVerified` VARCHAR(200) COMMENT 'موقع الحضور (للأنشطة الخارجية)',
  `gpsLocation` VARCHAR(200) COMMENT 'إحداثيات الموقع',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي؟',
  PRIMARY KEY (`attendanceId`),
  -- FOREIGN KEY (`activityRegistrationId`) REFERENCES `StudentActivityRegistration`(`...`),
  -- FOREIGN KEY (`activityId`) REFERENCES `SchoolActivity`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`recordedById`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حضور الأنشطة';

-- Table: Classroom (القاعة الدراسية)
CREATE TABLE IF NOT EXISTS `Classroom` (
  `classroomId` BIGINT NOT NULL COMMENT 'معرف القاعة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `classroomCode` VARCHAR(50) COMMENT 'رمز القاعة (فريد)',
  `classroomNameAr` VARCHAR(200) COMMENT 'اسم القاعة بالعربية',
  `classroomNameEn` VARCHAR(200) COMMENT 'اسم القاعة بالإنجليزية',
  `classroomNumber` INT COMMENT 'رقم القاعة (للإشارة السريعة)',
  `buildingId` BIGINT COMMENT 'معرف المبنى (يرتبط بجدول BuildingComponents في قسم الأصول)',
  `buildingName` VARCHAR(200) COMMENT 'اسم المبنى',
  `floorNumber` INT COMMENT 'رقم الطابق',
  `wing` VARCHAR(200) COMMENT 'الجناح (شرقي، غربي، شمالي، جنوبي)',
  `roomNumber` INT COMMENT 'رقم الغرفة',
  `locationDescription` TEXT COMMENT 'وصف الموقع (نص)',
  `latitude` VARCHAR(200) COMMENT 'إحداثيات الموقع (خط العرض)',
  `longitude` VARCHAR(200) COMMENT 'إحداثيات الموقع (خط الطول)',
  `capacity` VARCHAR(200) COMMENT 'السعة الاستيعابية (عدد الطلاب)',
  `examCapacity` VARCHAR(200) COMMENT 'السعة الاستيعابية للاختبارات (قد تختلف عن العادية)',
  `area` VARCHAR(200) COMMENT 'المساحة بالمتر المربع',
  `roomType` VARCHAR(50) COMMENT 'نوع القاعة (فصل دراسي، معمل علوم، معمل حاسب، مكتبة، صالة رياضية، مسرح، غرفة أنشطة، مكتب إداري، غرفة اجتماعات، مخزن، أخرى)',
  `roomSubType` VARCHAR(50) COMMENT 'النوع الفرعي (للمعامل مثلاً: فيزياء، كيمياء، أحياء)',
  `isLab` BOOLEAN COMMENT 'هل هي معمل؟',
  `labType` VARCHAR(50) COMMENT 'نوع المعمل (إن وجد)',
  `isSpecialized` BOOLEAN COMMENT 'قاعة متخصصة؟',
  `specializations` VARCHAR(200) COMMENT 'التخصصات المناسبة لها (JSON)',
  `hasComputers` BOOLEAN COMMENT 'هل تحتوي على أجهزة حاسوب؟',
  `computersCount` INT COMMENT 'عدد أجهزة الحاسوب',
  `hasProjector` BOOLEAN COMMENT 'هل يوجد بروجيكتور؟',
  `hasSmartBoard` BOOLEAN COMMENT 'هل يوجد سبورة ذكية؟',
  `hasWhiteBoard` BOOLEAN COMMENT 'هل يوجد سبورة بيضاء؟',
  `hasBlackBoard` BOOLEAN COMMENT 'هل يوجد سبورة طباشير؟',
  `hasAirConditioning` BOOLEAN COMMENT 'هل يوجد تكييف؟',
  `hasHeating` BOOLEAN COMMENT 'هل يوجد تدفئة؟',
  `hasInternet` BOOLEAN COMMENT 'هل يوجد اتصال بالإنترنت؟',
  `hasWifi` BOOLEAN COMMENT 'هل يوجد واي فاي؟',
  `hasPowerOutlets` BOOLEAN COMMENT 'هل يوجد منافذ كهرباء؟',
  `hasEmergencyExit` BOOLEAN COMMENT 'هل يوجد مخرج طوارئ؟',
  `hasFireExtinguisher` BOOLEAN COMMENT 'هل يوجد طفاية حريق؟',
  `hasFirstAidKit` BOOLEAN COMMENT 'هل يوجد حقيبة إسعافات أولية؟',
  `isAccessible` BOOLEAN COMMENT 'مناسبة لذوي الإعاقة؟',
  `accessibilityFeatures` VARCHAR(200) COMMENT 'ميزات الوصول لذوي الإعاقة (منحدر، مصعد، حمام مجهز)',
  `furnitureType` VARCHAR(50) COMMENT 'نوع الأثاث (مقاعد ثابتة، مقاعد متحركة، طاولات)',
  `furnitureCondition` VARCHAR(200) COMMENT 'حالة الأثاث',
  `condition` VARCHAR(200) COMMENT 'الحالة العامة (ممتازة، جيدة، مقبولة، سيئة، تحت الصيانة)',
  `conditionLastUpdated` DATE COMMENT 'آخر تحديث للحالة',
  `lastMaintenanceDate` DATE COMMENT 'تاريخ آخر صيانة',
  `nextMaintenanceDate` DATE COMMENT 'تاريخ الصيانة القادمة',
  `maintenanceStatus` VARCHAR(50) COMMENT 'حالة الصيانة (جيدة، تحتاج صيانة، تحت الصيانة، متوقفة)',
  `maintenanceNotes` TEXT COMMENT 'ملاحظات الصيانة',
  `isActive` BOOLEAN COMMENT 'مفعلة؟',
  `status` VARCHAR(50) COMMENT 'حالة القاعة (متاحة، محجوزة، تحت الصيانة، مغلقة)',
  `availableFrom` VARCHAR(200) COMMENT 'وقت التوفر من',
  `availableTo` VARCHAR(200) COMMENT 'وقت التوفر إلى',
  `availableDays` VARCHAR(200) COMMENT 'أيام التوفر (JSON)',
  `reservations` VARCHAR(200) COMMENT 'الحجوزات الحالية (JSON) - للعرض السريع',
  `departmentId` BIGINT COMMENT 'معرف القسم المسؤول عن القاعة (FK → SchoolDepartment.deptId)',
  `responsibleUserId` BIGINT COMMENT 'معرف المسؤول عن القاعة (FK → Employee.employeeId)',
  `contactPhone` VARCHAR(20) COMMENT 'هاتف المسؤول',
  `hasInventory` BOOLEAN COMMENT 'هل يوجد عهدة في القاعة؟',
  `inventoryItems` VARCHAR(200) COMMENT 'بنود العهدة (JSON)',
  `photo` VARCHAR(200) COMMENT 'صورة القاعة (مسار الملف)',
  `floorPlan` VARCHAR(200) COMMENT 'مخطط الطابق (مسار الملف)',
  `qrCode` VARCHAR(50) COMMENT 'رمز QR للقاعة',
  `barcode` VARCHAR(50) COMMENT 'باركود للقاعة',
  `rfidTag` VARCHAR(200) COMMENT 'رقم شريحة RFID (إن وجد)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`classroomId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`buildingId`) REFERENCES `BuildingComponents`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`responsibleUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='القاعة الدراسية';

-- Table: Timetable (الجدول الدراسي)
CREATE TABLE IF NOT EXISTS `Timetable` (
  `timetableId` BIGINT NOT NULL COMMENT 'معرف الجدول (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `sectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `timetableCode` TIME COMMENT 'رمز الجدول',
  `timetableNameAr` TIME COMMENT 'اسم الجدول بالعربية',
  `timetableNameEn` TIME COMMENT 'اسم الجدول بالإنجليزية',
  `version` VARCHAR(200) COMMENT 'إصدار الجدول (V1.0, V2.0)',
  `versionDate` DATE COMMENT 'تاريخ الإصدار',
  `effectiveFrom` DATE COMMENT 'تاريخ بدء العمل بالجدول',
  `effectiveTo` DATE COMMENT 'تاريخ انتهاء العمل بالجدول (إن وجد)',
  `isActive` BOOLEAN COMMENT 'هل الجدول نشط حالياً؟',
  `isDefault` BOOLEAN COMMENT 'هل هو الجدول الافتراضي لهذه الشعبة؟',
  `status` VARCHAR(50) COMMENT 'حالة الجدول (مسودة، معتمد، منتهي)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الجدول',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `totalPeriods` VARCHAR(200) COMMENT 'إجمالي عدد الحصص في الأسبوع',
  `workingDays` VARCHAR(200) COMMENT 'أيام العمل في الأسبوع (JSON)',
  `shiftId` BIGINT COMMENT 'معرف الفترة (صباحي، مسائي) (FK → SchoolShiftSetting.shiftId)',
  `createdFromTimetableId` BIGINT COMMENT 'معرف الجدول المصدر (إذا تم النسخ)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`timetableId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`sectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `ApprovedByUser`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`createdFromTimetableId`) REFERENCES `CreatedFromTimetable`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الجدول الدراسي';

-- Table: FacilityDepartmentAssignment (تخصيص المرافق التعليمية)
CREATE TABLE IF NOT EXISTS `FacilityDepartmentAssignment` (
  `assignmentId` BIGINT NOT NULL COMMENT 'معرف التخصيص (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `facilityType` VARCHAR(50) COMMENT 'نوع المرفق (قاعة، معمل، مكتبة، صالة، مخزن)',
  `facilityId` BIGINT COMMENT 'معرف المرفق (حسب النوع: FK → Classroom.classroomId أو غيره)',
  `departmentId` BIGINT COMMENT 'معرف القسم المستفيد (FK → SchoolDepartment.deptId)',
  `assignmentType` VARCHAR(50) COMMENT 'نوع التخصيص (كلي، جزئي، مؤقت، دائم)',
  `responsibleUserId` BIGINT COMMENT 'معرف المسؤول الرئيسي (FK → Employee.employeeId)',
  `responsibleRole` VARCHAR(200) COMMENT 'دور المسؤول (أمين معمل، مشرف قسم، رئيس قسم)',
  `assistantResponsibleUserId` BIGINT COMMENT 'معرف المساعد (إن وجد)',
  `assignmentDate` DATE COMMENT 'تاريخ التخصيص',
  `startDate` DATE COMMENT 'تاريخ بدء التخصيص',
  `endDate` DATE COMMENT 'تاريخ انتهاء التخصيص (إن كان مؤقتاً)',
  `isShared` BOOLEAN COMMENT 'هل المرفق مشترك بين عدة أقسام؟',
  `sharedWithDepartments` VARCHAR(200) COMMENT 'الأقسام المشاركة (JSON)',
  `sharingPercentage` DECIMAL(5,2) COMMENT 'نسبة الاستخدام (للمشترك)',
  `priority` VARCHAR(200) COMMENT 'أولوية القسم في استخدام المرفق',
  `schedule` VARCHAR(200) COMMENT 'جدول استخدام المرفق (JSON) - لتحديد أوقات استخدام كل قسم',
  `purpose` VARCHAR(200) COMMENT 'الغرض من التخصيص (تدريس، أنشطة، إداري)',
  `inventoryTransferred` VARCHAR(200) COMMENT 'هل تم نقل العهدة؟',
  `inventoryList` VARCHAR(200) COMMENT 'قائمة العهد المنقولة (JSON)',
  `handoverDocument` VARCHAR(200) COMMENT 'مستند التسليم (مسار الملف)',
  `handoverDate` DATE COMMENT 'تاريخ التسليم',
  `handoverAcceptedBy` VARCHAR(200) COMMENT 'مستلم العهدة (FK → Employee.employeeId)',
  `handoverNotes` TEXT COMMENT 'ملاحظات التسليم',
  `status` VARCHAR(50) COMMENT 'حالة التخصيص (نشط، منتهي، ملغي)',
  `terminationDate` DATE COMMENT 'تاريخ إنهاء التخصيص',
  `terminationReason` VARCHAR(200) COMMENT 'سبب الإنهاء',
  `terminatedByUserId` BIGINT COMMENT 'معرف من أنهى التخصيص',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`assignmentId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`facilityId`) REFERENCES `Classroom`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`responsibleUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assistantResponsibleUserId`) REFERENCES `AssistantResponsibleUser`(`...`),
  -- FOREIGN KEY (`handoverAcceptedBy`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`terminatedByUserId`) REFERENCES `TerminatedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تخصيص المرافق التعليمية';

-- Table: AcademicAssetMapping (الربط الأكاديمي والمنهجي)
CREATE TABLE IF NOT EXISTS `AcademicAssetMapping` (
  `mappingId` BIGINT NOT NULL COMMENT 'معرف الربط (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - اختياري (للربط بسنة محددة)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `curriculumId` BIGINT COMMENT 'معرف المنهج (FK → Curriculum.curriculumId) - اختياري',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل (FK → SchoolSemester.semesterId) - اختياري',
  `assetType` VARCHAR(50) COMMENT 'نوع الأصل المطلوب (قاعة، معمل، جهاز، كتاب، برنامج، مستهلكات)',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصل (FK → AssetCategory.categoryId) - من قسم الأصول',
  `assetId` BIGINT COMMENT 'معرف أصل محدد (إن وجد) - اختياري',
  `assetName` VARCHAR(200) COMMENT 'اسم الأصل المطلوب (للوصف)',
  `assetDescription` TEXT COMMENT 'وصف الأصل المطلوب',
  `quantityPerStudent` VARCHAR(50) COMMENT 'الكمية المطلوبة لكل طالب',
  `quantityPerClass` VARCHAR(50) COMMENT 'الكمية المطلوبة لكل فصل',
  `quantityPerSchool` VARCHAR(50) COMMENT 'الكمية المطلوبة للمدرسة ككل',
  `ratio` VARCHAR(200) COMMENT 'النسبة المعيارية (مثلاً: 1:2 تعني جهاز لكل طالبين)',
  `ratioType` VARCHAR(50) COMMENT 'نوع النسبة (طلاب:جهاز، طلاب:كتاب، فصول:معمل)',
  `minRequiredQty` VARCHAR(200) COMMENT 'الحد الأدنى المطلوب لتشغيل المقرر',
  `recommendedQty` VARCHAR(200) COMMENT 'الكمية الموصى بها',
  `currentAvailableQty` VARCHAR(200) COMMENT 'الكمية المتوفرة حالياً (حقل غير مخزن - يحسب آلياً)',
  `shortageQty` VARCHAR(200) COMMENT 'مقدار النقص (يحسب آلياً)',
  `priority` VARCHAR(200) COMMENT 'أولوية توفير هذا الأصل للمادة (عالية، متوسطة، منخفضة)',
  `isCritical` BOOLEAN COMMENT 'هل هو حرج (لا يمكن تدريس المادة بدونه)؟',
  `isNiceToHave` BOOLEAN COMMENT 'هل هو للتحسين وليس أساسياً؟',
  `preferredClassroomType` VARCHAR(50) COMMENT 'نوع القاعة المناسب (عادي، معمل فيزياء، معمل كيمياء، معمل حاسب، صالة رياضية)',
  `requiredFacilities` VARCHAR(200) COMMENT 'التجهيزات المطلوبة (JSON) - مثل (سبورة ذكية، بروجيكتور، إنترنت)',
  `requiredSoftware` VARCHAR(200) COMMENT 'البرامج المطلوبة (JSON) - للمواد التقنية',
  `requiredConsumables` VARCHAR(200) COMMENT 'المستهلكات المطلوبة (JSON) - مثل المواد الكيميائية',
  `specifications` VARCHAR(200) COMMENT 'المواصفات الفنية المطلوبة (نص)',
  `standards` VARCHAR(200) COMMENT 'المعايير المطلوبة (ISO، الخ)',
  `alternativeOptions` VARCHAR(200) COMMENT 'بدائل مقبولة (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`mappingId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`curriculumId`) REFERENCES `Curriculum`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الربط الأكاديمي والمنهجي';


-- ============================
-- Module: M3_Employee
-- ============================

-- Table: Employee (الموظف)
CREATE TABLE IF NOT EXISTS `Employee` (
  `employeeId` BIGINT NOT NULL COMMENT 'معرف الموظف (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `employeeCode` VARCHAR(50) COMMENT 'كود الموظف (رقم وظيفي فريد)',
  `nationalId` BIGINT COMMENT 'رقم الهوية أو الإقامة (فريد)',
  `nationalIdType` VARCHAR(50) COMMENT 'نوع الهوية (سعودي، مقيم، خليجي، زائر)',
  `nationalIdExpiryDate` DATE COMMENT 'تاريخ انتهاء الهوية',
  `passportNumber` INT COMMENT 'رقم جواز السفر (لغير السعوديين)',
  `passportExpiryDate` DATE COMMENT 'تاريخ انتهاء الجواز',
  `residenceNumber` INT COMMENT 'رقم الإقامة (للمقيمين)',
  `residenceExpiryDate` DATE COMMENT 'تاريخ انتهاء الإقامة',
  `residenceSponsor` VARCHAR(200) COMMENT 'اسم الكفيل (للمقيمين)',
  `firstNameAr` VARCHAR(200) COMMENT 'الاسم الأول بالعربية',
  `fatherNameAr` VARCHAR(200) COMMENT 'اسم الأب بالعربية',
  `grandfatherNameAr` VARCHAR(200) COMMENT 'اسم الجد بالعربية',
  `familyNameAr` VARCHAR(200) COMMENT 'اسم العائلة بالعربية',
  `fullNameAr` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية (يجمع تلقائياً)',
  `firstNameEn` VARCHAR(200) COMMENT 'الاسم الأول بالإنجليزية',
  `fatherNameEn` VARCHAR(200) COMMENT 'اسم الأب بالإنجليزية',
  `grandfatherNameEn` VARCHAR(200) COMMENT 'اسم الجد بالإنجليزية',
  `familyNameEn` VARCHAR(200) COMMENT 'اسم العائلة بالإنجليزية',
  `fullNameEn` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية (يجمع تلقائياً)',
  `fullNameArNormalized` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية للتطبيع (بدون تشكيل)',
  `fullNameEnNormalized` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية للتطبيع (أحرف كبيرة)',
  `gender` VARCHAR(200) COMMENT 'الجنس (ذكر، أنثى)',
  `birthDate` DATE COMMENT 'تاريخ الميلاد',
  `birthPlace` VARCHAR(200) COMMENT 'مكان الميلاد',
  `nationality` VARCHAR(200) COMMENT 'الجنسية',
  `maritalStatus` VARCHAR(50) COMMENT 'الحالة الاجتماعية (أعزب، متزوج، مطلق، أرمل)',
  `numberOfDependents` INT COMMENT 'عدد المعالين',
  `numberOfChildren` INT COMMENT 'عدد الأبناء',
  `spouseName` VARCHAR(200) COMMENT 'اسم الزوج/الزوجة (إن وجد)',
  `spousePhone` VARCHAR(20) COMMENT 'هاتف الزوج/الزوجة',
  `emergencyContactName` VARCHAR(200) COMMENT 'اسم جهة الاتصال في حالات الطوارئ',
  `emergencyContactPhone` VARCHAR(20) COMMENT 'هاتف جهة الاتصال',
  `emergencyContactRelation` VARCHAR(200) COMMENT 'صلة القرابة',
  `bloodType` VARCHAR(50) COMMENT 'فصيلة الدم',
  `hasSpecialNeeds` BOOLEAN COMMENT 'هل لديه احتياجات خاصة؟',
  `specialNeedsDetails` VARCHAR(200) COMMENT 'تفاصيل الاحتياجات الخاصة',
  `medicalConditions` VARCHAR(200) COMMENT 'حالات طبية مهمة',
  `allergies` VARCHAR(200) COMMENT 'حساسيات',
  `phonePrimary` VARCHAR(20) COMMENT 'رقم الجوال الأساسي',
  `phoneSecondary` VARCHAR(20) COMMENT 'رقم جوال إضافي',
  `emailPersonal` VARCHAR(100) COMMENT 'البريد الإلكتروني الشخصي',
  `emailOfficial` VARCHAR(100) COMMENT 'البريد الإلكتروني الرسمي (من المدرسة)',
  `address` VARCHAR(200) COMMENT 'العنوان التفصيلي',
  `city` VARCHAR(200) COMMENT 'المدينة',
  `district` VARCHAR(200) COMMENT 'الحي',
  `street` VARCHAR(200) COMMENT 'الشارع',
  `buildingNumber` INT COMMENT 'رقم المبنى',
  `unitNumber` INT COMMENT 'رقم الوحدة',
  `postalCode` VARCHAR(50) COMMENT 'الرمز البريدي',
  `additionalNumber` INT COMMENT 'الرقم الإضافي',
  `profilePhoto` VARCHAR(200) COMMENT 'صورة الموظف (مسار الملف)',
  `idCardImage` VARCHAR(200) COMMENT 'صورة بطاقة الهوية',
  `passportImage` VARCHAR(200) COMMENT 'صورة جواز السفر',
  `contractType` VARCHAR(50) COMMENT 'نوع العقد (دائم، مؤقت، موسمي، تحت التدريب)',
  `employeeType` VARCHAR(50) COMMENT 'نوع الموظف (معلم، إداري، فني، مشرف، مدير)',
  `category` VARCHAR(50) COMMENT 'فئة الموظف (سعودي، غير سعودي)',
  `departmentId` BIGINT COMMENT 'معرف القسم (FK → SchoolDepartment.deptId)',
  `jobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي',
  `jobGrade` DECIMAL(5,2) COMMENT 'المستوى الوظيفي (درجة)',
  `jobRank` VARCHAR(200) COMMENT 'الرتبة الوظيفية',
  `specialization` VARCHAR(200) COMMENT 'التخصص (للمعلمين)',
  `qualification` VARCHAR(200) COMMENT 'المؤهل العلمي',
  `qualificationSource` VARCHAR(200) COMMENT 'جهة المؤهل',
  `graduationYear` VARCHAR(200) COMMENT 'سنة التخرج',
  `graduationGrade` DECIMAL(5,2) COMMENT 'تقدير التخرج',
  `experienceYears` VARCHAR(200) COMMENT 'عدد سنوات الخبرة',
  `previousEmployer` VARCHAR(200) COMMENT 'جهة العمل السابقة',
  `hireDate` DATE COMMENT 'تاريخ التعيين',
  `startDate` DATE COMMENT 'تاريخ بدء العمل (المباشرة)',
  `endDate` DATE COMMENT 'تاريخ انتهاء الخدمة (إن وجد)',
  `employmentStatus` VARCHAR(50) COMMENT 'الحالة الوظيفية (على رأس العمل، إعارة، ندب، إجازة، منتهية الخدمة)',
  `statusReason` VARCHAR(50) COMMENT 'سبب تغيير الحالة',
  `statusDate` DATE COMMENT 'تاريخ تغيير الحالة',
  `isActive` BOOLEAN COMMENT 'موظف نشط؟',
  `canLogin` VARCHAR(200) COMMENT 'هل يمكنه الدخول للنظام؟',
  `portalUsername` VARCHAR(200) COMMENT 'اسم مستخدم البوابة',
  `portalPasswordHash` VARCHAR(200) COMMENT 'كلمة مرور مشفرة',
  `lastLoginDate` DATE COMMENT 'آخر تاريخ دخول',
  `lastLoginIp` VARCHAR(200) COMMENT 'آخر عنوان IP',
  `twoFactorEnabled` VARCHAR(200) COMMENT 'هل تفعيل المصادقة الثنائية؟',
  `preferredLanguage` VARCHAR(200) COMMENT 'اللغة المفضلة (عربية، إنجليزية)',
  `notificationPreference` VARCHAR(200) COMMENT 'تفضيلات الإشعارات (JSON)',
  `bankName` VARCHAR(200) COMMENT 'اسم البank',
  `bankAccountNumber` INT COMMENT 'رقم الحساب البنكي',
  `bankIban` VARCHAR(200) COMMENT 'رقم IBAN',
  `bankAccountName` INT COMMENT 'اسم صاحب الحساب',
  `hasDrivingLicense` BOOLEAN COMMENT 'هل لديه رخصة قيادة؟',
  `drivingLicenseNumber` INT COMMENT 'رقم الرخصة',
  `drivingLicenseExpiry` DATE COMMENT 'تاريخ انتهاء الرخصة',
  `hasCar` BOOLEAN COMMENT 'هل يملك سيارة؟',
  `carPlateNumber` INT COMMENT 'رقم لوحة السيارة',
  `parkingPermit` VARCHAR(200) COMMENT 'تصريح موقف',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات (تسجيل يدوي، استيراد)',
  `importBatchId` BIGINT COMMENT 'معرف دفعة الاستيراد',
  `verificationStatus` VARCHAR(50) COMMENT 'حالة التحقق من البيانات',
  `verifiedByUserId` BIGINT COMMENT 'معرف الموظف الذي تحقق',
  `verificationDate` DATE COMMENT 'تاريخ التحقق',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `deletedAt` DATE COMMENT 'تاريخ الحذف',
  `deletedByUserId` BIGINT COMMENT 'معرف من حذف',
  PRIMARY KEY (`employeeId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`nationalId`) REFERENCES `National`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`importBatchId`) REFERENCES `ImportBatch`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `VerifiedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
  -- FOREIGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`)
) COMMENT='الموظف';

-- Table: AppointmentDecision (قرار التعيين)
CREATE TABLE IF NOT EXISTS `AppointmentDecision` (
  `decisionId` BIGINT NOT NULL COMMENT 'معرف القرار (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `decisionNumber` INT COMMENT 'الرقم الرسمي للقرار (فريد)',
  `decisionDate` DATE COMMENT 'تاريخ صدور القرار (هجري)',
  `decisionDateGregorian` DATE COMMENT 'تاريخ صدور القرار (ميلادي)',
  `decisionSource` VARCHAR(200) COMMENT 'مصدر القرار (وزارة، مكتب تربية، إدارة المدرسة)',
  `decisionType` VARCHAR(50) COMMENT 'نوع القرار (تعيين جديد، ترقية، تمديد، تحويل)',
  `jobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي في القرار',
  `jobGrade` DECIMAL(5,2) COMMENT 'الدرجة الوظيفية',
  `jobRank` VARCHAR(200) COMMENT 'الرتبة (إن وجدت)',
  `departmentId` BIGINT COMMENT 'معرف القسم المعين به (FK → SchoolDepartment.deptId)',
  `employmentType` VARCHAR(50) COMMENT 'نوع التوظيف (دائم، مؤقت، موسمي)',
  `contractType` VARCHAR(50) COMMENT 'نوع العقد (دوام كامل، دوام جزئي)',
  `startDate` DATE COMMENT 'تاريخ المباشرة الفعلي',
  `probationPeriod` VARCHAR(200) COMMENT 'فترة التجربة (بالأشهر)',
  `probationEndDate` DATE COMMENT 'تاريخ انتهاء فترة التجربة (تحسب آلياً)',
  `salaryAmount` DECIMAL(15,2) COMMENT 'الراتب المقرر في القرار',
  `allowanceDetails` VARCHAR(200) COMMENT 'تفاصيل البدلات (JSON)',
  `otherBenefits` VARCHAR(200) COMMENT 'مزايا أخرى (سكن، مواصلات)',
  `attachmentPath` VARCHAR(200) COMMENT 'مسار ملف القرار الممسوح (PDF)',
  `attachmentName` VARCHAR(200) COMMENT 'اسم الملف',
  `attachmentType` VARCHAR(50) COMMENT 'نوع الملف',
  `approvedBy` VARCHAR(200) COMMENT 'جهة الاعتماد',
  `approvedByName` VARCHAR(200) COMMENT 'اسم المعتمد',
  `approvedByTitle` VARCHAR(200) COMMENT 'صفة المعتمد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`decisionId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='قرار التعيين';

-- Table: EmployeeDocuments (المستندات والوثائق)
CREATE TABLE IF NOT EXISTS `EmployeeDocuments` (
  `documentId` BIGINT NOT NULL COMMENT 'معرف الوثيقة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `documentType` VARCHAR(50) COMMENT 'نوع الوثيقة (هوية، جواز سفر، إقامة، شهادة علمية، شهادة خبرة، عقد عمل، سيرة ذاتية، صورة شخصية، تقرير طبي، أخرى)',
  `documentSubType` VARCHAR(50) COMMENT 'النوع الفرعي (للتخصص)',
  `documentName` VARCHAR(200) COMMENT 'اسم الوثيقة (للعرض)',
  `documentNumber` INT COMMENT 'رقم الوثيقة (مثل رقم الشهادة)',
  `issuingAuthority` BOOLEAN COMMENT 'جهة الإصدار',
  `issuingCountry` BOOLEAN COMMENT 'بلد الإصدار',
  `issueDate` DATE COMMENT 'تاريخ الإصدار',
  `expiryDate` DATE COMMENT 'تاريخ انتهاء الصلاحية (إن وجد)',
  `isExpiryRequired` DATE COMMENT 'هل تتطلب تاريخ انتهاء؟',
  `expiryReminderSent` VARCHAR(200) COMMENT 'هل تم إرسال تذكير بانتهاء الصلاحية؟',
  `expiryReminderDate` DATE COMMENT 'تاريخ إرسال التذكير',
  `filePath` VARCHAR(200) COMMENT 'مسار التخزين',
  `fileName` VARCHAR(200) COMMENT 'اسم الملف',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف (بايت)',
  `fileType` VARCHAR(50) COMMENT 'نوع الملف (PDF, JPG, PNG, DOCX)',
  `fileHash` VARCHAR(200) COMMENT 'قيمة تجزئة الملف (للتحقق)',
  `thumbnailPath` VARCHAR(200) COMMENT 'مسار الصورة المصغرة',
  `description` TEXT COMMENT 'وصف الوثيقة',
  `tags` VARCHAR(200) COMMENT 'علامات تصنيف (للبحث)',
  `isRequired` BOOLEAN COMMENT 'وثيقة إلزامية؟',
  `isVerified` BOOLEAN COMMENT 'هل تم التحقق منها؟',
  `verifiedByUserId` BIGINT COMMENT 'معرف من تحقق (FK → SystemUser.userId)',
  `verificationDate` DATE COMMENT 'تاريخ التحقق',
  `verificationNotes` TEXT COMMENT 'ملاحظات التحقق',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن رفضت)',
  `status` VARCHAR(50) COMMENT 'حالة الوثيقة (مرفوعة، قيد المراجعة، مقبولة، مرفوضة، منتهية الصلاحية)',
  `accessLevel` VARCHAR(50) COMMENT 'مستوى الوصول (عام، خاص، سري)',
  `isConfidential` BOOLEAN COMMENT 'وثيقة سرية؟',
  `sharedWith` VARCHAR(200) COMMENT 'مشارك مع (JSON)',
  `downloadCount` INT COMMENT 'عدد مرات التحميل',
  `lastDownloadedAt` DATE COMMENT 'آخر تاريخ تحميل',
  `lastDownloadedByUserId` BIGINT COMMENT 'آخر من حمّل',
  `isArchived` BOOLEAN COMMENT 'مؤرشفة؟',
  `archivedAt` DATE COMMENT 'تاريخ الأرشفة',
  `archivedByUserId` BIGINT COMMENT 'معرف من أرشف',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`documentId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`lastDownloadedByUserId`) REFERENCES `LastDownloadedByUser`(`...`),
  -- FOREIGN KEY (`archivedByUserId`) REFERENCES `ArchivedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المستندات والوثائق';

-- Table: EmployeeInventoryCustody (عهدة الموظف)
CREATE TABLE IF NOT EXISTS `EmployeeInventoryCustody` (
  `custodyId` BIGINT NOT NULL COMMENT 'معرف العهدة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId) - من قسم الأصول',
  `itemType` VARCHAR(50) COMMENT 'نوع القطعة (لاب توب، كمبيوتر، جهاز لوحي، مفاتيح، كتب، أدوات، زي موحد، أخرى)',
  `itemName` VARCHAR(200) COMMENT 'اسم القطعة',
  `itemDescription` TEXT COMMENT 'وصف القطعة',
  `itemBrand` VARCHAR(200) COMMENT 'الماركة',
  `itemModel` VARCHAR(200) COMMENT 'الموديل',
  `itemSerial` VARCHAR(200) COMMENT 'الرقم التسلسلي للقطعة (مهم جداً)',
  `itemCode` VARCHAR(50) COMMENT 'كود المخزون للقطعة',
  `itemColor` VARCHAR(200) COMMENT 'اللون',
  `estimatedValue` VARCHAR(200) COMMENT 'القيمة التقديرية',
  `conditionAtHandover` VARCHAR(200) COMMENT 'حالة العهدة عند التسليم (جديد، بحالة جيدة، مستعمل، يحتاج صيانة)',
  `handoverDate` DATE COMMENT 'تاريخ التسليم',
  `handoverNotes` TEXT COMMENT 'ملاحظات عند التسليم',
  `issuedByUserId` BIGINT COMMENT 'معرف المسلِّم (FK → Employee.employeeId)',
  `receivedByUserId` BIGINT COMMENT 'معرف المستلم (الموظف نفسه)',
  `receiptSignature` VARCHAR(200) COMMENT 'توقيع الاستلام (إلكتروني أو مسار صورة)',
  `receiptFormPath` VARCHAR(200) COMMENT 'مسار ملف نموذج الاستلام الموقع',
  `expectedReturnDate` DATE COMMENT 'تاريخ الإرجاع المتوقع',
  `actualReturnDate` DATE COMMENT 'تاريخ الإرجاع الفعلي',
  `conditionAtReturn` VARCHAR(200) COMMENT 'حالة العهدة عند الإرجاع',
  `returnNotes` TEXT COMMENT 'ملاحظات الإرجاع',
  `returnedToUserId` BIGINT COMMENT 'معرف مستلم الإرجاع',
  `returnReceiptSignature` VARCHAR(200) COMMENT 'توقيع استلام الإرجاع',
  `isReturned` BOOLEAN COMMENT 'هل تم الإرجاع؟',
  `isDamaged` BOOLEAN COMMENT 'هل حدث تلف؟',
  `damageDescription` TEXT COMMENT 'وصف التلف',
  `damageDate` DATE COMMENT 'تاريخ التلف',
  `damageReportedByUserId` BIGINT COMMENT 'معرف من أبلغ عن التلف',
  `damagePhotos` VARCHAR(200) COMMENT 'صور التلف (JSON)',
  `penaltyAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة (إن وجدت)',
  `penaltyStatus` VARCHAR(50) COMMENT 'حالة الغرامة',
  `isLost` BOOLEAN COMMENT 'مفقودة؟',
  `lostDate` DATE COMMENT 'تاريخ الفقدان',
  `lostNotes` TEXT COMMENT 'ملاحظات الفقدان',
  `replacementRequired` VARCHAR(200) COMMENT 'هل تحتاج استبدال؟',
  `replacementDate` DATE COMMENT 'تاريخ الاستبدال',
  `replacementCustodyId` BIGINT COMMENT 'معرف العهدة البديلة',
  `status` VARCHAR(50) COMMENT 'حالة العهدة (نشطة، مسترجعة، مفقودة، تالفة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`custodyId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`issuedByUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`receivedByUserId`) REFERENCES `ReceivedByUser`(`...`),
  -- FOREIGN KEY (`returnedToUserId`) REFERENCES `ReturnedToUser`(`...`),
  -- FOREIGN KEY (`damageReportedByUserId`) REFERENCES `DamageReportedByUser`(`...`),
  -- FOREIGN KEY (`replacementCustodyId`) REFERENCES `ReplacementCustody`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='عهدة الموظف';

-- Table: StaffCustody (عهد الموظفين)
CREATE TABLE IF NOT EXISTS `StaffCustody` (
  `staffCustodyId` BIGINT NOT NULL COMMENT 'معرف عهدة الموظف (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `custodySummary` VARCHAR(200) COMMENT 'ملخص العهد (JSON) - يمكن أن يحتوي على قائمة بالعهد أو إجماليات',
  `totalItems` VARCHAR(200) COMMENT 'إجمالي عدد القطع',
  `totalEstimatedValue` VARCHAR(200) COMMENT 'إجمالي القيمة التقديرية',
  `issueDate` DATE COMMENT 'تاريخ تسليم العهدة للموظف (بداية العلاقة)',
  `lastUpdateDate` DATE COMMENT 'آخر تحديث للعهد',
  `custodyStatus` VARCHAR(50) COMMENT 'حالة العهدة (بذمة الموظف، تم إخلاء الطرف، قيد التسوية)',
  `clearanceDate` DATE COMMENT 'تاريخ إخلاء الطرف',
  `clearedByUserId` BIGINT COMMENT 'معرف من اعتمد الإخلاء',
  `clearanceNotes` TEXT COMMENT 'ملاحظات الإخلاء',
  `documentPath` VARCHAR(200) COMMENT 'مسار ملف "نموذج استلام عهدة" موقع',
  `documentName` VARCHAR(200) COMMENT 'اسم المستند',
  `documentUploadedAt` DATE COMMENT 'تاريخ رفع المستند',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`staffCustodyId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`clearedByUserId`) REFERENCES `ClearedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='عهد الموظفين';

-- Table: EmployeeAttendance (الحضور والانصراف للموظفين)
CREATE TABLE IF NOT EXISTS `EmployeeAttendance` (
  `attendanceId` BIGINT NOT NULL COMMENT 'معرف الحضور (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - للمدارس المتعددة',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `attendanceDate` DATE COMMENT 'تاريخ اليوم',
  `dayOfWeek` VARCHAR(200) COMMENT 'اليوم (السبت، الأحد...)',
  `shiftId` BIGINT COMMENT 'معرف الفترة (صباحي، مسائي) (FK → SchoolShiftSetting.shiftId)',
  `expectedCheckIn` VARCHAR(200) COMMENT 'وقت الدخول المتوقع (من جدول الفترات)',
  `expectedCheckOut` VARCHAR(200) COMMENT 'وقت الخروج المتوقع',
  `checkInTime` TIME COMMENT 'وقت الحضور الفعلي',
  `checkOutTime` TIME COMMENT 'وقت الانصراف الفعلي',
  `checkInMethod` VARCHAR(200) COMMENT 'طريقة تسجيل الحضور (بصمة، كارت، تطبيق، يدوي، QR)',
  `checkOutMethod` VARCHAR(200) COMMENT 'طريقة تسجيل الانصراف',
  `deviceId` BIGINT COMMENT 'معرف جهاز البصمة (إن وجد)',
  `deviceName` VARCHAR(200) COMMENT 'اسم الجهاز',
  `locationVerified` VARCHAR(200) COMMENT 'هل تم التحقق من الموقع؟',
  `checkInLocation` VARCHAR(200) COMMENT 'موقع تسجيل الحضور (إحداثيات GPS)',
  `checkOutLocation` VARCHAR(200) COMMENT 'موقع تسجيل الانصراف',
  `checkInIP` VARCHAR(200) COMMENT 'عنوان IP عند تسجيل الحضور',
  `checkOutIP` VARCHAR(200) COMMENT 'عنوان IP عند تسجيل الانصراف',
  `checkInPhoto` VARCHAR(200) COMMENT 'صورة أثناء تسجيل الحضور (إن وجدت)',
  `checkOutPhoto` VARCHAR(200) COMMENT 'صورة أثناء تسجيل الانصراف',
  `status` VARCHAR(50) COMMENT 'حالة الحضور (حاضر، غائب، متأخر، إجازة، مهمة رسمية، تدريب)',
  `lateMinutes` VARCHAR(200) COMMENT 'دقائق التأخير (تحسب آلياً)',
  `earlyDepartureMinutes` VARCHAR(200) COMMENT 'دقائق الانصراف المبكر',
  `overtimeMinutes` TIME COMMENT 'دقائق العمل الإضافي (تحسب آلياً)',
  `overtimeRate` TIME COMMENT 'نسبة احتساب overtime (1.5، 2)',
  `isOvertimeApproved` TIME COMMENT 'هل تمت الموافقة على overtime؟',
  `overtimeApprovedByUserId` BIGINT COMMENT 'معرف من وافق',
  `totalWorkHours` VARCHAR(200) COMMENT 'إجمالي ساعات العمل (تحسب)',
  `breakHours` VARCHAR(200) COMMENT 'ساعات الاستراحة (تخصم)',
  `netWorkHours` VARCHAR(200) COMMENT 'صافي ساعات العمل',
  `isExcused` BOOLEAN COMMENT 'غياب بعذر؟',
  `excuseId` BIGINT COMMENT 'معرف الإجازة (FK → EmployeeLeave.leaveId) - إن كان غياباً بإجازة',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر',
  `excuseApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد العذر',
  `excuseApprovedAt` DATE COMMENT 'تاريخ اعتماد العذر',
  `absenceReason` VARCHAR(200) COMMENT 'سبب الغياب (إن كان غياباً بدون عذر)',
  `absenceType` VARCHAR(50) COMMENT 'نوع الغياب (بدون عذر، بعذر، مأذون)',
  `isHoliday` BOOLEAN COMMENT 'هل اليوم إجازة رسمية؟',
  `isWeekend` BOOLEAN COMMENT 'هل هو يوم عطلة أسبوعية؟',
  `isWorkingDay` BOOLEAN COMMENT 'هل هو يوم عمل فعلي؟',
  `replacementEmployeeId` BIGINT COMMENT 'معرف الموظف البديل (إن وجد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `recordedById` BIGINT COMMENT 'معرف مسجل الحضور (للحضور اليدوي)',
  `verifiedById` BIGINT COMMENT 'معرف من تحقق من الحضور',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `isOverridden` BOOLEAN COMMENT 'هل تم تجاوز النظام وتعديل الحضور؟',
  `overrideReason` VARCHAR(200) COMMENT 'سبب التجاوز',
  `overriddenByUserId` BIGINT COMMENT 'معرف من قام بالتجاوز',
  `overrideAt` VARCHAR(200) COMMENT 'وقت التجاوز',
  `previousCheckIn` VARCHAR(200) COMMENT 'وقت الحضور قبل التعديل',
  `previousCheckOut` VARCHAR(200) COMMENT 'وقت الانصراف قبل التعديل',
  `isSyncedWithPayroll` BOOLEAN COMMENT 'هل تم تصديره للرواتب؟',
  `syncedAt` VARCHAR(200) COMMENT 'وقت التصدير',
  `payrollId` BIGINT COMMENT 'معرف كشف الراتب المرتبط (FK → EmployeePayroll.payrollId) - بعد إنشاء الراتب',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`attendanceId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`deviceId`) REFERENCES `Device`(`...`),
  -- FOREIGN KEY (`overtimeApprovedByUserId`) REFERENCES `OvertimeApprovedByUser`(`...`),
  -- FOREIGN KEY (`excuseId`) REFERENCES `EmployeeLeave`(`...`),
  -- FOREIGN KEY (`excuseApprovedByUserId`) REFERENCES `ExcuseApprovedByUser`(`...`),
  -- FOREIGN KEY (`replacementEmployeeId`) REFERENCES `ReplacementEmployee`(`...`),
  -- FOREIGN KEY (`recordedById`) REFERENCES `RecordedBy`(`...`),
  -- FOREIGN KEY (`verifiedById`) REFERENCES `VerifiedBy`(`...`),
  -- FOREIGN KEY (`overriddenByUserId`) REFERENCES `OverriddenByUser`(`...`),
  -- FOREIGN KEY (`payrollId`) REFERENCES `EmployeePayroll`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الحضور والانصراف للموظفين';

-- Table: TeacherSchedule (الجدول الدراسي للمعلم)
CREATE TABLE IF NOT EXISTS `TeacherSchedule` (
  `scheduleId` BIGINT NOT NULL COMMENT 'معرف الجدول (المفتاح الرئيسي)',
  `teacherId` BIGINT COMMENT 'معرف المعلم (FK → Employee.employeeId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `dayOfWeek` VARCHAR(200) COMMENT 'اليوم (السبت=1، الأحد=2...)',
  `periodId` BIGINT COMMENT 'معرف الحصة (FK → ClassPeriod.periodId)',
  `periodNumber` INT COMMENT 'رقم الحصة (للبحث السريع)',
  `courseId` BIGINT COMMENT 'معرف المادة (FK → Course.courseId)',
  `sectionId` BIGINT COMMENT 'معرف الشعبة (FK → ClassSection.sectionId)',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId)',
  `classroomId` BIGINT COMMENT 'معرف القاعة (FK → Classroom.classroomId)',
  `isSubstitute` BOOLEAN COMMENT 'هل هي حصة نيابة؟',
  `originalTeacherId` BIGINT COMMENT 'معرف المعلم الأصلي (إن كانت نيابة)',
  `substituteDate` DATE COMMENT 'تاريخ النيابة',
  `substituteReason` VARCHAR(200) COMMENT 'سبب النيابة',
  `isActive` BOOLEAN COMMENT 'هل الحصة نشطة في الجدول؟',
  `isCancelled` BOOLEAN COMMENT 'هل ألغيت الحصة؟',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء',
  `cancelledAt` DATE COMMENT 'تاريخ الإلغاء',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`scheduleId`),
  -- FOREIGN KEY (`teacherId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`periodId`) REFERENCES `ClassPeriod`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`sectionId`) REFERENCES `ClassSection`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`classroomId`) REFERENCES `Classroom`(`...`),
  -- FOREIGN KEY (`originalTeacherId`) REFERENCES `OriginalTeacher`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الجدول الدراسي للمعلم';

-- Table: EmployeePayroll (الرواتب)
CREATE TABLE IF NOT EXISTS `EmployeePayroll` (
  `payrollId` BIGINT NOT NULL COMMENT 'معرف كشف الراتب (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `payrollMonth` VARCHAR(200) COMMENT 'شهر الاستحقاق (1-12)',
  `payrollYear` VARCHAR(200) COMMENT 'سنة الاستحقاق',
  `payrollPeriod` VARCHAR(200) COMMENT 'فترة الراتب (شهرية، نصف شهرية)',
  `payrollCode` VARCHAR(50) COMMENT 'كود كشف الراتب (فريد)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء الكشف',
  `paymentDate` DATE COMMENT 'تاريخ الصرف الفعلي',
  `basicSalary` DECIMAL(15,2) COMMENT 'الراتب الأساسي',
  `contractualSalary` DECIMAL(15,2) COMMENT 'الراتب التعاقدي (في العقد)',
  `positionAllowance` VARCHAR(200) COMMENT 'بدل موقع',
  `transportationAllowance` VARCHAR(200) COMMENT 'بدل مواصلات',
  `housingAllowance` VARCHAR(200) COMMENT 'بدل سكن',
  `communicationAllowance` VARCHAR(200) COMMENT 'بدل اتصالات',
  `foodAllowance` VARCHAR(200) COMMENT 'بدل غذاء',
  `educationAllowance` VARCHAR(200) COMMENT 'بدل تعليم (للأبناء)',
  `professionalAllowance` VARCHAR(200) COMMENT 'بدل احتراف',
  `dangerAllowance` VARCHAR(200) COMMENT 'بدل خطورة',
  `overtimeAmount` TIME COMMENT 'مبلغ العمل الإضافي (يُحسب من الحضور)',
  `overtimeHours` TIME COMMENT 'عدد ساعات العمل الإضافي',
  `overtimeRate` TIME COMMENT 'سعر الساعة الإضافية',
  `bonusAmount` DECIMAL(15,2) COMMENT 'مبلغ المكافآت',
  `bonusReason` VARCHAR(200) COMMENT 'سبب المكافأة',
  `incentiveAmount` DECIMAL(15,2) COMMENT 'مبلغ الحوافز',
  `otherEarnings` VARCHAR(200) COMMENT 'مستحقات أخرى (JSON)',
  `totalEarnings` VARCHAR(200) COMMENT 'إجمالي المستحقات (يحسب آلياً)',
  `socialInsuranceDeduction` VARCHAR(200) COMMENT 'خصم التأمينات الاجتماعية',
  `socialInsuranceNumber` INT COMMENT 'رقم التأمين الاجتماعي',
  `taxDeduction` VARCHAR(200) COMMENT 'خصم الضريبة',
  `taxId` BIGINT COMMENT 'الرقم الضريبي',
  `absenceDeduction` VARCHAR(200) COMMENT 'خصم الغياب (يُحسب من الحضور)',
  `lateDeduction` VARCHAR(200) COMMENT 'خصم التأخير',
  `penaltyDeduction` VARCHAR(200) COMMENT 'خصم الجزاءات (من EmployeeViolations)',
  `loanDeduction` VARCHAR(200) COMMENT 'خصم القروض والسلف',
  `advanceDeduction` VARCHAR(200) COMMENT 'خصم السلف المستردة',
  `healthInsuranceDeduction` VARCHAR(200) COMMENT 'خصم التأمين الصحي',
  `otherDeductions` VARCHAR(200) COMMENT 'استقطاعات أخرى (JSON)',
  `totalDeductions` VARCHAR(200) COMMENT 'إجمالي الاستقطاعات (يحسب آلياً)',
  `netSalary` DECIMAL(15,2) COMMENT 'صافي الراتب (totalEarnings - totalDeductions)',
  `bankName` VARCHAR(200) COMMENT 'اسم البنك',
  `bankAccountNumber` INT COMMENT 'رقم الحساب',
  `bankIban` VARCHAR(200) COMMENT 'رقم IBAN',
  `transferReference` VARCHAR(200) COMMENT 'رقم مرجع التحويل البنكي',
  `transferDate` DATE COMMENT 'تاريخ التحويل',
  `transferStatus` VARCHAR(50) COMMENT 'حالة التحويل (جاري، تم، فشل)',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع (تحويل بنكي، شيك، كاش)',
  `checkNumber` INT COMMENT 'رقم الشيك (إن وجد)',
  `receiptIssued` VARCHAR(200) COMMENT 'هل تم إصدار إيصال؟',
  `receiptNumber` INT COMMENT 'رقم الإيصال',
  `receiptPath` VARCHAR(200) COMMENT 'مسار ملف الإيصال',
  `status` VARCHAR(50) COMMENT 'حالة كشف الراتب (مسودة، معتمد، مدفوع، ملغي)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `paidByUserId` BIGINT COMMENT 'معرف من صرف',
  `paidAt` DATE COMMENT 'تاريخ الصرف',
  `attendanceSummary` VARCHAR(200) COMMENT 'ملخص الحضور للشهر (JSON) - لحفظ البيانات التي بني عليها الراتب',
  `attendanceFromDate` DATE COMMENT 'تاريخ بداية فترة الحضور المحتسبة',
  `attendanceToDate` DATE COMMENT 'تاريخ نهاية فترة الحضور',
  `workingDays` VARCHAR(200) COMMENT 'عدد أيام العمل في الشهر',
  `actualWorkingDays` VARCHAR(200) COMMENT 'أيام العمل الفعلية للموظف',
  `absenceDays` VARCHAR(200) COMMENT 'أيام الغياب',
  `lateDays` VARCHAR(200) COMMENT 'أيام التأخير',
  `notes` TEXT COMMENT 'ملاحظات',
  `previousPayrollId` BIGINT COMMENT 'معرف كشف الراتب السابق (للمقارنة)',
  `isAdjusted` BOOLEAN COMMENT 'هل تم تعديله بعد الصرف؟',
  `adjustmentReason` VARCHAR(200) COMMENT 'سبب التعديل',
  `adjustedAt` DATE COMMENT 'تاريخ التعديل',
  `adjustedByUserId` BIGINT COMMENT 'معرف من عدل',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`payrollId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`taxId`) REFERENCES `Tax`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`paidByUserId`) REFERENCES `PaidByUser`(`...`),
  -- FOREIGN KEY (`previousPayrollId`) REFERENCES `PreviousPayroll`(`...`),
  -- FOREIGN KEY (`adjustedByUserId`) REFERENCES `AdjustedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الرواتب';

-- Table: EmployeeLeave (الإجازات)
CREATE TABLE IF NOT EXISTS `EmployeeLeave` (
  `leaveId` BIGINT NOT NULL COMMENT 'معرف الإجازة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `leaveType` VARCHAR(50) COMMENT 'نوع الإجازة (سنوية، مرضية، عارضة، أمومة، أبوة، حج، دراسة، بدون راتب، تعويضية، رسمية)',
  `leaveSubType` VARCHAR(50) COMMENT 'النوع الفرعي (للتخصيص)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - لتتبع الرصيد السنوي',
  `requestDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `startDate` DATE COMMENT 'تاريخ بداية الإجازة',
  `endDate` DATE COMMENT 'تاريخ نهاية الإجازة',
  `totalDays` VARCHAR(200) COMMENT 'إجمالي عدد الأيام (تحسب آلياً)',
  `actualDays` VARCHAR(200) COMMENT 'أيام العمل الفعلية في هذه الإجازة (بعد استبعاد العطل)',
  `returnDate` DATE COMMENT 'تاريخ العودة المتوقع',
  `actualReturnDate` DATE COMMENT 'تاريخ العودة الفعلي',
  `reason` VARCHAR(200) COMMENT 'سبب الإجازة (نص)',
  `description` TEXT COMMENT 'وصف تفصيلي',
  `attachmentPath` VARCHAR(200) COMMENT 'مسار المستند الداعم (تقرير طبي، خطاب جهة)',
  `attachmentName` VARCHAR(200) COMMENT 'اسم المستند',
  `emergencyContact` VARCHAR(200) COMMENT 'جهة اتصال أثناء الإجازة',
  `emergencyPhone` VARCHAR(20) COMMENT 'هاتف للطوارئ',
  `workHandover` VARCHAR(200) COMMENT 'تسليم العمل (نص)',
  `handoverToEmployeeId` BIGINT COMMENT 'معرف الموظف المستلم للعمل (FK → Employee.employeeId)',
  `handoverNotes` TEXT COMMENT 'ملاحظات التسليم',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (قيد الانتظار، معتمدة، مرفوضة، ملغاة، منتهية)',
  `reviewedByUserId` BIGINT COMMENT 'معرف المراجع (FK → SystemUser.userId)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewNotes` TEXT COMMENT 'ملاحظات المراجعة',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `isPaid` BIGINT COMMENT 'إجازة مدفوعة؟',
  `paidPercentage` DECIMAL(5,2) COMMENT 'نسبة الراتب المدفوع أثناء الإجازة (100%، 50%، الخ)',
  `salaryDeduction` DECIMAL(15,2) COMMENT 'قيمة الخصم من الراتب (إن وجد)',
  `balanceBefore` DECIMAL(15,2) COMMENT 'رصيد الإجازات قبل الطلب',
  `balanceAfter` DECIMAL(15,2) COMMENT 'رصيد الإجازات بعد الطلب',
  `consumedFromBalance` DECIMAL(15,2) COMMENT 'المبلغ المستهلك من الرصيد',
  `leaveBalanceId` BIGINT COMMENT 'معرف سجل الرصيد المرتبط (من جدول أرصدة الإجازات)',
  `isDeducted` BOOLEAN COMMENT 'هل تم خصمها من الرصيد؟',
  `attendanceIds` VARCHAR(200) COMMENT 'معرفات أيام الغياب المرتبطة (JSON)',
  `isLinkedToAttendance` BOOLEAN COMMENT 'هل تم ربطها بالحضور؟',
  `linkedByUserId` BIGINT COMMENT 'معرف من قام بالربط',
  `linkedAt` DATE COMMENT 'تاريخ الربط',
  `isExpired` BOOLEAN COMMENT 'هل انتهت الإجازة؟',
  `expiredAt` DATE COMMENT 'تاريخ انتهاء الصلاحية (للإجازات المؤقتة)',
  `isAutoApproved` BOOLEAN COMMENT 'تمت الموافقة التلقائية؟',
  `autoApprovalRule` VARCHAR(200) COMMENT 'قاعدة الموافقة التلقائية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`leaveId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`handoverToEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`isPaid`) REFERENCES `IsPa`(`...`),
  -- FOREIGN KEY (`leaveBalanceId`) REFERENCES `LeaveBalance`(`...`),
  -- FOREIGN KEY (`linkedByUserId`) REFERENCES `LinkedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإجازات';

-- Table: PerformanceReview (جدول تقييم الأداء)
CREATE TABLE IF NOT EXISTS `PerformanceReview` (
  `reviewId` BIGINT NOT NULL COMMENT 'معرف التقييم (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف المُقيَّم (FK → Employee.employeeId)',
  `reviewerId` BIGINT COMMENT 'معرف المُقيِّم (FK → Employee.employeeId) - غالباً المشرف المباشر',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - للتقييمات الفصلية',
  `reviewPeriod` VARCHAR(200) COMMENT 'فترة التقييم (ربع أول، ربع ثاني، نصف سنوي، سنوي)',
  `reviewDate` DATE COMMENT 'تاريخ التقييم',
  `reviewType` VARCHAR(50) COMMENT 'نوع التقييم (سنوي، تجريبي، استثنائي، ترقية)',
  `evaluationMethod` VARCHAR(200) COMMENT 'طريقة التقييم (مباشر، 360 درجة، ذاتي)',
  `criteria` VARCHAR(200) COMMENT 'معايير التقييم (JSON) - قائمة المعايير والدرجات',
  `overallScore` DECIMAL(5,2) COMMENT 'الدرجة النهائية (من 100 أو من 5)',
  `overallRating` VARCHAR(200) COMMENT 'التقييم النهائي (ممتاز، جيد جداً، جيد، مقبول، ضعيف)',
  `strengths` VARCHAR(200) COMMENT 'نقاط القوة (نص)',
  `improvementAreas` VARCHAR(200) COMMENT 'نقاط التطوير (نص)',
  `achievements` VARCHAR(200) COMMENT 'إنجازات الموظف خلال الفترة',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهها',
  `goals` VARCHAR(200) COMMENT 'الأهداف المنجزة',
  `futureGoals` VARCHAR(200) COMMENT 'أهداف الفترة القادمة',
  `developmentPlan` VARCHAR(200) COMMENT 'خطة التطوير الفردية',
  `trainingNeeds` VARCHAR(200) COMMENT 'الاحتياجات التدريبية',
  `promotionRecommendation` VARCHAR(200) COMMENT 'توصية بالترقية؟',
  `promotionTo` VARCHAR(200) COMMENT 'المنصب المقترح (إن وجد)',
  `salaryIncrease` DECIMAL(15,2) COMMENT 'زيادة مقترحة في الراتب',
  `bonusRecommendation` VARCHAR(200) COMMENT 'توصية بمكافأة؟',
  `bonusAmount` DECIMAL(15,2) COMMENT 'المبلغ المقترح للمكافأة',
  `selfEvaluation` VARCHAR(200) COMMENT 'التقييم الذاتي (JSON) - إن وجد',
  `selfEvaluationScore` DECIMAL(5,2) COMMENT 'درجة التقييم الذاتي',
  `selfEvaluationNotes` TEXT COMMENT 'ملاحظات التقييم الذاتي',
  `reviewerComments` TEXT COMMENT 'تعليقات المُقيِّم',
  `employeeComments` TEXT COMMENT 'تعليقات الموظف على التقييم',
  `employeeAcknowledged` VARCHAR(200) COMMENT 'هل اطلع الموظف على التقييم؟',
  `acknowledgedAt` DATE COMMENT 'تاريخ الاطلاع',
  `acknowledgedIP` VARCHAR(200) COMMENT 'عنوان IP عند الاطلاع',
  `status` VARCHAR(50) COMMENT 'حالة التقييم (مسودة، مكتمل، معتمد، مقفول)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `isFinal` BOOLEAN COMMENT 'هل هو التقييم النهائي؟',
  `previousReviewId` BIGINT COMMENT 'معرف التقييم السابق (للمقارنة)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reviewId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`reviewerId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`previousReviewId`) REFERENCES `PreviousReview`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='جدول تقييم الأداء';

-- Table: EmployeeViolations (المخالفات والجزاءات)
CREATE TABLE IF NOT EXISTS `EmployeeViolations` (
  `violationId` BIGINT NOT NULL COMMENT 'معرف المخالفة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `reportedByUserId` BIGINT COMMENT 'معرف مقدم البلاغ (FK → SystemUser.userId)',
  `reportedByRole` VARCHAR(200) COMMENT 'دور مقدم البلاغ (مشرف، مدير، زميل، جهة خارجية)',
  `violationDate` DATE COMMENT 'تاريخ وقوع المخالفة',
  `violationTime` TIME COMMENT 'وقت المخالفة (إن وجد)',
  `reportedDate` DATE COMMENT 'تاريخ الإبلاغ',
  `violationType` VARCHAR(50) COMMENT 'نوع المخالفة (تأخير، غياب بدون عذر، إهمال عمل، سوء سلوك، إساءة للطلاب، انتهاك لوائح، خرق أمني، أخرى)',
  `violationCategory` VARCHAR(50) COMMENT 'فئة المخالفة (إدارية، سلوكية، مهنية، أمنية)',
  `severityLevel` VARCHAR(50) COMMENT 'مستوى الخطورة (بسيط، متوسط، جسيم، شديد)',
  `description` TEXT COMMENT 'وصف تفصيلي للمخالفة',
  `location` VARCHAR(200) COMMENT 'مكان المخالفة',
  `witnesses` VARCHAR(200) COMMENT 'الشهود (JSON) - أسماء وأدوار',
  `evidence` VARCHAR(200) COMMENT 'الأدلة (JSON) - مسارات ملفات الصور، المستندات، التسجيلات',
  `previousWarnings` VARCHAR(200) COMMENT 'هل سبق إنذار الموظف؟',
  `previousViolationIds` VARCHAR(200) COMMENT 'معرفات مخالفات سابقة لنفس الموظف (JSON)',
  `policyViolated` VARCHAR(200) COMMENT 'اللائحة أو النظام المنتهك',
  `policySection` VARCHAR(200) COMMENT 'البند المخالف من اللائحة',
  `action` VARCHAR(200) COMMENT 'الإجراء/الجزاء المتخذ (إنذار شفوي، إنذار كتابي، خصم مالي، حرمان من علاوة، إيقاف مؤقت، فصل، إحالة للتحقيق)',
  `actionDetails` VARCHAR(200) COMMENT 'تفاصيل الإجراء',
  `actionDate` DATE COMMENT 'تاريخ تنفيذ الإجراء',
  `actionByUserId` BIGINT COMMENT 'معرف من نفذ الإجراء (FK → SystemUser.userId)',
  `actionApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد الإجراء',
  `actionApprovalDate` DATE COMMENT 'تاريخ اعتماد الإجراء',
  `penaltyAmount` DECIMAL(15,2) COMMENT 'مبلغ الخصم المالي (إن وجد)',
  `penaltyCurrency` VARCHAR(200) COMMENT 'عملة الخصم',
  `penaltyPercentage` DECIMAL(5,2) COMMENT 'نسبة الخصم من الراتب',
  `deductionFromSalary` DECIMAL(15,2) COMMENT 'هل يخصم من الراتب؟',
  `deductionMonth` VARCHAR(200) COMMENT 'شهر الخصم',
  `deductionYear` VARCHAR(200) COMMENT 'سنة الخصم',
  `payrollId` BIGINT COMMENT 'معرف كشف الراتب المرتبط (FK → EmployeePayroll.payrollId)',
  `suspensionStartDate` DATE COMMENT 'تاريخ بداية الإيقاف (إن وجد)',
  `suspensionEndDate` DATE COMMENT 'تاريخ نهاية الإيقاف',
  `suspensionDays` VARCHAR(200) COMMENT 'عدد أيام الإيقاف',
  `demotionFrom` VARCHAR(200) COMMENT 'المنصب قبل خفض الدرجة',
  `demotionTo` VARCHAR(200) COMMENT 'المنصب بعد خفض الدرجة',
  `terminationDate` DATE COMMENT 'تاريخ الفصل (إن وجد)',
  `terminationReason` VARCHAR(200) COMMENT 'سبب الفصل',
  `appealAllowed` VARCHAR(200) COMMENT 'هل يسمح بالاعتراض؟',
  `appealDeadline` VARCHAR(200) COMMENT 'مهلة الاعتراض',
  `appealSubmitted` VARCHAR(200) COMMENT 'هل تم تقديم اعتراض؟',
  `appealDate` DATE COMMENT 'تاريخ الاعتراض',
  `appealReason` VARCHAR(200) COMMENT 'سبب الاعتراض',
  `appealDocuments` VARCHAR(200) COMMENT 'مستندات الاعتراض (JSON)',
  `appealReviewDate` DATE COMMENT 'تاريخ مراجعة الاعتراض',
  `appealReviewByUserId` BIGINT COMMENT 'معرف مراجع الاعتراض',
  `appealDecision` VARCHAR(200) COMMENT 'قرار الاعتراض (قبول، رفض، تخفيف)',
  `appealDecisionDate` DATE COMMENT 'تاريخ قرار الاعتراض',
  `appealNotes` TEXT COMMENT 'ملاحظات على الاعتراض',
  `finalDecision` VARCHAR(200) COMMENT 'القرار النهائي',
  `isResolved` BOOLEAN COMMENT 'هل تم حل المخالفة؟',
  `resolvedAt` DATE COMMENT 'تاريخ الحل',
  `resolvedByUserId` BIGINT COMMENT 'معرف من قام بالحل',
  `resolutionNotes` TEXT COMMENT 'ملاحظات الحل',
  `notificationToEmployee` VARCHAR(200) COMMENT 'هل تم إشعار الموظف؟',
  `employeeNotifiedAt` VARCHAR(200) COMMENT 'وقت الإشعار',
  `employeeAcknowledged` VARCHAR(200) COMMENT 'هل اطلع الموظف؟',
  `employeeAcknowledgedAt` VARCHAR(200) COMMENT 'وقت الاطلاع',
  `employeeSignature` VARCHAR(200) COMMENT 'توقيع الموظف على الإقرار',
  `isConfidential` BOOLEAN COMMENT 'مخالفة سرية؟',
  `status` VARCHAR(50) COMMENT 'حالة المخالفة (مسجلة، قيد التحقيق، صدر القرار، قيد الاعتراض، منتهية)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات إضافية',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`violationId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`reportedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`actionByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`actionApprovedByUserId`) REFERENCES `ActionApprovedByUser`(`...`),
  -- FOREIGN KEY (`payrollId`) REFERENCES `EmployeePayroll`(`...`),
  -- FOREIGN KEY (`appealReviewByUserId`) REFERENCES `AppealReviewByUser`(`...`),
  -- FOREIGN KEY (`resolvedByUserId`) REFERENCES `ResolvedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المخالفات والجزاءات';

-- Table: EmployeeTraining (التدريب والتطوير)
CREATE TABLE IF NOT EXISTS `EmployeeTraining` (
  `trainingId` BIGINT NOT NULL COMMENT 'معرف الدورة/البرنامج (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `trainingName` VARCHAR(200) COMMENT 'اسم الدورة التدريبية',
  `trainingCode` VARCHAR(50) COMMENT 'كود الدورة (إن وجد)',
  `trainingType` VARCHAR(50) COMMENT 'نوع التدريب (دورة داخلية، دورة خارجية، مؤتمر، ورشة عمل، تدريب عن بعد، تعليم مستمر)',
  `category` VARCHAR(50) COMMENT 'فئة التدريب (إداري، تربوي، تقني، تطوير ذاتي، قيادي، لغة)',
  `provider` VARCHAR(200) COMMENT 'الجهة المنظمة',
  `providerType` VARCHAR(50) COMMENT 'نوع الجهة (مركز تدريب، جامعة، شركة، وزارة)',
  `trainerName` VARCHAR(200) COMMENT 'اسم المدرب',
  `trainerTitle` VARCHAR(200) COMMENT 'مؤهلات المدرب',
  `location` VARCHAR(200) COMMENT 'مكان التدريب',
  `country` INT COMMENT 'بلد التدريب',
  `city` VARCHAR(200) COMMENT 'مدينة التدريب',
  `isOnline` BOOLEAN COMMENT 'تدريب عن بعد؟',
  `onlineLink` VARCHAR(200) COMMENT 'رابط الدورة (إن وجد)',
  `startDate` DATE COMMENT 'تاريخ بداية الدورة',
  `endDate` DATE COMMENT 'تاريخ نهاية الدورة',
  `totalHours` VARCHAR(200) COMMENT 'عدد الساعات التدريبية',
  `totalDays` VARCHAR(200) COMMENT 'عدد الأيام',
  `hoursPerDay` VARCHAR(200) COMMENT 'ساعات التدريب اليومية',
  `creditHours` VARCHAR(200) COMMENT 'ساعات معتمدة (إن وجدت)',
  `accreditation` VARCHAR(200) COMMENT 'جهة الاعتماد (إن وجدت)',
  `objectives` VARCHAR(200) COMMENT 'أهداف الدورة',
  `topics` VARCHAR(200) COMMENT 'المواضيع المغطاة (JSON)',
  `targetAudience` VARCHAR(200) COMMENT 'الفئة المستهدفة',
  `prerequisites` VARCHAR(200) COMMENT 'المتطلبات السابقة',
  `cost` DECIMAL(15,2) COMMENT 'تكلفة الدورة',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `paidBy` VARCHAR(200) COMMENT 'جهة الدفع (المدرسة، الموظف، منحة)',
  `registrationDate` DATE COMMENT 'تاريخ التسجيل',
  `registrationStatus` VARCHAR(50) COMMENT 'حالة التسجيل (مؤكد، قائمة انتظار، ملغي)',
  `attendanceStatus` VARCHAR(50) COMMENT 'حالة الحضور (حاضر، غائب، حضور جزئي)',
  `attendanceDays` VARCHAR(200) COMMENT 'أيام الحضور الفعلية (JSON)',
  `completionStatus` VARCHAR(50) COMMENT 'حالة الإكمال (مكتمل، غير مكتمل، منسحب)',
  `completionDate` DATE COMMENT 'تاريخ الإكمال',
  `grade` DECIMAL(5,2) COMMENT 'التقدير/الدرجة (إن وجد)',
  `gradePercentage` DECIMAL(5,2) COMMENT 'النسبة المئوية',
  `passingStatus` VARCHAR(50) COMMENT 'ناجح/راسب',
  `certificateIssued` VARCHAR(200) COMMENT 'هل صدرت شهادة؟',
  `certificateNumber` INT COMMENT 'رقم الشهادة',
  `certificateDate` DATE COMMENT 'تاريخ الشهادة',
  `certificateExpiryDate` DATE COMMENT 'تاريخ انتهاء صلاحية الشهادة (إن وجد)',
  `certificatePath` VARCHAR(200) COMMENT 'مسار ملف الشهادة (PDF/صورة)',
  `certificateName` VARCHAR(200) COMMENT 'اسم ملف الشهادة',
  `evaluation` VARCHAR(200) COMMENT 'تقييم الموظف للدورة (1-5)',
  `evaluationFeedback` DECIMAL(15,2) COMMENT 'تعليقات الموظف على الدورة',
  `trainerEvaluation` VARCHAR(200) COMMENT 'تقييم المدرب للموظف',
  `skillsAcquired` VARCHAR(200) COMMENT 'المهارات المكتسبة (JSON)',
  `impactOnWork` VARCHAR(200) COMMENT 'أثر التدريب على العمل',
  `isRequired` BOOLEAN COMMENT 'تدريب إلزامي؟',
  `isRecurring` BOOLEAN COMMENT 'يتكرر دورياً؟',
  `recurringPeriod` VARCHAR(200) COMMENT 'فترة التكرار',
  `recommendedBy` VARCHAR(200) COMMENT 'الموصي بالتدريب (المشرف، تقييم الأداء، إدارة)',
  `linkedToReviewId` BIGINT COMMENT 'معرف تقييم الأداء المرتبط (FK → PerformanceReview.reviewId)',
  `linkedToGoal` VARCHAR(200) COMMENT 'مرتبط بهدف تطويري',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`trainingId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`linkedToReviewId`) REFERENCES `PerformanceReview`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التدريب والتطوير';

-- Table: EmployeeAdditionalTasks (المهام الإضافية)
CREATE TABLE IF NOT EXISTS `EmployeeAdditionalTasks` (
  `taskId` BIGINT NOT NULL COMMENT 'معرف المهمة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `taskName` VARCHAR(200) COMMENT 'اسم المهمة (رائد فصل، منسق جودة، عضو كنترول، مشرف طابور، منسق نشاط، أمين مصادر، مشرف مختبر، رئيس لجنة)',
  `taskCode` VARCHAR(50) COMMENT 'كود المهمة',
  `taskType` VARCHAR(50) COMMENT 'نوع المهمة (إشرافية، تنظيمية، فنية، تربوية)',
  `description` TEXT COMMENT 'شرح تفصيلي للمسؤوليات المطلوبة',
  `objectives` VARCHAR(200) COMMENT 'أهداف المهمة',
  `deliverables` VARCHAR(200) COMMENT 'مخرجات المهمة المتوقعة',
  `scope` VARCHAR(200) COMMENT 'نطاق المهمة (على مستوى الصف، المرحلة، المدرسة)',
  `assignedByUserId` BIGINT COMMENT 'معرف من كلّف بالمهمة (FK → SystemUser.userId)',
  `assignedDate` DATE COMMENT 'تاريخ التكليف',
  `startDate` DATE COMMENT 'تاريخ بدء التكليف الفعلي',
  `endDate` DATE COMMENT 'تاريخ انتهاء التكليف المتوقع',
  `actualEndDate` DATE COMMENT 'تاريخ انتهاء التكليف الفعلي',
  `duration` VARCHAR(200) COMMENT 'مدة التكليف (بالأشهر)',
  `isOngoing` BOOLEAN COMMENT 'مستمرة؟',
  `isActive` BOOLEAN COMMENT 'هل المهمة نشطة حالياً؟',
  `priority` VARCHAR(200) COMMENT 'أولوية المهمة (عاجلة، مهمة، عادية)',
  `status` VARCHAR(50) COMMENT 'حالة المهمة (مخطط لها، جارية، مكتملة، متعثرة، ملغاة)',
  `progressPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز',
  `accomplishments` VARCHAR(200) COMMENT 'الإنجازات المحققة (نص)',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهت التنفيذ',
  `performanceRating` VARCHAR(200) COMMENT 'تقييم إنجاز هذه المهمة (من 1 إلى 5 أو ممتاز، جيد، الخ)',
  `ratingDate` DATE COMMENT 'تاريخ التقييم',
  `ratedByUserId` BIGINT COMMENT 'معرف من قام بالتقييم',
  `ratingNotes` TEXT COMMENT 'ملاحظات التقييم',
  `allowanceAmount` DECIMAL(15,2) COMMENT 'قيمة البدل الشهري لهذه المهمة (إن وجد)',
  `allowanceType` VARCHAR(50) COMMENT 'نوع البدل (ثابت، نسبة)',
  `isPaid` BIGINT COMMENT 'هل يتم صرف بدل؟',
  `payrollIncluded` VARCHAR(200) COMMENT 'هل تم تضمينه في الراتب؟',
  `bonusAmount` DECIMAL(15,2) COMMENT 'قيمة المكافأة عند الإنجاز (إن وجدت)',
  `bonusPaid` BIGINT COMMENT 'هل صرفت المكافأة؟',
  `bonusPaidDate` DATE COMMENT 'تاريخ صرف المكافأة',
  `completionNotes` TEXT COMMENT 'ملاحظات عند إغلاق المهمة',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON)',
  `relatedTo` VARCHAR(200) COMMENT 'مرتبط بـ (نشاط، لجنة، مشروع)',
  `relatedId` BIGINT COMMENT 'معرف المرتبط به',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`taskId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assignedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`ratedByUserId`) REFERENCES `RatedByUser`(`...`),
  -- FOREIGN KEY (`isPaid`) REFERENCES `IsPa`(`...`),
  -- FOREIGN KEY (`bonusPaid`) REFERENCES `BonusPa`(`...`),
  -- FOREIGN KEY (`relatedId`) REFERENCES `Related`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المهام الإضافية';

-- Table: Mentor (المعلم المرشد)
CREATE TABLE IF NOT EXISTS `Mentor` (
  `mentorId` BIGINT NOT NULL COMMENT 'معرف العلاقة الإرشادية (المفتاح الرئيسي)',
  `mentorEmployeeId` BIGINT COMMENT 'معرف المعلم المرشد (FK → Employee.employeeId)',
  `menteeEmployeeId` BIGINT COMMENT 'معرف المعلم المتدرب (FK → Employee.employeeId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `startDate` DATE COMMENT 'تاريخ بدء فترة الإرشاد',
  `endDate` DATE COMMENT 'تاريخ انتهاء فترة الإرشاد المتوقع',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `mentorshipType` VARCHAR(50) COMMENT 'نوع الإرشاد (توجيه تربوي، تدريب تقني، متابعة إدارية، تأهيل قيادي)',
  `objectives` VARCHAR(200) COMMENT 'أهداف برنامج الإرشاد',
  `focusAreas` VARCHAR(200) COMMENT 'مجالات التركيز (تخطيط دروس، إدارة صف، استراتيجيات تدريس، تقييم)',
  `meetingFrequency` VARCHAR(200) COMMENT 'دورية الاجتماعات (أسبوعي، كل أسبوعين، شهري)',
  `meetingDuration` VARCHAR(200) COMMENT 'مدة الاجتماع (بالدقائق)',
  `meetingsCount` INT COMMENT 'عدد الاجتماعات المخططة',
  `actualMeetingsCount` INT COMMENT 'عدد الاجتماعات الفعلية',
  `meetingsSchedule` VARCHAR(200) COMMENT 'جدول الاجتماعات (JSON)',
  `nextMeetingDate` DATE COMMENT 'تاريخ الاجتماع القادم',
  `lastMeetingDate` DATE COMMENT 'تاريخ آخر اجتماع',
  `lastMeetingNotes` TEXT COMMENT 'ملاحظات آخر اجتماع',
  `observations` VARCHAR(200) COMMENT 'ملاحظات عامة على تطور المتدرب',
  `strengths` VARCHAR(200) COMMENT 'نقاط القوة التي تم رصدها',
  `areasForImprovement` VARCHAR(200) COMMENT 'مجالات تحتاج تحسين',
  `progressReports` VARCHAR(200) COMMENT 'تقارير التقدم (JSON)',
  `goalsAchieved` VARCHAR(200) COMMENT 'الأهداف التي تحققت',
  `challenges` VARCHAR(200) COMMENT 'التحديات التي واجهت العلاقة الإرشادية',
  `feedbackFromMentee` DECIMAL(15,2) COMMENT 'تقييم المتدرب للمرشد',
  `feedbackFromMentor` DECIMAL(15,2) COMMENT 'تقييم المرشد للمتدرب',
  `satisfactionRating` VARCHAR(200) COMMENT 'معدل الرضا (1-5)',
  `status` VARCHAR(50) COMMENT 'حالة العلاقة (نشطة، مكتملة، متوقفة، ملغاة)',
  `completionStatus` VARCHAR(50) COMMENT 'حالة الإكمال (مكتمل بنجاح، مكتمل جزئياً، لم يكتمل)',
  `completionDate` DATE COMMENT 'تاريخ الإكمال',
  `completionNotes` TEXT COMMENT 'ملاحظات الإكمال',
  `certificateIssued` VARCHAR(200) COMMENT 'هل صدرت شهادة للمتدرب؟',
  `certificateNumber` INT COMMENT 'رقم الشهادة',
  `certificatePath` VARCHAR(200) COMMENT 'مسار الشهادة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`mentorId`),
  -- FOREIGN KEY (`mentorEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`menteeEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المعلم المرشد';

-- Table: SelfServicePortalRequests (البوابة الذاتية وبلاغات الموظفين)
CREATE TABLE IF NOT EXISTS `SelfServicePortalRequests` (
  `requestId` BIGINT NOT NULL COMMENT 'معرف الطلب (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف مقدم الطلب (FK → Employee.employeeId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestNumber` INT COMMENT 'رقم الطلب المتسلسل (يولد آلياً)',
  `requestType` VARCHAR(50) COMMENT 'نوع الطلب (طلب عهدة جديدة، بلاغ عطل جهاز، طلب صيانة مكتب، طلب إجازة، استفسار إداري، طلب مستند، شكوى، اقتراح، طلب تدريب)',
  `requestSubType` VARCHAR(50) COMMENT 'النوع الفرعي (للتخصيص)',
  `category` VARCHAR(50) COMMENT 'فئة الطلب (إداري، فني، مالي، موارد بشرية)',
  `title` VARCHAR(200) COMMENT 'عنوان الطلب (ملخص)',
  `description` TEXT COMMENT 'تفاصيل الطلب أو وصف المشكلة',
  `priority` VARCHAR(200) COMMENT 'الأولوية (عادي، مهم، عاجل، حرج)',
  `impact` VARCHAR(200) COMMENT 'تأثير المشكلة (فردي، مجموعة، قسم، مدرسة كاملة)',
  `location` VARCHAR(200) COMMENT 'موقع المشكلة (مكتب، فصل، معمل)',
  `assetId` BIGINT COMMENT 'معرف الأصل المرتبط (إن كان بلاغ عطل) (FK → Asset.assetId)',
  `assetName` VARCHAR(200) COMMENT 'اسم الأصل (للبلاغات)',
  `requestedDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `requestedTime` TIME COMMENT 'وقت التقديم',
  `desiredCompletionDate` DATE COMMENT 'التاريخ المطلوب للإنجاز',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - صور، مستندات',
  `attachmentPaths` VARCHAR(200) COMMENT 'مسارات المرفقات',
  `assignedToUserId` BIGINT COMMENT 'معرف الموظف المسؤول عن المعالجة (FK → Employee.employeeId)',
  `assignedToDepartment` VARCHAR(200) COMMENT 'القسم المسؤول',
  `assignedAt` DATE COMMENT 'تاريخ التعيين',
  `assignedByUserId` BIGINT COMMENT 'معرف من قام بالتعيين',
  `estimatedCompletionDate` DATE COMMENT 'تاريخ الإنجاز المتوقع',
  `estimatedHours` VARCHAR(200) COMMENT 'الساعات التقديرية للإنجاز',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (مفتوح، قيد المراجعة، قيد التنفيذ، بانتظار رد، منجز، مرفوض، ملغي)',
  `progressPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز',
  `statusHistory` DATE COMMENT 'تاريخ الحالات (JSON) - تتبع تغيرات الحالة',
  `internalNotes` TEXT COMMENT 'ملاحظات داخلية (للمعالجين)',
  `actionTaken` VARCHAR(200) COMMENT 'الإجراءات المتخذة',
  `completionDate` DATE COMMENT 'تاريخ الإنجاز الفعلي',
  `completionTime` TIME COMMENT 'وقت الإنجاز',
  `completedByUserId` BIGINT COMMENT 'معرف من أنجز الطلب',
  `completionNotes` TEXT COMMENT 'ملاحظات الإنجاز',
  `responseToEmployee` VARCHAR(200) COMMENT 'الرد المقدم للموظف',
  `responseDate` DATE COMMENT 'تاريخ الرد',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن رفض)',
  `cancelledByUserId` BIGINT COMMENT 'معرف من ألغى الطلب',
  `cancellationDate` DATE COMMENT 'تاريخ الإلغاء',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء',
  `employeeRating` VARCHAR(200) COMMENT 'تقييم الموظف للخدمة (1-5)',
  `employeeFeedback` DECIMAL(15,2) COMMENT 'ملاحظات الموظف على الخدمة',
  `ratingDate` DATE COMMENT 'تاريخ التقييم',
  `responseTime` TIME COMMENT 'زمن الاستجابة (بين التقديم وأول معالجة)',
  `isUrgent` BOOLEAN COMMENT 'طلب عاجل؟',
  `requiresApproval` VARCHAR(200) COMMENT 'هل يتطلب موافقة؟',
  `approvedByUserId` BIGINT COMMENT 'معرف من وافق (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الموافقة',
  `approvalNotes` TEXT COMMENT 'ملاحظات الموافقة',
  `trackingNumber` INT COMMENT 'رقم المتابعة للموظف',
  `source` VARCHAR(200) COMMENT 'مصدر الطلب (بوابة ذاتية، بريد، استقبال)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`requestId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`assignedToUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`assignedByUserId`) REFERENCES `AssignedByUser`(`...`),
  -- FOREIGN KEY (`completedByUserId`) REFERENCES `CompletedByUser`(`...`),
  -- FOREIGN KEY (`cancelledByUserId`) REFERENCES `CancelledByUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='البوابة الذاتية وبلاغات الموظفين';

-- Table: VacantPosition (الوظائف الشاغرة)
CREATE TABLE IF NOT EXISTS `VacantPosition` (
  `positionId` BIGINT NOT NULL COMMENT 'معرف الوظيفة الشاغرة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `positionCode` VARCHAR(50) COMMENT 'كود الوظيفة (فريد)',
  `jobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي المطلوب',
  `jobGrade` DECIMAL(5,2) COMMENT 'الدرجة الوظيفية',
  `jobRank` VARCHAR(200) COMMENT 'الرتبة (إن وجدت)',
  `departmentId` BIGINT COMMENT 'معرف القسم (FK → SchoolDepartment.deptId)',
  `employmentType` VARCHAR(50) COMMENT 'نوع التوظيف (دائم، مؤقت، موسمي، دوام جزئي)',
  `contractType` VARCHAR(50) COMMENT 'نوع العقد (دوام كامل، دوام جزئي، استشاري)',
  `vacancyReason` VARCHAR(200) COMMENT 'سبب الشغور (توسعة، بديل، استحداث)',
  `replacedEmployeeId` BIGINT COMMENT 'معرف الموظف المستبدل (إن كان بديلاً) (FK → Employee.employeeId)',
  `qualifications` VARCHAR(200) COMMENT 'المؤهلات المطلوبة (JSON)',
  `experienceYears` VARCHAR(200) COMMENT 'عدد سنوات الخبرة المطلوبة',
  `skills` VARCHAR(200) COMMENT 'المهارات المطلوبة (JSON)',
  `certifications` VARCHAR(200) COMMENT 'الشهادات المطلوبة (JSON)',
  `languages` VARCHAR(200) COMMENT 'اللغات المطلوبة (JSON)',
  `ageFrom` VARCHAR(200) COMMENT 'الحد الأدنى للعمر',
  `ageTo` VARCHAR(200) COMMENT 'الحد الأقصى للعمر',
  `gender` VARCHAR(200) COMMENT 'الجنس المطلوب (ذكر، أنثى، لا يهم)',
  `nationality` VARCHAR(200) COMMENT 'الجنسية المطلوبة (إن وجدت)',
  `salaryRangeFrom` DECIMAL(15,2) COMMENT 'الحد الأدنى للراتب',
  `salaryRangeTo` DECIMAL(15,2) COMMENT 'الحد الأقصى للراتب',
  `otherBenefits` VARCHAR(200) COMMENT 'مزايا أخرى (سكن، مواصلات)',
  `jobDescription` TEXT COMMENT 'وصف المهام والمسؤوليات (نص مفصل)',
  `requirements` VARCHAR(200) COMMENT 'متطلبات إضافية',
  `postingDate` DATE COMMENT 'تاريخ نشر الإعلان',
  `postingEndDate` DATE COMMENT 'تاريخ انتهاء الإعلان',
  `postingChannels` VARCHAR(200) COMMENT 'قنوات النشر (داخلي، موقع المدرسة، صحيفة، لينكد إن، الخ)',
  `isInternalOnly` BOOLEAN COMMENT 'متاح داخلياً فقط؟',
  `priority` VARCHAR(200) COMMENT 'أولوية الشغور (عالية، متوسطة، منخفضة)',
  `urgency` VARCHAR(200) COMMENT 'درجة الإلحاح (عاجل، طبيعي)',
  `numberOfPositions` INT COMMENT 'عدد الوظائف الشاغرة',
  `filledPositions` VARCHAR(200) COMMENT 'عدد الوظائف التي تم شغلها',
  `remainingPositions` VARCHAR(200) COMMENT 'عدد الوظائف المتبقية',
  `status` VARCHAR(50) COMMENT 'حالة الوظيفة (شاغرة، قيد الإجراء، تم شغلها، معلقة، ملغاة)',
  `applicationsCount` INT COMMENT 'عدد المتقدمين',
  `shortlistedCount` INT COMMENT 'عدد المقبولين مبدئياً',
  `interviewedCount` INT COMMENT 'عدد من تمت مقابلتهم',
  `offeredCount` INT COMMENT 'عدد من عرضت عليهم الوظيفة',
  `hiredCount` INT COMMENT 'عدد من تم تعيينهم',
  `hiringDate` DATE COMMENT 'تاريخ التعيين المتوقع',
  `actualHiringDate` DATE COMMENT 'تاريخ التعيين الفعلي',
  `hiredEmployeeId` BIGINT COMMENT 'معرف الموظف المعين (FK → Employee.employeeId) - بعد التعيين',
  `closedAt` DATE COMMENT 'تاريخ إغلاق الوظيفة',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق الوظيفة',
  `closingReason` VARCHAR(200) COMMENT 'سبب الإغلاق (تم التعيين، إلغاء، تعليق)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`positionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`replacedEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`hiredEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `ClosedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الوظائف الشاغرة';

-- Table: JobApplicant (المتقدمين للوظائف)
CREATE TABLE IF NOT EXISTS `JobApplicant` (
  `applicantId` BIGINT NOT NULL COMMENT 'معرف المتقدم (المفتاح الرئيسي)',
  `positionId` BIGINT COMMENT 'معرف الوظيفة المتقدم لها (FK → VacantPosition.positionId)',
  `applicationNumber` INT COMMENT 'رقم الطلب (يولد آلياً)',
  `applicationDate` DATE COMMENT 'تاريخ التقديم',
  `firstNameAr` VARCHAR(200) COMMENT 'الاسم الأول بالعربية',
  `fatherNameAr` VARCHAR(200) COMMENT 'اسم الأب بالعربية',
  `grandfatherNameAr` VARCHAR(200) COMMENT 'اسم الجد بالعربية',
  `familyNameAr` VARCHAR(200) COMMENT 'اسم العائلة بالعربية',
  `fullNameAr` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية',
  `firstNameEn` VARCHAR(200) COMMENT 'الاسم الأول بالإنجليزية',
  `fatherNameEn` VARCHAR(200) COMMENT 'اسم الأب بالإنجليزية',
  `familyNameEn` VARCHAR(200) COMMENT 'اسم العائلة بالإنجليزية',
  `fullNameEn` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية',
  `nationalId` BIGINT COMMENT 'رقم الهوية أو الإقامة',
  `nationalIdType` VARCHAR(50) COMMENT 'نوع الهوية',
  `passportNumber` INT COMMENT 'رقم جواز السفر (لغير السعوديين)',
  `birthDate` DATE COMMENT 'تاريخ الميلاد',
  `birthPlace` VARCHAR(200) COMMENT 'مكان الميلاد',
  `gender` VARCHAR(200) COMMENT 'الجنس',
  `nationality` VARCHAR(200) COMMENT 'الجنسية',
  `maritalStatus` VARCHAR(50) COMMENT 'الحالة الاجتماعية',
  `phonePrimary` VARCHAR(20) COMMENT 'رقم الجوال الأساسي',
  `phoneSecondary` VARCHAR(20) COMMENT 'رقم جوال إضافي',
  `email` VARCHAR(100) COMMENT 'البريد الإلكتروني',
  `address` VARCHAR(200) COMMENT 'العنوان',
  `city` VARCHAR(200) COMMENT 'المدينة',
  `qualification` VARCHAR(200) COMMENT 'المؤهل العلمي',
  `qualificationSource` VARCHAR(200) COMMENT 'جهة المؤهل',
  `graduationYear` VARCHAR(200) COMMENT 'سنة التخرج',
  `graduationGrade` DECIMAL(5,2) COMMENT 'تقدير التخرج',
  `experienceYears` VARCHAR(200) COMMENT 'عدد سنوات الخبرة',
  `currentEmployer` VARCHAR(200) COMMENT 'جهة العمل الحالية (إن وجدت)',
  `currentJobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي الحالي',
  `currentSalary` DECIMAL(15,2) COMMENT 'الراتب الحالي',
  `expectedSalary` DECIMAL(15,2) COMMENT 'الراتب المتوقع',
  `skills` VARCHAR(200) COMMENT 'المهارات (JSON)',
  `languages` VARCHAR(200) COMMENT 'اللغات (JSON)',
  `certifications` VARCHAR(200) COMMENT 'الشهادات (JSON)',
  `cvPath` VARCHAR(200) COMMENT 'مسار ملف السيرة الذاتية',
  `cvName` VARCHAR(200) COMMENT 'اسم ملف السيرة الذاتية',
  `portfolioPath` VARCHAR(200) COMMENT 'مسار ملف الأعمال (إن وجد)',
  `coverLetterPath` VARCHAR(200) COMMENT 'مسار خطاب التقديم',
  `attachments` VARCHAR(200) COMMENT 'مرفقات أخرى (JSON)',
  `source` VARCHAR(200) COMMENT 'مصدر التقديم (موقع المدرسة، لينكد إن، توصية، إعلان)',
  `referredBy` VARCHAR(200) COMMENT 'اسم من أوصى به (إن وجد)',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (مقدم، قيد المراجعة، مقبول مبدئياً، للمقابلة، مرفوض، عرض وظيفي، مقبول، ملغي)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewedByUserId` BIGINT COMMENT 'معرف من راجع الطلب',
  `reviewNotes` TEXT COMMENT 'ملاحظات المراجعة',
  `shortlistDate` DATE COMMENT 'تاريخ القبول المبدئي',
  `shortlistNotes` TEXT COMMENT 'ملاحظات القبول المبدئي',
  `interviewDate` DATE COMMENT 'تاريخ المقابلة',
  `interviewTime` TIME COMMENT 'وقت المقابلة',
  `interviewLocation` VARCHAR(200) COMMENT 'مكان المقابلة',
  `interviewers` VARCHAR(200) COMMENT 'أعضاء لجنة المقابلة (JSON) - معرفات الموظفين',
  `interviewType` VARCHAR(50) COMMENT 'نوع المقابلة (شخصية، عن بعد)',
  `interviewLink` VARCHAR(200) COMMENT 'رابط المقابلة (إن كانت عن بعد)',
  `interviewScore` DECIMAL(5,2) COMMENT 'نتيجة المقابلة',
  `interviewFeedback` DECIMAL(15,2) COMMENT 'ملاحظات المقابلة',
  `interviewNotes` TEXT COMMENT 'محضر المقابلة',
  `testDate` DATE COMMENT 'تاريخ الاختبار (إن وجد)',
  `testType` VARCHAR(50) COMMENT 'نوع الاختبار',
  `testScore` DECIMAL(5,2) COMMENT 'نتيجة الاختبار',
  `testFeedback` DECIMAL(15,2) COMMENT 'ملاحظات الاختبار',
  `offerExtended` VARCHAR(200) COMMENT 'هل تم تقديم عرض وظيفي؟',
  `offerDate` DATE COMMENT 'تاريخ تقديم العرض',
  `offerAmount` DECIMAL(15,2) COMMENT 'قيمة العرض المالي',
  `offerDetails` VARCHAR(200) COMMENT 'تفاصيل العرض (بدلات، مزايا)',
  `offerAccepted` VARCHAR(200) COMMENT 'هل قبل العرض؟',
  `acceptanceDate` DATE COMMENT 'تاريخ القبول',
  `acceptanceNotes` TEXT COMMENT 'ملاحظات القبول',
  `offerRejectionReason` VARCHAR(200) COMMENT 'سبب رفض العرض',
  `hiredAsEmployeeId` BIGINT COMMENT 'معرف الموظف بعد التعيين (FK → Employee.employeeId)',
  `hiredDate` DATE COMMENT 'تاريخ التعيين',
  `isBlacklisted` BOOLEAN COMMENT 'هل المتقدم في القائمة السوداء؟',
  `blacklistReason` VARCHAR(200) COMMENT 'سبب الإدراج في القائمة السوداء',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`applicantId`),
  -- FOREIGN KEY (`positionId`) REFERENCES `VacantPosition`(`...`),
  -- FOREIGN KEY (`nationalId`) REFERENCES `National`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `ReviewedByUser`(`...`),
  -- FOREIGN KEY (`hiredAsEmployeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المتقدمين للوظائف';

-- Table: EmployeeCommittees (المجالس واللجان)
CREATE TABLE IF NOT EXISTS `EmployeeCommittees` (
  `committeeId` BIGINT NOT NULL COMMENT 'معرف اللجنة/المجلس (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `committeeCode` VARCHAR(50) COMMENT 'كود اللجنة',
  `committeeNameAr` VARCHAR(200) COMMENT 'اسم اللجنة بالعربية',
  `committeeNameEn` VARCHAR(200) COMMENT 'اسم اللجنة بالإنجليزية',
  `committeeType` VARCHAR(50) COMMENT 'نوع اللجنة (إدارية، تربوية، مالية، اجتماعية، نظامية، فنية، تخطيط، تطوير)',
  `committeeCategory` VARCHAR(50) COMMENT 'فئة اللجنة (دائمة، مؤقتة، استشارية، تنفيذية)',
  `formationDate` DATE COMMENT 'تاريخ تشكيل اللجنة',
  `formationDecisionNumber` INT COMMENT 'رقم قرار التشكيل',
  `formationDecisionDate` DATE COMMENT 'تاريخ قرار التشكيل',
  `formationDecisionPath` VARCHAR(200) COMMENT 'مسار ملف قرار التشكيل',
  `startDate` DATE COMMENT 'تاريخ بدء عمل اللجنة',
  `endDate` DATE COMMENT 'تاريخ انتهاء عمل اللجنة المتوقع',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `duration` VARCHAR(200) COMMENT 'مدة اللجنة (بالشهور)',
  `objectives` VARCHAR(200) COMMENT 'أهداف اللجنة واختصاصاتها',
  `responsibilities` VARCHAR(200) COMMENT 'مسؤوليات اللجنة',
  `meetingFrequency` VARCHAR(200) COMMENT 'دورية الاجتماعات (أسبوعي، شهري، ربع سنوي)',
  `reportingTo` VARCHAR(200) COMMENT 'الجهة التي ترفع لها اللجنة تقاريرها (مدير المدرسة، مجلس الإدارة)',
  `parentCommitteeId` BIGINT COMMENT 'معرف اللجنة الأم (إن كانت لجنة فرعية)',
  `chairpersonId` BIGINT COMMENT 'معرف رئيس اللجنة (FK → Employee.employeeId)',
  `viceChairpersonId` BIGINT COMMENT 'معرف نائب الرئيس (FK → Employee.employeeId)',
  `secretaryId` BIGINT COMMENT 'معرف مقرر اللجنة (FK → Employee.employeeId)',
  `spokespersonId` BIGINT COMMENT 'معرف المتحدث الرسمي (إن وجد)',
  `membersCount` INT COMMENT 'عدد الأعضاء',
  `quorum` VARCHAR(200) COMMENT 'النصاب القانوني للاجتماعات',
  `decisionMakingMethod` VARCHAR(200) COMMENT 'طريقة اتخاذ القرارات (تصويت، توافق، أغلبية)',
  `budget` VARCHAR(200) COMMENT 'ميزانية اللجنة (إن وجدت)',
  `budgetSource` VARCHAR(200) COMMENT 'مصدر الميزانية',
  `isActive` BOOLEAN COMMENT 'هل اللجنة نشطة؟',
  `status` VARCHAR(50) COMMENT 'حالة اللجنة (نشطة، متوقفة، منحلة)',
  `dissolutionDate` DATE COMMENT 'تاريخ الحل',
  `dissolutionReason` VARCHAR(200) COMMENT 'سبب الحل',
  `dissolutionDecisionNumber` INT COMMENT 'رقم قرار الحل',
  `dissolutionDecisionPath` VARCHAR(200) COMMENT 'مسار ملف قرار الحل',
  `achievements` VARCHAR(200) COMMENT 'إنجازات اللجنة (ملخص)',
  `reports` VARCHAR(200) COMMENT 'تقارير اللجنة (JSON) - مسارات ملفات',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`committeeId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`parentCommitteeId`) REFERENCES `ParentCommittee`(`...`),
  -- FOREIGN KEY (`chairpersonId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`viceChairpersonId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`secretaryId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`spokespersonId`) REFERENCES `Spokesperson`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المجالس واللجان';

-- Table: CommitteeMembers (أعضاء المجالس)
CREATE TABLE IF NOT EXISTS `CommitteeMembers` (
  `memberId` BIGINT NOT NULL COMMENT 'معرف العضوية (المفتاح الرئيسي)',
  `committeeId` BIGINT COMMENT 'معرف اللجنة (FK → EmployeeCommittees.committeeId)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `role` VARCHAR(200) COMMENT 'الدور في اللجنة (رئيس، نائب رئيس، مقرر، عضو، خبير، مستشار)',
  `roleDetails` VARCHAR(200) COMMENT 'تفاصيل الدور (وصف المهام)',
  `appointmentDate` DATE COMMENT 'تاريخ التعيين في اللجنة',
  `appointmentDecisionNumber` INT COMMENT 'رقم قرار التعيين (إن وجد)',
  `startDate` DATE COMMENT 'تاريخ بدء العضوية',
  `endDate` DATE COMMENT 'تاريخ انتهاء العضوية المتوقع',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `isActive` BOOLEAN COMMENT 'عضوية نشطة؟',
  `status` VARCHAR(50) COMMENT 'حالة العضوية (نشطة، منتهية، مستقال، منتهية)',
  `resignationDate` DATE COMMENT 'تاريخ الاستقالة (إن وجد)',
  `resignationReason` VARCHAR(200) COMMENT 'سبب الاستقالة',
  `terminationDate` DATE COMMENT 'تاريخ إنهاء العضوية',
  `terminationReason` VARCHAR(200) COMMENT 'سبب الإنهاء',
  `terminatedByUserId` BIGINT COMMENT 'معرف من أنهى العضوية',
  `attendanceRate` DECIMAL(5,2) COMMENT 'نسبة حضور اجتماعات اللجنة',
  `votingRights` VARCHAR(200) COMMENT 'هل له حق التصويت؟',
  `signatureAuthority` VARCHAR(200) COMMENT 'هل له صلاحية التوقيع؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`memberId`),
  -- FOREIGN KEY (`committeeId`) REFERENCES `EmployeeCommittees`(`...`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`terminatedByUserId`) REFERENCES `TerminatedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='أعضاء المجالس';

-- Table: EmployeeMeetings (اجتماعات الموظفين)
CREATE TABLE IF NOT EXISTS `EmployeeMeetings` (
  `meetingId` BIGINT NOT NULL COMMENT 'معرف الاجتماع (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `committeeId` BIGINT COMMENT 'معرف اللجنة (FK → EmployeeCommittees.committeeId) - إن كان اجتماع لجنة',
  `meetingType` VARCHAR(50) COMMENT 'نوع الاجتماع (لجنة، قسم، إداري، عام، مع أولياء أمور، تدريبي)',
  `meetingNumber` INT COMMENT 'رقم الاجتماع (تسلسلي حسب النوع)',
  `title` VARCHAR(200) COMMENT 'عنوان الاجتماع',
  `objectives` VARCHAR(200) COMMENT 'أهداف الاجتماع',
  `agenda` VARCHAR(200) COMMENT 'جدول الأعمال (JSON) - بنود الاجتماع',
  `organizerId` BIGINT COMMENT 'معرف المنظم (FK → Employee.employeeId)',
  `organizerDepartment` VARCHAR(200) COMMENT 'القسم المنظم',
  `chairpersonId` BIGINT COMMENT 'معرف رئيس الاجتماع (FK → Employee.employeeId)',
  `secretaryId` BIGINT COMMENT 'معرف مقرر الاجتماع (FK → Employee.employeeId) - مسؤول المحضر',
  `meetingDate` DATE COMMENT 'تاريخ الاجتماع',
  `startTime` TIME COMMENT 'وقت البداية',
  `endTime` TIME COMMENT 'وقت النهاية المتوقع',
  `actualEndTime` TIME COMMENT 'وقت النهاية الفعلي',
  `duration` VARCHAR(200) COMMENT 'المدة (بالدقائق)',
  `location` VARCHAR(200) COMMENT 'مكان الاجتماع',
  `locationType` VARCHAR(50) COMMENT 'نوع المكان (قاعة اجتماعات، مكتب، افتراضي)',
  `virtualMeetingLink` VARCHAR(200) COMMENT 'رابط الاجتماع الافتراضي (إن وجد)',
  `virtualMeetingPlatform` VARCHAR(200) COMMENT 'منصة الاجتماع (Zoom, Teams, Meet)',
  `meetingPassword` VARCHAR(200) COMMENT 'كلمة مرور الاجتماع (إن وجدت)',
  `isRecurring` BOOLEAN COMMENT 'اجتماع متكرر؟',
  `recurringPattern` VARCHAR(200) COMMENT 'نمط التكرار',
  `parentMeetingId` BIGINT COMMENT 'معرف الاجتماع الأم (للسلسلة المتكررة)',
  `attendees` VARCHAR(200) COMMENT 'المدعوون (JSON) - قائمة بالموظفين المدعوين',
  `expectedAttendeesCount` INT COMMENT 'عدد المدعوين',
  `confirmedAttendeesCount` INT COMMENT 'عدد المؤكدين حضورهم',
  `actualAttendeesCount` INT COMMENT 'عدد الحاضرين فعلياً',
  `quorumAchieved` VARCHAR(200) COMMENT 'هل تحقق النصاب؟',
  `quorumPercentage` DECIMAL(5,2) COMMENT 'نسبة الحضور',
  `status` VARCHAR(50) COMMENT 'حالة الاجتماع (مخطط، مؤكد، منعقد، ملغي، مؤجل)',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء (إن وجد)',
  `cancelledByUserId` BIGINT COMMENT 'معرف من ألغى',
  `postponementDate` DATE COMMENT 'تاريخ التأجيل الجديد (إن وجد)',
  `minutes` VARCHAR(200) COMMENT 'محضر الاجتماع (نص مفصل)',
  `decisions` VARCHAR(200) COMMENT 'القرارات المتخذة (JSON)',
  `actionItems` DATE COMMENT 'مهام متابعة (JSON) - مسؤول، تاريخ، حالة',
  `recommendations` VARCHAR(200) COMMENT 'التوصيات',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (JSON) - عروض تقديمية، مستندات',
  `minutesFilePath` VARCHAR(200) COMMENT 'مسار ملف محضر الاجتماع (PDF)',
  `minutesApproved` VARCHAR(200) COMMENT 'هل تم اعتماد المحضر؟',
  `minutesApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد المحضر',
  `minutesApprovalDate` DATE COMMENT 'تاريخ اعتماد المحضر',
  `isConfidential` BOOLEAN COMMENT 'اجتماع سري؟',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`meetingId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`committeeId`) REFERENCES `EmployeeCommittees`(`...`),
  -- FOREIGN KEY (`organizerId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`chairpersonId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`secretaryId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`parentMeetingId`) REFERENCES `ParentMeeting`(`...`),
  -- FOREIGN KEY (`cancelledByUserId`) REFERENCES `CancelledByUser`(`...`),
  -- FOREIGN KEY (`minutesApprovedByUserId`) REFERENCES `MinutesApprovedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='اجتماعات الموظفين';

-- Table: MeetingAttendance (حضور الاجتماعات)
CREATE TABLE IF NOT EXISTS `MeetingAttendance` (
  `attendanceId` BIGINT NOT NULL COMMENT 'معرف الحضور (المفتاح الرئيسي)',
  `meetingId` BIGINT COMMENT 'معرف الاجتماع (FK → EmployeeMeetings.meetingId)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `committeeId` BIGINT COMMENT 'معرف اللجنة (اختياري، للربط السريع)',
  `invitationStatus` VARCHAR(50) COMMENT 'حالة الدعوة (مدعو، مؤكد الحضور، معتذر، لم يرد)',
  `invitationSentDate` DATE COMMENT 'تاريخ إرسال الدعوة',
  `invitationResponseDate` DATE COMMENT 'تاريخ الرد على الدعوة',
  `invitationResponseNotes` TEXT COMMENT 'ملاحظات الرد',
  `attendanceStatus` VARCHAR(50) COMMENT 'حالة الحضور (حاضر، غائب، متأخر، غائب بعذر)',
  `arrivalTime` TIME COMMENT 'وقت الحضور',
  `departureTime` TIME COMMENT 'وقت الانصراف',
  `lateMinutes` VARCHAR(200) COMMENT 'دقائق التأخير',
  `earlyDepartureMinutes` VARCHAR(200) COMMENT 'دقائق الانصراف المبكر',
  `durationAttended` VARCHAR(200) COMMENT 'مدة الحضور (بالدقائق)',
  `excuseReason` VARCHAR(200) COMMENT 'سبب الغياب/التأخير (إن وجد)',
  `excuseDocument` VARCHAR(200) COMMENT 'مستند العذر (إن وجد)',
  `excuseApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد العذر',
  `excuseApprovedAt` DATE COMMENT 'تاريخ اعتماد العذر',
  `participatedInDiscussion` VARCHAR(200) COMMENT 'هل شارك في النقاش؟',
  `contributions` VARCHAR(200) COMMENT 'مساهماته في الاجتماع (ملخص)',
  `tasksAssigned` VARCHAR(200) COMMENT 'المهام المسندة إليه في هذا الاجتماع (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `recordedByUserId` BIGINT COMMENT 'معرف مسجل الحضور (عادة المقرر)',
  `recordedAt` VARCHAR(200) COMMENT 'وقت التسجيل',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`attendanceId`),
  -- FOREIGN KEY (`meetingId`) REFERENCES `EmployeeMeetings`(`...`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`committeeId`) REFERENCES `Committee`(`...`),
  -- FOREIGN KEY (`excuseApprovedByUserId`) REFERENCES `ExcuseApprovedByUser`(`...`),
  -- FOREIGN KEY (`recordedByUserId`) REFERENCES `RecordedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حضور الاجتماعات';

-- Table: InternalTransfer (النقل الداخلي)
CREATE TABLE IF NOT EXISTS `InternalTransfer` (
  `transferId` BIGINT NOT NULL COMMENT 'معرف النقل (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `transferType` VARCHAR(50) COMMENT 'نوع النقل (داخلي - بين أقسام، داخلي - بين مدارس، خارجي - من/إلى مدرسة أخرى)',
  `transferNumber` INT COMMENT 'رقم قرار النقل',
  `transferDate` DATE COMMENT 'تاريخ قرار النقل',
  `effectiveDate` DATE COMMENT 'تاريخ سريان النقل',
  `fromSchoolId` BIGINT COMMENT 'معرف المدرسة السابقة (FK → School.schoolId)',
  `toSchoolId` BIGINT COMMENT 'معرف المدرسة الجديدة (FK → School.schoolId)',
  `fromDepartmentId` BIGINT COMMENT 'معرف القسم السابق (FK → SchoolDepartment.deptId)',
  `toDepartmentId` BIGINT COMMENT 'معرف القسم الجديد (FK → SchoolDepartment.deptId)',
  `fromJobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي السابق',
  `toJobTitle` VARCHAR(200) COMMENT 'المسمى الوظيفي الجديد',
  `fromGrade` DECIMAL(5,2) COMMENT 'الدرجة الوظيفية السابقة',
  `toGrade` DECIMAL(5,2) COMMENT 'الدرجة الوظيفية الجديدة',
  `fromSalary` DECIMAL(15,2) COMMENT 'الراتب السابق',
  `toSalary` DECIMAL(15,2) COMMENT 'الراتب الجديد (إن تغير)',
  `transferReason` VARCHAR(200) COMMENT 'سبب النقل',
  `transferDecisionPath` VARCHAR(200) COMMENT 'مسار ملف قرار النقل',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد النقل (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة النقل (مخطط، معتمد، منفذ، ملغي)',
  `executionDate` DATE COMMENT 'تاريخ التنفيذ الفعلي',
  `executedByUserId` BIGINT COMMENT 'معرف من نفذ النقل (FK → SystemUser.userId)',
  `handoverCompleted` VARCHAR(200) COMMENT 'هل تم تسليم العمل في القسم السابق؟',
  `handoverDate` DATE COMMENT 'تاريخ التسليم',
  `handoverNotes` TEXT COMMENT 'ملاحظات التسليم',
  `receivedInNewDepartment` VARCHAR(200) COMMENT 'هل تم الاستلام في القسم الجديد؟',
  `receiveDate` DATE COMMENT 'تاريخ الاستلام',
  `receiveNotes` TEXT COMMENT 'ملاحظات الاستلام',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`transferId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`fromSchoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`toSchoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`fromDepartmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`toDepartmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`executedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='النقل الداخلي';

-- Table: ExternalTransfer (النقل الخارجي)
CREATE TABLE IF NOT EXISTS `ExternalTransfer` (
  `externalTransferId` BIGINT NOT NULL COMMENT 'معرف النقل الخارجي (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId) - إن كان موجوداً في النظام',
  `transferDirection` VARCHAR(200) COMMENT 'اتجاه النقل (من خارج إلى المدرسة، من المدرسة إلى خارج)',
  `transferNumber` INT COMMENT 'رقم قرار النقل',
  `transferDate` DATE COMMENT 'تاريخ قرار النقل',
  `effectiveDate` DATE COMMENT 'تاريخ سريان النقل',
  `fromEntity` VARCHAR(200) COMMENT 'اسم الجهة السابقة (إن كان وارداً)',
  `fromEntityType` VARCHAR(50) COMMENT 'نوع الجهة السابقة (وزارة، مدرسة حكومية، مدرسة أهلية، شركة)',
  `fromEntityAddress` VARCHAR(200) COMMENT 'عنوان الجهة السابقة',
  `toEntity` VARCHAR(200) COMMENT 'اسم الجهة الجديدة (إن كان صادراً)',
  `toEntityType` VARCHAR(50) COMMENT 'نوع الجهة الجديدة',
  `toEntityAddress` VARCHAR(200) COMMENT 'عنوان الجهة الجديدة',
  `positionAtPrevious` VARCHAR(200) COMMENT 'المنصب في الجهة السابقة',
  `positionAtNew` VARCHAR(200) COMMENT 'المنصب في الجهة الجديدة',
  `transferReason` VARCHAR(200) COMMENT 'سبب النقل',
  `transferDocumentPath` VARCHAR(200) COMMENT 'مسار ملف قرار النقل',
  `clearanceCompleted` VARCHAR(200) COMMENT 'هل تم إخلاء الطرف من الجهة السابقة؟',
  `clearanceDate` DATE COMMENT 'تاريخ إخلاء الطرف',
  `clearanceDocumentPath` VARCHAR(200) COMMENT 'مسار ملف إخلاء الطرف',
  `joinedDate` DATE COMMENT 'تاريخ الالتحاق بالجهة الجديدة',
  `joinedDocumentPath` VARCHAR(200) COMMENT 'مسار ملف الالتحاق',
  `newEmployeeId` BIGINT COMMENT 'معرف الموظف الجديد (إن تم إنشاؤه في النظام)',
  `terminationId` BIGINT COMMENT 'معرف إنهاء الخدمة المرتبط (FK → EmployeeTermination.terminationId) - إن كان صادراً',
  `appointmentDecisionId` BIGINT COMMENT 'معرف قرار التعيين المرتبط (FK → AppointmentDecision.decisionId) - إن كان وارداً',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد النقل (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة النقل (قيد الإجراء، معتمد، منفذ، ملغي)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`externalTransferId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`newEmployeeId`) REFERENCES `NewEmployee`(`...`),
  -- FOREIGN KEY (`terminationId`) REFERENCES `EmployeeTermination`(`...`),
  -- FOREIGN KEY (`appointmentDecisionId`) REFERENCES `AppointmentDecision`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='النقل الخارجي';

-- Table: EmployeeTermination (إنهاء الخدمة)
CREATE TABLE IF NOT EXISTS `EmployeeTermination` (
  `terminationId` BIGINT NOT NULL COMMENT 'معرف إنهاء الخدمة (المفتاح الرئيسي)',
  `employeeId` BIGINT COMMENT 'معرف الموظف (FK → Employee.employeeId)',
  `terminationType` VARCHAR(50) COMMENT 'نوع إنهاء الخدمة (استقالة، تقاعد، فصل تأديبي، إنهاء عقد، نقل خارجي، وفاة، إنهاء فترة تجربة)',
  `terminationNumber` INT COMMENT 'رقم قرار الإنهاء',
  `terminationDate` DATE COMMENT 'تاريخ قرار الإنهاء',
  `lastWorkingDate` DATE COMMENT 'تاريخ آخر يوم عمل',
  `effectiveDate` DATE COMMENT 'تاريخ سريان الإنهاء',
  `reason` VARCHAR(200) COMMENT 'سبب الإنهاء (نص مفصل)',
  `reasonCategory` VARCHAR(50) COMMENT 'فئة السبب (شخصي، وظيفي، تأديبي، صحي)',
  `resignationDate` DATE COMMENT 'تاريخ تقديم الاستقالة (إن وجد)',
  `resignationNoticePeriod` VARCHAR(200) COMMENT 'فترة الإشعار (بالأيام)',
  `resignationNoticeServed` VARCHAR(200) COMMENT 'هل تم خدمة فترة الإشعار؟',
  `terminationInitiator` VARCHAR(200) COMMENT 'المبادر بالإنهاء (موظف، إدارة، جهة خارجية)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalDocumentPath` VARCHAR(200) COMMENT 'مسار ملف قرار الاعتماد',
  `finalSettlementAmount` DECIMAL(15,2) COMMENT 'مبلغ التسوية النهائية',
  `settlementBreakdown` VARCHAR(200) COMMENT 'تفاصيل التسوية (JSON) - راتب مستحق، مكافأة نهاية خدمة، رصيد إجازات، تعويضات',
  `settlementDate` DATE COMMENT 'تاريخ صرف التسوية',
  `settlementReceiptNumber` INT COMMENT 'رقم إيصال التسوية',
  `settlementStatus` VARCHAR(50) COMMENT 'حالة التسوية (محسوبة، معتمدة، مدفوعة)',
  `clearanceStatus` VARCHAR(50) COMMENT 'حالة إخلاء الطرف (مكتمل، غير مكتمل، قيد الإجراء)',
  `clearanceDate` DATE COMMENT 'تاريخ إخلاء الطرف',
  `clearanceCompletedByUserId` BIGINT COMMENT 'معرف من أكمل إجراءات الإخلاء',
  `clearanceNotes` TEXT COMMENT 'ملاحظات الإخلاء',
  `inventoryReturned` VARCHAR(200) COMMENT 'هل تم إرجاع العهد؟',
  `inventoryReturnDate` DATE COMMENT 'تاريخ إرجاع العهد',
  `inventoryVerifiedByUserId` BIGINT COMMENT 'معرف من تحقق من العهد',
  `documentsReturned` VARCHAR(200) COMMENT 'هل تم استلام المستندات؟',
  `documentsReturnDate` DATE COMMENT 'تاريخ استلام المستندات',
  `exitInterviewConducted` VARCHAR(200) COMMENT 'هل تم إجراء مقابلة خروج؟',
  `exitInterviewDate` DATE COMMENT 'تاريخ مقابلة الخروج',
  `exitInterviewNotes` TEXT COMMENT 'ملاحظات مقابلة الخروج',
  `exitInterviewerId` BIGINT COMMENT 'معرف من أجرى المقابلة',
  `finalSettlementPaid` BIGINT COMMENT 'هل تم دفع التسوية النهائية؟',
  `paymentDate` DATE COMMENT 'تاريخ الدفع',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع',
  `bankTransferReference` VARCHAR(200) COMMENT 'رقم مرجع التحويل',
  `socialInsuranceNotified` VARCHAR(200) COMMENT 'هل تم إشعار التأمينات؟',
  `socialInsuranceNotificationDate` DATE COMMENT 'تاريخ الإشعار',
  `employeeFileClosed` VARCHAR(200) COMMENT 'هل تم إغلاق ملف الموظف؟',
  `fileClosureDate` DATE COMMENT 'تاريخ الإغلاق',
  `fileClosureByUserId` BIGINT COMMENT 'معرف من أغلق الملف',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`terminationId`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`clearanceCompletedByUserId`) REFERENCES `ClearanceCompletedByUser`(`...`),
  -- FOREIGN KEY (`inventoryVerifiedByUserId`) REFERENCES `InventoryVerifiedByUser`(`...`),
  -- FOREIGN KEY (`exitInterviewerId`) REFERENCES `ExitInterviewer`(`...`),
  -- FOREIGN KEY (`finalSettlementPaid`) REFERENCES `FinalSettlementPa`(`...`),
  -- FOREIGN KEY (`fileClosureByUserId`) REFERENCES `FileClosureByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إنهاء الخدمة';


-- ============================
-- Module: M4_Assets
-- ============================

-- Table: Asset (الأصول الأساسي)
CREATE TABLE IF NOT EXISTS `Asset` (
  `assetId` BIGINT NOT NULL COMMENT 'معرف الأصل (المفتاح الرئيسي - مهم جداً)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId). هذا الحقل يربط كل أصل بمدرسته.',
  `assetUniqueCode` VARCHAR(50) COMMENT 'الرقم التعريفي الفريد (يتم توليده آلياً. مثال: AST-2024-00001)',
  `assetNameAr` VARCHAR(200) COMMENT 'اسم الأصل باللغة العربية (مثال: "جهاز حاسب آلي محمول")',
  `assetNameEn` VARCHAR(200) COMMENT 'اسم الأصل باللغة الإنجليزية (مثال: "Laptop Computer")',
  `assetTag` VARCHAR(200) COMMENT 'علامة أو ملصق الأصل (رقم مختصر يكتب على ملصق يوضع على الجهاز. مثال: "IT-LP-01")',
  `serialNumber` INT COMMENT 'الرقم التسلسلي من المصنع (مهم جداً للمتابعة مع الضمان)',
  `modelNumber` INT COMMENT 'رقم الموديل',
  `manufacturer` VARCHAR(200) COMMENT 'الشركة المصنعة',
  `brand` VARCHAR(200) COMMENT 'العلامة التجارية (مثل: Dell، HP، Samsung)',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصل (FK → AssetCategory.categoryId). يربط الأصل بفئته.',
  `assetStatusId` BIGINT COMMENT 'معرف حالة الأصل (FK → AssetStatus.statusId). يربط الأصل بحالته الحالية.',
  `assetLocationId` BIGINT COMMENT 'معرف الموقع المكاني الحالي (FK → AssetLocation.locationId). يحدد أين يوجد الأصل الآن.',
  `condition` VARCHAR(200) COMMENT 'حالة الأصل (جديد، جيد، يحتاج صيانة، تالف، مهمل)',
  `acquisitionType` VARCHAR(50) COMMENT 'نوع الحصول (شراء، هبة، نقل داخلي، تأجير)',
  `acquisitionDate` DATE COMMENT 'تاريخ الحصول على الأصل',
  `acquisitionCost` DECIMAL(15,2) COMMENT 'تكلفة الشراء أو القيمة عند الحصول عليها',
  `currency` VARCHAR(200) COMMENT 'العملة (SAR, USD, etc.)',
  `supplierName` VARCHAR(200) COMMENT 'اسم المورد أو البائع',
  `purchaseOrderReference` VARCHAR(200) COMMENT 'رقم أمر الشراء المرتبط (FK → PurchaseOrders.poNumber)',
  `warrantyContractId` BIGINT COMMENT 'معرف عقد الضمان المرتبط (FK → AssetWarrantyContract.contractId)',
  `isInsured` BOOLEAN COMMENT 'هل الأصل مغطى بالتأمين؟',
  `insurancePolicyNumber` INT COMMENT 'رقم وثيقة التأمين',
  `insuranceExpiryDate` DATE COMMENT 'تاريخ انتهاء التغطية التأمينية',
  `usefulLifeYears` VARCHAR(200) COMMENT 'العمر الإنتاجي المقدر (بالسنوات، يُستخدم لحساب الإهلاك)',
  `salvageValue` VARCHAR(200) COMMENT 'القيمة التخريدية (قيمة الأصل بعد انتهاء عمره الإنتاجي)',
  `currentValue` VARCHAR(200) COMMENT 'القيمة الدفترية الحالية (يتم تحديثها آلياً بواسطة نظام الإهلاك)',
  `barcode` VARCHAR(50) COMMENT 'باركود الأصل (نص أو رقم)',
  `qrCode` VARCHAR(50) COMMENT 'رابط أو نص يمثل رمز QR',
  `rfidTag` VARCHAR(200) COMMENT 'رقم شريحة RFID (إن وجدت)',
  `hasPhysicalTag` BOOLEAN COMMENT 'هل تم وضع ملصق فعلي على الأصل؟',
  `physicalTagDate` DATE COMMENT 'تاريخ وضع الملصق',
  `notes` TEXT COMMENT 'ملاحظات إضافية (مثل وصف لأي ضرر سابق أو ملاحظة خاصة)',
  `isActive` BOOLEAN COMMENT 'هل الأصل لا يزال قيد الاستخدام ولم يتم التخلص منه؟',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي (لإخفاء الأصل بدلاً من حذفه نهائياً)',
  `createdByUserId` BIGINT COMMENT 'معرف المستخدم الذي أضاف الأصل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من قام بتعديل بيانات الأصل',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  PRIMARY KEY (`assetId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`assetStatusId`) REFERENCES `AssetStatus`(`...`),
  -- FOREIGN KEY (`assetLocationId`) REFERENCES `AssetLocation`(`...`),
  -- FOREIGN KEY (`purchaseOrderReference`) REFERENCES `PurchaseOrders`(`...`),
  -- FOREIGN KEY (`warrantyContractId`) REFERENCES `AssetWarrantyContract`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأصول الأساسي';

-- Table: AssetCategory (فئات الأصول)
CREATE TABLE IF NOT EXISTS `AssetCategory` (
  `categoryId` BIGINT NOT NULL COMMENT 'معرف الفئة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - لتمكين كل مدرسة من تخصيص تصنيفاتها الخاصة',
  `parentCategoryId` BIGINT COMMENT 'معرف الفئة الأم (Self FK → AssetCategory.categoryId) - لبناء الهيكل الهرمي (مستويات متعددة)',
  `categoryCode` VARCHAR(50) COMMENT 'كود الفئة (فريد داخل المدرسة) - مثال: "IT-COMP", "FURN-DESK"',
  `categoryNameAr` VARCHAR(50) COMMENT 'اسم الفئة بالعربية (مثال: "أجهزة إلكترونية")',
  `categoryNameEn` VARCHAR(50) COMMENT 'اسم الفئة بالإنجليزية (مثال: "Electronics")',
  `categoryLevel` VARCHAR(50) COMMENT 'مستوى الفئة في الشجرة الهرمية (1، 2، 3... - يُحسب آلياً)',
  `fullPath` VARCHAR(200) COMMENT 'المسار الكامل للفئة (مثال: "الأصول / أجهزة إلكترونية / حواسيب / لابتوبات") - يُحسب آلياً',
  `description` TEXT COMMENT 'وصف الفئة',
  `depreciationRate` DECIMAL(5,2) COMMENT 'نسبة الإهلاك السنوية المتوقعة (كنسبة مئوية، مثال: 25.00)',
  `depreciationMethod` VARCHAR(200) COMMENT 'طريقة الإهلاك الافتراضية لهذه الفئة (القسط الثابت، القسط المتناقص، وحدات الإنتاج) - يمكن توريثها للأصول الفردية',
  `usefulLifeYears` VARCHAR(200) COMMENT 'العمر الإنتاجي الافتراضي بالسنوات (مثال: للحواسيب 3 سنوات، للأثاث 10 سنوات)',
  `accountCode` INT COMMENT 'كود الحساب المحاسبي المرتبط بهذه الفئة (للتكامل مع نظام الأستاذ العام)',
  `expenseAccountCode` INT COMMENT 'كود حساب المصروف المرتبط (لشراء الأصول)',
  `accumulatedDepAccountCode` INT COMMENT 'كود حساب مجمع الإهلاك',
  `isActive` BOOLEAN COMMENT 'هل الفئة مفعلة؟ (يمكن تعطيل الفئات القديمة)',
  `isSystem` BOOLEAN COMMENT 'هل هي فئة نظامية (لا يمكن حذفها أو تعديلها من قبل المستخدم)',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب عرض الفئة (للقوائم المنسدلة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`categoryId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`parentCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='فئات الأصول';

-- Table: AssetLocation (المواقع المكانية)
CREATE TABLE IF NOT EXISTS `AssetLocation` (
  `locationId` BIGINT NOT NULL COMMENT 'معرف الموقع (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `parentLocationId` BIGINT COMMENT 'معرف الموقع الأب (Self FK → AssetLocation.locationId) - لإنشاء هيكل هرمي (مبنى ← طابق ← غرفة)',
  `locationCode` VARCHAR(50) COMMENT 'كود الموقع (فريد داخل المدرسة) - مثال: "B1-F2-R205"',
  `locationNameAr` VARCHAR(200) COMMENT 'اسم الموقع بالعربية (مثال: "المبنى الرئيسي - الدور الثاني - غرفة 205")',
  `locationNameEn` VARCHAR(200) COMMENT 'اسم الموقع بالإنجليزية (مثال: "Main Building - 2nd Floor - Room 205")',
  `locationType` VARCHAR(50) COMMENT 'نوع الموقع (مبنى، طابق، جناح، قاعة، مكتب، معمل، مستودع، خزانة)',
  `buildingName` VARCHAR(200) COMMENT 'اسم المبنى (للبحث السريع)',
  `floorNumber` INT COMMENT 'رقم الطابق',
  `roomNumber` INT COMMENT 'رقم الغرفة',
  `section` VARCHAR(200) COMMENT 'القسم أو الجناح',
  `area` VARCHAR(200) COMMENT 'المساحة بالمتر المربع (للمواقع الكبيرة مثل المباني)',
  `capacity` VARCHAR(200) COMMENT 'السعة الاستيعابية (للقاعات والمكاتب)',
  `isActive` BOOLEAN COMMENT 'هل الموقع مفعل؟',
  `hasPhysicalSign` BOOLEAN COMMENT 'هل تم وضع لافتة تعريفية على الموقع؟',
  `responsiblePersonId` BIGINT COMMENT 'معرف الشخص المسؤول عن هذا الموقع (FK → Employee.employeeId) - اختياري',
  `contactPhone` VARCHAR(20) COMMENT 'هاتف المسؤول عن الموقع',
  `mapReference` VARCHAR(200) COMMENT 'إحداثيات الموقع على خريطة المدرسة (نص)',
  `qrCode` VARCHAR(50) COMMENT 'رمز QR للموقع (لتسهيل الجرد عبر التطبيق)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`locationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`parentLocationId`) REFERENCES `AssetLocation`(`...`),
  -- FOREIGN KEY (`responsiblePersonId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المواقع المكانية';

-- Table: AssetStatus (حالات الأصل)
CREATE TABLE IF NOT EXISTS `AssetStatus` (
  `statusId` BIGINT NOT NULL COMMENT 'معرف الحالة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - لتمكين كل مدرسة من إضافة حالاتها الخاصة',
  `statusCode` VARCHAR(50) COMMENT 'كود الحالة (فريد داخل المدرسة) - مثال: "ACTIVE", "MAINT", "RETIRED"',
  `statusNameAr` VARCHAR(50) COMMENT 'اسم الحالة بالعربية (نشط، تحت الصيانة، معار، مهمل، تالف، مستبعد، مفقود، في الانتظار)',
  `statusNameEn` VARCHAR(50) COMMENT 'اسم الحالة بالإنجليزية (Active, Maintenance, Loaned, Scrap, Damaged, Retired, Lost, Pending)',
  `statusType` VARCHAR(50) COMMENT 'نوع الحالة (تشغيلي، صيانة، خارج الخدمة)',
  `isOperational` BOOLEAN COMMENT 'هل هذه الحالة تسمح باستخدام الأصل؟ (نعم/لا) - مهم جداً لمنع تخصيص أصول غير صالحة للاستخدام',
  `isAvailableForAssignment` BOOLEAN COMMENT 'هل يمكن تخصيص هذا الأصل لأحد في هذه الحالة؟',
  `requiresApproval` VARCHAR(200) COMMENT 'هل يتطلب الانتقال إلى هذه الحالة موافقة إدارية؟',
  `colorCode` VARCHAR(50) COMMENT 'رمز اللون للتمييز في الشاشات (Hex code مثل #00FF00)',
  `isActive` BOOLEAN COMMENT 'هل الحالة مفعلة (يمكن استخدامها)؟',
  `isSystem` BOOLEAN COMMENT 'هل هي حالة نظامية لا يمكن حذفها أو تعديلها؟',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب عرض الحالة في القوائم',
  `descriptionAr` TEXT COMMENT 'وصف الحالة بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الحالة بالإنجليزية',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`statusId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حالات الأصل';

-- Table: AssetWarrantyContract (الضمان والعقود)
CREATE TABLE IF NOT EXISTS `AssetWarrantyContract` (
  `contractId` BIGINT NOT NULL COMMENT 'معرف العقد (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `contractType` VARCHAR(50) COMMENT 'نوع العقد (ضمان، صيانة، ترخيص برمجيات، إيجار)',
  `contractNumber` INT COMMENT 'رقم العقد الرسمي',
  `contractName` VARCHAR(200) COMMENT 'اسم العقد (مثال: "ضمان أجهزة الحاسوب - HP")',
  `providerName` VARCHAR(200) COMMENT 'اسم المورد أو شركة الصيانة',
  `providerContact` VARCHAR(200) COMMENT 'جهة اتصال المورد (شخص، هاتف، بريد)',
  `startDate` DATE COMMENT 'تاريخ بداية التغطية',
  `endDate` DATE COMMENT 'تاريخ نهاية التغطية',
  `coverageDetails` VARCHAR(200) COMMENT 'تفاصيل التغطية (ما الذي يشملّه الضمان؟ قطع غيار، صيانة وقائية، دعم فني)',
  `coverageType` VARCHAR(50) COMMENT 'نوع التغطية (ضمان مصنع، ضمان ممتد، عقد صيانة سنوي)',
  `contractValue` VARCHAR(200) COMMENT 'قيمة العقد الإجمالية',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `paymentTerms` VARCHAR(200) COMMENT 'شروط الدفع',
  `hasRenewalOption` BOOLEAN COMMENT 'هل يوجد خيار التجديد؟',
  `renewalTerms` VARCHAR(200) COMMENT 'شروط التجديد (إن وجدت)',
  `isActive` BOOLEAN COMMENT 'هل العقد ساري المفعول؟',
  `contractStatus` VARCHAR(50) COMMENT 'حالة العقد (ساري، منتهي، ملغى، مجدد)',
  `reminderDays` VARCHAR(200) COMMENT 'عدد الأيام قبل انتهاء العقد لإرسال التذكير (افتراضي 30)',
  `isAlertEnabled` BOOLEAN COMMENT 'تفعيل التنبيهات التلقائية لانتهاء الصلاحية؟',
  `lastAlertSentDate` DATE COMMENT 'تاريخ آخر تنبيه تم إرساله',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (مسار ملف العقد)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`contractId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الضمان والعقود';

-- Table: AssetDocument (وثائق الأصل)
CREATE TABLE IF NOT EXISTS `AssetDocument` (
  `documentId` BIGINT NOT NULL COMMENT 'معرف الوثيقة (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل المرتبط (FK → Asset.assetId) - مهم جداً، هذا هو الرابط الأساسي',
  `contractId` BIGINT COMMENT 'معرف العقد المرتبط (FK → AssetWarrantyContract.contractId) - اختياري، لربط المستند مباشرة بالعقد أيضاً',
  `docType` VARCHAR(50) COMMENT 'نوع الوثيقة (فاتورة، كتالوج، صورة، شهادة ملكية، دليل مستخدم، عقد صيانة)',
  `docCode` VARCHAR(50) COMMENT 'كود الوثيقة',
  `docName` VARCHAR(200) COMMENT 'اسم الوثيقة',
  `description` TEXT COMMENT 'وصف الوثيقة',
  `fileName` VARCHAR(200) COMMENT 'اسم الملف المرفوع',
  `filePath` VARCHAR(200) COMMENT 'مسار التخزين في السيرفر',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف (بايت)',
  `mimeType` VARCHAR(50) COMMENT 'نوع الملف (PDF، JPG، PNG، DOCX)',
  `uploadDate` DATE COMMENT 'تاريخ الرفع',
  `uploadedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `isVerified` BOOLEAN COMMENT 'هل تم التحقق من صحة الوثيقة؟',
  `verifiedByUserId` BIGINT COMMENT 'معرف من قام بالتحقق',
  `verifiedAt` DATE COMMENT 'تاريخ التحقق',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`documentId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`contractId`) REFERENCES `AssetWarrantyContract`(`...`),
  -- FOREIGN KEY (`uploadedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `VerifiedByUser`(`...`)
) COMMENT='وثائق الأصل';

-- Table: AssetRequirementRequest (مقترحات وطلبات الاحتياج)
CREATE TABLE IF NOT EXISTS `AssetRequirementRequest` (
  `requestId` BIGINT NOT NULL COMMENT 'معرف الطلب (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestNumber` INT COMMENT 'رقم الطلب التسلسلي (يُولد تلقائياً، مثال: REQ-2024-001)',
  `requestType` VARCHAR(50) COMMENT 'نوع الطلب (احتياج جديد، استبدال أصل تالف، زيادة سعة، تطوير، طوارئ)',
  `assetType` VARCHAR(50) COMMENT 'نوع الأصل المقترح (طاولات، حواسيب، أجهزة عرض، أثاث، مركبات، أخرى)',
  `assetCategoryId` BIGINT COMMENT 'معرف الفئة المقترحة (FK → AssetCategory.categoryId) - لتسهيل التصنيف',
  `quantity` VARCHAR(200) COMMENT 'الكمية المطلوبة',
  `estimatedUnitCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية للوحدة',
  `estimatedTotalCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية الإجمالية (تُحسب = estimatedUnitCost * quantity)',
  `currency` VARCHAR(200) COMMENT 'العملة (SAR, USD)',
  `priority` VARCHAR(200) COMMENT 'الأولوية (عاجل، مهم، عادي، منخفض)',
  `urgencyReason` VARCHAR(200) COMMENT 'سبب العجلة (مثل: تعطل كلي للمعدات الحالية)',
  `requestingDepartmentId` BIGINT COMMENT 'معرف القسم الطالب (FK → SchoolDepartment.deptId)',
  `requestedByUserId` BIGINT COMMENT 'معرف الموظف مقدم الطلب (FK → Employee.employeeId)',
  `requestDate` DATE COMMENT 'تاريخ تقديم الطلب',
  `justification` VARCHAR(200) COMMENT 'مبررات الاحتياج ونتائج تحليل الفجوة (نص طويل)',
  `gapAnalysisSummary` VARCHAR(200) COMMENT 'ملخص تحليل الفجوة (ماذا يوجد حالياً، ماذا نحتاج، الفرق)',
  `initialSpecs` VARCHAR(200) COMMENT 'المواصفات الأولية المطلوبة (نص أو JSON)',
  `suggestedSuppliers` VARCHAR(200) COMMENT 'موردون مقترحون (JSON)',
  `requiredByDate` DATE COMMENT 'التاريخ المطلوب فيه توفير الأصل',
  `renewalPlanId` BIGINT COMMENT 'ربط الطلب بخطة تجديد الأسطول (إن وجدت) (FK → PlanId من جدول خطط التطوير - خارج هذا القسم)',
  `isReplacement` BOOLEAN COMMENT 'هل الطلب لاستبدال أصل قديم؟',
  `assetToReplaceId` BIGINT COMMENT 'معرف الأصل المطلوب استبداله (FK → Asset.assetId) - إذا كان isReplacement = نعم',
  `replacementReason` VARCHAR(200) COMMENT 'سبب الاستبدال (انتهاء العمر الافتراضي، كثرة الأعطال، تقادم تقني)',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد (مسودة، قيد المراجعة، معتمد، مرفوض، محول للشراء)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (في حال تم الرفض)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الطلب (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `convertedToPO` VARCHAR(200) COMMENT 'هل تم تحويل الطلب إلى أمر شراء؟',
  `purchaseOrderId` BIGINT COMMENT 'معرف أمر الشراء المرتبط (FK → PurchaseOrders.purchaseOrderId) - بعد التحويل',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`requestId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`requestingDepartmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`requestedByUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`renewalPlanId`) REFERENCES `PlanId`(`...`),
  -- FOREIGN KEY (`assetToReplaceId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`purchaseOrderId`) REFERENCES `PurchaseOrders`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مقترحات وطلبات الاحتياج';

-- Table: TechnicalSpecifications (المواصفات الفنية والمعايير)
CREATE TABLE IF NOT EXISTS `TechnicalSpecifications` (
  `specId` BIGINT NOT NULL COMMENT 'معرف المواصفة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `specCode` VARCHAR(50) COMMENT 'كود المواصفة (فريد، مثال: TECH-LAP-2024)',
  `specNameAr` VARCHAR(200) COMMENT 'اسم المواصفة بالعربية (مثال: "مواصفات حاسب آلي للمعلمين")',
  `specNameEn` VARCHAR(200) COMMENT 'اسم المواصفة بالإنجليزية (مثال: "Teacher Laptop Specifications")',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصل المرتبطة (FK → AssetCategory.categoryId)',
  `assetType` VARCHAR(50) COMMENT 'نوع الأصل (لابتوب، طابعة، مكتب، كرسي،...)',
  `technicalDetails` VARCHAR(200) COMMENT 'تفاصيل المواصفات (المعالج، الرام، المادة، الحجم، اللون، إلخ) (نص طويل أو JSON)',
  `requiredCertifications` VARCHAR(200) COMMENT 'الشهادات المطلوبة (مثال: شهادة الطاقة، شهادة الجودة ISO) (JSON)',
  `acceptanceCriteria` VARCHAR(200) COMMENT 'معايير القبول الفني عند الاستلام (نص طويل)',
  `qualityStandards` VARCHAR(200) COMMENT 'معايير الجودة (ISO، كود البناء، المعايير السعودية) (JSON)',
  `warrantyRequirements` VARCHAR(200) COMMENT 'متطلبات الضمان المطلوبة في العقد',
  `deliveryRequirements` VARCHAR(200) COMMENT 'متطلبات التغليف والنقل',
  `installationRequirements` VARCHAR(200) COMMENT 'متطلبات التركيب (إن وجدت)',
  `safetyRequirements` VARCHAR(200) COMMENT 'متطلبات السلامة',
  `isActive` BOOLEAN COMMENT 'هل المواصفة مفعلة (يمكن استخدامها)؟',
  `validFrom` DATE COMMENT 'تاريخ بدء صلاحية المواصفة',
  `validTo` DATE COMMENT 'تاريخ انتهاء صلاحية المواصفة',
  `version` VARCHAR(200) COMMENT 'إصدار المواصفة (للتعامل مع التحديثات)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (كتالوجات، صور، ملفات PDF) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`specId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المواصفات الفنية والمعايير';

-- Table: FeasibilityRiskAnalysis (دراسات الجدوى والمخاطر)
CREATE TABLE IF NOT EXISTS `FeasibilityRiskAnalysis` (
  `analysisId` BIGINT NOT NULL COMMENT 'معرف التحليل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestId` BIGINT COMMENT 'معرف طلب الاحتياج المرتبط (FK → AssetRequirementRequest.requestId) - العلاقة 1-1 غالباً',
  `analysisNumber` INT COMMENT 'رقم التحليل (يولد تلقائياً)',
  `analysisDate` DATE COMMENT 'تاريخ إجراء التحليل',
  `analystUserId` BIGINT COMMENT 'معرف من قام بالتحليل (FK → Employee.employeeId)',
  `operationalRisks` VARCHAR(200) COMMENT 'وصف المخاطر التشغيلية (نص طويل)',
  `financialRisks` VARCHAR(200) COMMENT 'وصف المخاطر المالية (نص طويل)',
  `riskLevel` VARCHAR(50) COMMENT 'مستوى المخاطر (منخفض، متوسط، مرتفع)',
  `riskMitigationPlan` VARCHAR(200) COMMENT 'خطة تخفيف المخاطر (نص)',
  `expectedLifeSpan` VARCHAR(200) COMMENT 'العمر الافتراضي المتوقع (بالسنوات)',
  `usefulLifeEstimate` DECIMAL(15,2) COMMENT 'تقدير العمر الإنتاجي (قد يُعبّر عنه بالسنوات أو ساعات التشغيل)',
  `roiEstimate` VARCHAR(200) COMMENT 'العائد المتوقع من الاستثمار (ROI) (نسبة مئوية)',
  `paybackPeriod` VARCHAR(200) COMMENT 'فترة استرداد رأس المال (بالسنوات)',
  `npvEstimate` VARCHAR(200) COMMENT 'صافي القيمة الحالية (قيمة مالية)',
  `alternativeSolutions` VARCHAR(200) COMMENT 'الحلول البديلة (نص أو JSON)',
  `finalRecommendation` VARCHAR(200) COMMENT 'التوصية النهائية (شراء، رفض، تأجيل، بديل)',
  `recommendationReason` VARCHAR(200) COMMENT 'سبب التوصية (نص)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد التحليل (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة التحليل (مسودة، معتمد)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (دراسات، تقارير) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`analysisId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`requestId`) REFERENCES `AssetRequirementRequest`(`...`),
  -- FOREIGN KEY (`analystUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='دراسات الجدوى والمخاطر';

-- Table: AssetBudgetAllocation (ميزانية الأصول)
CREATE TABLE IF NOT EXISTS `AssetBudgetAllocation` (
  `allocationId` BIGINT NOT NULL COMMENT 'معرف التخصيص (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية للميزانية (مثال: 2025)',
  `budgetType` VARCHAR(50) COMMENT 'نوع الميزانية (رأسمالي - Capex، تشغيلي - Opex)',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصل (FK → AssetCategory.categoryId) - يمكن أن يكون فارغاً للتخصيص العام',
  `departmentId` BIGINT COMMENT 'معرف القسم (FK → SchoolDepartment.deptId) - يمكن أن يكون فارغاً للتخصيص العام',
  `allocatedAmount` DECIMAL(15,2) COMMENT 'المبلغ المخصص لهذا البند (السقف المالي)',
  `spentAmount` DECIMAL(15,2) COMMENT 'المبلغ الذي تم صرفه حتى الآن (يتم تحديثه آلياً عند إنشاء أوامر الشراء)',
  `remainingAmount` DECIMAL(15,2) COMMENT 'المبلغ المتبقي بعد الصرف (يُحسب آلياً = allocatedAmount - spentAmount)',
  `budgetLineCode` VARCHAR(50) COMMENT 'رمز بند الميزانية في النظام المالي الخارجي (للتكامل)',
  `notes` TEXT COMMENT 'ملاحظات',
  `status` VARCHAR(50) COMMENT 'حالة تخصيص الميزانية (نشط، مستنفذ، ملغي)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`allocationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='ميزانية الأصول';

-- Table: PurchaseOrders (طلبات الشراء والمناقصات)
CREATE TABLE IF NOT EXISTS `PurchaseOrders` (
  `purchaseOrderId` BIGINT NOT NULL COMMENT 'معرف أمر الشراء (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `poNumber` INT COMMENT 'رقم أمر الشراء الرسمي (فريد، مهم للرجوع إليه)',
  `poDate` DATE COMMENT 'تاريخ إصدار الأمر',
  `requestId` BIGINT COMMENT 'معرف طلب الاحتياج المرتبط (FK → AssetRequirementRequest.requestId) - يمكن أن يكون واحداً لواحد أو عدة طلبات في أمر واحد (علاقة M:M، تحتاج جدول وسيط)',
  `supplierName` VARCHAR(200) COMMENT 'اسم المورد',
  `supplierContact` VARCHAR(200) COMMENT 'جهة اتصال المورد',
  `supplierAddress` VARCHAR(200) COMMENT 'عنوان المورد',
  `totalAmount` DECIMAL(15,2) COMMENT 'القيمة الإجمالية للشراء (شامل الضريبة)',
  `taxAmount` DECIMAL(15,2) COMMENT 'قيمة الضريبة (مثال: VAT 15%)',
  `taxRegistrationNumber` INT COMMENT 'الرقم الضريبي للمورد (إن وجد)',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `paymentTerms` VARCHAR(200) COMMENT 'شروط الدفع (مثال: 30% مقدماً، 70% عند الاستلام)',
  `deliveryTerms` VARCHAR(200) COMMENT 'شروط التسليم (مثال: FOB، CIF، تسليم باب المدرسة)',
  `deliveryDeadline` DATE COMMENT 'آخر موعد للتسليم المتفق عليه (التاريخ)',
  `actualDeliveryDate` DATE COMMENT 'تاريخ الاستلام الفعلي (يُعبأ عند الاستلام)',
  `shippingMethod` VARCHAR(200) COMMENT 'طريقة الشحن',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الأمر (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `poStatus` VARCHAR(50) COMMENT 'حالة أمر الشراء (مسودة، معتمد، مرسل للمورد، قيد التنفيذ، تم الاستلام جزئياً، مكتمل، ملغي)',
  `cancellationReason` VARCHAR(200) COMMENT 'سبب الإلغاء (إن وجد)',
  `budgetAllocationId` BIGINT COMMENT 'معرف تخصيص الميزانية المرتبط (FK → AssetBudgetAllocation.allocationId) - لتحديد بند الميزانية الذي سيتم الخصم منه',
  `notes` TEXT COMMENT 'ملاحظات',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (PDF لأمر الشراء، العطاء) (JSON)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`purchaseOrderId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`requestId`) REFERENCES `AssetRequirementRequest`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`budgetAllocationId`) REFERENCES `AssetBudgetAllocation`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='طلبات الشراء والمناقصات';

-- Table: AssetReceiving (الاستلام المبدئي وفحص الجودة)
CREATE TABLE IF NOT EXISTS `AssetReceiving` (
  `receivingId` BIGINT NOT NULL COMMENT 'معرف عملية الاستلام (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `purchaseOrderId` BIGINT COMMENT 'معرف أمر الشراء المرتبط (FK → PurchaseOrders.purchaseOrderId)',
  `receivingNumber` INT COMMENT 'رقم سند الاستلام (يُولد آلياً)',
  `receivedDate` DATE COMMENT 'تاريخ وصول الأصل الفعلي إلى المدرسة',
  `receivedByUserId` BIGINT COMMENT 'معرف من قام بالاستلام (FK → Employee.employeeId) - عضو لجنة الاستلام',
  `inspectorUserId` BIGINT COMMENT 'معرف المفتش (FK → Employee.employeeId) - عضو لجنة فحص الجودة',
  `deliveryNoteNumber` INT COMMENT 'رقم إذن التسليم من المورد (للرجوع إليه)',
  `deliveryCompany` VARCHAR(200) COMMENT 'شركة النقل (إن وجدت)',
  `inspectionResult` VARCHAR(200) COMMENT 'نتيجة الفحص (مطابق، غير مطابق جزئياً، مرفوض، يحتاج إصلاح)',
  `inspectionDate` DATE COMMENT 'تاريخ فحص الجودة',
  `inspectionNotes` TEXT COMMENT 'ملاحظات اللجنة الفنية عند الفحص (نص طويل، يوثق أي ملاحظات أو عيوب)',
  `qualityScore` DECIMAL(5,2) COMMENT 'تقييم جودة الأصل (1-10) - اختياري',
  `deliveryStatus` VARCHAR(50) COMMENT 'حالة التسليم (تم الاستلام كاملاً، تأخير، استلام جزئي)',
  `receivedItemsDetails` VARCHAR(200) COMMENT 'تفاصيل الأصناف المستلمة (JSON) - يمكن أن تحتوي على قائمة بالأصناف والكميات المستلمة مقابل المطلوبة',
  `acceptedAssets` VARCHAR(200) COMMENT 'قائمة بالأصول التي تم قبولها (سيتم تحويلها إلى سجلات في جدول Asset)',
  `rejectedItems` VARCHAR(200) COMMENT 'الأصناف المرفوضة مع أسباب الرفض (JSON)',
  `returnRequested` VARCHAR(200) COMMENT 'هل تم طلب إعادة الأصناف المرفوضة للمورد؟',
  `returnDate` DATE COMMENT 'تاريخ إعادة الأصناف (إن وجد)',
  `correctiveActionRequested` VARCHAR(200) COMMENT 'هل تم طلب إجراء تصحيحي من المورد؟',
  `correctiveActionDetails` VARCHAR(200) COMMENT 'تفاصيل الإجراء التصحيحي المطلوب',
  `finalDecision` VARCHAR(200) COMMENT 'القرار النهائي للجنة (قبول كامل، قبول جزئي مع خصم، رفض كامل، إعادة)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور الأصول، تقارير الفحص) (JSON)',
  `status` VARCHAR(50) COMMENT 'حالة عملية الاستلام (مفتوح، قيد الفحص، مكتمل، ملغي)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`receivingId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`purchaseOrderId`) REFERENCES `PurchaseOrders`(`...`),
  -- FOREIGN KEY (`receivedByUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`inspectorUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الاستلام المبدئي وفحص الجودة';

-- Table: AssetUsageLog (سجل التشغيل والاستخدام)
CREATE TABLE IF NOT EXISTS `AssetUsageLog` (
  `usageLogId` BIGINT NOT NULL COMMENT 'معرف سجل الاستخدام (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - للتكرار',
  `usageType` VARCHAR(50) COMMENT 'نوع الاستخدام (تشغيل عادي، اختبار، صيانة، طارئ)',
  `startDateTime` DATE COMMENT 'تاريخ ووقت بدء التشغيل',
  `endDateTime` DATE COMMENT 'تاريخ ووقت إيقاف التشغيل',
  `durationMinutes` DATETIME COMMENT 'مدة الاستخدام بالدقائق (تُحسب آلياً من startDateTime و endDateTime)',
  `purpose` VARCHAR(200) COMMENT 'الغرض من الاستخدام (تعليمي، إداري، تدريب، اجتماع، صيانة، أخرى)',
  `purposeDetails` VARCHAR(200) COMMENT 'تفاصيل إضافية عن الغرض (مثل اسم المادة الدراسية، نوع النشاط)',
  `userId` BIGINT COMMENT 'معرف المستخدم الذي استخدم الأصل (FK → SystemUser.userId) - يمكن أن يكون معلم، موظف إداري، أو طالب',
  `userType` VARCHAR(50) COMMENT 'نوع المستخدم (معلم، موظف، طالب)',
  `locationId` BIGINT COMMENT 'معرف الموقع الذي تم فيه الاستخدام (FK → AssetLocation.locationId)',
  `usageStatus` VARCHAR(50) COMMENT 'حالة الاستخدام (قيد الاستخدام، مكتمل، معلق، منقطع)',
  `notes` TEXT COMMENT 'ملاحظات أثناء الاستخدام (أي مشاكل طرأت، كفاءة الأداء)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`usageLogId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`locationId`) REFERENCES `AssetLocation`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سجل التشغيل والاستخدام';

-- Table: MaintenanceTickets (بلاغات الأعطال)
CREATE TABLE IF NOT EXISTS `MaintenanceTickets` (
  `ticketId` BIGINT NOT NULL COMMENT 'معرف تذكرة الصيانة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `ticketNumber` INT COMMENT 'رقم التذكرة (يُولد آلياً، مثال: MT-2024-001)',
  `assetId` BIGINT COMMENT 'معرف الأصل المعطوب (FK → Asset.assetId)',
  `reportedByUserId` BIGINT COMMENT 'معرف مقدم البلاغ (FK → SystemUser.userId)',
  `reportDate` DATE COMMENT 'تاريخ ووقت تسجيل البلاغ',
  `issueType` BOOLEAN COMMENT 'نوع المشكلة (كهربائي، ميكانيكي، برمجي، هيكلي، تسرب، أخرى)',
  `severityLevel` VARCHAR(50) COMMENT 'مستوى الخطورة (منخفض، متوسط، عالي، طارئ - يحدد أولوية الاستجابة)',
  `issueDescription` BOOLEAN COMMENT 'وصف تفصيلي للمشكلة (من المبلغ)',
  `reportedLocation` VARCHAR(200) COMMENT 'موقع العطل (نص أو FK → AssetLocation.locationId)',
  `assignedToUserId` BIGINT COMMENT 'معرف الفني المسؤول عن الإصلاح (FK → Employee.employeeId) - من قسم الموظفين',
  `assignedDate` DATE COMMENT 'تاريخ التعيين',
  `diagnosis` VARCHAR(200) COMMENT 'تشخيص الفني للمشكلة (نص)',
  `requiredParts` VARCHAR(200) COMMENT 'قطع الغيار المطلوبة (JSON) - يمكن ربطها بجدول MaintenanceSpareParts',
  `estimatedCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية للإصلاح',
  `estimatedCompletionDate` DATE COMMENT 'تاريخ الإنجاز المتوقع',
  `actualCompletionDate` DATE COMMENT 'تاريخ الإنجاز الفعلي',
  `resolutionDetails` VARCHAR(200) COMMENT 'تفاصيل الإجراءات التي تمت لحل المشكلة',
  `resolutionSummary` VARCHAR(200) COMMENT 'ملخص الحل',
  `resolutionCost` DECIMAL(15,2) COMMENT 'التكلفة الفعلية للإصلاح',
  `ticketStatus` VARCHAR(50) COMMENT 'حالة التذكرة (مفتوح، قيد المراجعة، معتمد، قيد الإصلاح، في انتظار قطع غيار، مكتمل، مغلق، ملغي)',
  `closureNotes` TEXT COMMENT 'ملاحظات عند الإغلاق',
  `closedByUserId` BIGINT COMMENT 'معرف من أغلق التذكرة',
  `closedAt` DATE COMMENT 'تاريخ الإغلاق',
  `relatedExecutionId` BIGINT COMMENT 'معرف سجل تنفيذ الصيانة المرتبط (FK → MaintenanceExecution.executionId) - بعد تنفيذ الصيانة',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور للمشكلة، تقارير) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`ticketId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`reportedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`reportedLocation`) REFERENCES `AssetLocation`(`...`),
  -- FOREIGN KEY (`assignedToUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`closedByUserId`) REFERENCES `ClosedByUser`(`...`),
  -- FOREIGN KEY (`relatedExecutionId`) REFERENCES `MaintenanceExecution`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='بلاغات الأعطال';

-- Table: PreventiveMaintenanceSchedule (جدولة الصيانة الوقائية)
CREATE TABLE IF NOT EXISTS `PreventiveMaintenanceSchedule` (
  `scheduleId` BIGINT NOT NULL COMMENT 'معرف جدول الصيانة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `scheduleCode` VARCHAR(50) COMMENT 'كود جدول الصيانة (فريد)',
  `assetId` BIGINT COMMENT 'معرف الأصل المستهدف (FK → Asset.assetId) - يمكن أن يكون فارغاً لتطبيق الجدول على فئة أصول',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصول (FK → AssetCategory.categoryId) - يُستخدم إذا كان الجدول لفئة كاملة',
  `taskNameAr` VARCHAR(200) COMMENT 'اسم مهمة الصيانة بالعربية (مثال: "فحص شامل لوحدة التكييف")',
  `taskNameEn` VARCHAR(200) COMMENT 'اسم المهمة بالإنجليزية',
  `maintenanceType` VARCHAR(50) COMMENT 'نوع الصيانة (تنظيف، معايرة، فحص، تشحيم، استبدال قطع)',
  `frequency` VARCHAR(200) COMMENT 'التكرار (أسبوعي، شهري، ربع سنوي، سنوي، حسب ساعات التشغيل)',
  `frequencyValue` VARCHAR(200) COMMENT 'القيمة العددية للتكرار (مثال: 3 أشهر، 500 ساعة تشغيل)',
  `frequencyUnit` VARCHAR(200) COMMENT 'وحدة التكرار (شهر، أسبوع، يوم، ساعة تشغيل)',
  `nextDueDate` DATE COMMENT 'موعد الصيانة القادم (يُحسب آلياً بناءً على آخر تاريخ تم تنفيذه والتكرار)',
  `lastServiceDate` DATE COMMENT 'تاريخ آخر صيانة تمت (يتم تحديثه عند التنفيذ)',
  `estimatedDuration` VARCHAR(200) COMMENT 'المدة التقديرية للمهمة (بالدقائق)',
  `assignedToTeam` VARCHAR(200) COMMENT 'الفريق المسؤول (نص أو FK → Employee.employeeId)',
  `instructions` VARCHAR(200) COMMENT 'تعليمات الصيانة (نص طويل)',
  `checklist` VARCHAR(200) COMMENT 'قائمة مرجعية لإجراءات الصيانة (JSON)',
  `requiredParts` VARCHAR(200) COMMENT 'قطع الغيار المطلوبة لهذه المهمة الوقائية (JSON)',
  `estimatedCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية',
  `contractId` BIGINT COMMENT 'معرف عقد الصيانة الخارجي المرتبط (FK → AssetWarrantyContract.contractId) - اختياري',
  `isReminderActive` BOOLEAN COMMENT 'تفعيل/تعطيل التنبيهات التلقائية قبل الموعد (نعم/لا)',
  `reminderDaysBefore` VARCHAR(200) COMMENT 'عدد الأيام قبل الموعد لإرسال التذكير (افتراضي 7 أيام)',
  `status` VARCHAR(50) COMMENT 'حالة الجدول (نشط، معلق، ملغي)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`scheduleId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`assignedToTeam`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`contractId`) REFERENCES `AssetWarrantyContract`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='جدولة الصيانة الوقائية';

-- Table: MaintenanceExecution (سجل تنفيذ الصيانة)
CREATE TABLE IF NOT EXISTS `MaintenanceExecution` (
  `executionId` BIGINT NOT NULL COMMENT 'معرف سجل التنفيذ (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `executionNumber` INT COMMENT 'رقم سجل التنفيذ (يُولد آلياً)',
  `ticketId` BIGINT COMMENT 'معرف تذكرة العطل المرتبطة (FK → MaintenanceTickets.ticketId) - اختياري (للصيانة التفاعلية)',
  `scheduleId` BIGINT COMMENT 'معرف جدول الصيانة الوقائية المرتبط (FK → PreventiveMaintenanceSchedule.scheduleId) - اختياري (للصيانة الوقائية)',
  `assetId` BIGINT COMMENT 'معرف الأصل الذي تمت صيانته (FK → Asset.assetId)',
  `executionType` VARCHAR(50) COMMENT 'نوع التنفيذ (صيانة تفاعلية، صيانة وقائية، طارئ)',
  `startDateTime` DATE COMMENT 'وقت بدء العمل الفعلي',
  `endDateTime` DATE COMMENT 'وقت الانتهاء (لحساب زمن الاستجابة/التنفيذ)',
  `executedByUserId` BIGINT COMMENT 'معرف الفني المنفذ (FK → Employee.employeeId)',
  `workPerformed` VARCHAR(200) COMMENT 'وصف دقيق لما تم إنجازه من أعمال (نص طويل)',
  `sparePartsUsed` VARCHAR(200) COMMENT 'قطع الغيار المستهلكة (JSON) - يمكن ربطها بتفاصيل MaintenanceSpareParts',
  `maintenanceCost` DECIMAL(15,2) COMMENT 'التكلفة المالية المباشرة (أجور + قطع غيار)',
  `additionalNotes` TEXT COMMENT 'ملاحظات إضافية',
  `isOperationalAfter` BOOLEAN COMMENT 'هل عاد الأصل للخدمة بنجاح؟ (نعم/لا)',
  `newAssetStatusId` BIGINT COMMENT 'معرف الحالة الجديدة للأصل بعد الصيانة (FK → AssetStatus.statusId) - مثلاً "نشط" أو "بحاجة لصيانة إضافية"',
  `resolutionSummary` VARCHAR(200) COMMENT 'ملخص الإجراءات والحل',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور قبل وبعد الإصلاح، تقارير)',
  `status` VARCHAR(50) COMMENT 'حالة سجل التنفيذ (مكتمل، قيد التنفيذ، ملغي)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`executionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`ticketId`) REFERENCES `MaintenanceTickets`(`...`),
  -- FOREIGN KEY (`scheduleId`) REFERENCES `PreventiveMaintenanceSchedule`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`executedByUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`newAssetStatusId`) REFERENCES `AssetStatus`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سجل تنفيذ الصيانة';

-- Table: MaintenanceSpareParts (قطع الغيار والمستهلكات)
CREATE TABLE IF NOT EXISTS `MaintenanceSpareParts` (
  `partId` BIGINT NOT NULL COMMENT 'معرف قطعة الغيار (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `partCode` VARCHAR(50) COMMENT 'الكود المخزني للقطعة (SKU) (فريد)',
  `partNameAr` VARCHAR(200) COMMENT 'اسم قطعة الغيار أو المادة بالعربية (مثال: "فلتر زيت")',
  `partNameEn` VARCHAR(200) COMMENT 'الاسم بالإنجليزية',
  `partCategory` VARCHAR(50) COMMENT 'فئة القطعة (كهربائية، ميكانيكية، إلكترونية، استهلاكية)',
  `manufacturer` VARCHAR(200) COMMENT 'الشركة المصنعة (اختياري)',
  `compatibleAssets` VARCHAR(200) COMMENT 'الأصول المتوافقة مع هذه القطعة (JSON) - قائمة بمعرفات الأصول أو الفئات',
  `unitOfMeasure` VARCHAR(200) COMMENT 'وحدة القياس (قطعة، علبة، لتر، متر)',
  `currentStockQuantity` VARCHAR(200) COMMENT 'الكمية المتوفرة حالياً في المخزون',
  `minStockLevel` VARCHAR(50) COMMENT 'الحد الأدنى للكمية (عند الوصول إليه، يتم إصدار تنبيه للتزويد)',
  `maxStockLevel` VARCHAR(50) COMMENT 'الحد الأقصى للكمية',
  `reorderQuantity` VARCHAR(200) COMMENT 'كمية إعادة الطلب الموصى بها (متى نطلب وماذا نطلب)',
  `unitCost` DECIMAL(15,2) COMMENT 'سعر الوحدة (لحساب التكلفة عند الاستهلاك)',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `supplierName` VARCHAR(200) COMMENT 'المورد المفضل',
  `locationInWarehouse` VARCHAR(200) COMMENT 'موقع القطعة في المستودع (رف، خزانة)',
  `isActive` BOOLEAN COMMENT 'هل القطعة لا تزال مستخدمة؟',
  `status` VARCHAR(50) COMMENT 'حالة القطعة في المخزون (متوفر، شحيح، نفذ، مطلوب)',
  `lastRestockDate` DATE COMMENT 'تاريخ آخر تزويد',
  `totalConsumed` VARCHAR(200) COMMENT 'إجمالي الكمية المستهلكة (يُحسب آلياً من استهلاكات الصيانة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`partId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='قطع الغيار والمستهلكات';

-- Table: AssetSuspensionRequests (طلبات تعليق الأصل)
CREATE TABLE IF NOT EXISTS `AssetSuspensionRequests` (
  `suspensionId` BIGINT NOT NULL COMMENT 'معرف طلب التعليق (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestNumber` INT COMMENT 'رقم الطلب (يُولد آلياً)',
  `assetId` BIGINT COMMENT 'معرف الأصل المراد تعليقه (FK → Asset.assetId)',
  `requestedByUserId` BIGINT COMMENT 'معرف مقدم الطلب (FK → SystemUser.userId)',
  `requestDate` DATE COMMENT 'تاريخ الطلب',
  `reason` VARCHAR(200) COMMENT 'سبب التعليق (أمني، فني، إداري، قيد التحقيق، تلف كامل)',
  `reasonDetails` VARCHAR(200) COMMENT 'تفاصيل السبب (نص)',
  `startDate` DATE COMMENT 'تاريخ بدء التعليق المتوقع',
  `expectedEndDate` DATE COMMENT 'التاريخ المتوقع لفك التعليق (يمكن أن يكون فارغاً إذا كان دائماً)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (تقارير، صور) (JSON)',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الطلب (قيد المراجعة، معتمد، مرفوض، ملغي)',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `isRevoked` BOOLEAN COMMENT 'هل تم إلغاء التعليق وإعادة الأصل للخدمة؟',
  `revokeDate` DATE COMMENT 'تاريخ الإلغاء',
  `revokeReason` VARCHAR(200) COMMENT 'سبب الإلغاء',
  `revokedByUserId` BIGINT COMMENT 'معرف من ألغى التعليق',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي للتعليق',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (نشط، منتهي، ملغي)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`suspensionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`requestedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`revokedByUserId`) REFERENCES `RevokedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='طلبات تعليق الأصل';

-- Table: MaintenanceNotifications (إشعارات الصيانة)
CREATE TABLE IF NOT EXISTS `MaintenanceNotifications` (
  `notificationId` BIGINT NOT NULL COMMENT 'معرف الإشعار (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `relatedEntityType` VARCHAR(50) COMMENT 'نوع الكيان المرتبط (MaintenanceTicket, PreventiveSchedule, SparePart, AssetSuspension)',
  `relatedEntityId` BIGINT COMMENT 'معرف الكيان المرتبط (يمكن أن يكون ticketId, scheduleId, partId, suspensionId)',
  `notificationType` VARCHAR(50) COMMENT 'نوع الإشعار (بلاغ جديد، موعد صيانة قادم، تحذير مخزون، اكتمال صيانة، تعليق أصل)',
  `title` VARCHAR(200) COMMENT 'عنوان الإشعار',
  `messageContent` VARCHAR(200) COMMENT 'نص الرسالة التنبيهية',
  `recipientUserId` BIGINT COMMENT 'معرف المستخدم المستلم (FK → SystemUser.userId)',
  `priority` VARCHAR(200) COMMENT 'أولوية الإشعار (عادي، مهم، عاجل)',
  `isRead` BOOLEAN COMMENT 'هل تم الاطلاع على التنبيه؟',
  `readAt` DATE COMMENT 'تاريخ القراءة',
  `sentAt` DATE COMMENT 'تاريخ ووقت إرسال النظام للتنبيه',
  `deliveryMethod` VARCHAR(200) COMMENT 'طريقة الإرسال (تطبيق، بريد إلكتروني، رسالة نصية)',
  `status` VARCHAR(50) COMMENT 'حالة الإشعار (مرسل، مقروء، ملغي)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (غالباً النظام نفسه)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`notificationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`relatedEntityId`) REFERENCES `RelatedEntity`(`...`),
  -- FOREIGN KEY (`recipientUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إشعارات الصيانة';

-- Table: UsageViolations (مخالفات الاستخدام)
CREATE TABLE IF NOT EXISTS `UsageViolations` (
  `violationId` BIGINT NOT NULL COMMENT 'معرف المخالفة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `assetId` BIGINT COMMENT 'معرف الأصل المخالف في استخدامه (FK → Asset.assetId)',
  `violationType` VARCHAR(50) COMMENT 'نوع المخالفة (سوء استخدام، تجاوز حدود الصلاحية، إهمال صيانة، استخدام غير مصرح به، فقدان أصل)',
  `violationDate` DATE COMMENT 'تاريخ المخالفة',
  `reportedByUserId` BIGINT COMMENT 'معرف من أبلغ عن المخالفة (FK → SystemUser.userId)',
  `reportedDate` DATE COMMENT 'تاريخ الإبلاغ',
  `violatingUserId` BIGINT COMMENT 'معرف المستخدم المخالف (FK → SystemUser.userId) - يمكن أن يكون موظفاً أو طالباً',
  `description` TEXT COMMENT 'وصف دقيق للمخالفة وما حدث',
  `evidence` VARCHAR(200) COMMENT 'أدلة (JSON) - مسارات ملفات صور، فيديوهات',
  `penaltyAction` VARCHAR(200) COMMENT 'الإجراء المتخذ (إنذار، تعليق استخدام الأصل، خصم مالي، إحالة للتحقيق)',
  `penaltyAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة المالية (إن وجدت)',
  `penaltyAmountCurrency` DECIMAL(15,2) COMMENT 'عملة الغرامة',
  `deductionFromSalary` DECIMAL(15,2) COMMENT 'هل سيتم خصم المبلغ من راتب الموظف (نعم/لا)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الإجراء التأديبي (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة المخالفة (مسجلة، قيد التحقيق، تم اتخاذ إجراء، مغلقة)',
  `closedAt` DATE COMMENT 'تاريخ إغلاق المخالفة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`violationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`reportedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`violatingUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مخالفات الاستخدام';

-- Table: AssetFinancials (القيم المالية للأصل)
CREATE TABLE IF NOT EXISTS `AssetFinancials` (
  `financialsId` BIGINT NOT NULL COMMENT 'معرف السجل المالي (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل المرتبط (FK → Asset.assetId) - علاقة 1-1 (أصل واحد له سجل مالي واحد)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - للتكرار وتسهيل التقارير',
  `purchasePrice` DECIMAL(15,2) COMMENT 'سعر الشراء الأساسي من الفاتورة (قبل أي إضافات)',
  `shippingCosts` DECIMAL(15,2) COMMENT 'تكاليف الشحن والنقل',
  `customsFees` DECIMAL(15,2) COMMENT 'الرسوم الجمركية (للواردات)',
  `installationCosts` DECIMAL(15,2) COMMENT 'تكاليف التركيب والتهيئة',
  `otherCosts` DECIMAL(15,2) COMMENT 'تكاليف أخرى (تأمين، رسوم ترخيص، الخ) (JSON)',
  `totalInitialCost` DECIMAL(15,2) COMMENT 'التكلفة الكلية (تجمع آلياً = purchasePrice + shippingCosts + customsFees + installationCosts + otherCosts)',
  `currency` VARCHAR(200) COMMENT 'العملة المستخدمة (SAR, USD, EUR, GBP, etc.)',
  `exchangeRateToSAR` DECIMAL(5,2) COMMENT 'سعر الصرف للريال السعودي (لتوحيد الحسابات المالية في التقارير)',
  `salvageValue` VARCHAR(200) COMMENT 'القيمة التخريدية (الخردة) المتوقعة في نهاية العمر الإنتاجي',
  `residualValue` VARCHAR(200) COMMENT 'القيمة المتبقية (مرادف لـ salvageValue)',
  `residualValueLastUpdate` DATE COMMENT 'تاريخ آخر تحديث للقيمة التخريدية',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية للإدخال (مثال: 2025)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (FK → SystemUser.userId)',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل السجل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`financialsId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='القيم المالية للأصل';

-- Table: AssetDepreciation (سياسات وحسابات الإهلاك)
CREATE TABLE IF NOT EXISTS `AssetDepreciation` (
  `depreciationId` BIGINT NOT NULL COMMENT 'معرف سجل الإهلاك (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId) - علاقة 1-1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `methodType` VARCHAR(50) COMMENT 'طريقة الإهلاك (القسط الثابت - Straight Line، القسط المتناقص - Declining Balance، وحدات الإنتاج - Units of Production)',
  `usefulLifeYears` VARCHAR(200) COMMENT 'العمر الإنتاجي المقدر (بالسنوات) - يُستخدم لحساب قسط الإهلاك السنوي في طريقة القسط الثابت',
  `usefulLifeUnits` VARCHAR(200) COMMENT 'العمر الإنتاجي المقدر بوحدات الإنتاج (ساعات تشغيل، وحدات منتجة) - يُستخدم في طريقة وحدات الإنتاج',
  `depreciationRate` DECIMAL(5,2) COMMENT 'نسبة الإهلاك السنوية (تستخدم في طريقة القسط المتناقص)',
  `currentBookValue` VARCHAR(200) COMMENT 'القيمة الدفترية الحالية للأصل في بداية الفترة الحالية (قيمة قابلة للإهلاك)',
  `accumulatedDepreciation` DATE COMMENT 'مجمع الإهلاك المتراكم حتى تاريخه (إجمالي ما تم إهلاكه من قيمة الأصل)',
  `netBookValue` VARCHAR(200) COMMENT 'صافي القيمة الدفترية (currentBookValue - accumulatedDepreciation) - قد يكون حساباً مباشراً أو يُحسب آلياً',
  `depreciableAmount` DECIMAL(15,2) COMMENT 'القيمة القابلة للإهلاك (التكلفة - الخردة)',
  `lastDepreciationDate` DATE COMMENT 'تاريخ آخر عملية إهلاك تم تسجيلها (آخر قسط تم)',
  `lastDepreciationPeriod` VARCHAR(200) COMMENT 'آخر فترة تم إهلاكها (مثال: الشهر 12 من السنة 2024)',
  `isFullyDepreciated` BOOLEAN COMMENT 'هل تم إهلاك الأصل بالكامل؟ (نعم/لا)',
  `notes` TEXT COMMENT 'ملاحظات حول سياسة الإهلاك',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`depreciationId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سياسات وحسابات الإهلاك';

-- Table: DepreciationTransactions (معاملات الإهلاك الدورية)
CREATE TABLE IF NOT EXISTS `DepreciationTransactions` (
  `transactionId` BIGINT NOT NULL COMMENT 'معرف المعاملة (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `depreciationId` BIGINT COMMENT 'معرف سجل الإهلاك المرتبط (FK → AssetDepreciation.depreciationId)',
  `periodStart` VARCHAR(200) COMMENT 'بداية الفترة المالية (مثال: 2025-01-01)',
  `periodEnd` VARCHAR(200) COMMENT 'نهاية الفترة المالية (مثال: 2025-01-31)',
  `periodType` VARCHAR(50) COMMENT 'نوع الفترة (شهري، ربع سنوي، نصف سنوي، سنوي)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية',
  `periodNumber` INT COMMENT 'رقم الفترة (مثال: 1 = يناير، 2 = فبراير)',
  `depreciationAmount` DECIMAL(15,2) COMMENT 'قيمة قسط الإهلاك لهذه الفترة (المبلغ الذي تم إهلاكه)',
  `accumulatedDepreciationAfter` VARCHAR(200) COMMENT 'مجمع الإهلاك بعد إضافة هذا القسط',
  `netBookValueAfter` VARCHAR(200) COMMENT 'صافي القيمة الدفترية بعد الإهلاك',
  `isPostedToLedger` BOOLEAN COMMENT 'هل تم ترحيل القيد إلى دفتر الأستاذ العام؟ (نعم/لا)',
  `ledgerEntryReference` VARCHAR(200) COMMENT 'رقم مرجع القيد في دفتر الأستاذ العام (إن تم ترحيله)',
  `postedToLedgerDate` DATE COMMENT 'تاريخ الترحيل إلى دفتر الأستاذ',
  `calculatedByUserId` BIGINT COMMENT 'معرف من قام بحساب الإهلاك (غالباً النظام آلياً، أو مستخدم)',
  `calculationDate` DATE COMMENT 'تاريخ حساب الإهلاك',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ إنشاء السجل',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`transactionId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`depreciationId`) REFERENCES `AssetDepreciation`(`...`),
  -- FOREIGN KEY (`calculatedByUserId`) REFERENCES `CalculatedByUser`(`...`)
) COMMENT='معاملات الإهلاك الدورية';

-- Table: RevaluationImpairment (إعادة التقييم والانخفاض)
CREATE TABLE IF NOT EXISTS `RevaluationImpairment` (
  `revaluationId` BIGINT NOT NULL COMMENT 'معرف عملية إعادة التقييم (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `type` VARCHAR(50) COMMENT 'نوع العملية (إعادة تقييم - Revaluation، انخفاض قيمة - Impairment)',
  `effectiveDate` DATE COMMENT 'تاريخ سريان القيمة الجديدة',
  `oldBookValue` VARCHAR(200) COMMENT 'القيمة الدفترية قبل العملية (قبل التعديل)',
  `oldAccumulatedDepreciation` VARCHAR(200) COMMENT 'مجمع الإهلاك القديم',
  `oldNetBookValue` VARCHAR(200) COMMENT 'صافي القيمة الدفترية القديمة',
  `newValue` VARCHAR(200) COMMENT 'القيمة الجديدة المعتمدة (السوقية العادلة)',
  `newAccumulatedDepreciation` VARCHAR(200) COMMENT 'مجمع الإهلاك الجديد (بعد إعادة التوزيع)',
  `newNetBookValue` VARCHAR(200) COMMENT 'صافي القيمة الدفترية الجديد',
  `difference` VARCHAR(200) COMMENT 'فرق التقييم (ربح أو خسارة)',
  `differenceType` VARCHAR(50) COMMENT 'نوع الفرق (ربح إعادة تقييم - يضاف لحقوق الملكية، خسارة إعادة تقييم - يخصم من حقوق الملكية، خسارة انخفاض - تحمل على قائمة الدخل)',
  `valuationFirm` VARCHAR(200) COMMENT 'جهة التقييم المعتمدة (اسم الشركة أو الخبير)',
  `valuationReportNumber` INT COMMENT 'رقم تقرير التقييم',
  `valuationReportDate` DATE COMMENT 'تاريخ تقرير التقييم',
  `valuationMethod` VARCHAR(200) COMMENT 'طريقة التقييم المستخدمة (السوقي، التكلفة، الدخل)',
  `reason` VARCHAR(200) COMMENT 'سبب التقييم أو الانخفاض الجوهري (نص)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (تقرير التقييم، صور) (JSON)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد العملية (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة العملية (مسودة، معتمدة، مرحلة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`revaluationId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إعادة التقييم والانخفاض';

-- Table: AssetExpenses (المصروفات الرأسمالية والتشغيلية)
CREATE TABLE IF NOT EXISTS `AssetExpenses` (
  `expenseId` BIGINT NOT NULL COMMENT 'معرف المصروف (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `expenseType` VARCHAR(50) COMMENT 'نوع المصروف (رأسمالي - Capex، تشغيلي - Opex)',
  `expenseDate` DATE COMMENT 'تاريخ حدوث المصروف (تاريخ الفاتورة)',
  `amount` DECIMAL(15,2) COMMENT 'قيمة المصروف',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `description` TEXT COMMENT 'تفاصيل المصروف (صيانة كبرى، قطع غيار، تركيب، تدريب، الخ)',
  `relatedExecutionId` BIGINT COMMENT 'معرف سجل تنفيذ الصيانة المرتبط (FK → MaintenanceExecution.executionId) - اختياري',
  `isCapitalized` BOOLEAN COMMENT 'هل سيتم إضافة المصروف لقيمة الأصل (رأسمالته)؟ (نعم/لا) - يحدد بناءً على expenseType وقواعد محاسبية',
  `capitalizationDate` DATE COMMENT 'تاريخ إضافة المصروف لقيمة الأصل (إذا isCapitalized = نعم)',
  `accountedInFinancials` INT COMMENT 'هل تم إضافة المصروف لقيمة الأصل في جدول AssetFinancials؟',
  `accountedInDepreciation` INT COMMENT 'هل تم تعديل الإهلاك المستقبلي بسبب رأسمالة المصروف؟',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد تصنيف المصروف (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`expenseId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`relatedExecutionId`) REFERENCES `MaintenanceExecution`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المصروفات الرأسمالية والتشغيلية';

-- Table: FeasibilityComparison (مقارنات الجدوى والاستبدال)
CREATE TABLE IF NOT EXISTS `FeasibilityComparison` (
  `comparisonId` BIGINT NOT NULL COMMENT 'معرف المقارنة (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل المُقارَن (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `comparisonDate` DATE COMMENT 'تاريخ إجراء المقارنة',
  `repairEstimate` VARCHAR(200) COMMENT 'تكلفة الإصلاح المقدرة (مجمع: قطع غيار + أجور + مصروفات)',
  `repairEstimateBreakdown` VARCHAR(200) COMMENT 'تفاصيل تقدير تكلفة الإصلاح (JSON)',
  `replacementAssetId` BIGINT COMMENT 'معرف الأصل البديل المقترح (FK → Asset.assetId) - يمكن أن يكون أصل جديد لم يتم إضافته للنظام بعد، أو موجود مسبقاً',
  `replacementCost` DECIMAL(15,2) COMMENT 'تكلفة شراء أصل بديل جديد (سعر الشراء + التركيب + التشغيل الأولي)',
  `replacementCostBreakdown` DECIMAL(15,2) COMMENT 'تفاصيل تكلفة الاستبدال (JSON)',
  `totalCostOfOwnershipAnalysis` DECIMAL(15,2) COMMENT 'تحليل إجمالي تكلفة الامتلاك للبديل (نص أو JSON)',
  `recommendation` VARCHAR(200) COMMENT 'توصية اللجنة (إصلاح، استبدال، إيقاف الخدمة، تأجيل القرار)',
  `recommendationReason` VARCHAR(200) COMMENT 'سبب التوصية (نص مفصل)',
  `decisionStatus` VARCHAR(50) COMMENT 'حالة القرار (بانتظار القرار، استمرار بإصلاح الأصل، استبدال، إلغاء الأصل)',
  `decisionDate` DATE COMMENT 'تاريخ القرار',
  `approvedByUserId` BIGINT COMMENT 'معرف من اتخذ القرار (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`comparisonId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`replacementAssetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مقارنات الجدوى والاستبدال';

-- Table: FinancialAuditArchive (الأرشفة المالية)
CREATE TABLE IF NOT EXISTS `FinancialAuditArchive` (
  `archiveId` BIGINT NOT NULL COMMENT 'معرف الأرشفة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportType` VARCHAR(50) COMMENT 'نوع التقرير المؤرشف (تقرير إهلاك، تقرير قيمة دفترية، تقرير إعادة تقييم، ميزانية الأصول)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية للتقرير',
  `periodStart` VARCHAR(200) COMMENT 'بداية الفترة التي يغطيها التقرير',
  `periodEnd` VARCHAR(200) COMMENT 'نهاية الفترة',
  `generationDate` DATE COMMENT 'تاريخ إصدار التقرير الأصلي',
  `archivedDate` DATE COMMENT 'تاريخ الأرشفة (نقل البيانات إلى الأرشيف)',
  `totalAssetsValue` VARCHAR(200) COMMENT 'إجمالي قيم الأصول في هذا التقرير (لقطة)',
  `totalDepreciationValue` VARCHAR(200) COMMENT 'إجمالي الإهلاك في هذه الفترة',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير المعتمد (PDF/Excel) - يمكن أن يكون ملفاً يتم إنشاؤه عند الأرشفة',
  `isReadOnly` BOOLEAN COMMENT 'دائماً True (لمنع أي تعديل)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (من قام بالأرشفة)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`archiveId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`)
) COMMENT='الأرشفة المالية';

-- Table: FinancialSummaryReports (تقارير القيمة المالية المجمعة)
CREATE TABLE IF NOT EXISTS `FinancialSummaryReports` (
  `summaryId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية محل التقرير',
  `reportDate` DATE COMMENT 'تاريخ إصدار التقرير',
  `reportType` VARCHAR(50) COMMENT 'نوع التقرير (سنوي، ربع سنوي، حسب الطلب)',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصول (FK → AssetCategory.categoryId) - يمكن أن يكون فارغاً للتقرير العام',
  `totalBookValue` VARCHAR(200) COMMENT 'إجمالي القيمة الدفترية لكافة الأصول (أو للفئة)',
  `totalDepreciation` VARCHAR(200) COMMENT 'إجمالي الإهلاك المتراكم للفترة',
  `totalAssetsCount` INT COMMENT 'عدد الأصول التي شملها التقرير المالي',
  `totalAcquisitionCost` DATE COMMENT 'إجمالي تكلفة الشراء للأصول (التكلفة التاريخية)',
  `fullyDepreciatedAssetsCount` INT COMMENT 'عدد الأصول التي تم إهلاكها بالكامل',
  `assetsWithImpairmentCount` INT COMMENT 'عدد الأصول التي تم تسجيل انخفاض في قيمتها',
  `revaluationGains` VARCHAR(200) COMMENT 'إجمالي أرباح إعادة التقييم',
  `revaluationLosses` VARCHAR(200) COMMENT 'إجمالي خسائر إعادة التقييم',
  `auditStatus` VARCHAR(50) COMMENT 'حالة تدقيق التقرير (غير مدقق، مدقق داخلياً، مدقق خارجياً، تحت التدقيق)',
  `auditFirmName` VARCHAR(200) COMMENT 'اسم شركة التدقيق (إن وجد)',
  `auditorName` VARCHAR(200) COMMENT 'اسم المدقق (إن وجد)',
  `auditDate` DATE COMMENT 'تاريخ التدقيق',
  `auditorSignature` VARCHAR(200) COMMENT 'توقيع المدقق الإلكتروني',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`summaryId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير القيمة المالية المجمعة';

-- Table: AssetAssignment (تخصيص الأصول)
CREATE TABLE IF NOT EXISTS `AssetAssignment` (
  `assignmentId` BIGINT NOT NULL COMMENT 'معرف التخصيص (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `assigneeType` VARCHAR(50) COMMENT 'نوع المستلم (موظف، طالب، قسم، معمل، أخرى)',
  `assigneeId` BIGINT COMMENT 'معرف المستلم (حسب النوع: Employee.employeeId أو Student.studentId أو SchoolDepartment.deptId)',
  `assigneeName` VARCHAR(200) COMMENT 'اسم المستلم (نسخة احتياطية للعرض السريع)',
  `assignerUserId` BIGINT COMMENT 'معرف من قام بالتخصيص (FK → SystemUser.userId)',
  `assignmentDate` DATE COMMENT 'تاريخ بدء التخصيص (تاريخ التسليم)',
  `expectedReturnDate` DATE COMMENT 'تاريخ الإرجاع المتوقع (نهاية العقد الدراسي، نهاية السنة، إلخ)',
  `actualReturnDate` DATE COMMENT 'تاريخ استرجاع الأصل الفعلي',
  `assignmentReason` VARCHAR(200) COMMENT 'سبب التخصيص (وظيفة، دراسة، مشروع، إعارة مؤقتة)',
  `conditionAtAssignment` VARCHAR(200) COMMENT 'حالة الأصل عند التسليم (جديد، جيد، يحتاج صيانة)',
  `conditionNotesAtAssignment` TEXT COMMENT 'ملاحظات عند التسليم',
  `conditionAtReturn` VARCHAR(200) COMMENT 'حالة الأصل عند الإرجاع',
  `conditionNotesAtReturn` TEXT COMMENT 'ملاحظات عند الإرجاع',
  `damageNotes` TEXT COMMENT 'ملاحظات عن أي تلف حدث أثناء فترة التخصيص',
  `penaltyAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة (إن وجدت بسبب تلف أو فقدان)',
  `penaltyStatus` VARCHAR(50) COMMENT 'حالة الغرامة (مستحقة، مدفوعة، معفاة)',
  `assignmentStatus` VARCHAR(50) COMMENT 'حالة التخصيص (نشط، ملغي، مسترجع، منتهي)',
  `isReturned` BOOLEAN COMMENT 'هل تم استرجاع الأصل؟',
  `returnReceiptNumber` INT COMMENT 'رقم إيصال الاسترجاع (إن وجد)',
  `returnedToUserId` BIGINT COMMENT 'معرف من استلم الأصل عند الإرجاع (FK → SystemUser.userId)',
  `returnDate` DATE COMMENT 'تاريخ الإرجاع',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`assignmentId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assigneeId`) REFERENCES `Assignee`(`...`),
  -- FOREIGN KEY (`assignerUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`returnedToUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تخصيص الأصول';

-- Table: AssetLoans (إعارات الأصول)
CREATE TABLE IF NOT EXISTS `AssetLoans` (
  `loanId` BIGINT NOT NULL COMMENT 'معرف الإعارة (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `borrowerType` VARCHAR(50) COMMENT 'نوع المستعير (طالب، موظف، زائر، جهة خارجية)',
  `borrowerId` BIGINT COMMENT 'معرف المستعير (حسب النوع)',
  `borrowerName` VARCHAR(200) COMMENT 'اسم المستعير (نسخة احتياطية)',
  `borrowerContact` VARCHAR(200) COMMENT 'جهة اتصال المستعير (هاتف أو بريد)',
  `loanDate` DATE COMMENT 'تاريخ بداية الإعارة',
  `expectedReturnDate` DATE COMMENT 'تاريخ الإرجاع المتوقع',
  `actualReturnDate` DATE COMMENT 'تاريخ الإرجاع الفعلي',
  `loanPurpose` VARCHAR(200) COMMENT 'الغرض من الإعارة (نشاط صفي، بحث، اجتماع، فعالية)',
  `issuerUserId` BIGINT COMMENT 'معرف من قام بالإعارة (FK → SystemUser.userId)',
  `conditionAtLoan` VARCHAR(200) COMMENT 'حالة الأصل عند الإعارة',
  `conditionAtReturn` VARCHAR(200) COMMENT 'حالة الأصل عند الإرجاع',
  `isOverdue` BOOLEAN COMMENT 'هل تأخر المستعير في الإرجاع؟ (يُحسب آلياً)',
  `overdueDays` VARCHAR(200) COMMENT 'عدد أيام التأخير (يُحسب)',
  `fineAmount` DECIMAL(15,2) COMMENT 'قيمة الغرامة (إن وجدت)',
  `finePaid` BIGINT COMMENT 'هل دفعت الغرامة؟',
  `finePaidDate` DATE COMMENT 'تاريخ دفع الغرامة',
  `loanStatus` VARCHAR(50) COMMENT 'حالة الإعارة (نشطة، مسترجعة، متأخرة، مفقودة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`loanId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`borrowerId`) REFERENCES `Borrower`(`...`),
  -- FOREIGN KEY (`issuerUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`finePaid`) REFERENCES `FinePa`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إعارات الأصول';

-- Table: AssetTransferRequests (طلبات النقل والتحويل)
CREATE TABLE IF NOT EXISTS `AssetTransferRequests` (
  `transferRequestId` BIGINT NOT NULL COMMENT 'معرف طلب النقل (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `requestNumber` INT COMMENT 'رقم الطلب (يُولد آلياً)',
  `fromEntityType` VARCHAR(50) COMMENT 'نوع الجهة/القسم المسؤول حالياً (قسم، موقع، مدرسة)',
  `fromEntityId` BIGINT COMMENT 'معرف الجهة الحالية',
  `toEntityType` VARCHAR(50) COMMENT 'نوع الجهة/القسم المسؤول الجديد',
  `toEntityId` BIGINT COMMENT 'معرف الجهة الجديدة',
  `transferType` VARCHAR(50) COMMENT 'نوع النقل (نقل مكاني، تحويل إداري، نقل بين المدارس)',
  `requestReason` VARCHAR(200) COMMENT 'سبب النقل',
  `requestedByUserId` BIGINT COMMENT 'معرف مقدم الطلب (FK → SystemUser.userId)',
  `requestDate` DATE COMMENT 'تاريخ الطلب',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الموافقة (قيد المراجعة، معتمد، مرفوض، ملغي)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvalNotes` TEXT COMMENT 'ملاحظات الاعتماد',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `transferExecutionDate` DATE COMMENT 'تاريخ تنفيذ النقل الفعلي',
  `executedByUserId` BIGINT COMMENT 'معرف من نفذ النقل (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `status` VARCHAR(50) COMMENT 'حالة الطلب (مفتوح، معتمد، منفذ، ملغي)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`transferRequestId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`fromEntityId`) REFERENCES `FromEntity`(`...`),
  -- FOREIGN KEY (`toEntityId`) REFERENCES `ToEntity`(`...`),
  -- FOREIGN KEY (`requestedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`executedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='طلبات النقل والتحويل';

-- Table: AssetInspectionLog (فحص الاستلام والإرجاع)
CREATE TABLE IF NOT EXISTS `AssetInspectionLog` (
  `inspectionId` BIGINT NOT NULL COMMENT 'معرف الفحص (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `relatedTransactionType` VARCHAR(50) COMMENT 'نوع العملية المرتبطة (استلام من مورد، إرجاع من موظف، إرجاع من طالب، نقل داخلي)',
  `relatedTransactionId` BIGINT COMMENT 'معرف العملية المرتبطة (مثل assignmentId, loanId, receivingId, transferRequestId)',
  `inspectionType` VARCHAR(50) COMMENT 'نوع الفحص (عند الاستلام، عند الإرجاع، فحص دوري)',
  `inspectionDate` DATE COMMENT 'تاريخ الفحص',
  `inspectorUserId` BIGINT COMMENT 'معرف المفتش (FK → SystemUser.userId)',
  `physicalCondition` VARCHAR(200) COMMENT 'الحالة الفيزيائية (سليم، به أضرار بسيطة، تالف جزئياً، تالف كلياً، مفقود)',
  `damageDetails` VARCHAR(200) COMMENT 'وصف دقيق للأضرار إن وجدت',
  `damagePhotos` VARCHAR(200) COMMENT 'مسارات صور الأضرار (JSON)',
  `functionalStatus` VARCHAR(50) COMMENT 'الحالة الوظيفية (يعمل بكفاءة، يعمل بخلل، لا يعمل)',
  `missingParts` VARCHAR(200) COMMENT 'قطع غيار مفقودة (JSON)',
  `inspectionResult` VARCHAR(200) COMMENT 'نتيجة الفحص (مقبول، مرفوض، يحتاج صيانة، يحتاج استبدال)',
  `recommendedAction` VARCHAR(200) COMMENT 'الإجراء الموصى به (صيانة، استبدال، خصم قيمة، إحالة للتحقيق)',
  `estimatedRepairCost` DECIMAL(15,2) COMMENT 'تكلفة الإصلاح التقديرية (إن وجدت)',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`inspectionId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`relatedTransactionId`) REFERENCES `RelatedTransaction`(`...`),
  -- FOREIGN KEY (`inspectorUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='فحص الاستلام والإرجاع';

-- Table: AssetMovementHistory (سجل حركة الأصول التاريخي)
CREATE TABLE IF NOT EXISTS `AssetMovementHistory` (
  `historyId` BIGINT NOT NULL COMMENT 'معرف السجل التاريخي (المفتاح الرئيسي)',
  `assetId` BIGINT COMMENT 'معرف الأصل (FK → Asset.assetId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `actionType` VARCHAR(50) COMMENT 'نوع الحدث (نقل، تخصيص، إعارة، إرجاع، صيانة، تغيير حالة، تغيير موقع، شراء، استلام)',
  `actionDescription` TEXT COMMENT 'وصف الإجراء المتخذ',
  `oldValue` VARCHAR(200) COMMENT 'القيمة القديمة قبل التغيير (مثلاً الموقع القديم، الحالة القديمة، المسؤول القديم)',
  `newValue` VARCHAR(200) COMMENT 'القيمة الجديدة بعد التغيير',
  `relatedEntityType` VARCHAR(50) COMMENT 'نوع الكيان المرتبط بالحدث (AssetAssignment, AssetLoans, MaintenanceTicket, AssetTransferRequest)',
  `relatedEntityId` BIGINT COMMENT 'معرف الكيان المرتبط',
  `actionDate` DATE COMMENT 'تاريخ ووقت الحركة الفعلي',
  `performedByUserId` BIGINT COMMENT 'معرف من قام بالحركة (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء (نفس actionDate غالباً)',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`historyId`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`relatedEntityId`) REFERENCES `RelatedEntity`(`...`),
  -- FOREIGN KEY (`performedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='سجل حركة الأصول التاريخي';

-- Table: LoanTrackingAlerts (تنبيهات ومتابعة الإعارات)
CREATE TABLE IF NOT EXISTS `LoanTrackingAlerts` (
  `alertId` BIGINT NOT NULL COMMENT 'معرف التنبيه (المفتاح الرئيسي)',
  `loanId` BIGINT COMMENT 'معرف الإعارة المرتبطة (FK → AssetLoans.loanId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `alertType` VARCHAR(50) COMMENT 'نوع التنبيه (تذكير قبل الانتهاء، إشعار تأخير، تنبيه غرامة)',
  `alertDate` DATE COMMENT 'تاريخ إرسال التنبيه',
  `alertMessage` VARCHAR(200) COMMENT 'نص التنبيه المرسل',
  `deliveryMethod` VARCHAR(200) COMMENT 'طريقة الإرسال (بريد إلكتروني، رسالة نصية، إشعار تطبيق)',
  `isSent` BOOLEAN COMMENT 'هل تم إرسال التنبيه بنجاح؟',
  `sentTo` VARCHAR(200) COMMENT 'المستلم (عنوان البريد أو رقم الهاتف)',
  `isAcknowledged` BOOLEAN COMMENT 'هل استلمت الجهة المستعيرة التنبيه واطّلعت عليه؟',
  `acknowledgedAt` DATE COMMENT 'تاريخ الاطلاع',
  `violationRecorded` VARCHAR(200) COMMENT 'هل تم تسجيل مخالفة تأخير بسبب عدم الاستجابة؟',
  `violationId` BIGINT COMMENT 'معرف المخالفة المسجلة (FK → UsageViolations.violationId) - اختياري',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل (النظام غالباً)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`alertId`),
  -- FOREIGN KEY (`loanId`) REFERENCES `AssetLoans`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`violationId`) REFERENCES `UsageViolations`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`)
) COMMENT='تنبيهات ومتابعة الإعارات';

-- Table: InventoryPlans (خطط الجرد)
CREATE TABLE IF NOT EXISTS `InventoryPlans` (
  `planId` BIGINT NOT NULL COMMENT 'معرف خطة الجرد (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `planNumber` INT COMMENT 'رقم الخطة (يُولد آلياً)',
  `planName` VARCHAR(200) COMMENT 'مسمى الجرد (مثال: "الجرد السنوي 2025")',
  `inventoryType` VARCHAR(50) COMMENT 'نوع الجرد (دوري، مفاجئ، عند إخلاء طرف، جزئي)',
  `scopeType` VARCHAR(50) COMMENT 'نطاق الجرد (مدرسة كاملة، قسم معين، فئة محددة، موقع محدد)',
  `scopeValue` VARCHAR(200) COMMENT 'قيمة النطاق (مثلاً معرف القسم، معرف الفئة، معرف الموقع) - حسب scopeType',
  `startDate` DATE COMMENT 'تاريخ بداية أعمال الجرد الميداني',
  `endDate` DATE COMMENT 'التاريخ المستهدف لإنهاء الجرد',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `assignedTeamLeaderId` BIGINT COMMENT 'معرف قائد فريق الجرد (FK → Employee.employeeId)',
  `assignedTeamMembers` VARCHAR(200) COMMENT 'أعضاء فريق الجرد (JSON) - قائمة بـ Employee.employeeId',
  `instructions` VARCHAR(200) COMMENT 'تعليمات للفريق',
  `status` VARCHAR(50) COMMENT 'حالة الخطة (مسودة، نشطة، مكتملة، ملغاة، قيد المراجعة)',
  `completionPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز (يُحسب آلياً)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`planId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assignedTeamLeaderId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='خطط الجرد';

-- Table: FieldInventoryLog (الجرد الميداني)
CREATE TABLE IF NOT EXISTS `FieldInventoryLog` (
  `logId` BIGINT NOT NULL COMMENT 'معرف سجل الجرد (المفتاح الرئيسي)',
  `planId` BIGINT COMMENT 'معرف خطة الجرد المرتبطة (FK → InventoryPlans.planId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `scannerUserId` BIGINT COMMENT 'معرف من قام بالمسح (FK → SystemUser.userId)',
  `scanTimestamp` DATE COMMENT 'وقت وتاريخ المسح بدقة',
  `scannedCode` VARCHAR(50) COMMENT 'كود الباركود/QR الذي تم قراءته (عادة assetUniqueCode أو assetTag)',
  `assetId` BIGINT COMMENT 'معرف الأصل الناتج عن المسح (يتم البحث عنه آلياً باستخدام scannedCode)',
  `physicalLocation` VARCHAR(200) COMMENT 'الموقع الفعلي الذي تم العثور فيه على الأصل (نص أو FK → AssetLocation.locationId)',
  `actualCondition` VARCHAR(200) COMMENT 'الحالة الفعلية للأصل عند الجرد (سليم، تالف، يحتاج صيانة، غير قابل للتشغيل)',
  `conditionNotes` TEXT COMMENT 'ملاحظات عن الحالة',
  `found` VARCHAR(200) COMMENT 'هل تم العثور على الأصل؟ (نعم/لا)',
  `foundNotes` TEXT COMMENT 'ملاحظات إذا لم يتم العثور عليه (مكان محتمل، آخر شخص معروف لديه الأصل)',
  `assetPhoto` VARCHAR(200) COMMENT 'صورة للأصل (مسار ملف) - اختياري',
  `gpsLocation` VARCHAR(200) COMMENT 'إحداثيات GPS لموقع المسح (للتأكد من أن المسح تم في الموقع الصحيح)',
  `isVerified` BOOLEAN COMMENT 'هل تم التحقق من صحة المسح؟',
  `verifiedByUserId` BIGINT COMMENT 'معرف من تحقق (FK → SystemUser.userId)',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`logId`),
  -- FOREIGN KEY (`planId`) REFERENCES `InventoryPlans`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`scannerUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`physicalLocation`) REFERENCES `AssetLocation`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='الجرد الميداني';

-- Table: InventoryReconciliation (مطابقة وفروقات الجرد)
CREATE TABLE IF NOT EXISTS `InventoryReconciliation` (
  `reconciliationId` BIGINT NOT NULL COMMENT 'معرف المطابقة (المفتاح الرئيسي)',
  `planId` BIGINT COMMENT 'معرف خطة الجرد (FK → InventoryPlans.planId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `assetId` BIGINT COMMENT 'معرف الأصل (من جدول Asset)',
  `discrepancyType` VARCHAR(50) COMMENT 'نوع الفرق (مطابق، نقص/مفقود، زيادة/غير مسجل، تالف، اختلاف موقع، اختلاف حالة)',
  `systemLocationId` BIGINT COMMENT 'الموقع المسجل في النظام سابقاً (من Asset.assetLocationId)',
  `actualLocationId` BIGINT COMMENT 'الموقع الذي وجد فيه فعلياً (من FieldInventoryLog.physicalLocation)',
  `systemCondition` VARCHAR(200) COMMENT 'الحالة المسجلة في النظام',
  `actualCondition` VARCHAR(200) COMMENT 'الحالة الفعلية (من FieldInventoryLog.actualCondition)',
  `reasonForDiff` VARCHAR(200) COMMENT 'السبب المحتمل للفرق (خطأ إدخال، سرقة، نقل غير موثق، إعارة بدون تسجيل، إهداء، تلف كلي)',
  `investigationNotes` TEXT COMMENT 'ملاحظات التحقيق (إن وجدت)',
  `correctiveAction` VARCHAR(200) COMMENT 'الإجراء التصحيحي المقترح (تحديث السجلات، بحث إداري، إبلاغ الجهات الأمنية، شطب الأصل)',
  `isResolved` BOOLEAN COMMENT 'هل تم حل الفرق وتحديث السجلات؟',
  `resolutionDate` DATE COMMENT 'تاريخ الحل',
  `resolvedByUserId` BIGINT COMMENT 'معرف من قام بحل الفرق (FK → SystemUser.userId)',
  `resolutionNotes` TEXT COMMENT 'ملاحظات الحل',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد نتيجة المطابقة (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `status` VARCHAR(50) COMMENT 'حالة المطابقة (مفتوح، قيد التحقيق، محلول، معتمد)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reconciliationId`),
  -- FOREIGN KEY (`planId`) REFERENCES `InventoryPlans`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetId`) REFERENCES `Asset`(`...`),
  -- FOREIGN KEY (`systemLocationId`) REFERENCES `SystemLocation`(`...`),
  -- FOREIGN KEY (`actualLocationId`) REFERENCES `ActualLocation`(`...`),
  -- FOREIGN KEY (`resolvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مطابقة وفروقات الجرد';

-- Table: ComplianceAudit (الامتثال والرقابة)
CREATE TABLE IF NOT EXISTS `ComplianceAudit` (
  `auditId` BIGINT NOT NULL COMMENT 'معرف التدقيق (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `auditNumber` INT COMMENT 'رقم التدقيق (يُولد آلياً)',
  `auditDate` DATE COMMENT 'تاريخ عملية الرقابة/التفتيش',
  `auditType` VARCHAR(50) COMMENT 'نوع التدقيق (داخلي، خارجي، مفاجئ، دوري)',
  `standardType` VARCHAR(50) COMMENT 'المعيار المطبق (ISO 55000، لائحة وزارة التربية، سياسة داخلية، معايير محاسبية)',
  `standardVersion` VARCHAR(200) COMMENT 'إصدار المعيار',
  `auditedByUserId` BIGINT COMMENT 'معرف المدقق (FK → SystemUser.userId)',
  `auditScope` VARCHAR(200) COMMENT 'نطاق التدقيق (جميع الأصول، أصول قسم معين، أصول فئة معينة)',
  `complianceScore` DECIMAL(5,2) COMMENT 'نسبة الامتثال المحققة (من 100)',
  `violationsFound` VARCHAR(200) COMMENT 'المخالفات أو نقاط عدم المطابقة المكتشفة (نص أو JSON)',
  `violationsDetails` VARCHAR(200) COMMENT 'تفاصيل المخالفات (JSON)',
  `correctiveActionsRequired` VARCHAR(200) COMMENT 'الإجراءات التصحيحية المطلوبة (نص)',
  `correctiveActionsDeadline` VARCHAR(200) COMMENT 'الموعد النهائي لتنفيذ الإجراءات التصحيحية',
  `correctiveActionsStatus` VARCHAR(50) COMMENT 'حالة الإجراءات التصحيحية (قيد التنفيذ، منجزة، متأخرة)',
  `followUpAuditDate` DATE COMMENT 'تاريخ التدقيق المتابع (إن وجد)',
  `auditReportPath` VARCHAR(200) COMMENT 'مسار ملف تقرير التدقيق (PDF)',
  `status` VARCHAR(50) COMMENT 'حالة التدقيق (مخطط، قيد التنفيذ، مكتمل، ملغي)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد تقرير التدقيق (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`auditId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`auditedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الامتثال والرقابة';

-- Table: FinalApprovalAudit (اعتماد نتائج الرقابة)
CREATE TABLE IF NOT EXISTS `FinalApprovalAudit` (
  `finalApprovalId` BIGINT NOT NULL COMMENT 'معرف الاعتماد النهائي (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `planId` BIGINT COMMENT 'معرف خطة الجرد المرتبطة (FK → InventoryPlans.planId) - اختياري (قد يكون مرتبطاً بتدقيق وليس جرد)',
  `auditId` BIGINT COMMENT 'معرف التدقيق المرتبط (FK → ComplianceAudit.auditId) - اختياري',
  `approvalType` VARCHAR(50) COMMENT 'نوع الاعتماد (جرد سنوي، تدقيق داخلي، تدقيق خارجي، شطب أصول)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد الرسمي من الإدارة العليا',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDocPath` VARCHAR(200) COMMENT 'مسار ملف "محضر الجرد المعتمد" أو "تقرير التدقيق المعتمد"',
  `summaryOfChanges` VARCHAR(200) COMMENT 'ملخص التغييرات التي تم إجراؤها على النظام بناءً على هذا الاعتماد (مثال: تم شطب 5 أصول، تم تعديل مواقع 12 أصلاً، تم تحديث حالة 3 أصول إلى "تالف")',
  `finalStatusUpdate` DATE COMMENT 'تأكيد تحديث كافة حالات الأصول في النظام (نعم/لا)',
  `statusUpdateDate` DATE COMMENT 'تاريخ تحديث النظام',
  `statusUpdatedByUserId` BIGINT COMMENT 'معرف من قام بتحديث النظام (FK → SystemUser.userId)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`finalApprovalId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`planId`) REFERENCES `InventoryPlans`(`...`),
  -- FOREIGN KEY (`auditId`) REFERENCES `ComplianceAudit`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`statusUpdatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='اعتماد نتائج الرقابة';

-- Table: FacilityDepartmentAssignment (تخصيص المرافق التعليمية)
CREATE TABLE IF NOT EXISTS `FacilityDepartmentAssignment` (
  `assignmentId` BIGINT NOT NULL COMMENT 'معرف التخصيص (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `facilityType` VARCHAR(50) COMMENT 'نوع المرفق (قاعة، معمل، مكتبة، صالة رياضية، مخزن، مكتب)',
  `facilityId` BIGINT COMMENT 'معرف المرفق (FK → Classroom.classroomId أو Asset.assetId)',
  `departmentId` BIGINT COMMENT 'معرف القسم المستفيد (FK → SchoolDepartment.deptId)',
  `responsibleUserId` BIGINT COMMENT 'رئيس القسم أو أمين المختبر المسؤول (FK → Employee.employeeId)',
  `assignmentType` VARCHAR(50) COMMENT 'نوع التخصيص (كلي، جزئي، مؤقت، دائم)',
  `startDate` DATE COMMENT 'تاريخ التخصيص للقسم',
  `endDate` DATE COMMENT 'تاريخ انتهاء التخصيص (إن كان مؤقتاً)',
  `isShared` BOOLEAN COMMENT 'هل المرفق مشترك بين عدة أقسام؟',
  `sharedWithDepartments` VARCHAR(200) COMMENT 'الأقسام المشاركة (JSON) - قائمة بـ DepartmentId',
  `sharingSchedule` VARCHAR(200) COMMENT 'جدول الاستخدام (JSON) - لتحديد أوقات استخدام كل قسم',
  `priority` VARCHAR(200) COMMENT 'أولوية القسم في استخدام المرفق',
  `notes` TEXT COMMENT 'ملاحظات',
  `status` VARCHAR(50) COMMENT 'حالة التخصيص (نشط، منتهي، ملغي)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`assignmentId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`facilityId`) REFERENCES `Classroom`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`responsibleUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تخصيص المرافق التعليمية';

-- Table: EducationalConsumablesTracking (استهلاك المواد التعليمية)
CREATE TABLE IF NOT EXISTS `EducationalConsumablesTracking` (
  `consumptionId` BIGINT NOT NULL COMMENT 'معرف سجل الاستهلاك (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `consumableId` BIGINT COMMENT 'معرف المادة الاستهلاكية (من جدول منفصل أو من Asset للمواد التي تدخل ضمن الأصول)',
  `consumableName` VARCHAR(200) COMMENT 'اسم المادة المستهلكة (حبر، أوراق، مواد كيميائية، أدوات، الخ)',
  `consumableCode` VARCHAR(50) COMMENT 'كود المادة (SKU)',
  `category` VARCHAR(50) COMMENT 'فئة المادة (حبر، ورق، كيميائيات، لوازم فنية، لوازم معمل)',
  `quantityConsumed` VARCHAR(200) COMMENT 'الكمية المستهلكة',
  `unitOfMeasure` VARCHAR(200) COMMENT 'وحدة القياس (لتر، قطعة، رزمة، كجم)',
  `consumptionDate` DATE COMMENT 'تاريخ الاستهلاك',
  `consumedByUserId` BIGINT COMMENT 'معرف من صرف المادة (FK → SystemUser.userId)',
  `departmentId` BIGINT COMMENT 'معرف القسم المستهلك (FK → SchoolDepartment.deptId)',
  `courseId` BIGINT COMMENT 'معرف المادة الدراسية المرتبطة بالاستهلاك (FK → Course.courseId) - اختياري',
  `activityId` BIGINT COMMENT 'معرف النشاط الطلابي المرتبط بالاستهلاك (FK → SchoolActivity.activityId) - اختياري',
  `purpose` VARCHAR(200) COMMENT 'الغرض من الاستهلاك (تجربة معملية، نشاط فني، اختبار، طباعة، الخ)',
  `notes` TEXT COMMENT 'ملاحظات',
  `unitCost` DECIMAL(15,2) COMMENT 'تكلفة الوحدة في وقت الاستهلاك (لحساب التكلفة الإجمالية)',
  `totalCost` DECIMAL(15,2) COMMENT 'التكلفة الإجمالية (quantityConsumed × unitCost)',
  `budgetLineCode` VARCHAR(50) COMMENT 'كود بند الميزانية الذي سيتم تحميل الاستهلاك عليه',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`consumptionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`consumableId`) REFERENCES `Consumable`(`...`),
  -- FOREIGN KEY (`consumedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`courseId`) REFERENCES `Course`(`...`),
  -- FOREIGN KEY (`activityId`) REFERENCES `SchoolActivity`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='استهلاك المواد التعليمية';


-- ============================
-- Module: M5_Finance
-- ============================

-- Table: StudentAccount (الحساب المالي)
CREATE TABLE IF NOT EXISTS `StudentAccount` (
  `accountId` BIGINT NOT NULL COMMENT 'معرف الحساب (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId) - علاقة 1-1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - للحسابات السنوية',
  `accountNumber` INT COMMENT 'رقم الحساب (فريد، يولد آلياً)',
  `totalDebit` VARCHAR(200) COMMENT 'إجمالي الرسوم المستحقة على الطالب (مدين)',
  `totalCredit` VARCHAR(200) COMMENT 'إجمالي المدفوعات التي دفعها الطالب (دائن)',
  `currentBalance` DECIMAL(15,2) COMMENT 'الرصيد الحالي (totalDebit - totalCredit)',
  `balanceType` DECIMAL(15,2) COMMENT 'نوع الرصيد (مدين، دائن، صفر)',
  `lastTransactionDate` DATE COMMENT 'تاريخ آخر معاملة (فاتورة أو دفع)',
  `lastPaymentDate` DATE COMMENT 'تاريخ آخر دفعة',
  `lastPaymentAmount` DECIMAL(15,2) COMMENT 'قيمة آخر دفعة',
  `accountStatus` INT COMMENT 'حالة الحساب (نشط، مجمد، مغلق، منتهي)',
  `isExempt` BOOLEAN COMMENT 'هل الطالب معفى من الرسوم كلياً؟',
  `exemptionPercentage` DECIMAL(5,2) COMMENT 'نسبة الإعفاء (إن كان جزئياً)',
  `exemptionReason` VARCHAR(200) COMMENT 'سبب الإعفاء (منحة، خصم أخوة، خصم أبناء موظفين، كفالة)',
  `exemptionApprovedByUserId` BIGINT COMMENT 'معرف من اعتمد الإعفاء (FK → SystemUser.userId)',
  `exemptionApprovalDate` DATE COMMENT 'تاريخ اعتماد الإعفاء',
  `exemptionDocument` VARCHAR(200) COMMENT 'مستند الإعفاء (مسار ملف)',
  `minimumPaymentRequired` VARCHAR(200) COMMENT 'الحد الأدنى المطلوب دفعه قبل التسجيل (نسبة أو مبلغ)',
  `isBlockedFromRegistration` BOOLEAN COMMENT 'هل تم منع الطالب من التسجيل بسبب المستحقات؟',
  `blockReason` VARCHAR(200) COMMENT 'سبب المنع',
  `unblockDate` DATE COMMENT 'تاريخ رفع المنع',
  `paymentPlan` VARCHAR(200) COMMENT 'خطة الدفع المتفق عليها (نص)',
  `notes` TEXT COMMENT 'ملاحظات عامة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`accountId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`exemptionApprovedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الحساب المالي';

-- Table: StudentInvoice (الفواتير)
CREATE TABLE IF NOT EXISTS `StudentInvoice` (
  `invoiceId` BIGINT NOT NULL COMMENT 'معرف الفاتورة (المفتاح الرئيسي)',
  `accountId` BIGINT COMMENT 'معرف الحساب المالي للطالب (FK → StudentAccount.accountId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId) - للتكرار',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `invoiceNumber` INT COMMENT 'رقم الفاتورة (فريد، يولد آلياً)',
  `invoiceDate` DATE COMMENT 'تاريخ إصدار الفاتورة',
  `dueDate` DATE COMMENT 'تاريخ الاستحقاق (آخر موعد للدفع)',
  `issueDate` DATE COMMENT 'تاريخ الإصدار (مرادف لـ invoiceDate)',
  `totalAmount` DECIMAL(15,2) COMMENT 'المبلغ الإجمالي للفاتورة (قبل الخصم والضريبة)',
  `discountAmount` DECIMAL(15,2) COMMENT 'قيمة الخصم الإجمالي (من مبلغ الفاتورة)',
  `discountReason` INT COMMENT 'سبب الخصم (إن وجد)',
  `taxAmount` DECIMAL(15,2) COMMENT 'قيمة الضريبة (مثل VAT 15%)',
  `taxRate` DECIMAL(5,2) COMMENT 'نسبة الضريبة (افتراضي 15%)',
  `taxRegistrationNumber` INT COMMENT 'الرقم الضريبي للمدرسة',
  `netAmount` DECIMAL(15,2) COMMENT 'المبلغ الصافي بعد الخصم وإضافة الضريبة (totalAmount - discountAmount + taxAmount)',
  `paidAmount` DECIMAL(15,2) COMMENT 'المبلغ المدفوع من الفاتورة',
  `remainingAmount` DECIMAL(15,2) COMMENT 'المبلغ المتبقي (netAmount - paidAmount)',
  `invoiceType` VARCHAR(50) COMMENT 'نوع الفاتورة (رسوم دراسة، رسوم نشاط، رسوم كتب، رسوم مواصلات، رسوم زي مدرسي، أخرى)',
  `invoiceCategory` VARCHAR(50) COMMENT 'فئة الفاتورة (إجبارية، اختيارية)',
  `paymentStatus` VARCHAR(50) COMMENT 'حالة الدفع (غير مدفوعة، مدفوعة جزئياً، مدفوعة كاملة، ملغاة)',
  `invoiceStatus` VARCHAR(50) COMMENT 'حالة الفاتورة (مفتوحة، مقفلة، ملغاة، منتهية)',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع المفضلة (تحويل بنكي، كاش، بطاقة ائتمان، شيك)',
  `isLate` BOOLEAN COMMENT 'هل الفاتورة متأخرة (تم تجاوز dueDate دون سداد كامل)؟',
  `lateDays` VARCHAR(200) COMMENT 'عدد أيام التأخير (تحسب تلقائياً)',
  `lateFeePercentage` DECIMAL(15,2) COMMENT 'نسبة رسوم التأخير (إذا لم تكن مضمنة في الفاتورة)',
  `lateFeeAmount` DECIMAL(15,2) COMMENT 'قيمة رسوم التأخير المحسوبة',
  `installmentPlan` VARCHAR(200) COMMENT 'خطة التقسيط (نعم/لا)',
  `installmentCount` INT COMMENT 'عدد الأقساط (إن وجد)',
  `currentInstallment` VARCHAR(200) COMMENT 'القسط الحالي المستحق',
  `parentApprovalRequired` VARCHAR(200) COMMENT 'هل تتطلب موافقة ولي الأمر؟',
  `parentApprovalStatus` VARCHAR(50) COMMENT 'حالة موافقة ولي الأمر (قيد الانتظار، موافق، مرفوض)',
  `parentApprovalDate` DATE COMMENT 'تاريخ الموافقة',
  `sentToParent` VARCHAR(200) COMMENT 'هل تم إرسال الفاتورة لولي الأمر؟',
  `parentNotifiedAt` DATE COMMENT 'تاريخ الإرسال',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`invoiceId`),
  -- FOREIGN KEY (`accountId`) REFERENCES `StudentAccount`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الفواتير';

-- Table: InvoiceItem (بنود الفاتورة)
CREATE TABLE IF NOT EXISTS `InvoiceItem` (
  `itemId` BIGINT NOT NULL COMMENT 'معرف البند (المفتاح الرئيسي)',
  `invoiceId` BIGINT COMMENT 'معرف الفاتورة (FK → StudentInvoice.invoiceId)',
  `feeTypeId` BIGINT COMMENT 'معرف نوع الرسم (FK → FeeType.feeTypeId)',
  `itemCode` VARCHAR(50) COMMENT 'كود البند (من FeeType أو مخصص)',
  `itemDescription` TEXT COMMENT 'وصف بند الفاتورة (مثال: "رسوم الفصل الدراسي الأول - الصف الخامس")',
  `quantity` VARCHAR(200) COMMENT 'الكمية (مثل عدد الأشهر، عدد الكتب، عدد الحصص)',
  `unitPrice` DECIMAL(15,2) COMMENT 'سعر الوحدة (مثل سعر الكتاب، سعر الشهر الدراسي)',
  `totalPrice` DECIMAL(15,2) COMMENT 'السعر الإجمالي (الكمية × سعر الوحدة) - يُحسب آلياً',
  `discountPercentage` INT COMMENT 'نسبة الخصم على هذا البند (إن وجد)',
  `discountAmount` DECIMAL(15,2) COMMENT 'مبلغ الخصم على هذا البند (يحسب = totalPrice × discountPercentage/100)',
  `priceAfterDiscount` DECIMAL(15,2) COMMENT 'السعر بعد الخصم (totalPrice - discountAmount)',
  `taxPercentage` DECIMAL(5,2) COMMENT 'نسبة الضريبة على هذا البند (قد تختلف عن الفاتورة الأم)',
  `taxAmount` DECIMAL(15,2) COMMENT 'مبلغ الضريبة على هذا البند',
  `netAmount` DECIMAL(15,2) COMMENT 'المبلغ الصافي للبند (السعر بعد الخصم + الضريبة)',
  `dueDate` DATE COMMENT 'تاريخ الاستحقاق لهذا البند (إذا اختلف عن تاريخ الفاتورة)',
  `isPaid` BIGINT COMMENT 'هل البند مدفوع بالكامل؟',
  `paidAmount` DECIMAL(15,2) COMMENT 'المبلغ المدفوع لهذا البند (جزئياً أو كلياً)',
  `remainingAmount` DECIMAL(15,2) COMMENT 'المبلغ المتبقي على هذا البند',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع لهذا البند (إذا اختلفت)',
  `isLate` BOOLEAN COMMENT 'هل البند متأخر عن السداد؟',
  `lateFeeApplied` DECIMAL(15,2) COMMENT 'هل طُبّقت رسوم تأخير على هذا البند؟',
  `lateFeeAmount` DECIMAL(15,2) COMMENT 'مبلغ رسوم التأخير على هذا البند',
  `installmentNumber` INT COMMENT 'رقم القسط (إذا كان هذا البند يمثل قسطاً ضمن خطة تقسيط)',
  `installmentTotal` VARCHAR(200) COMMENT 'إجمالي عدد الأقساط لهذه الفاتورة/البند',
  `isWaived` BOOLEAN COMMENT 'هل البند معفى؟',
  `waiverReason` VARCHAR(200) COMMENT 'سبب الإعفاء',
  `waiverDate` DATE COMMENT 'تاريخ الإعفاء',
  `status` VARCHAR(50) COMMENT 'حالة البند (نشط، مدفوع، ملغي، معفى)',
  `notes` TEXT COMMENT 'ملاحظات حول البند',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`itemId`),
  -- FOREIGN KEY (`invoiceId`) REFERENCES `StudentInvoice`(`...`),
  -- FOREIGN KEY (`feeTypeId`) REFERENCES `FeeType`(`...`),
  -- FOREIGN KEY (`isPaid`) REFERENCES `IsPa`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='بنود الفاتورة';

-- Table: Payment (المدفوعات)
CREATE TABLE IF NOT EXISTS `Payment` (
  `paymentId` BIGINT NOT NULL COMMENT 'معرف الدفعة (المفتاح الرئيسي)',
  `accountId` BIGINT COMMENT 'معرف الحساب المالي (FK → StudentAccount.accountId)',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId) - للتكرار',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - اختياري',
  `paymentNumber` INT COMMENT 'رقم سند الدفع (فريد، يولد آلياً)',
  `paymentDate` DATE COMMENT 'تاريخ الدفع',
  `paymentTime` TIME COMMENT 'وقت الدفع (للدفعات الإلكترونية)',
  `amount` DECIMAL(15,2) COMMENT 'المبلغ المدفوع',
  `currency` VARCHAR(200) COMMENT 'العملة (SAR, USD)',
  `exchangeRate` DECIMAL(5,2) COMMENT 'سعر الصرف (إن كانت العملة مختلفة عن العملة الأساسية)',
  `convertedAmount` DECIMAL(15,2) COMMENT 'المبلغ بعد التحويل للعملة الأساسية',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع (تحويل بنكي، كاش، بطاقة ائتمان، شيك، محفظة إلكترونية)',
  `paymentType` VARCHAR(50) COMMENT 'نوع الدفع (رسوم دراسية، قسط، غرامة تأخير، تبرع، أخرى)',
  `bankName` VARCHAR(200) COMMENT 'اسم البنك (للتحويلات البنكية)',
  `bankTransactionId` BIGINT COMMENT 'رقم المعاملة البنكية (Reference)',
  `checkNumber` INT COMMENT 'رقم الشيك (إن وجد)',
  `checkBank` VARCHAR(200) COMMENT 'بنك الشيك',
  `checkDate` DATE COMMENT 'تاريخ الشيك',
  `creditCardLast4` VARCHAR(200) COMMENT 'آخر 4 أرقام من البطاقة الائتمانية',
  `creditCardType` VARCHAR(50) COMMENT 'نوع البطاقة (فيزا، ماستركارد)',
  `walletType` VARCHAR(50) COMMENT 'نوع المحفظة الإلكترونية (STC Pay، Apple Pay، Google Pay)',
  `payerName` VARCHAR(200) COMMENT 'اسم الدافع (ولي الأمر أو الطالب)',
  `payerType` VARCHAR(50) COMMENT 'نوع الدافع (ولي أمر، طالب، جهة خارجية)',
  `payerEmail` VARCHAR(100) COMMENT 'بريد الدافع الإلكتروني (للإيصال)',
  `receiptNumber` INT COMMENT 'رقم الإيصال (فريد، يولد آلياً)',
  `receiptPrinted` VARCHAR(200) COMMENT 'هل تم طباعة الإيصال؟',
  `receiptSentToEmail` VARCHAR(100) COMMENT 'هل تم إرسال الإيصال عبر البريد الإلكتروني؟',
  `receiptEmailSentAt` DATE COMMENT 'تاريخ إرسال الإيصال',
  `paymentStatus` VARCHAR(50) COMMENT 'حالة الدفع (معلق، مؤكد، ملغي، فشل)',
  `isConfirmed` BOOLEAN COMMENT 'هل تم تأكيد الدفع (تم وصوله فعلاً للحساب البنكي)؟',
  `confirmationDate` DATE COMMENT 'تاريخ التأكيد',
  `confirmedByUserId` BIGINT COMMENT 'معرف من قام بالتأكيد (FK → SystemUser.userId)',
  `allocatedInvoices` VARCHAR(200) COMMENT 'الفواتير التي تم توزيع الدفع عليها (JSON) - {invoiceId: allocatedAmount}',
  `allocatedItems` VARCHAR(200) COMMENT 'البنود التي تم توزيع الدفع عليها (JSON) - {itemId: allocatedAmount}',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`paymentId`),
  -- FOREIGN KEY (`accountId`) REFERENCES `StudentAccount`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`bankTransactionId`) REFERENCES `BankTransaction`(`...`),
  -- FOREIGN KEY (`confirmedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المدفوعات';

-- Table: FeeType (أنواع الرسوم)
CREATE TABLE IF NOT EXISTS `FeeType` (
  `feeTypeId` BIGINT NOT NULL COMMENT 'معرف نوع الرسم (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `feeCode` DECIMAL(15,2) COMMENT 'رمز الرسم (فريد داخل المدرسة)',
  `feeNameAr` DECIMAL(15,2) COMMENT 'الاسم بالعربية (مثال: "رسوم دراسية")',
  `feeNameEn` DECIMAL(15,2) COMMENT 'الاسم بالإنجليزية (مثال: "Tuition Fee")',
  `feeCategory` DECIMAL(15,2) COMMENT 'فئة الرسم (تعليمية، خدمات، أنشطة، غرامات، أخرى)',
  `amount` DECIMAL(15,2) COMMENT 'المبلغ الافتراضي لهذا الرسم (قبل الخصم)',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `billingFrequency` VARCHAR(200) COMMENT 'تكرار الفوترة (شهري، فصل دراسي، سنوي، لمرة واحدة)',
  `isTaxable` BOOLEAN COMMENT 'هل الرسم خاضع للضريبة؟',
  `taxPercentage` DECIMAL(5,2) COMMENT 'نسبة الضريبة (إذا كان خاضعاً، افتراضي 15%)',
  `isMandatory` BOOLEAN COMMENT 'هل الرسم إجباري لجميع الطلاب؟',
  `isOptional` BOOLEAN COMMENT 'هل الرسم اختياري (يمكن إضافته بناءً على طلب الطالب)؟',
  `isDiscountable` BOOLEAN COMMENT 'هل يقبل خصماً؟',
  `discountPercentageAllowed` INT COMMENT 'الحد الأقصى لنسبة الخصم المسموح بها',
  `isRefundable` BOOLEAN COMMENT 'هل الرسم قابل للاسترداد في حالة الانسحاب؟',
  `refundPercentage` DECIMAL(5,2) COMMENT 'نسبة الاسترداد (إذا كان قابلاً للاسترداد)',
  `refundCutoffDate` DATE COMMENT 'آخر موعد للانسحاب لاستحقاق الاسترداد',
  `isRecurring` BOOLEAN COMMENT 'هل الرسم متكرر (يتم فوترته تلقائياً كل فترة)؟',
  `recurrenceType` VARCHAR(50) COMMENT 'نوع التكرار (شهري، فصل دراسي، سنوي)',
  `appliesToGrades` DECIMAL(5,2) COMMENT 'ينطبق على الصفوف (JSON) - قائمة بـ gradeLevelId',
  `appliesToNationalities` VARCHAR(200) COMMENT 'ينطبق على الجنسيات (JSON) - للرسوم الخاصة بجنسيات معينة',
  `appliesToStudentTypes` VARCHAR(50) COMMENT 'ينطبق على أنواع الطلاب (جدد، قدامى، منتظمون، منقولون)',
  `isActive` BOOLEAN COMMENT 'هل نوع الرسم مفعل؟',
  `validFrom` DATE COMMENT 'تاريخ بدء صلاحية هذا المبلغ',
  `validTo` DATE COMMENT 'تاريخ انتهاء صلاحية هذا المبلغ',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`feeTypeId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='أنواع الرسوم';

-- Table: Installment (الأقساط)
CREATE TABLE IF NOT EXISTS `Installment` (
  `installmentId` BIGINT NOT NULL COMMENT 'معرف القسط (المفتاح الرئيسي)',
  `invoiceId` BIGINT COMMENT 'معرف الفاتورة المرتبطة (FK → StudentInvoice.invoiceId)',
  `itemId` BIGINT COMMENT 'معرف بند الفاتورة المرتبط (FK → InvoiceItem.itemId) - اختياري (إذا كان التقسيط على مستوى بند وليس فاتورة كاملة)',
  `accountId` BIGINT COMMENT 'معرف الحساب المالي (FK → StudentAccount.accountId) - للتكرار',
  `studentId` BIGINT COMMENT 'معرف الطالب (FK → Student.studentId) - للتكرار',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `installmentNumber` INT COMMENT 'رقم القسط (1، 2، 3، ...)',
  `installmentTotal` VARCHAR(200) COMMENT 'إجمالي عدد الأقساط لهذه الفاتورة/البند',
  `installmentAmount` DECIMAL(15,2) COMMENT 'مبلغ هذا القسط',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `dueDate` DATE COMMENT 'تاريخ استحقاق هذا القسط',
  `extendedDueDate` DATE COMMENT 'تاريخ الاستحقاق بعد التمديد (إن وجد)',
  `paidAmount` DECIMAL(15,2) COMMENT 'المبلغ المدفوع لهذا القسط (0 إذا لم يدفع)',
  `remainingAmount` DECIMAL(15,2) COMMENT 'المبلغ المتبقي لهذا القسط (installmentAmount - paidAmount)',
  `paymentDate` DATE COMMENT 'تاريخ دفع القسط (آخر دفعة إن تم الدفع على دفعات)',
  `paymentMethod` VARCHAR(200) COMMENT 'طريقة الدفع المستخدمة لهذا القسط',
  `paymentReference` VARCHAR(200) COMMENT 'رقم مرجع الدفع (رقم السند، رقم العملية البنكية)',
  `installmentType` VARCHAR(50) COMMENT 'نوع القسط (قسط منتظم، قسط أول (مقدم)، قسط أخير، دفعة مقدم)',
  `installmentStatus` VARCHAR(50) COMMENT 'حالة القسط (غير مدفوع، مدفوع كامل، مدفوع جزئياً، متأخر، ملغي، معاد جدولته)',
  `isLate` BOOLEAN COMMENT 'هل القسط متأخر عن السداد؟',
  `lateDays` DATE COMMENT 'عدد أيام التأخير (تحسب تلقائياً من dueDate إلى تاريخ اليوم أو تاريخ الدفع)',
  `lateFeePercentage` DECIMAL(15,2) COMMENT 'نسبة رسوم التأخير المطبقة على هذا القسط (حسب سياسة المدرسة)',
  `lateFeeAmount` DECIMAL(15,2) COMMENT 'قيمة رسوم التأخير المحسوبة لهذا القسط',
  `lateFeePaid` BIGINT COMMENT 'هل تم دفع رسوم التأخير؟',
  `lateFeePaymentDate` DATE COMMENT 'تاريخ دفع رسوم التأخير',
  `lateFeePaymentReference` DECIMAL(15,2) COMMENT 'مرجع دفع رسوم التأخير',
  `isRescheduled` BOOLEAN COMMENT 'هل تمت إعادة جدولة هذا القسط؟',
  `rescheduledDate` DATE COMMENT 'تاريخ إعادة الجدولة',
  `rescheduledByUserId` BIGINT COMMENT 'معرف من قام بإعادة الجدولة (FK → SystemUser.userId)',
  `rescheduledReason` VARCHAR(200) COMMENT 'سبب إعادة الجدولة',
  `newDueDate` DATE COMMENT 'تاريخ الاستحقاق الجديد (بعد إعادة الجدولة)',
  `isWaived` BOOLEAN COMMENT 'هل تم إعفاء هذا القسط من السداد؟',
  `waiverReason` VARCHAR(200) COMMENT 'سبب الإعفاء',
  `waiverDate` DATE COMMENT 'تاريخ الإعفاء',
  `waivedByUserId` BIGINT COMMENT 'معرف من اعتمد الإعفاء (FK → SystemUser.userId)',
  `waiverApprovalDocument` VARCHAR(200) COMMENT 'مستند الإعفاء (مسار ملف)',
  `notes` TEXT COMMENT 'ملاحظات حول هذا القسط (مثل اتفاق خاص، ظروف طارئة)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'تاريخ آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`installmentId`),
  -- FOREIGN KEY (`invoiceId`) REFERENCES `StudentInvoice`(`...`),
  -- FOREIGN KEY (`itemId`) REFERENCES `InvoiceItem`(`...`),
  -- FOREIGN KEY (`accountId`) REFERENCES `StudentAccount`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`lateFeePaid`) REFERENCES `LateFeePa`(`...`),
  -- FOREIGN KEY (`rescheduledByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`waivedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأقساط';

-- Table: AssetWarrantyContract (الضمان والعقود)
CREATE TABLE IF NOT EXISTS `AssetWarrantyContract` (
  `contractValue` VARCHAR(200) NOT NULL COMMENT 'قيمة العقد الإجمالية',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `paymentTerms` VARCHAR(200) COMMENT 'شروط الدفع',
  PRIMARY KEY (`contractValue`)
) COMMENT='الضمان والعقود';

-- Table: FinancialAuditArchive (الأرشفة المالية)
CREATE TABLE IF NOT EXISTS `FinancialAuditArchive` (
  `reportType` VARCHAR(50) NOT NULL COMMENT 'نوع التقرير (تقرير إهلاك، تقرير قيمة دفترية، ميزانية الأصول)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية للتقرير',
  `totalAssetsValue` VARCHAR(200) COMMENT 'إجمالي قيم الأصول في هذا التقرير (لقطة)',
  `totalDepreciationValue` VARCHAR(200) COMMENT 'إجمالي الإهلاك في هذه الفترة',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير المعتمد (PDF/Excel)',
  `isReadOnly` BOOLEAN COMMENT 'دائماً True (لمنع التعديل على البيانات المؤرشفة)',
  PRIMARY KEY (`reportType`)
) COMMENT='الأرشفة المالية';


-- ============================
-- Module: M6_Statistics
-- ============================

-- Table: DashboardConfiguration (إعدادات لوحات المؤشرات)
CREATE TABLE IF NOT EXISTS `DashboardConfiguration` (
  `configId` BIGINT NOT NULL COMMENT 'معرف الإعداد (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للإعدادات العامة للمكتب',
  `kpiType` VARCHAR(50) COMMENT 'نوع المؤشر (نسبة النجاح، نسبة الحضور، كثافة الفصول، نسبة الإشغال، معدل التسرب، نسبة الإنجاز، إلخ)',
  `kpiCode` VARCHAR(50) COMMENT 'كود المؤشر (فريد)',
  `kpiNameAr` VARCHAR(200) COMMENT 'اسم المؤشر بالعربية',
  `kpiNameEn` VARCHAR(200) COMMENT 'اسم المؤشر بالإنجليزية',
  `kpiDescription` TEXT COMMENT 'وصف المؤشر وكيفية حسابه',
  `sourceModule` VARCHAR(200) COMMENT 'المصدر الرئيسي للبيانات (Students, Employees, Assets, Finance)',
  `sourceTable` VARCHAR(200) COMMENT 'الجدول المصدر',
  `sourceField` VARCHAR(200) COMMENT 'الحقل المصدر (أو صيغة الحساب)',
  `aggregationMethod` VARCHAR(200) COMMENT 'طريقة التجميع (متوسط، مجموع، عدد، نسبة، حد أدنى، حد أقصى)',
  `chartType` VARCHAR(50) COMMENT 'طريقة العرض (أعمدة، منحنيات، دائري، جدول، عداد، شريط تقدم)',
  `refreshInterval` VARCHAR(200) COMMENT 'فترة تحديث البيانات (بالدقائق) - افتراضي 60',
  `targetValue` VARCHAR(200) COMMENT 'القيمة المستهدفة (Benchmark)',
  `thresholdGreen` VARCHAR(200) COMMENT 'الحد الأدنى للون الأخضر (آمن)',
  `thresholdYellow` VARCHAR(200) COMMENT 'الحد الأدنى للون الأصفر (تنبيه)',
  `thresholdRed` VARCHAR(200) COMMENT 'الحد الأدنى للون الأحمر (خطر) - أي قيمة أقل تكون حمراء',
  `alertEnabled` VARCHAR(200) COMMENT 'هل يتم إرسال تنبيه عند تجاوز الحدود؟',
  `alertRecipients` VARCHAR(200) COMMENT 'المستلمون عند التنبيه (JSON) - قائمة معرفات المستخدمين',
  `isActive` BOOLEAN COMMENT 'هل المؤشر مفعل؟',
  `displayOrder` VARCHAR(200) COMMENT 'ترتيب عرض المؤشر في لوحة التحكم',
  `dashboardId` BIGINT COMMENT 'معرف لوحة التحكم التي ينتمي إليها (للوحات المتعددة)',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`configId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`dashboardId`) REFERENCES `Dashboard`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='إعدادات لوحات المؤشرات';

-- Table: KPI_Metrics (المؤشرات التشغيلية)
CREATE TABLE IF NOT EXISTS `KPI_Metrics` (
  `metricId` BIGINT NOT NULL COMMENT 'معرف المؤشر (المفتاح الرئيسي)',
  `configId` BIGINT COMMENT 'معرف إعداد المؤشر (FK → DashboardConfiguration.configId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `periodType` VARCHAR(50) COMMENT 'نوع الفترة (يومي، أسبوعي، شهري، ربع سنوي، نصف سنوي، سنوي)',
  `periodValue` VARCHAR(200) COMMENT 'قيمة الفترة (مثال: شهر 1، ربع 2، أسبوع 3)',
  `periodStartDate` DATE COMMENT 'تاريخ بداية الفترة',
  `periodEndDate` DATE COMMENT 'تاريخ نهاية الفترة',
  `actualValue` VARCHAR(200) COMMENT 'القيمة الحالية للمؤشر',
  `targetValue` VARCHAR(200) COMMENT 'القيمة المستهدفة (Benchmark) لهذه الفترة (قد تختلف عن الافتراضية)',
  `previousValue` VARCHAR(200) COMMENT 'القيمة في الفترة السابقة (لحساب نسبة التغير)',
  `changePercentage` DECIMAL(5,2) COMMENT 'نسبة التغير عن الفترة السابقة (يُحسب آلياً)',
  `statusColor` VARCHAR(50) COMMENT 'لون الحالة (أخضر، أصفر، أحمر) - يُحسب بناءً على actualValue مقارنة بـ thresholdGreen, thresholdYellow, thresholdRed من DashboardConfiguration',
  `calculationMethod` VARCHAR(200) COMMENT 'طريقة الحساب (تلقائي، يدوي، مستورد)',
  `calculationDate` DATE COMMENT 'تاريخ حساب/تسجيل القيمة',
  `calculatedByUserId` BIGINT COMMENT 'معرف من قام بالحساب (FK → SystemUser.userId)',
  `dataSource` VARCHAR(200) COMMENT 'مصدر البيانات (مباشر من قاعدة البيانات، ملف Excel، إدخال يدوي)',
  `notes` TEXT COMMENT 'ملاحظات حول القيمة (مثل: انخفاض غير طبيعي بسبب عطلة رسمية)',
  `isVerified` BOOLEAN COMMENT 'هل تم التحقق من صحة القيمة؟',
  `verifiedByUserId` BIGINT COMMENT 'معرف من تحقق (FK → SystemUser.userId)',
  `verifiedAt` VARCHAR(200) COMMENT 'وقت التحقق',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`metricId`),
  -- FOREIGN KEY (`configId`) REFERENCES `DashboardConfiguration`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`calculatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`verifiedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المؤشرات التشغيلية';

-- Table: TrendAnalysisResult (نتائج تحليل الاتجاهات)
CREATE TABLE IF NOT EXISTS `TrendAnalysisResult` (
  `analysisId` BIGINT NOT NULL COMMENT 'معرف التحليل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `studyPeriod` VARCHAR(200) COMMENT 'فترة الدراسة (السنوات الخمس الماضية، السنوات الثلاث الماضية، إلخ)',
  `startYear` VARCHAR(200) COMMENT 'بداية فترة الدراسة',
  `endYear` VARCHAR(200) COMMENT 'نهاية فترة الدراسة',
  `kpiType` VARCHAR(50) COMMENT 'المؤشر المحلل (نمو أعداد الطلاب، نسبة النجاح، نسبة الحضور، كثافة الفصول، إلخ)',
  `kpiCode` VARCHAR(50) COMMENT 'كود المؤشر من DashboardConfiguration (FK → DashboardConfiguration.kpiCode) - اختياري',
  `historicalValues` DATE COMMENT 'القيم التاريخية (JSON) - {year1: value1, year2: value2, ...}',
  `trendDirection` VARCHAR(200) COMMENT 'اتجاه الاتجاه (متزايد، متناقض، ثابت، دوري)',
  `slope` VARCHAR(200) COMMENT 'ميل الخط (معدل التغير السنوي)',
  `intercept` VARCHAR(200) COMMENT 'نقطة التقاطع مع المحور الصادي',
  `correlationCoefficient` VARCHAR(200) COMMENT 'معامل الارتباط (قرب 1 يعني دقة عالية)',
  `forecastedValue` VARCHAR(200) COMMENT 'القيمة التنبؤية للفترة القادمة (السنة القادمة)',
  `forecastedValueNext` VARCHAR(200) COMMENT 'القيمة التنبؤية للفترة التي تليها (سنتين قادمة) - اختياري',
  `confidenceLevel` VARCHAR(50) COMMENT 'نسبة الثقة في التوقع (مثل 95%)',
  `lowerBound` VARCHAR(200) COMMENT 'الحد الأدنى للتوقع (عند نسبة الثقة المحددة)',
  `upperBound` VARCHAR(200) COMMENT 'الحد الأعلى للتوقع (عند نسبة الثقة المحددة)',
  `forecastingMethod` VARCHAR(200) COMMENT 'طريقة التنبؤ المستخدمة (الانحدار الخطي، المتوسط المتحرك، إلخ)',
  `analysisDate` DATE COMMENT 'تاريخ إجراء التحليل',
  `analyzedByUserId` BIGINT COMMENT 'معرف من قام بالتحليل (FK → SystemUser.userId) - غالباً النظام آلياً',
  `notes` TEXT COMMENT 'ملاحظات حول التحليل (مثل: تأثير جائحة كورونا على النتائج)',
  `status` VARCHAR(50) COMMENT 'حالة التحليل (مسودة، معتمد)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد التحليل (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`analysisId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`kpiCode`) REFERENCES `DashboardConfiguration`(`...`),
  -- FOREIGN KEY (`analyzedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='نتائج تحليل الاتجاهات';

-- Table: SchoolStatisticsDraft (مسودات الإحصائية المدرسية)
CREATE TABLE IF NOT EXISTS `SchoolStatisticsDraft` (
  `draftId` BIGINT NOT NULL COMMENT 'معرف المسودة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `semesterId` BIGINT COMMENT 'معرف الفصل الدراسي (FK → SchoolSemester.semesterId) - اختياري',
  `periodType` VARCHAR(50) COMMENT 'نوع الفترة الإحصائية (شهري، ربع سنوي، فصل دراسي، سنوي)',
  `periodValue` VARCHAR(200) COMMENT 'قيمة الفترة (مثال: 1 للشهر الأول، 2 للربع الثاني)',
  `periodStartDate` DATE COMMENT 'تاريخ بداية الفترة الإحصائية',
  `periodEndDate` DATE COMMENT 'تاريخ نهاية الفترة الإحصائية',
  `draftNumber` INT COMMENT 'رقم المسودة (تسلسلي حسب المدرسة)',
  `draftVersion` VARCHAR(200) COMMENT 'إصدار المسودة (1.0, 1.1, 2.0) - للتعديلات المتعددة',
  `studentDataJson` VARCHAR(200) COMMENT 'بيانات الطلاب (أعداد، فئات، جنس) - JSON مفصل',
  `staffDataJson` VARCHAR(200) COMMENT 'بيانات الكادر (أعداد المعلمين والإداريين، المؤهلات، الجنسيات) - JSON مفصل',
  `financialSummaryJson` VARCHAR(200) COMMENT 'ملخص مالي مختصر (اختياري)',
  `assetSummaryJson` VARCHAR(200) COMMENT 'ملخص الأصول والمرافق (اختياري)',
  `completenessPercentage` DECIMAL(5,2) COMMENT 'نسبة اكتمال البيانات (يُحسب آلياً)',
  `draftStatus` VARCHAR(50) COMMENT 'حالة المسودة (جديد، قيد الإعداد، مكتمل، جاهز للرفع، قيد المراجعة، تم الرفع)',
  `isLocked` BOOLEAN COMMENT 'هل المسودة مقفلة (لمنع التعديل بعد الرفع)؟',
  `lockedAt` DATE COMMENT 'تاريخ القفل',
  `lockedByUserId` BIGINT COMMENT 'معرف من قفل المسودة',
  `lastSavedAt` DATE COMMENT 'تاريخ آخر حفظ',
  `savedByUserId` BIGINT COMMENT 'معرف آخر من حفظ',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`draftId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`semesterId`) REFERENCES `SchoolSemester`(`...`),
  -- FOREIGN KEY (`lockedByUserId`) REFERENCES `LockedByUser`(`...`),
  -- FOREIGN KEY (`savedByUserId`) REFERENCES `SavedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مسودات الإحصائية المدرسية';

-- Table: SubmittedStatistics (الإحصائيات المرفوعة)
CREATE TABLE IF NOT EXISTS `SubmittedStatistics` (
  `submissionId` BIGINT NOT NULL COMMENT 'معرف الإحصاء المرفوع (المفتاح الرئيسي)',
  `draftId` BIGINT COMMENT 'معرف المسودة المصدر (FK → SchoolStatisticsDraft.draftId) - علاقة 1-1',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `submissionNumber` INT COMMENT 'رقم الإيداع (يُولد آلياً)',
  `submissionTimestamp` DATE COMMENT 'وقت الرفع (تاريخ ووقت)',
  `submissionMethod` VARCHAR(200) COMMENT 'طريقة الرفع (بوابة إلكترونية، بريد رسمي، يدوي)',
  `submittedByUserId` BIGINT COMMENT 'معرف من قام بالرفع (FK → SystemUser.userId)',
  `directorSignature` VARCHAR(200) COMMENT 'التوقيع الإلكتروني للمدير (قيمة تجزئة أو مسار ملف)',
  `directorSignatureDate` DATE COMMENT 'تاريخ التوقيع',
  `studentDataSnapshot` VARCHAR(200) COMMENT 'لقطة من بيانات الطلاب وقت الرفع (JSON) - نسخة محفوظة',
  `staffDataSnapshot` VARCHAR(200) COMMENT 'لقطة من بيانات الكادر وقت الرفع (JSON) - نسخة محفوظة',
  `financialSummarySnapshot` VARCHAR(200) COMMENT 'لقطة من الملخص المالي (JSON) - اختياري',
  `assetSummarySnapshot` VARCHAR(200) COMMENT 'لقطة من الملخص الأصول (JSON) - اختياري',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد (معلق، قيد المراجعة، مقبول، مرفوض للتعديل، معتمد نهائياً)',
  `reviewerNotes` TEXT COMMENT 'ملاحظات المراجع (من المكتب)',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `reviewedByUserId` BIGINT COMMENT 'معرف مراجع المكتب (FK → SystemUser.userId) - من القسم الأول (Office)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد (عند القبول)',
  `approvalCertificateNumber` INT COMMENT 'رقم شهادة الاعتماد (إن وجد)',
  `approvalCertificatePath` VARCHAR(200) COMMENT 'مسار ملف شهادة الاعتماد (PDF)',
  `isFinal` BOOLEAN COMMENT 'هل هي النسخة النهائية المعتمدة؟',
  `isArchived` BOOLEAN COMMENT 'هل تمت أرشفتها؟',
  `archivedAt` DATE COMMENT 'تاريخ الأرشفة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`submissionId`),
  -- FOREIGN KEY (`draftId`) REFERENCES `SchoolStatisticsDraft`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`reviewedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإحصائيات المرفوعة';

-- Table: StatisticsUpdateHistory (سجل تحديثات الإحصاء)
CREATE TABLE IF NOT EXISTS `StatisticsUpdateHistory` (
  `historyId` BIGINT NOT NULL COMMENT 'معرف السجل (المفتاح الرئيسي)',
  `draftId` BIGINT COMMENT 'معرف المسودة المتأثرة (FK → SchoolStatisticsDraft.draftId) - اختياري',
  `submissionId` BIGINT COMMENT 'معرف الإحصاء المرفوع المتأثر (FK → SubmittedStatistics.submissionId) - اختياري',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `changeType` VARCHAR(50) COMMENT 'نوع التغيير (إضافة طالب، انسحاب طالب، تعيين معلم، إنهاء خدمة معلم، تعديل عدد فصول، تعديل نسبة نجاح، تعديل خطأ إدخال)',
  `changeCategory` VARCHAR(50) COMMENT 'فئة التغيير (طلاب، كادر، مالية، أصول)',
  `oldValue` VARCHAR(200) COMMENT 'القيمة السابقة (قبل التعديل) - نص أو رقم',
  `newValue` VARCHAR(200) COMMENT 'القيمة الجديدة (بعد التعديل)',
  `changeDate` DATE COMMENT 'تاريخ التغيير الفعلي (حدث التغيير، وليس تاريخ التسجيل)',
  `updateReason` DATE COMMENT 'سبب التعديل (تبرير المدرسة لهذا التغيير الجوهري) - نص طويل',
  `supportingDocument` VARCHAR(200) COMMENT 'مستند داعم (مسار ملف) - اختياري',
  `changedByUserId` BIGINT COMMENT 'معرف من قام بالتعديل (FK → SystemUser.userId)',
  `isApproved` BOOLEAN COMMENT 'هل تم اعتماد هذا التغيير من قبل المشرف؟',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`historyId`),
  -- FOREIGN KEY (`draftId`) REFERENCES `SchoolStatisticsDraft`(`...`),
  -- FOREIGN KEY (`submissionId`) REFERENCES `SubmittedStatistics`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`changedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سجل تحديثات الإحصاء';

-- Table: StatisticsArchive (أرشيف الإحصائيات التاريخية)
CREATE TABLE IF NOT EXISTS `StatisticsArchive` (
  `archiveId` BIGINT NOT NULL COMMENT 'معرف الأرشيف (المفتاح الرئيسي)',
  `submissionId` BIGINT COMMENT 'معرف الإحصاء المرفوع المصدر (FK → SubmittedStatistics.submissionId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `archivedYear` VARCHAR(200) COMMENT 'العام المؤرشف (السنة الدراسية أو التقويمية)',
  `periodType` VARCHAR(50) COMMENT 'نوع الفترة المؤرشفة (شهري، ربع سنوي، فصل دراسي، سنوي)',
  `periodValue` VARCHAR(200) COMMENT 'قيمة الفترة',
  `archivedAt` DATE COMMENT 'تاريخ الأرشفة (نقل البيانات للأرشيف)',
  `archivedByUserId` BIGINT COMMENT 'معرف من قام بالأرشفة (FK → SystemUser.userId)',
  `finalDataSnapshot` VARCHAR(200) COMMENT 'لقطة البيانات الكاملة (JSON) - نسخة غير قابلة للتعديل',
  `studentSnapshot` VARCHAR(200) COMMENT 'لقطة بيانات الطلاب (JSON) - نسخة فرعية',
  `staffSnapshot` VARCHAR(200) COMMENT 'لقطة بيانات الكادر (JSON) - نسخة فرعية',
  `financialSnapshot` VARCHAR(200) COMMENT 'لقطة بيانات مالية (JSON) - اختياري',
  `assetSnapshot` VARCHAR(200) COMMENT 'لقطة بيانات الأصول (JSON) - اختياري',
  `retentionPeriod` VARCHAR(200) COMMENT 'مدة الاحتفاظ (بالسنوات) - حسب السياسة',
  `retentionEndDate` DATE COMMENT 'تاريخ انتهاء مدة الاحتفاظ (بعدها يمكن الحذف)',
  `isReadOnly` BOOLEAN COMMENT 'دائماً True (لمنع أي تعديل)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل (نادراً ما يحدث)',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي (للحذف بعد انتهاء مدة الاحتفاظ)',
  PRIMARY KEY (`archiveId`),
  -- FOREIGN KEY (`submissionId`) REFERENCES `SubmittedStatistics`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`archivedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='أرشيف الإحصائيات التاريخية';

-- Table: SystemReports (سجل التقارير الدورية)
CREATE TABLE IF NOT EXISTS `SystemReports` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportType` VARCHAR(50) COMMENT 'نوع التقرير (دوري، إضافات، حركات، حالات، تلف)',
  `reportSubType` VARCHAR(50) COMMENT 'النوع الفرعي (شؤون طلاب، شؤون موظفين، مالي، أصول)',
  `reportTitle` VARCHAR(200) COMMENT 'مسمى التقرير (مثال: "تقرير الأصول الربع سنوي")',
  `reportFrequency` VARCHAR(200) COMMENT 'تكرار التقرير (يومي، أسبوعي، شهري، ربع سنوي، سنوي، حسب الطلب)',
  `periodStart` VARCHAR(200) COMMENT 'بداية الفترة الزمنية التي يغطيها التقرير',
  `periodEnd` VARCHAR(200) COMMENT 'نهاية الفترة الزمنية',
  `generationDate` DATE COMMENT 'تاريخ ووقت التوليد الآلي',
  `generatedBy` DECIMAL(5,2) COMMENT 'طريقة التوليد (تلقائي - Scheduled، يدوي - Manual)',
  `generatedByUserId` BIGINT COMMENT 'معرف من قام بالتوليد (إذا يدوياً) (FK → SystemUser.userId)',
  `fileFormat` VARCHAR(200) COMMENT 'صيغة الملف (PDF, Excel, CSV)',
  `filePath` VARCHAR(200) COMMENT 'مسار تخزين الملف في الأرشيف الرقمي',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف (بايت)',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، منشور، مؤرشف)',
  `isPublished` BOOLEAN COMMENT 'هل تم نشره للمستخدمين؟',
  `publishedAt` DATE COMMENT 'تاريخ النشر',
  `publishedByUserId` BIGINT COMMENT 'معرف من نشر',
  `viewCount` INT COMMENT 'عدد مرات عرض التقرير',
  `lastViewedAt` DATE COMMENT 'تاريخ آخر عرض',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`generatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`publishedByUserId`) REFERENCES `PublishedByUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سجل التقارير الدورية';

-- Table: ReportApprovals (اعتمادات التقارير)
CREATE TABLE IF NOT EXISTS `ReportApprovals` (
  `approvalId` BIGINT NOT NULL COMMENT 'معرف الاعتماد (المفتاح الرئيسي)',
  `reportId` BIGINT COMMENT 'معرف التقرير المراد اعتماده (FK → SystemReports.reportId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `submissionDate` DATE COMMENT 'تاريخ رفع التقرير للمراجعة',
  `submittedByUserId` BIGINT COMMENT 'معرف من رفع التقرير (FK → SystemUser.userId)',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة الاعتماد (مسودة، بانتظار المراجعة، قيد المراجعة، معتمد، مرفوض، ملغي)',
  `reviewerId` BIGINT COMMENT 'معرف المراجع (FK → SystemUser.userId) - اختياري',
  `reviewDate` DATE COMMENT 'تاريخ المراجعة',
  `comments` TEXT COMMENT 'ملاحظات الإدارة على صحة البيانات',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد الرسمي (عند القبول)',
  `approvedByUserId` BIGINT COMMENT 'معرف المعتمد (FK → SystemUser.userId)',
  `digitalSignature` VARCHAR(200) COMMENT 'توقيع إلكتروني أو كود تأكيد (قيمة تجزئة أو مسار ملف)',
  `certificateNumber` INT COMMENT 'رقم شهادة الاعتماد (إن وجد)',
  `certificatePath` VARCHAR(200) COMMENT 'مسار ملف شهادة الاعتماد',
  `isFinal` BOOLEAN COMMENT 'هل هذا هو الاعتماد النهائي؟',
  `validUntil` VARCHAR(200) COMMENT 'صلاحية الاعتماد حتى (للتقارير المؤقتة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`approvalId`),
  -- FOREIGN KEY (`reportId`) REFERENCES `SystemReports`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`submittedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`reviewerId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='اعتمادات التقارير';

-- Table: ComparativeReport (التقارير المقارنة)
CREATE TABLE IF NOT EXISTS `ComparativeReport` (
  `comparativeId` BIGINT NOT NULL COMMENT 'معرف التقرير المقارن (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `comparisonTitle` VARCHAR(200) COMMENT 'عنوان المقارنة (مثال: "مقارنة نتائج الفصل الأول والثاني 2025")',
  `firstPeriodLabel` VARCHAR(200) COMMENT 'تسمية الفترة الأولى (مثال: "الفصل الأول 2025")',
  `firstPeriodStart` VARCHAR(200) COMMENT 'بداية الفترة الأولى',
  `firstPeriodEnd` VARCHAR(200) COMMENT 'نهاية الفترة الأولى',
  `secondPeriodLabel` VARCHAR(200) COMMENT 'تسمية الفترة الثانية (مثال: "الفصل الثاني 2025")',
  `secondPeriodStart` VARCHAR(200) COMMENT 'بداية الفترة الثانية',
  `secondPeriodEnd` VARCHAR(200) COMMENT 'نهاية الفترة الثانية',
  `comparisonType` VARCHAR(50) COMMENT 'نوع المقارنة (زمني، بين مدارس، بين فئات)',
  `kpiCompared` VARCHAR(200) COMMENT 'المؤشرات التي تمت مقارنتها (JSON)',
  `comparisonData` VARCHAR(200) COMMENT 'بيانات المقارنة التفصيلية (JSON)',
  `autoInsights` VARCHAR(200) COMMENT 'الاستنتاجات الآلية (ملخص ذكي يكتبه النظام للنتائج)',
  `summary` VARCHAR(200) COMMENT 'ملخص عام للمقارنة',
  `generationDate` DATE COMMENT 'تاريخ استخراج التقرير',
  `generatedByUserId` BIGINT COMMENT 'معرف من قام بالتوليد (FK → SystemUser.userId)',
  `fileFormat` VARCHAR(200) COMMENT 'صيغة الملف (PDF, Excel)',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF/Excel)',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف',
  `viewCount` INT COMMENT 'عدد مرات العرض',
  `lastViewedAt` DATE COMMENT 'تاريخ آخر عرض',
  `status` VARCHAR(50) COMMENT 'حالة التقرير (مسودة، منشور، مؤرشف)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`comparativeId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`generatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='التقارير المقارنة';

-- Table: FinancialSummaryReports (تقارير القيمة المالية المجمعة)
CREATE TABLE IF NOT EXISTS `FinancialSummaryReports` (
  `summaryId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `fiscalYear` VARCHAR(200) COMMENT 'السنة المالية محل التقرير',
  `reportDate` DATE COMMENT 'تاريخ إصدار التقرير',
  `reportType` VARCHAR(50) COMMENT 'نوع التقرير (سنوي، ربع سنوي، حسب الطلب)',
  `totalBookValue` VARCHAR(200) COMMENT 'إجمالي القيمة الدفترية لكافة الأصول',
  `totalDepreciation` VARCHAR(200) COMMENT 'إجمالي الإهلاك المتراكم للفترة',
  `totalAssetsCount` INT COMMENT 'عدد الأصول التي شملها التقرير المالي',
  `totalAcquisitionCost` DATE COMMENT 'إجمالي تكلفة الشراء للأصول (التكلفة التاريخية)',
  `totalRevaluationGains` VARCHAR(200) COMMENT 'إجمالي أرباح إعادة التقييم',
  `totalImpairmentLosses` VARCHAR(200) COMMENT 'إجمالي خسائر الانخفاض في القيمة',
  `totalRevenue` VARCHAR(200) COMMENT 'إجمالي الإيرادات (من StudentInvoice)',
  `totalExpenses` VARCHAR(200) COMMENT 'إجمالي المصروفات (من AssetExpenses وغيرها)',
  `netIncome` VARCHAR(200) COMMENT 'صافي الدخل (totalRevenue - totalExpenses)',
  `auditStatus` VARCHAR(50) COMMENT 'حالة تدقيق التقرير (غير مدقق، مدقق داخلياً، مدقق خارجياً، تحت التدقيق)',
  `auditFirmName` VARCHAR(200) COMMENT 'اسم شركة التدقيق (إن وجد)',
  `auditorName` VARCHAR(200) COMMENT 'اسم المدقق (إن وجد)',
  `auditDate` DATE COMMENT 'تاريخ التدقيق',
  `auditorSignature` VARCHAR(200) COMMENT 'توقيع المدقق الإلكتروني',
  `approvalStatus` VARCHAR(50) COMMENT 'حالة اعتماد التقرير (مسودة، معتمد)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF/Excel)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`summaryId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير القيمة المالية المجمعة';

-- Table: ExternalComplianceReports (تقارير الامتثال والرفع الخارجي)
CREATE TABLE IF NOT EXISTS `ExternalComplianceReports` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي حسب الجهة)',
  `targetEntity` VARCHAR(200) COMMENT 'الجهة المستلمة (وزارة التربية، مكتب التعليم، هيئة التقويم، جهة خارجية أخرى)',
  `entityType` VARCHAR(50) COMMENT 'نوع الجهة (حكومية، خاصة، دولية)',
  `standardType` VARCHAR(50) COMMENT 'المعيار المطبق (المعايير المدرسية، معايير الجودة، متطلبات الترخيص)',
  `standardVersion` VARCHAR(200) COMMENT 'إصدار المعيار',
  `reportType` VARCHAR(50) COMMENT 'نوع التقرير (امتثال سنوي، تقرير جودة، تقرير ترخيص، إحصاء رسمي)',
  `periodStart` VARCHAR(200) COMMENT 'بداية فترة التقرير',
  `periodEnd` VARCHAR(200) COMMENT 'نهاية فترة التقرير',
  `generationDate` DATE COMMENT 'تاريخ إنشاء التقرير',
  `generatedByUserId` BIGINT COMMENT 'معرف من أنشأ التقرير (FK → SystemUser.userId)',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF)',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف',
  `submissionDate` DATE COMMENT 'تاريخ ووقت الإرسال الفعلي',
  `submissionMethod` VARCHAR(200) COMMENT 'طريقة الرفع (ربط API، بريد رسمي، بوابة إلكترونية، يدوي)',
  `apiEndpoint` VARCHAR(200) COMMENT 'رابط API (إذا كانت الطريقة API)',
  `apiRequestId` BIGINT COMMENT 'معرف طلب API (للتتبع)',
  `receiptReference` VARCHAR(200) COMMENT 'رقم إيصال الاستلام من الجهة الخارجية',
  `receiptDate` DATE COMMENT 'تاريخ استلام الإيصال',
  `receiptAttachment` VARCHAR(200) COMMENT 'مسار ملف الإيصال (PDF)',
  `submissionStatus` VARCHAR(50) COMMENT 'حالة الرفع (قيد الإعداد، تم الإرسال، قيد الاستلام، تم الاستلام، مرفوض، فشل)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `resubmissionDate` DATE COMMENT 'تاريخ إعادة الرفع (إن وجد)',
  `isFinal` BOOLEAN COMMENT 'هل هو التقرير النهائي المعتمد وزارياً؟',
  `finalApprovalDate` DATE COMMENT 'تاريخ الاعتماد النهائي',
  `finalApprovalNumber` INT COMMENT 'رقم الاعتماد النهائي',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`generatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`apiRequestId`) REFERENCES `ApiRequest`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير الامتثال والرفع الخارجي';

-- Table: GapAnalysisReports (تحليلات الفجوة والاحتياج)
CREATE TABLE IF NOT EXISTS `GapAnalysisReports` (
  `analysisId` BIGINT NOT NULL COMMENT 'معرف التحليل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `analysisNumber` INT COMMENT 'رقم التحليل (تسلسلي)',
  `analysisType` VARCHAR(50) COMMENT 'نوع التحليل (طلاب:معلمين، طلاب:فصول، أصول:منهج، تجهيزات:معايير)',
  `assetCategoryId` BIGINT COMMENT 'معرف فئة الأصول (FK → AssetCategory.categoryId) - إذا كان التحليل لأصول',
  `gradeLevelId` BIGINT COMMENT 'معرف الصف (FK → GradeCapacity.gradeLevelId) - إذا كان التحليل لصف معين',
  `departmentId` BIGINT COMMENT 'معرف القسم (FK → SchoolDepartment.deptId) - إذا كان التحليل لقسم',
  `requiredQty` VARCHAR(200) COMMENT 'الكمية المطلوبة (حسب المنهج/الطاقة/المعيار)',
  `availableQty` VARCHAR(200) COMMENT 'الكمية المتوفرة حالياً في النظام',
  `gapValue` VARCHAR(200) COMMENT 'الفرق (بالزيادة أو النقص) - (availableQty - requiredQty)',
  `gapPercentage` DECIMAL(5,2) COMMENT 'نسبة الفرق (من requiredQty)',
  `gapType` VARCHAR(50) COMMENT 'نوع الفجوة (نقص، زيادة، مطابق)',
  `recommendation` VARCHAR(200) COMMENT 'توصية التقرير (شراء جديد، نقل من قسم آخر، استبدال، لا حاجة لإجراء)',
  `priority` VARCHAR(200) COMMENT 'أولوية معالجة الفجوة (عالية، متوسطة، منخفضة)',
  `estimatedCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية لمعالجة الفجوة (إن كانت نقصاً)',
  `analysisDate` DATE COMMENT 'تاريخ التحليل',
  `analyzedByUserId` BIGINT COMMENT 'معرف من قام بالتحليل (FK → SystemUser.userId)',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF/Excel)',
  `status` VARCHAR(50) COMMENT 'حالة التحليل (مسودة، معتمد، منفذ)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`analysisId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assetCategoryId`) REFERENCES `AssetCategory`(`...`),
  -- FOREIGN KEY (`gradeLevelId`) REFERENCES `GradeCapacity`(`...`),
  -- FOREIGN KEY (`departmentId`) REFERENCES `SchoolDepartment`(`...`),
  -- FOREIGN KEY (`analyzedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تحليلات الفجوة والاحتياج';

-- Table: ReportsArchive (أرشفة التقارير)
CREATE TABLE IF NOT EXISTS `ReportsArchive` (
  `archiveId` BIGINT NOT NULL COMMENT 'معرف الأرشيف (المفتاح الرئيسي)',
  `sourceReportType` VARCHAR(50) COMMENT 'نوع التقرير المصدر (SystemReport, ComparativeReport, FinancialSummaryReport, ExternalComplianceReport)',
  `sourceReportId` BIGINT COMMENT 'معرف التقرير المصدر (حسب النوع)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `archivedAt` DATE COMMENT 'تاريخ النقل للأرشيف',
  `archivedByUserId` BIGINT COMMENT 'معرف من قام بالأرشفة (FK → SystemUser.userId)',
  `retentionPeriod` VARCHAR(200) COMMENT 'مدة الاحتفاظ القانونية (بالسنوات)',
  `retentionEndDate` DATE COMMENT 'تاريخ انتهاء مدة الاحتفاظ (يُحسب = archivedAt + retentionPeriod)',
  `storageLocation` VARCHAR(200) COMMENT 'المسار السحابي أو الفيزيائي للأرشيف',
  `filePath` VARCHAR(200) COMMENT 'مسار الملف في موقع التخزين',
  `fileSize` VARCHAR(200) COMMENT 'حجم الملف',
  `isReadOnly` BOOLEAN COMMENT 'دائماً True (لمنع أي تعديل)',
  `disposalDate` DATE COMMENT 'تاريخ الإتلاف المتوقع (بعد retentionEndDate)',
  `disposalStatus` VARCHAR(50) COMMENT 'حالة الإتلاف (في الانتظار، تم الإتلاف)',
  `disposalMethod` VARCHAR(200) COMMENT 'طريقة الإتلاف (حذف آمن، تمزيق، إرجاع لجهة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`archiveId`),
  -- FOREIGN KEY (`sourceReportId`) REFERENCES `SourceReport`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`archivedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='أرشفة التقارير';

-- Table: ExceptionalStatistics (الإحصائيات الاستثنائية)
CREATE TABLE IF NOT EXISTS `ExceptionalStatistics` (
  `statisticsId` BIGINT NOT NULL COMMENT 'معرف الإحصاء (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `academicYearId` BIGINT COMMENT 'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `totalIncidents` VARCHAR(200) COMMENT 'إجمالي الحالات المسجلة (من EmergencyIncidents)',
  `totalClosureDays` VARCHAR(200) COMMENT 'مجموع الأيام التي تعطلت فيها الدراسة (من EmergencyClosures)',
  `totalDamageCost` DECIMAL(15,2) COMMENT 'تقدير مالي للخسائر المادية (من EmergencyIncidents و MaintenanceTickets)',
  `totalAwardsCount` INT COMMENT 'عدد الجوائز التي حصلت عليها المدرسة (من SchoolAwards)',
  `totalParticipationsCount` INT COMMENT 'عدد المشاركات الخارجية (من ExternalParticipations)',
  `totalDeficitCount` INT COMMENT 'عدد حالات العجز التعليمي المسجلة (من SchoolDeficit)',
  `totalSurplusCount` INT COMMENT 'عدد حالات الفائض التعليمي المسجلة (من SchoolSurplus)',
  `emergencySummary` VARCHAR(200) COMMENT 'ملخص حالات الطوارئ (JSON)',
  `closureSummary` VARCHAR(200) COMMENT 'ملخص أيام الإغلاق (JSON)',
  `awardSummary` VARCHAR(200) COMMENT 'ملخص الجوائز (JSON)',
  `generationDate` DATE COMMENT 'تاريخ إنشاء الإحصاء',
  `generatedByUserId` BIGINT COMMENT 'معرف من أنشأ الإحصاء (FK → SystemUser.userId)',
  `filePath` VARCHAR(200) COMMENT 'مسار ملف التقرير (PDF/Excel)',
  `status` VARCHAR(50) COMMENT 'حالة الإحصاء (مسودة، معتمد)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`statisticsId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`academicYearId`) REFERENCES `SchoolAcademicYear`(`...`),
  -- FOREIGN KEY (`generatedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإحصائيات الاستثنائية';


-- ============================
-- Module: M7_Auth
-- ============================

-- Table: SystemUser (المستخدمين)
CREATE TABLE IF NOT EXISTS `SystemUser` (
  `userId` BIGINT NOT NULL COMMENT 'معرف المستخدم (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للمستخدمين على مستوى المكتب (Office)',
  `officeId` BIGINT COMMENT 'معرف المكتب (FK → Office.officeId) - للمستخدمين على مستوى المكتب',
  `username` VARCHAR(200) COMMENT 'اسم المستخدم (فريد عالمياً أو على مستوى المدرسة)',
  `passwordHash` VARCHAR(200) COMMENT 'كلمة المرور مشفرة (باستخدام خوارزمية آمنة مثل bcrypt)',
  `passwordSalt` VARCHAR(200) COMMENT 'قيمة الملح المستخدمة في التشفير',
  `passwordExpiryDate` DATE COMMENT 'تاريخ انتهاء صلاحية كلمة المرور',
  `lastPasswordChangeDate` DATE COMMENT 'تاريخ آخر تغيير لكلمة المرور',
  `mustChangePassword` VARCHAR(200) COMMENT 'هل يجب تغيير كلمة المرور عند أول دخول؟',
  `failedAttempts` VARCHAR(200) COMMENT 'عدد محاولات الدخول الفاشلة المتتالية',
  `lastFailedAttempt` DATE COMMENT 'تاريخ آخر محاولة فاشلة',
  `isLocked` BOOLEAN COMMENT 'هل الحساب مقفل؟',
  `lockReason` VARCHAR(200) COMMENT 'سبب القفل (محاولات فاشلة متكررة، تعطيل من الإدارة)',
  `lockExpiryDate` DATE COMMENT 'تاريخ فتح الحساب (للقفل المؤقت)',
  `isActive` BOOLEAN COMMENT 'هل الحساب مفعل؟',
  `activationDate` DATE COMMENT 'تاريخ تفعيل الحساب',
  `deactivationDate` DATE COMMENT 'تاريخ تعطيل الحساب',
  `deactivationReason` VARCHAR(200) COMMENT 'سبب التعطيل',
  `fullNameAr` VARCHAR(200) COMMENT 'الاسم الكامل بالعربية',
  `fullNameEn` VARCHAR(200) COMMENT 'الاسم الكامل بالإنجليزية',
  `nationalId` BIGINT COMMENT 'الرقم الوطني/الإقامة (فريد)',
  `email` VARCHAR(100) COMMENT 'البريد الإلكتروني (فريد، يستخدم لتسجيل الدخول أيضاً)',
  `emailVerified` VARCHAR(100) COMMENT 'هل تم التحقق من البريد الإلكتروني؟',
  `emailVerifiedAt` DATE COMMENT 'تاريخ التحقق',
  `phone` VARCHAR(20) COMMENT 'رقم الجوال (فريد)',
  `phoneVerified` VARCHAR(20) COMMENT 'هل تم التحقق من الجوال؟',
  `phoneVerifiedAt` DATE COMMENT 'تاريخ التحقق',
  `userType` VARCHAR(50) COMMENT 'نوع المستخدم (مدير نظام، مدير مدرسة، وكيل، معلم، طالب، ولي أمر، مشرف مكتب)',
  `employeeId` BIGINT COMMENT 'معرف الموظف المرتبط (FK → Employee.employeeId) - إذا كان المستخدم موظفاً',
  `studentId` BIGINT COMMENT 'معرف الطالب المرتبط (FK → Student.studentId) - إذا كان المستخدم طالباً',
  `guardianId` BIGINT COMMENT 'معرف ولي الأمر المرتبط (FK → Guardian.guardianId) - إذا كان المستخدم ولي أمر',
  `twoFactorEnabled` VARCHAR(200) COMMENT 'هل تم تفعيل المصادقة الثنائية؟',
  `twoFactorMethod` VARCHAR(200) COMMENT 'طريقة المصادقة الثنائية (بريد إلكتروني، رسالة نصية، تطبيق مصادقة)',
  `twoFactorSecret` VARCHAR(200) COMMENT 'سر المصادقة الثنائية (للتطبيقات مثل Google Authenticator)',
  `twoFactorBackupCodes` VARCHAR(50) COMMENT 'رموز النسخ الاحتياطي للمصادقة الثنائية (JSON)',
  `lastLoginDate` DATE COMMENT 'تاريخ آخر دخول',
  `lastLoginIp` VARCHAR(200) COMMENT 'آخر عنوان IP للدخول',
  `lastLoginDevice` VARCHAR(200) COMMENT 'آخر جهاز تم الدخول منه',
  `lastLoginUserAgent` VARCHAR(200) COMMENT 'متصفح/نظام التشغيل لآخر دخول',
  `previousLoginDate` DATE COMMENT 'تاريخ الدخول السابق',
  `preferredLanguage` VARCHAR(200) COMMENT 'اللغة المفضلة (عربية، إنجليزية)',
  `timezone` TIME COMMENT 'المنطقة الزمنية',
  `dateFormat` DATE COMMENT 'تنسيق التاريخ المفضل (DD/MM/YYYY, MM/DD/YYYY)',
  `theme` VARCHAR(200) COMMENT 'مظهر الواجهة (فاتح، داكن)',
  `profilePicture` VARCHAR(200) COMMENT 'صورة الملف الشخصي (مسار الملف)',
  `signatureImage` VARCHAR(200) COMMENT 'صورة التوقيع (مسار الملف) - للمستخدمين الذين لديهم صلاحية توقيع',
  `notificationPreferences` VARCHAR(200) COMMENT 'تفضيلات الإشعارات (JSON)',
  `dashboardLayout` VARCHAR(200) COMMENT 'تخطيط لوحة التحكم المخصص (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `deletedAt` DATE COMMENT 'تاريخ الحذف (حذف منطقي)',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`userId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`officeId`) REFERENCES `Office`(`...`),
  -- FOREIGN KEY (`nationalId`) REFERENCES `National`(`...`),
  -- FOREIGN KEY (`employeeId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`guardianId`) REFERENCES `Guardian`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المستخدمين';

-- Table: UserActivityLog (تتبع النشاط الزمني للمستخدم)
CREATE TABLE IF NOT EXISTS `UserActivityLog` (
  `logId` BIGINT NOT NULL COMMENT 'معرف السجل (المفتاح الرئيسي)',
  `userId` BIGINT COMMENT 'معرف المستخدم (FK → SystemUser.userId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - للتكرار',
  `activityType` VARCHAR(50) COMMENT 'نوع النشاط (تسجيل دخول، تسجيل خروج، محاولة دخول فاشلة، تغيير كلمة مرور، تغيير بريد إلكتروني، تفعيل 2FA، تغيير صلاحيات، إنشاء مستخدم، حذف مستخدم)',
  `activityTimestamp` DATE COMMENT 'تاريخ ووقت النشاط',
  `status` VARCHAR(50) COMMENT 'حالة النشاط (نجاح، فشل، محظور)',
  `failureReason` VARCHAR(200) COMMENT 'سبب الفشل (إن وجد) - (كلمة مرور خاطئة، حساب مقفل، صلاحية منتهية)',
  `ipAddress` VARCHAR(200) COMMENT 'عنوان IP للمستخدم',
  `deviceType` VARCHAR(50) COMMENT 'نوع الجهاز (كمبيوتر، هاتف، جهاز لوحي)',
  `deviceName` VARCHAR(200) COMMENT 'اسم الجهاز (إن وجد)',
  `operatingSystem` VARCHAR(200) COMMENT 'نظام التشغيل',
  `browser` VARCHAR(200) COMMENT 'المتصفح المستخدم',
  `userAgent` VARCHAR(200) COMMENT 'سلسلة User Agent كاملة (للتتبع)',
  `location` VARCHAR(200) COMMENT 'الموقع التقريبي بناءً على IP (مدينة، دولة) - اختياري',
  `sessionId` BIGINT COMMENT 'معرف الجلسة',
  `actionDetails` VARCHAR(200) COMMENT 'تفاصيل إضافية عن النشاط (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`logId`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`sessionId`) REFERENCES `Session`(`...`)
) COMMENT='تتبع النشاط الزمني للمستخدم';

-- Table: PermissionType (أنواع الصلاحيات)
CREATE TABLE IF NOT EXISTS `PermissionType` (
  `typeId` BIGINT NOT NULL COMMENT 'معرف نوع الصلاحية (المفتاح الرئيسي)',
  `typeCode` VARCHAR(50) COMMENT 'رمز نوع الصلاحية (فريد، مثال: "VIEW", "CREATE", "EDIT", "DELETE", "APPROVE")',
  `typeNameAr` VARCHAR(50) COMMENT 'اسم نوع الصلاحية بالعربية',
  `typeNameEn` VARCHAR(50) COMMENT 'اسم نوع الصلاحية بالإنجليزية',
  `category` VARCHAR(50) COMMENT 'فئة الصلاحية (عرض، إنشاء، تعديل، حذف، اعتماد، تصدير، طباعة)',
  `scopeType` VARCHAR(50) COMMENT 'نطاق الصلاحية (خاص - Own، عام - All، قسمي - Department، مدرستي - School)',
  `riskLevel` VARCHAR(50) COMMENT 'مستوى الخطورة (منخفض، متوسط، مرتفع، حرج)',
  `requiresApproval` VARCHAR(200) COMMENT 'هل تتطلب هذه الصلاحية موافقة إدارية لمنحها لمستخدم؟',
  `approvalLevel` VARCHAR(50) COMMENT 'مستوى الموافقة المطلوب (مدير قسم، مدير مدرسة، مدير نظام)',
  `descriptionAr` TEXT COMMENT 'الوصف بالعربية',
  `descriptionEn` TEXT COMMENT 'الوصف بالإنجليزية',
  `isActive` BOOLEAN COMMENT 'هل نوع الصلاحية مفعل؟',
  `isSystem` BOOLEAN COMMENT 'صلاحية نظامية (لا يمكن حذفها أو تعديلها)',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب العرض',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`typeId`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='أنواع الصلاحيات';

-- Table: Permission (الصلاحيات)
CREATE TABLE IF NOT EXISTS `Permission` (
  `permissionId` BIGINT NOT NULL COMMENT 'معرف الصلاحية (المفتاح الرئيسي)',
  `permissionKey` VARCHAR(200) COMMENT 'مفتاح الصلاحية (فريد، مثال: "students.create")',
  `module` VARCHAR(200) COMMENT 'الوحدة/الموديول (Student, Finance, Employee, Asset, Report, Settings)',
  `subModule` VARCHAR(200) COMMENT 'الوحدة الفرعية (Enrollment, Grades, Attendance, Payroll)',
  `action` VARCHAR(200) COMMENT 'الإجراء (view, create, edit, delete, approve, export, print, import)',
  `typeId` BIGINT COMMENT 'معرف نوع الصلاحية (FK → PermissionType.typeId)',
  `scope` VARCHAR(200) COMMENT 'النطاق الافتراضي (خاص، قسمي، مدرستي، عام)',
  `nameAr` VARCHAR(200) COMMENT 'اسم الصلاحية بالعربية (مثال: "إنشاء طالب جديد")',
  `nameEn` VARCHAR(200) COMMENT 'اسم الصلاحية بالإنجليزية (مثال: "Create New Student")',
  `descriptionAr` TEXT COMMENT 'الوصف التفصيلي بالعربية',
  `descriptionEn` TEXT COMMENT 'الوصف التفصيلي بالإنجليزية',
  `riskLevel` VARCHAR(50) COMMENT 'مستوى الخطورة (منخفض، متوسط، مرتفع، حرج)',
  `isSensitive` BOOLEAN COMMENT 'هل الصلاحية حساسة (تتطلب تسجيلاً إضافياً في سجل التدقيق)؟',
  `requiresLogging` VARCHAR(200) COMMENT 'هل تتطلب تسجيلاً إلزامياً في AuditLog عند استخدامها؟',
  `conditions` VARCHAR(200) COMMENT 'شروط تطبيق الصلاحية (JSON) - شروط إضافية مثل "فقط مواد يدرسها المعلم"',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`permissionId`),
  -- FOREIGN KEY (`typeId`) REFERENCES `PermissionType`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الصلاحيات';

-- Table: Role (الأدوار)
CREATE TABLE IF NOT EXISTS `Role` (
  `roleId` BIGINT NOT NULL COMMENT 'معرف الدور (المفتاح الرئيسي)',
  `roleCode` VARCHAR(50) COMMENT 'رمز الدور (فريد، مثال: "SCHOOL_PRINCIPAL", "TEACHER")',
  `roleNameAr` VARCHAR(200) COMMENT 'اسم الدور بالعربية',
  `roleNameEn` VARCHAR(200) COMMENT 'اسم الدور بالإنجليزية',
  `roleType` VARCHAR(50) COMMENT 'نوع الدور (نظام، مدرسي، مكتبي، مؤقت)',
  `hierarchyLevel` VARCHAR(50) COMMENT 'مستوى التسلسل الهرمي (1-10) - كلما زاد الرقم زادت الصلاحيات',
  `parentRoleId` BIGINT COMMENT 'معرف الدور الأب (Self FK → Role.roleId) - لوراثة الصلاحيات',
  `isInheritable` BOOLEAN COMMENT 'هل يمكن توريث هذا الدور لأدوار فرعية؟',
  `isAssignable` BOOLEAN COMMENT 'هل يمكن تعيين هذا الدور للمستخدمين؟',
  `isSystem` BOOLEAN COMMENT 'دور نظامي (لا يمكن حذفه أو تعديله)',
  `isActive` BOOLEAN COMMENT 'هل الدور مفعل؟',
  `descriptionAr` TEXT COMMENT 'وصف الدور بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الدور بالإنجليزية',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`roleId`),
  -- FOREIGN KEY (`parentRoleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الأدوار';

-- Table: RolePermission (صلاحيات الأدوار)
CREATE TABLE IF NOT EXISTS `RolePermission` (
  `rolePermissionId` BIGINT NOT NULL COMMENT 'معرف السجل (المفتاح الرئيسي)',
  `roleId` BIGINT COMMENT 'معرف الدور (FK → Role.roleId)',
  `permissionId` BIGINT COMMENT 'معرف الصلاحية (FK → Permission.permissionId)',
  `scopeOverride` VARCHAR(200) COMMENT 'تجاوز للنطاق الافتراضي (خاص، قسمي، مدرستي، عام) - إذا كان مختلفاً عن النطاق الافتراضي للصلاحية',
  `isInherited` BOOLEAN COMMENT 'هل هذه الصلاحية موروثة من دور أب؟',
  `inheritedFromRoleId` BIGINT COMMENT 'معرف الدور الذي ورثت منه الصلاحية (FK → Role.roleId) - اختياري',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة لهذا الدور؟',
  `startDate` DATE COMMENT 'تاريخ بداية التفعيل (يمكن تحديد صلاحية لفترة محددة)',
  `endDate` DATE COMMENT 'تاريخ نهاية التفعيل',
  `grantedByUserId` BIGINT COMMENT 'معرف من منح الصلاحية (FK → SystemUser.userId)',
  `grantedAt` VARCHAR(200) COMMENT 'وقت منح الصلاحية',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`rolePermissionId`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`permissionId`) REFERENCES `Permission`(`...`),
  -- FOREIGN KEY (`inheritedFromRoleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`grantedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='صلاحيات الأدوار';

-- Table: UserRole (تعيين الأدوار للمستخدمين)
CREATE TABLE IF NOT EXISTS `UserRole` (
  `userRoleId` BIGINT NOT NULL COMMENT 'معرف التعيين (المفتاح الرئيسي)',
  `userId` BIGINT COMMENT 'معرف المستخدم (FK → SystemUser.userId)',
  `roleId` BIGINT COMMENT 'معرف الدور (FK → Role.roleId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - لتحديد سياق الدور (مثلاً دور معلم في مدرسة محددة)',
  `isPrimary` BOOLEAN COMMENT 'هل هو الدور الأساسي للمستخدم (يستخدم كافتراضي)؟',
  `scopeContext` VARCHAR(200) COMMENT 'سياق النطاق (JSON) - معلومات إضافية عن نطاق الدور (مثل القسم المسؤول عنه)',
  `startDate` DATE COMMENT 'تاريخ بداية التعيين',
  `endDate` DATE COMMENT 'تاريخ نهاية التعيين (يمكن أن يكون NULL إذا كان مستمراً)',
  `isActive` BOOLEAN COMMENT 'هل التعيين مفعل حالياً؟',
  `assignedByUserId` BIGINT COMMENT 'معرف من قام بتعيين الدور (FK → SystemUser.userId)',
  `assignedAt` VARCHAR(200) COMMENT 'وقت التعيين',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`userRoleId`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`assignedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='تعيين الأدوار للمستخدمين';

-- Table: GovernanceRBAC (حوكمة الصلاحيات والأدوار)
CREATE TABLE IF NOT EXISTS `GovernanceRBAC` (
  `governanceId` BIGINT NOT NULL COMMENT 'معرف سجل الحوكمة (المفتاح الرئيسي)',
  `roleId` BIGINT COMMENT 'معرف الدور الذي له صلاحية إدارة الصلاحيات (FK → Role.roleId)',
  `targetRoleId` BIGINT COMMENT 'معرف الدور المستهدف (الذي يمكن إدارة صلاحياته) (FK → Role.roleId) - يمكن أن يكون NULL للصلاحيات المباشرة',
  `targetPermissionId` BIGINT COMMENT 'معرف الصلاحية المستهدفة (FK → Permission.permissionId) - يمكن أن يكون NULL لجميع الصلاحيات',
  `action` VARCHAR(200) COMMENT 'الإجراء المسموح به (grant - منح, revoke - سحب, modify - تعديل, view - عرض)',
  `canDelegate` VARCHAR(200) COMMENT 'هل يمكن لهذا الدور تفويض صلاحيات الإدارة هذه لدور آخر؟',
  `approvalRequired` VARCHAR(200) COMMENT 'هل يتطلب الإجراء موافقة إضافية؟',
  `approvalRoleId` BIGINT COMMENT 'معرف الدور الذي يجب أن يوافق (FK → Role.roleId) - اختياري',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`governanceId`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`targetRoleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`targetPermissionId`) REFERENCES `Permission`(`...`),
  -- FOREIGN KEY (`approvalRoleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حوكمة الصلاحيات والأدوار';

-- Table: UserPermission (الصلاحيات المباشرة للمستخدمين)
CREATE TABLE IF NOT EXISTS `UserPermission` (
  `userPermissionId` BIGINT NOT NULL COMMENT 'معرف السجل (المفتاح الرئيسي)',
  `userId` BIGINT COMMENT 'معرف المستخدم (FK → SystemUser.userId)',
  `permissionId` BIGINT COMMENT 'معرف الصلاحية (FK → Permission.permissionId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - سياق الصلاحية (يمكن أن تختلف الصلاحية حسب المدرسة)',
  `scopeOverride` VARCHAR(200) COMMENT 'تجاوز للنطاق الافتراضي',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة للمستخدم؟',
  `startDate` DATE COMMENT 'تاريخ بداية التفعيل',
  `endDate` DATE COMMENT 'تاريخ نهاية التفعيل (يمكن أن يكون NULL)',
  `grantedByUserId` BIGINT COMMENT 'معرف من منح الصلاحية (FK → SystemUser.userId)',
  `grantedAt` VARCHAR(200) COMMENT 'وقت منح الصلاحية',
  `reason` VARCHAR(200) COMMENT 'سبب منح الصلاحية مباشرة (بدون دور)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`userPermissionId`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`permissionId`) REFERENCES `Permission`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`grantedByUserId`) REFERENCES `SystemUser`(`...`)
) COMMENT='الصلاحيات المباشرة للمستخدمين';

-- Table: AccessPolicy (سياسات الوصول)
CREATE TABLE IF NOT EXISTS `AccessPolicy` (
  `policyId` BIGINT NOT NULL COMMENT 'معرف السياسة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للسياسات العامة',
  `policyCode` VARCHAR(50) COMMENT 'رمز السياسة (فريد)',
  `policyNameAr` VARCHAR(200) COMMENT 'اسم السياسة بالعربية',
  `policyNameEn` VARCHAR(200) COMMENT 'اسم السياسة بالإنجليزية',
  `policyType` VARCHAR(50) COMMENT 'نوع السياسة (زمني - Time, مكاني - Location, جهاز - Device, عنوان IP)',
  `policyRule` VARCHAR(200) COMMENT 'قاعدة السياسة (JSON) - تحتوي على الشروط',
  `effect` VARCHAR(200) COMMENT 'تأثير السياسة (السماح، المنع، تتطلب موافقة إضافية)',
  `priority` VARCHAR(200) COMMENT 'الأولوية (1-100) - كلما قل الرقم زادت الأولوية',
  `appliesTo` VARCHAR(200) COMMENT 'تطبق على (أدوار - Roles، مستخدمين - Users، صلاحيات - Permissions)',
  `appliesToIds` VARCHAR(200) COMMENT 'المعرفات التي تطبق عليهم (JSON)',
  `isActive` BOOLEAN COMMENT 'هل السياسة مفعلة؟',
  `validFrom` DATE COMMENT 'تاريخ بدء صلاحية السياسة',
  `validTo` DATE COMMENT 'تاريخ انتهاء صلاحية السياسة',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`policyId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='سياسات الوصول';

-- Table: PermissionBase (الجداول الأساسية لنظام الصلاحيات)
CREATE TABLE IF NOT EXISTS `PermissionBase` (
  `baseId` BIGINT NOT NULL COMMENT 'معرف الأساس (المفتاح الرئيسي)',
  `moduleCode` VARCHAR(50) COMMENT 'رمز الوحدة (مثال: "STD" للطلاب، "EMP" للموظفين)',
  `moduleNameAr` VARCHAR(200) COMMENT 'اسم الوحدة بالعربية',
  `moduleNameEn` VARCHAR(200) COMMENT 'اسم الوحدة بالإنجليزية',
  `sectionCode` VARCHAR(50) COMMENT 'رمز القسم (مثال: "ENROLL" للتسجيل)',
  `sectionNameAr` VARCHAR(200) COMMENT 'اسم القسم بالعربية',
  `sectionNameEn` VARCHAR(200) COMMENT 'اسم القسم بالإنجليزية',
  `description` TEXT COMMENT 'وصف الوحدة/القسم',
  `defaultPermissions` VARCHAR(200) COMMENT 'الصلاحيات الافتراضية لهذا القسم (JSON) - قائمة بـ actions',
  `isActive` BOOLEAN COMMENT 'هل القسم مفعل؟',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب العرض',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`baseId`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الجداول الأساسية لنظام الصلاحيات';

-- Table: StudentBasePermissions (صلاحيات الطالب الأساسية)
CREATE TABLE IF NOT EXISTS `StudentBasePermissions` (
  `permissionId` BIGINT NOT NULL COMMENT 'معرف الصلاحية (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للسياسات العامة',
  `roleId` BIGINT COMMENT 'معرف الدور المطبق عليه هذه الصلاحية (FK → Role.roleId)',
  `permissionCode` VARCHAR(50) COMMENT 'كود الصلاحية (فريد، مثال: "STUDENT_VIEW_OWN", "STUDENT_EDIT_BY_ADMIN")',
  `category` VARCHAR(50) COMMENT 'فئة الصلاحية (بيانات شخصية، وثائق، حالة دراسية)',
  `resourceType` VARCHAR(50) COMMENT 'نوع المورد (Student, StudentDocument, Enrollment)',
  `action` VARCHAR(200) COMMENT 'الإجراء المسموح (view, create, edit, delete, verify, approve)',
  `scope` VARCHAR(200) COMMENT 'نطاق الصلاحية (خاص - Own فقط، عام - All، قسمي - Department، مدرستي - School)',
  `descriptionAr` TEXT COMMENT 'وصف الصلاحية بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الصلاحية بالإنجليزية',
  `requiresApproval` VARCHAR(200) COMMENT 'هل يتطلب الإجراء موافقة إدارية؟',
  `requireDocumentation` VARCHAR(200) COMMENT 'هل يتطلب الإجراء توثيقاً (مستندات مرفقة)؟',
  `notes` TEXT COMMENT 'ملاحظات إضافية (مثل: "تتطلب موافقة مدير المدرسة")',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `STUDENT_VIEW_OWN` VARCHAR(200) COMMENT 'الطالب يرى بياناته فقط - scope = Own',
  `STUDENT_VIEW_ALL_ADMIN` VARCHAR(200) COMMENT 'الإدارة ترى بيانات جميع الطلاب - scope = All',
  `STUDENT_EDIT_BY_ADMIN` VARCHAR(200) COMMENT 'الإدارة تعدل بيانات الطلاب - action = edit',
  `STUDENT_VIEW_BY_TEACHER` VARCHAR(200) COMMENT 'المعلم يرى بيانات طلاب فصله فقط - scope = Class',
  `DOCUMENT_UPLOAD_BY_STUDENT` VARCHAR(200) COMMENT 'الطالب يرفع وثائقه الخاصة - scope = Own',
  `DOCUMENT_VERIFY_BY_ADMIN` VARCHAR(200) COMMENT 'مسؤولو التوثيق فقط يتحققون من الوثائق',
  `ENROLLMENT_STATUS_BY_TOP_MANAGEMENT` VARCHAR(50) COMMENT 'الإدارة العليا فقط تغير حالة التحاق الطالب',
  PRIMARY KEY (`permissionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='صلاحيات الطالب الأساسية';

-- Table: StudentAcademicPermissions (الصلاحيات الأكاديمية المرتبطة بالطالب)
