  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `ENROLLMENT_CREATE_BY_STUDENT` VARCHAR(200) COMMENT 'الطالب يسجل نفسه في المواد (خلال فترة التسجيل)',
