  `GRADE_APPROVE_BY_PRINCIPAL` DECIMAL(5,2) COMMENT 'مدير المدرسة يعتمد الدرجات النهائية',
  `TIMETABLE_VIEW_BY_TEACHER` TIME COMMENT 'المعلم يرى جدوله فقط',
  `TIMETABLE_VIEW_BY_STUDENT` TIME COMMENT 'الطالب يرى جدول فصله',
  PRIMARY KEY (`permissionId`),
