  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الصلاحيات الأكاديمية المرتبطة بالطالب';

-- Table: StudentFinancePermissions (صلاحيات المالية المرتبطة بالطالب)
CREATE TABLE IF NOT EXISTS `StudentFinancePermissions` (
