-- Table: OfficePermissions (صلاحيات المكتب التربوي)
CREATE TABLE IF NOT EXISTS `OfficePermissions` (
  `permissionId` BIGINT NOT NULL COMMENT 'معرف الصلاحية (المفتاح الرئيسي)',
  `officeId` BIGINT COMMENT 'معرف المكتب (FK → Office.officeId)',
  `roleId` BIGINT COMMENT 'معرف الدور (FK → Role.roleId)',
