  `scope` VARCHAR(200) COMMENT 'نطاق الصلاحية (مدارس معينة، جميع المدارس التابعة)',
  `applicableSchoolIds` VARCHAR(200) COMMENT 'المدارس التي ينطبق عليها (JSON) - إذا كان النطاق محدداً',
  `requiresApproval` VARCHAR(200) COMMENT 'هل يتطلب الإجراء موافقة من مستوى أعلى؟',
  `descriptionAr` TEXT COMMENT 'وصف الصلاحية بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الصلاحية بالإنجليزية',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `SCHOOL_SUPERVISE_BY_OFFICE` VARCHAR(200) COMMENT 'لمشرفي المكتب التربوي فقط - يمكنهم الإشراف على المدارس التابعة',
  `CERTIFICATE_APPROVE_BY_OFFICE` VARCHAR(200) COMMENT 'اعتماد الشهادات الصادرة من المدارس (للشهادات المعتمدة من الوزارة)',
  `CERTIFICATE_REVOKE_BY_OFFICE` VARCHAR(200) COMMENT 'سحب أو إلغاء شهادة (في حال تزوير أو خطأ جسيم - حساس جداً)',
  `DATA_VIEW_BY_OFFICE` VARCHAR(200) COMMENT 'الاطلاع على البيانات والإحصائيات الرسمية (للتقارير الوزارية)',
