  `category` VARCHAR(50) COMMENT 'فئة الصلاحية (سجل سلوكي، شكاوى، إرشاد، متابعة)',
  `subCategory` VARCHAR(50) COMMENT 'الفئة الفرعية (إيجابي، مخالفة، تقديم شكوى، تصعيد، ملاحظات إرشادية، تقدم أكاديمي)',
  `permissionKey` VARCHAR(200) COMMENT 'مفتاح الصلاحية (فريد، مثال: "behavior.record.positive")',
  `allowedActions` VARCHAR(200) COMMENT 'الإجراءات المسموحة (JSON) - قائمة بالإجراءات',
  `scope` VARCHAR(200) COMMENT 'نطاق الصلاحية (خاص، فصله، مدرسته، عام)',
  `isSensitive` BOOLEAN COMMENT 'هل هذه الصلاحية حساسة (تتطلب مستوى أمان أعلى)؟',
  `requiresJustification` VARCHAR(200) COMMENT 'هل يتطلب الإجراء تبريراً؟',
  `justificationApprovalRequired` VARCHAR(200) COMMENT 'هل يتطلب التبرير موافقة؟',
  `descriptionAr` TEXT COMMENT 'وصف الصلاحية بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الصلاحية بالإنجليزية',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`matrixId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`permissionId`) REFERENCES `BehaviorPermissions`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='صلاحيات السلوك والمتابعة';

-- Table: BehaviorPermissions (السلوك)
CREATE TABLE IF NOT EXISTS `BehaviorPermissions` (
  `permissionId` BIGINT NOT NULL COMMENT 'معرف الصلاحية (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `roleId` BIGINT COMMENT 'معرف الدور (FK → Role.roleId)',
  `behaviorCategory` VARCHAR(50) COMMENT 'فئة السلوك (إيجابي، مخالفة، شكوى، إرشاد)',
  `permissionCode` VARCHAR(50) COMMENT 'كود الصلاحية (مثال: "BEHAVIOR_RECORD_POSITIVE", "BEHAVIOR_RECORD_NEGATIVE")',
  `action` VARCHAR(200) COMMENT 'الإجراء المسموح (record, view, escalate, add_note, monitor)',
  `scope` VARCHAR(200) COMMENT 'نطاق الصلاحية (خاص، فصله، مدرسته)',
  `requiresEvidence` VARCHAR(200) COMMENT 'هل يتطلب الإجراء أدلة (صور، مستندات)؟',
  `isSensitive` BOOLEAN COMMENT 'هل الصلاحية حساسة (تتطلب مستوى أمان أعلى)؟',
  `accessibleBy` VARCHAR(200) COMMENT 'من يمكنه الوصول لهذه البيانات (نفس الدور، مشرف، إدارة)',
  `descriptionAr` TEXT COMMENT 'وصف الصلاحية بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الصلاحية بالإنجليزية',
  `isActive` BOOLEAN COMMENT 'هل الصلاحية مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  `BEHAVIOR_RECORD_POSITIVE` VARCHAR(200) COMMENT 'تسجيل سلوك إيجابي (للمعلمين والإداريين للتحفيز)',
  `BEHAVIOR_RECORD_NEGATIVE` VARCHAR(200) COMMENT 'تسجيل مخالفة سلوكية (بموضوعية مع إرفاق الأدلة)',
  `COMPLAINT_SUBMIT` VARCHAR(200) COMMENT 'تقديم شكوى أو تظلم (للطالب أو ولي الأمر مع المستندات)',
  `COMPLAINT_ESCALATE` VARCHAR(200) COMMENT 'تصعيد الشكوى لمستوى أعلى (في حال عدم الحل في المستوى الأدنى)',
  `GUIDANCE_NOTE_ADD` VARCHAR(200) COMMENT 'إضافة ملاحظات إرشادية (حساسة جداً: للمرشدين فقط)',
  `PROGRESS_MONITOR` VARCHAR(200) COMMENT 'متابعة التقدم الأكاديمي والسلوكي (لدعم الطلاب المتعثرين)',
  PRIMARY KEY (`permissionId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`roleId`) REFERENCES `Role`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='السلوك';

-- Table: AuditLog (سجل التدقيق)
CREATE TABLE IF NOT EXISTS `AuditLog` (
  `auditId` BIGINT NOT NULL COMMENT 'معرف سجل التدقيق (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL لعمليات على مستوى المكتب',
  `userId` BIGINT COMMENT 'معرف المستخدم الذي قام بالعملية (FK → SystemUser.userId)',
  `userRoleAtExecution` VARCHAR(200) COMMENT 'دور المستخدم عند التنفيذ (لحظة العملية، قد يختلف عن دوره الحالي)',
  `action` VARCHAR(200) COMMENT 'الإجراء (INSERT, UPDATE, DELETE, GRANT, REVOKE, APPROVE, REJECT, LOGIN, LOGOUT)',
  `entityType` VARCHAR(50) COMMENT 'نوع الكيان المتأثر (Student, Grade, Payment, User, Role, Permission)',
  `entityId` BIGINT COMMENT 'معرف الكيان المتأثر',
  `oldValue` VARCHAR(200) COMMENT 'البيانات قبل التعديل (JSON) - لتغييرات UPDATE',
  `newValue` VARCHAR(200) COMMENT 'البيانات بعد التعديل (JSON)',
  `changeSummary` VARCHAR(200) COMMENT 'ملخص التغيير (نص مختصر)',
  `tableName` VARCHAR(200) COMMENT 'اسم الجدول المتأثر (للبحث السريع)',
  `fieldName` VARCHAR(200) COMMENT 'اسم الحقل المتأثر (إن كان تغيير حقل واحد)',
  `ipAddress` VARCHAR(200) COMMENT 'عنوان IP للمستخدم',
  `deviceType` VARCHAR(50) COMMENT 'نوع الجهاز (كمبيوتر، هاتف، جهاز لوحي)',
  `userAgent` VARCHAR(200) COMMENT 'متصفح/نظام التشغيل',
  `sessionId` BIGINT COMMENT 'معرف الجلسة',
  `accessContext` VARCHAR(200) COMMENT 'سياق الوصول (JSON) - معلومات إضافية مثل الموقع، التطبيق المستخدم',
  `severity` VARCHAR(200) COMMENT 'مستوى الخطورة (معلومات، تحذير، حرج)',
  `riskScore` DECIMAL(5,2) COMMENT 'درجة المخاطرة (1-100) - للعمليات الحساسة',
  `isSuspicious` BOOLEAN COMMENT 'هل العملية مشبوهة؟ (تمت في وقت غير رسمي، من جهاز غير معتاد)',
  `wasAllowed` VARCHAR(200) COMMENT 'هل تم السماح بالوصول؟ (نعم/لا - حالات الرفض)',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن لم يسمح)',
  `notes` TEXT COMMENT 'ملاحظات إضافية',
  `createdAt` DATE COMMENT 'تاريخ ووقت العملية (مفهرس للبحث السريع)',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`auditId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`entityId`) REFERENCES `Entity`(`...`),
  -- FOREIGN KEY (`sessionId`) REFERENCES `Session`(`...`)
) COMMENT='سجل التدقيق';

-- Table: StudentPermissionAudit (سجل صلاحيات الطالب)
CREATE TABLE IF NOT EXISTS `StudentPermissionAudit` (
  `auditId` BIGINT NOT NULL COMMENT 'معرف سجل التدقيق (المفتاح الرئيسي)',
  `studentId` BIGINT COMMENT 'معرف الطالب المتأثر (FK → Student.studentId)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `userId` BIGINT COMMENT 'معرف المستخدم الذي حاول الوصول (FK → SystemUser.userId)',
  `userRole` VARCHAR(200) COMMENT 'دور المستخدم عند التنفيذ',
  `permissionKey` VARCHAR(200) COMMENT 'مفتاح الصلاحية المستخدمة (مثال: "grades.view")',
  `entityType` VARCHAR(50) COMMENT 'نوع الكيان (Student, Grade, Attendance, HealthRecord)',
  `entityId` BIGINT COMMENT 'معرف الكيان المتأثر',
  `action` VARCHAR(200) COMMENT 'الإجراء (view, edit, delete, export)',
  `accessContext` VARCHAR(200) COMMENT 'سياق الوصول (JSON) - IP, Device, Location',
  `wasAllowed` VARCHAR(200) COMMENT 'هل تم السماح بالوصول؟',
  `rejectionReason` VARCHAR(200) COMMENT 'سبب الرفض (إن وجد)',
  `riskScore` DECIMAL(5,2) COMMENT 'درجة المخاطرة (1-100)',
  `createdAt` VARCHAR(200) COMMENT 'وقت التنفيذ (مفهرس)',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`auditId`),
  -- FOREIGN KEY (`studentId`) REFERENCES `Student`(`...`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`userId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`entityId`) REFERENCES `Entity`(`...`)
) COMMENT='سجل صلاحيات الطالب';

-- Table: RoleMatrix (مصفوفة الأدوار النموذجية)
CREATE TABLE IF NOT EXISTS `RoleMatrix` (
  `matrixId` BIGINT NOT NULL COMMENT 'معرف المصفوفة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للأدوار العامة',
  `roleCode` VARCHAR(50) COMMENT 'كود الدور (مرجع)',
  `roleNameAr` VARCHAR(200) COMMENT 'اسم الدور بالعربية',
  `roleNameEn` VARCHAR(200) COMMENT 'اسم الدور بالإنجليزية',
  `roleType` VARCHAR(50) COMMENT 'نوع الدور (نظام، مدرسي، مكتبي)',
  `permissions` VARCHAR(200) COMMENT 'الصلاحيات الأساسية لهذا الدور (JSON) - قائمة بمفاتيح الصلاحيات',
  `descriptionAr` TEXT COMMENT 'وصف الدور بالعربية',
  `descriptionEn` TEXT COMMENT 'وصف الدور بالإنجليزية',
  `isActive` BOOLEAN COMMENT 'هل الدور مفعل؟',
  `sortOrder` VARCHAR(200) COMMENT 'ترتيب العرض',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`matrixId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='مصفوفة الأدوار النموذجية';

-- Table: PrivilegeRules (الامتيازات وقواعد النظام)
CREATE TABLE IF NOT EXISTS `PrivilegeRules` (
  `ruleId` BIGINT NOT NULL COMMENT 'معرف القاعدة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId) - يمكن أن يكون NULL للقواعد العامة',
  `ruleCode` VARCHAR(50) COMMENT 'كود القاعدة (فريد)',
  `ruleNameAr` VARCHAR(200) COMMENT 'اسم القاعدة بالعربية',
  `ruleNameEn` VARCHAR(200) COMMENT 'اسم القاعدة بالإنجليزية',
  `ruleCategory` VARCHAR(50) COMMENT 'فئة القاعدة (تدقيق، موافقات، حدود، تنبيهات)',
  `appliesTo` VARCHAR(200) COMMENT 'تنطبق على (صلاحية محددة، فئة صلاحيات، كل الصلاحيات)',
  `appliesToValue` VARCHAR(200) COMMENT 'قيمة ما تنطبق عليه (permissionKey, permissionCategory, أو ''*'')',
  `condition` VARCHAR(200) COMMENT 'شرط تطبيق القاعدة (JSON) - مثل: "إذا كان الإجراء = تعديل"',
  `action` VARCHAR(200) COMMENT 'الإجراء المطلوب (تسجيل في AuditLog، طلب موافقة، إرسال تنبيه، منع العملية)',
  `actionParameters` VARCHAR(200) COMMENT 'معاملات الإجراء (JSON) - مثل مستوى الموافقة المطلوب',
  `priority` VARCHAR(200) COMMENT 'الأولوية (1-100)',
  `isActive` BOOLEAN COMMENT 'هل القاعدة مفعلة؟',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`ruleId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الامتيازات وقواعد النظام';


-- ============================
-- Module: M8_Emergency
-- ============================

-- Table: EmergencyHosting (الاستضافة الطارئة)
CREATE TABLE IF NOT EXISTS `EmergencyHosting` (
  `hostingId` BIGINT NOT NULL COMMENT 'معرف حالة الاستضافة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `hostingNumber` INT COMMENT 'رقم الحالة (تسلسلي)',
  `hostingType` VARCHAR(50) COMMENT 'نوع الاستضافة (نازحين، طلاب خارجيين، أغراض صحية، مركز قيادة طوارئ، أخرى)',
  `hostingDate` DATE COMMENT 'تاريخ بدء الاستضافة',
  `endDate` DATE COMMENT 'تاريخ انتهاء الاستضافة الفعلي (أو المتوقع)',
  `expectedEndDate` DATE COMMENT 'تاريخ الانتهاء المتوقع عند بدء الاستضافة',
  `actualCount` INT COMMENT 'عدد الأفراد المستضافين فعلياً',
  `maxCapacity` VARCHAR(200) COMMENT 'السعة القصوى للمدرسة لهذا النوع من الاستضافة',
  `utilizationPercentage` DECIMAL(5,2) COMMENT 'نسبة الاستغلال (actualCount / maxCapacity)',
  `reason` VARCHAR(200) COMMENT 'سبب الاستضافة (كوارث طبيعية، حريق مدرسة مجاورة، أزمة صحية، أخرى)',
  `sourceLocation` VARCHAR(200) COMMENT 'موقع المصدر (منطقة، مدينة) للأفراد المستضافين',
  `supportOrg` VARCHAR(200) COMMENT 'الجهة الداعمة (مثل اليونيسيف، الهلال الأحمر، وزارة الصحة)',
  `supportOrgContact` VARCHAR(200) COMMENT 'جهة اتصال الجهة الداعمة',
  `facilitiesUsed` VARCHAR(200) COMMENT 'المرافق المستخدمة في الاستضافة (JSON) - قاعات، معامل، ملاعب',
  `resourcesProvided` VARCHAR(200) COMMENT 'الموارد التي قدمتها المدرسة (JSON) - مياه، كهرباء، إنترنت، أغذية',
  `resourcesReceived` VARCHAR(200) COMMENT 'الموارد التي تلقتها المدرسة من جهات داعمة (JSON)',
  `expenses` VARCHAR(200) COMMENT 'التكاليف التي تكبدتها المدرسة (JSON)',
  `totalExpenses` VARCHAR(200) COMMENT 'إجمالي التكاليف',
  `status` VARCHAR(50) COMMENT 'حالة الاستضافة (نشطة، منتهية، قيد التجهيز)',
  `closureNotes` TEXT COMMENT 'ملاحظات عند إنهاء الاستضافة',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة من هذه التجربة',
  `reportedByUserId` BIGINT COMMENT 'معرف من سجل الحالة (FK → SystemUser.userId)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور، تقارير) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`hostingId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`reportedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الاستضافة الطارئة';

-- Table: EmergencyIncidents (حوادث الطوارئ)
CREATE TABLE IF NOT EXISTS `EmergencyIncidents` (
  `incidentId` BIGINT NOT NULL COMMENT 'معرف الحادثة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `incidentNumber` INT COMMENT 'رقم الحادثة (تسلسلي حسب العام)',
  `incidentType` VARCHAR(50) COMMENT 'نوع الحادثة (زلزال، حريق، وباء، اضطراب أمني، فيضان، عاصفة، حادث كيميائي، انهيار، أخرى)',
  `incidentDate` DATE COMMENT 'تاريخ الحادثة',
  `incidentTime` TIME COMMENT 'وقت الحادثة',
  `severity` VARCHAR(200) COMMENT 'مستوى الخطورة (منخفض، متوسط، عالٍ، حرج)',
  `description` TEXT COMMENT 'وصف تفصيلي للحادثة',
  `location` VARCHAR(200) COMMENT 'موقع الحادثة داخل المدرسة (مبنى، طابق، غرفة)',
  `reportedByUserId` BIGINT COMMENT 'معرف من أبلغ عن الحادثة (FK → SystemUser.userId)',
  `reportedAt` VARCHAR(200) COMMENT 'وقت الإبلاغ',
  `isPlanActive` BOOLEAN COMMENT 'هل تم تفعيل خطة الطوارئ المعتمدة؟',
  `emergencyPlanId` BIGINT COMMENT 'معرف خطة الطوارئ المستخدمة (FK → من جدول خطط الطوارئ - خارج هذا القسم)',
  `affectedCount` INT COMMENT 'عدد المتضررين (إحصائية أولية)',
  `studentsAffected` VARCHAR(200) COMMENT 'عدد الطلاب المتضررين',
  `employeesAffected` VARCHAR(200) COMMENT 'عدد الموظفين المتضررين',
  `injuriesCount` INT COMMENT 'عدد الإصابات',
  `severeInjuriesCount` INT COMMENT 'عدد الإصابات الخطيرة',
  `fatalitiesCount` INT COMMENT 'عدد الوفيات (لا قدر الله)',
  `propertyDamage` VARCHAR(200) COMMENT 'قيمة الأضرار المادية التقديرية',
  `propertyDamageDescription` TEXT COMMENT 'وصف الأضرار المادية',
  `emergencyResponse` VARCHAR(200) COMMENT 'الإجراءات المتخذة فوراً (إخلاء، إسعافات أولية، إطفاء)',
  `externalAgencies` VARCHAR(200) COMMENT 'الجهات الخارجية المستجوبة (دفاع مدني، إسعاف، شرطة) (JSON)',
  `externalResponseTime` TIME COMMENT 'وقت استجابة الجهات الخارجية',
  `status` VARCHAR(50) COMMENT 'حالة البلاغ (مفتوح، قيد المعالجة، مغلق، تحت التحقيق)',
  `closureDate` DATE COMMENT 'تاريخ الإغلاق',
  `closureNotes` TEXT COMMENT 'ملاحظات الإغلاق',
  `investigationReport` VARCHAR(200) COMMENT 'رابط تقرير التحقيق (إن وجد)',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة لتجنب تكرار الحادثة',
  `recommendations` VARCHAR(200) COMMENT 'توصيات للتحسين',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور، تقارير) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`incidentId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`reportedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`emergencyPlanId`) REFERENCES `EmergencyPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حوادث الطوارئ';

-- Table: EmergencyClosures (الإغلاق الطارئ)
CREATE TABLE IF NOT EXISTS `EmergencyClosures` (
  `closureId` BIGINT NOT NULL COMMENT 'معرف الإغلاق (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `closureNumber` INT COMMENT 'رقم الإغلاق (تسلسلي)',
  `closureReason` VARCHAR(200) COMMENT 'سبب الإغلاق (ظروف جوية، وباء، تهديد أمني، عطل فني شامل، أمر حكومي، أخرى)',
  `authority` VARCHAR(200) COMMENT 'الجهة المقررة للإغلاق (وزارة الصحة، الدفاع المدني، وزارة التعليم، المكتب التربوي، إدارة المدرسة)',
  `authorityDecisionNumber` INT COMMENT 'رقم قرار الإغلاق (إن وجد)',
  `startDate` DATE COMMENT 'تاريخ بداية توقف الدراسة',
  `endDate` DATE COMMENT 'تاريخ نهاية الإغلاق (المتوقع أو الفعلي)',
  `actualEndDate` DATE COMMENT 'تاريخ العودة الفعلي',
  `totalClosureDays` VARCHAR(200) COMMENT 'عدد أيام الإغلاق',
  `schoolDaysAffected` VARCHAR(200) COMMENT 'عدد أيام الدراسة الفعلية التي تأثرت',
  `alternativeEducation` VARCHAR(200) COMMENT 'هل تم تفعيل التعليم عن بعد؟',
  `alternativeEducationType` VARCHAR(50) COMMENT 'نوع التعليم البديل (عن بعد متزامن، عن بعد غير متزامن، حصص تعويضية، حصص صيفية)',
  `altEducationPlatform` VARCHAR(200) COMMENT 'المنصة المستخدمة (Teams, Zoom, منصة مدرستي، أخرى)',
  `altEducationDetails` VARCHAR(200) COMMENT 'تفاصيل خطة التعليم البديل',
  `wasCompensated` VARCHAR(200) COMMENT 'هل تم تعويض الفاقد التعليمي؟',
  `compensationPlanId` BIGINT COMMENT 'معرف خطة التعويض المرتبطة (FK → RemediationPlan.planId - من المجموعة 8-ج)',
  `parentNotificationSent` VARCHAR(200) COMMENT 'هل تم إشعار أولياء الأمور؟',
  `parentNotificationDate` DATE COMMENT 'تاريخ إشعار أولياء الأمور',
  `parentNotificationMethod` VARCHAR(200) COMMENT 'طريقة الإشعار (رسالة نصية، بريد إلكتروني، تطبيق)',
  `status` VARCHAR(50) COMMENT 'حالة الإغلاق (مخطط، جاري، منتهي)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`closureId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`compensationPlanId`) REFERENCES `RemediationPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الإغلاق الطارئ';

-- Table: TransportationServices (خدمات النقل المدرسي)
CREATE TABLE IF NOT EXISTS `TransportationServices` (
  `serviceId` BIGINT NOT NULL COMMENT 'معرف خدمة النقل (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `routeId` BIGINT COMMENT 'معرف المسار (فريد داخل المدرسة)',
  `routeName` VARCHAR(200) COMMENT 'اسم المسار (مثال: "المسار الشرقي")',
  `routeCode` VARCHAR(50) COMMENT 'كود المسار',
  `routeDescription` TEXT COMMENT 'وصف المسار (المناطق التي يغطيها)',
  `busId` BIGINT COMMENT 'معرف الحافلة (يمكن ربطه بجدول Asset في القسم الرابع)',
  `busPlateNumber` INT COMMENT 'رقم لوحة الحافلة',
  `busCapacity` VARCHAR(200) COMMENT 'سعة الحافلة (عدد الطلاب)',
  `busModel` VARCHAR(200) COMMENT 'موديل الحافلة',
  `busYear` VARCHAR(200) COMMENT 'سنة الصنع',
  `driverId` BIGINT COMMENT 'معرف السائق (FK → Employee.employeeId)',
  `driverName` VARCHAR(200) COMMENT 'اسم السائق',
  `driverLicenseNumber` INT COMMENT 'رقم رخصة السائق',
  `driverPhone` VARCHAR(20) COMMENT 'هاتف السائق',
  `supervisorId` BIGINT COMMENT 'معرف المشرف (FK → Employee.employeeId)',
  `supervisorName` VARCHAR(200) COMMENT 'اسم المشرف',
  `supervisorPhone` VARCHAR(20) COMMENT 'هاتف المشرف',
  `shiftId` BIGINT COMMENT 'معرف الفترة (صباحي، مسائي) (FK → SchoolShiftSetting.shiftId)',
  `tripType` VARCHAR(50) COMMENT 'نوع الرحلة (صباحية، مسائية، جميع الأيام)',
  `startTime` TIME COMMENT 'وقت بدء الرحلة',
  `endTime` TIME COMMENT 'وقت انتهاء الرحلة',
  `estimatedDuration` VARCHAR(200) COMMENT 'المدة التقديرية للرحلة',
  `stops` VARCHAR(200) COMMENT 'محطات التوقف (JSON) - تحتوي على المحطة، العنوان، الوقت، الإحداثيات',
  `isActive` BOOLEAN COMMENT 'هل المسار نشط؟',
  `status` VARCHAR(50) COMMENT 'حالة الخدمة (نشطة، متوقفة، كاملة)',
  `operatorCompany` VARCHAR(200) COMMENT 'الشركة المشغلة (إن وجدت)',
  `contractId` BIGINT COMMENT 'معرف العقد مع الشركة المشغلة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`serviceId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`routeId`) REFERENCES `Route`(`...`),
  -- FOREIGN KEY (`busId`) REFERENCES `Bus`(`...`),
  -- FOREIGN KEY (`driverId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`supervisorId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`shiftId`) REFERENCES `SchoolShiftSetting`(`...`),
  -- FOREIGN KEY (`contractId`) REFERENCES `Contract`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='خدمات النقل المدرسي';

-- Table: SchoolMergers (عمليات الدمج المدرسي)
CREATE TABLE IF NOT EXISTS `SchoolMergers` (
  `mergerId` BIGINT NOT NULL COMMENT 'معرف عملية الدمج (المفتاح الرئيسي)',
  `mergerNumber` INT COMMENT 'رقم قرار الدمج',
  `mergerDate` DATE COMMENT 'تاريخ صدور قرار الدمج',
  `effectiveDate` DATE COMMENT 'تاريخ السريان الفعلي للدمج',
  `sourceSchoolIds` VARCHAR(200) COMMENT 'المدارس المندمجة (JSON) - قائمة بـ School.schoolId',
  `targetSchoolId` BIGINT COMMENT 'المدرسة الدامجة (المدرسة الناتجة) (FK → School.schoolId)',
  `mergerReason` VARCHAR(200) COMMENT 'سبب الدمج (نقص عدد الطلاب، خفض التكاليف، تحسين الجودة، قرار وزار)',
  `decisionAuthority` VARCHAR(200) COMMENT 'جهة إصدار القرار (مكتب التربية، وزارة التعليم)',
  `decisionDocumentPath` VARCHAR(200) COMMENT 'مسار ملف قرار الدمج',
  `studentsTransferStatus` VARCHAR(50) COMMENT 'حالة نقل الطلاب (قيد التنفيذ، مكتمل)',
  `employeesTransferStatus` VARCHAR(50) COMMENT 'حالة نقل الموظفين (قيد التنفيذ، مكتمل)',
  `assetsTransferStatus` VARCHAR(50) COMMENT 'حالة نقل الأصول (قيد التنفيذ، مكتمل)',
  `status` VARCHAR(50) COMMENT 'حالة العملية (مخطط، قيد التنفيذ، مكتمل، ملغي)',
  `completionDate` DATE COMMENT 'تاريخ اكتمال الدمج',
  `completionNotes` TEXT COMMENT 'ملاحظات عند الإكمال',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`mergerId`),
  -- FOREIGN KEY (`targetSchoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='عمليات الدمج المدرسي';

-- Table: SchoolAwards (الجوائز والتميز)
CREATE TABLE IF NOT EXISTS `SchoolAwards` (
  `awardId` BIGINT NOT NULL COMMENT 'معرف الجائزة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `awardNumber` INT COMMENT 'رقم الجائزة (تسلسلي)',
  `awardName` VARCHAR(200) COMMENT 'اسم الجائزة (مثال: "جائزة التميز المدرسي")',
  `awardCategory` VARCHAR(50) COMMENT 'فئة الجائزة (تعليمية، تربوية، رياضية، ثقافية، بيئية، خدمة مجتمع)',
  `level` VARCHAR(50) COMMENT 'المستوى (محلي، وطني، إقليمي، دولي)',
  `issuingBody` BOOLEAN COMMENT 'الجهة المانحة (وزارة التعليم، مركز تميز، منظمة دولية)',
  `issuingBodyType` BOOLEAN COMMENT 'نوع الجهة (حكومية، خاصة، دولية)',
  `awardDate` DATE COMMENT 'تاريخ التكريم',
  `awardPlace` VARCHAR(200) COMMENT 'مكان التكريم (مدينة، دولة)',
  `ranking` VARCHAR(200) COMMENT 'الترتيب المحقق (الأول، الثاني، الثالث، متميز)',
  `participantsJson` VARCHAR(200) COMMENT 'المشاركون (JSON) - قائمة بأسماء المشاركين وأدوارهم',
  `studentParticipants` VARCHAR(200) COMMENT 'عدد الطلاب المشاركين',
  `teacherParticipants` VARCHAR(200) COMMENT 'عدد المعلمين المشاركين',
  `awardDetails` VARCHAR(200) COMMENT 'تفاصيل الجائزة (ما تم تقديره، سبب الفوز)',
  `certificatePath` VARCHAR(200) COMMENT 'مسار ملف شهادة الجائزة (PDF)',
  `photosPath` VARCHAR(200) COMMENT 'مسارات صور التكريم (JSON)',
  `videoPath` VARCHAR(200) COMMENT 'مسار فيديو التكريم (اختياري)',
  `impact` VARCHAR(200) COMMENT 'أثر الجائزة على المدرسة (زيادة السمعة، تحفيز الطلاب، الخ)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`awardId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الجوائز والتميز';

-- Table: ExternalParticipations (المشاركات والتمثيل الخارجي)
CREATE TABLE IF NOT EXISTS `ExternalParticipations` (
  `participationId` BIGINT NOT NULL COMMENT 'معرف المشاركة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `participationNumber` INT COMMENT 'رقم المشاركة (تسلسلي)',
  `eventName` VARCHAR(200) COMMENT 'اسم الفعالية (مؤتمر، مسابقة، معرض، مهرجان، زيارة)',
  `eventType` VARCHAR(50) COMMENT 'نوع الفعالية (رياضي، علمي، ثقافي، فني، تطوعي، أكاديمي)',
  `organizer` VARCHAR(200) COMMENT 'الجهة المنظمة',
  `organizerType` VARCHAR(50) COMMENT 'نوع الجهة (مدرسة، جامعة، جهة حكومية، منظمة دولية)',
  `location` VARCHAR(200) COMMENT 'مكان الفعالية (مدينة، دولة)',
  `startDate` DATE COMMENT 'تاريخ بدء الفعالية',
  `endDate` DATE COMMENT 'تاريخ انتهاء الفعالية',
  `results` VARCHAR(200) COMMENT 'نتائج المشاركة (المراكز المحققة، الشهادات، الدروس المستفادة)',
  `ranking` VARCHAR(200) COMMENT 'الترتيب (إن وجد)',
  `participantsJson` VARCHAR(200) COMMENT 'المشاركون (JSON) - قائمة بالأسماء والأدوار',
  `studentParticipants` VARCHAR(200) COMMENT 'عدد الطلاب المشاركين',
  `teacherParticipants` VARCHAR(200) COMMENT 'عدد المعلمين المشاركين',
  `expenses` VARCHAR(200) COMMENT 'تكاليف المشاركة (سفر، إقامة، تسجيل)',
  `fundingSource` VARCHAR(200) COMMENT 'مصدر التمويل (المدرسة، جهة خارجية، ذاتي)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور، شهادات، تقارير) (JSON)',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة',
  `recommendations` VARCHAR(200) COMMENT 'توصيات للمشاركات المستقبلية',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`participationId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='المشاركات والتمثيل الخارجي';

-- Table: CommunityPartnerships (الشراكات المجتمعية)
CREATE TABLE IF NOT EXISTS `CommunityPartnerships` (
  `partnershipId` BIGINT NOT NULL COMMENT 'معرف الشراكة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `partnershipNumber` INT COMMENT 'رقم الشراكة (تسلسلي)',
  `partnerName` VARCHAR(200) COMMENT 'اسم الشريك (المؤسسة أو الجهة المانحة)',
  `partnerType` VARCHAR(50) COMMENT 'نوع الشريك (شركة، منظمة غير ربحية، جامعة، جهة حكومية، فرد)',
  `supportType` VARCHAR(50) COMMENT 'نوع الدعم (تجهيزات، صيانة، تطوير برامج، مالي، تدريب، تبادل خبرات)',
  `agreementDate` DATE COMMENT 'تاريخ الاتفاقية',
  `startDate` DATE COMMENT 'تاريخ بدء الشراكة',
  `endDate` DATE COMMENT 'تاريخ انتهاء الشراكة (إن وجد)',
  `isRenewable` BOOLEAN COMMENT 'هل الشراكة قابلة للتجديد؟',
  `agreementDocumentPath` VARCHAR(200) COMMENT 'مسار ملف الاتفاقية (PDF)',
  `supportValue` VARCHAR(200) COMMENT 'قيمة الدعم المالي (إن وجد)',
  `supportValueCurrency` VARCHAR(200) COMMENT 'عملة الدعم',
  `supportInKind` VARCHAR(200) COMMENT 'دعم عيني (تجهيزات، خدمات) (JSON)',
  `impact` VARCHAR(200) COMMENT 'الأثر المحقق من الشراكة (تقييم مدى فعالية الدعم)',
  `impactRating` VARCHAR(200) COMMENT 'تقييم الأثر (1-5)',
  `responsibleUserId` BIGINT COMMENT 'معرف المسؤول عن الشراكة من المدرسة (FK → Employee.employeeId)',
  `partnerContactPerson` VARCHAR(200) COMMENT 'جهة اتصال الشريك',
  `partnerContactEmail` VARCHAR(100) COMMENT 'بريد جهة اتصال الشريك',
  `partnerContactPhone` VARCHAR(20) COMMENT 'هاتف جهة اتصال الشريك',
  `status` VARCHAR(50) COMMENT 'حالة الشراكة (نشطة، منتهية، مجددة، ملغاة)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`partnershipId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`responsibleUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='الشراكات المجتمعية';

-- Table: SafetySecurityReports (تقارير السلامة والأمان)
CREATE TABLE IF NOT EXISTS `SafetySecurityReports` (
  `reportId` BIGINT NOT NULL COMMENT 'معرف التقرير (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `reportNumber` INT COMMENT 'رقم التقرير (تسلسلي)',
  `reportDate` DATE COMMENT 'تاريخ التقرير',
  `reportPeriod` VARCHAR(200) COMMENT 'فترة التقرير (شهري، ربع سنوي، سنوي)',
  `safetyLevel` VARCHAR(50) COMMENT 'مستوى السلامة العام (ممتاز، جيد، مقبول، يحتاج تحسين)',
  `extinguisherExp` DATE COMMENT 'تاريخ انتهاء صلاحية أقرب طفاية حريق (للتذكير)',
  `extinguishersCount` INT COMMENT 'عدد الطفايات المتوفرة',
  `extinguishersLastInspection` DATE COMMENT 'تاريخ آخر فحص للطفايات',
  `extinguishersNextInspection` DATE COMMENT 'تاريخ الفحص القادم',
  `alarmStatus` VARCHAR(50) COMMENT 'حالة أنظمة الإنذار (يعمل بكفاءة، يحتاج صيانة، معطل)',
  `alarmLastTest` DATE COMMENT 'تاريخ آخر اختبار لأنظمة الإنذار',
  `emergencyLightsStatus` VARCHAR(50) COMMENT 'حالة أضواء الطوارئ',
  `fireAlarmSystem` VARCHAR(200) COMMENT 'نوع نظام إنذار الحريق (يدوي، آلي، متكامل)',
  `fireHosesStatus` VARCHAR(50) COMMENT 'حالة خراطيم الحريق',
  `evacuationMaps` VARCHAR(200) COMMENT 'هل توجد خرائط إخلاء واضحة؟',
  `evacuationMapLocations` VARCHAR(200) COMMENT 'مواقع خرائط الإخلاء (JSON)',
  `emergencyExitsStatus` VARCHAR(50) COMMENT 'حالة مخارج الطوارئ (كلها تعمل، بعضها معطل)',
  `drillCount` INT COMMENT 'عدد تدريبات الإخلاء المنفذة خلال الفترة',
  `drillDates` DATE COMMENT 'تواريخ التدريبات (JSON)',
  `drillAverageTime` TIME COMMENT 'متوسط زمن الإخلاء (بالدقائق)',
  `drillEvaluation` VARCHAR(200) COMMENT 'تقييم التدريبات (فعالة، تحتاج تحسين)',
  `safetyCommitteeFormed` VARCHAR(200) COMMENT 'هل تم تشكيل لجنة سلامة؟',
  `safetyCommitteeMembers` VARCHAR(200) COMMENT 'أعضاء لجنة السلامة (JSON)',
  `safetyTrainingHours` VARCHAR(200) COMMENT 'عدد ساعات التدريب على السلامة',
  `incidentsCount` INT COMMENT 'عدد الحوادث المسجلة خلال الفترة',
  `recommendations` VARCHAR(200) COMMENT 'توصيات لتحسين السلامة',
  `actionPlan` VARCHAR(200) COMMENT 'خطة عمل للتحسين',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (صور، تقارير) (JSON)',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد التقرير (FK → SystemUser.userId)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`reportId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='تقارير السلامة والأمان';

-- Table: SchoolDeficit (حالات العجز التعليمي)
CREATE TABLE IF NOT EXISTS `SchoolDeficit` (
  `deficitId` BIGINT NOT NULL COMMENT 'معرف العجز (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `deficitNumber` INT COMMENT 'رقم العجز (تسلسلي)',
  `deficitType` VARCHAR(50) COMMENT 'نوع العجز (فصول، كادر تعليمي، تجهيزات، مالي، برامج تعليمية، وسائل نقل)',
  `deficitCategory` VARCHAR(50) COMMENT 'فئة العجز (كمي، نوعي، مؤقت، دائم)',
  `deficitAmount` DECIMAL(15,2) COMMENT 'مقدار العجز (عدد الوحدات الناقصة أو النسبة المئوية)',
  `requiredAmount` DECIMAL(15,2) COMMENT 'المبلغ أو العدد المطلوب',
  `availableAmount` DECIMAL(15,2) COMMENT 'المبلغ أو العدد المتاح حالياً',
  `deficitDescription` TEXT COMMENT 'وصف تفصيلي للعجز',
  `educationalImpact` VARCHAR(200) COMMENT 'وصف لكيفية تأثر الطلاب والنتائج التعليمية بالعجز (نص مفصل)',
  `impactLevel` VARCHAR(50) COMMENT 'مستوى التأثير (منخفض، متوسط، عالٍ، حرج)',
  `detectionDate` DATE COMMENT 'تاريخ اكتشاف العجز',
  `detectedByUserId` BIGINT COMMENT 'معرف من اكتشف العجز (FK → SystemUser.userId)',
  `currentStatus` VARCHAR(50) COMMENT 'الحالة الحالية (نشط، قيد المعالجة، تم الحل، مؤجل)',
  `statusUpdateDate` DATE COMMENT 'تاريخ آخر تحديث للحالة',
  `proposedSolution` VARCHAR(200) COMMENT 'الحل المقترح لمعالجة العجز',
  `estimatedCost` DECIMAL(15,2) COMMENT 'التكلفة التقديرية للمعالجة',
  `estimatedResolutionDate` DATE COMMENT 'التاريخ المتوقع لحل العجز',
  `actualResolutionDate` DATE COMMENT 'تاريخ الحل الفعلي',
  `resolvedByUserId` BIGINT COMMENT 'معرف من قام بحل العجز (FK → SystemUser.userId)',
  `resolutionNotes` TEXT COMMENT 'ملاحظات الحل',
  `relatedRemediationPlanId` BIGINT COMMENT 'معرف خطة المعالجة المرتبطة (FK → RemediationPlan.planId)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (تقارير، دراسات) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`deficitId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`detectedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`resolvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`relatedRemediationPlanId`) REFERENCES `RemediationPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حالات العجز التعليمي';

-- Table: SchoolSurplus (حالات الفائض التعليمي)
CREATE TABLE IF NOT EXISTS `SchoolSurplus` (
  `surplusId` BIGINT NOT NULL COMMENT 'معرف الفائض (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `surplusNumber` INT COMMENT 'رقم الفائض (تسلسلي)',
  `surplusType` VARCHAR(50) COMMENT 'نوع الفائض (فصول، كادر تعليمي، تجهيزات، ميزانية، وقت، وسائل نقل)',
  `surplusCategory` VARCHAR(50) COMMENT 'فئة الفائض (كمي، نوعي، مؤقت، دائم)',
  `surplusAmount` DECIMAL(15,2) COMMENT 'مقدار الفائض (عدد الوحدات الزائدة أو النسبة المئوية)',
  `availableAmount` DECIMAL(15,2) COMMENT 'المبلغ أو العدد المتاح حالياً',
  `requiredAmount` DECIMAL(15,2) COMMENT 'المبلغ أو العدد المطلوب (صفر أو أقل)',
  `surplusDescription` TEXT COMMENT 'وصف تفصيلي للفائض',
  `utilizationPlan` VARCHAR(200) COMMENT 'خطة الاستغلال (مقترح المدرسة للاستفادة من الفائض)',
  `utilizationType` VARCHAR(50) COMMENT 'نوع الاستغلال (نقل لمدرسة أخرى، تأجير، إعادة توزيع داخلي، بيع، إيقاف)',
  `potentialBeneficiary` VARCHAR(200) COMMENT 'جهة مستفيدة محتملة (مدرسة، قسم، جهة خارجية)',
  `discoveryDate` DATE COMMENT 'تاريخ اكتشاف الفائض',
  `discoveredByUserId` BIGINT COMMENT 'معرف من اكتشف الفائض (FK → SystemUser.userId)',
  `currentStatus` VARCHAR(50) COMMENT 'الحالة الحالية (مكتشف، قيد المعالجة، تم الاستغلال، ملغي)',
  `statusUpdateDate` DATE COMMENT 'تاريخ آخر تحديث للحالة',
  `utilizationDate` DATE COMMENT 'تاريخ استغلال الفائض المتوقع',
  `actualUtilizationDate` DATE COMMENT 'تاريخ الاستغلال الفعلي',
  `utilizedByUserId` BIGINT COMMENT 'معرف من قام بالاستغلال (FK → SystemUser.userId)',
  `utilizationNotes` TEXT COMMENT 'ملاحظات الاستغلال',
  `relatedRemediationPlanId` BIGINT COMMENT 'معرف خطة المعالجة المرتبطة (قد تكون خطة للاستفادة من الفائض) (FK → RemediationPlan.planId)',
  `attachments` VARCHAR(200) COMMENT 'مرفقات (تقارير، دراسات) (JSON)',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`surplusId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`discoveredByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`utilizedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`relatedRemediationPlanId`) REFERENCES `RemediationPlan`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='حالات الفائض التعليمي';

-- Table: RemediationPlan (خطط معالجة العجز/الفائض)
CREATE TABLE IF NOT EXISTS `RemediationPlan` (
  `planId` BIGINT NOT NULL COMMENT 'معرف الخطة (المفتاح الرئيسي)',
  `schoolId` BIGINT COMMENT 'معرف المدرسة (FK → School.schoolId)',
  `planNumber` INT COMMENT 'رقم الخطة (تسلسلي)',
  `planName` VARCHAR(200) COMMENT 'اسم الخطة (مثال: "خطة معالجة عجز الكادر في الرياضيات")',
  `relatedDeficitId` BIGINT COMMENT 'معرف العجز المرتبط (FK → SchoolDeficit.deficitId) - اختياري',
  `relatedSurplusId` BIGINT COMMENT 'معرف الفائض المرتبط (FK → SchoolSurplus.surplusId) - اختياري',
  `planType` VARCHAR(50) COMMENT 'نوع الخطة (معالجة عجز، استغلال فائض)',
  `selectedOption` VARCHAR(200) COMMENT 'الخيار المختار (توسع، دمج، نقل، شراكة، تعاقد خارجي، تأجير، إعادة توزيع)',
  `optionDetails` VARCHAR(200) COMMENT 'تفاصيل الخيار المختار (نص مفصل)',
  `objectives` VARCHAR(200) COMMENT 'أهداف الخطة',
  `actionSteps` VARCHAR(200) COMMENT 'خطوات التنفيذ (JSON)',
  `startDate` DATE COMMENT 'التاريخ المتوقع لبدء تنفيذ المعالجة',
  `endDate` DATE COMMENT 'التاريخ المتوقع للانتهاء',
  `actualStartDate` DATE COMMENT 'تاريخ البدء الفعلي',
  `actualEndDate` DATE COMMENT 'تاريخ الانتهاء الفعلي',
  `estimatedBudget` VARCHAR(200) COMMENT 'التكلفة المالية المقدرة للمعالجة',
  `actualCost` DECIMAL(15,2) COMMENT 'التكلفة الفعلية',
  `currency` VARCHAR(200) COMMENT 'العملة',
  `executionLead` VARCHAR(200) COMMENT 'الشخص أو الجهة المسؤولة عن الخطة (اسم أو معرف موظف)',
  `executionLeadUserId` BIGINT COMMENT 'معرف المسؤول (FK → Employee.employeeId)',
  `executionTeam` VARCHAR(200) COMMENT 'فريق التنفيذ (JSON) - قائمة بـ Employee.employeeId',
  `progressPercentage` DECIMAL(5,2) COMMENT 'نسبة الإنجاز',
  `status` VARCHAR(50) COMMENT 'حالة الخطة (قيد الإعداد، معتمدة، قيد التنفيذ، مكتملة، ملغاة، متعثرة)',
  `approvalDate` DATE COMMENT 'تاريخ الاعتماد',
  `approvedByUserId` BIGINT COMMENT 'معرف من اعتمد الخطة (FK → SystemUser.userId)',
  `completionReport` VARCHAR(200) COMMENT 'تقرير الإنجاز (نص)',
  `lessonsLearned` VARCHAR(200) COMMENT 'الدروس المستفادة',
  `notes` TEXT COMMENT 'ملاحظات',
  `createdByUserId` BIGINT COMMENT 'منشئ السجل',
  `updatedByUserId` BIGINT COMMENT 'آخر من عدل',
  `createdAt` DATE COMMENT 'تاريخ الإنشاء',
  `updatedAt` DATE COMMENT 'آخر تحديث',
  `isDeleted` BOOLEAN COMMENT 'حذف منطقي',
  PRIMARY KEY (`planId`),
  -- FOREIGN KEY (`schoolId`) REFERENCES `School`(`...`),
  -- FOREIGN KEY (`relatedDeficitId`) REFERENCES `SchoolDeficit`(`...`),
  -- FOREIGN KEY (`relatedSurplusId`) REFERENCES `SchoolSurplus`(`...`),
  -- FOREIGN KEY (`executionLeadUserId`) REFERENCES `Employee`(`...`),
  -- FOREIGN KEY (`approvedByUserId`) REFERENCES `SystemUser`(`...`),
  -- FOREIGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
  -- FOREIGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`)
) COMMENT='خطط معالجة العجز/الفائض';


SET FOREIGN_KEY_CHECKS = 1;
